/* ---------- LRT on the real track ---------- */
let lrtPath=null;const lrts=[];
function buildLrtPath(){const ways=D.lrt.filter(w=>!w[0]).map(w=>flat2(w[1]));const key=p=>Math.round(p[0]/3)+','+Math.round(p[1]/3);const ends=new Map();ways.forEach((w,i)=>{for(const e of [0,1]){const k=key(e?w[w.length-1]:w[0]);if(!ends.has(k))ends.set(k,[]);ends.get(k).push([i,e]);}});
  let best=null;for(let st=0;st<ways.length;st++)for(const e0 of [0,1]){const used=new Set([st]);let path=e0?ways[st].slice().reverse():ways[st].slice();let guard=0;
    while(guard++<200){const tail=path[path.length-1],prev=path[path.length-2];const L=(ends.get(key(tail))||[]).filter(([i])=>!used.has(i));if(!L.length)break;let pickW=null,bestDot=-2;for(const [i,e] of L){const w=e?ways[i].slice().reverse():ways[i];const nx=w[Math.min(1,w.length-1)];const d1=[tail[0]-prev[0],tail[1]-prev[1]],d2=[nx[0]-tail[0],nx[1]-tail[1]];const dot=(d1[0]*d2[0]+d1[1]*d2[1])/((Math.hypot(...d1)*Math.hypot(...d2))||1);if(dot>bestDot){bestDot=dot;pickW=[i,w];}}
      if(bestDot<.3)break;used.add(pickW[0]);path=path.concat(pickW[1].slice(1));}
    let len=0;for(let i=1;i<path.length;i++)len+=Math.hypot(path[i][0]-path[i-1][0],path[i][1]-path[i-1][1]);if(!best||len>best.len)best={pts:path,len};}
  if(!best)return;const cum=[0];for(let i=1;i<best.pts.length;i++)cum.push(cum[i-1]+Math.hypot(best.pts[i][0]-best.pts[i-1][0],best.pts[i][1]-best.pts[i-1][1]));lrtPath={pts:best.pts,cum,len:best.len};
  const stops=[];for(const [br,f] of D.plat){const p=flat2(f);const cx=p.reduce((a,q)=>a+q[0],0)/p.length,cz=p.reduce((a,q)=>a+q[1],0)/p.length;let bs=-1,bd=12;for(let s=0;s<lrtPath.len;s+=2){const q=posOn(lrtPath,s);const d=Math.hypot(q.x-cx,q.z-cz);if(d<bd){bd=d;bs=s;}}if(bs>=0&&!stops.some(s=>Math.abs(s-bs)<30))stops.push(bs);}lrtPath.stops=stops.sort((a,b)=>a-b);}
function lrtMesh(){const g=new THREE.Group();const L=13.9;
  const [c,gx]=cvs(1024,128);gx.fillStyle='#f3f3ef';gx.fillRect(0,0,1024,128);gx.fillStyle='#1d2730';gx.fillRect(0,26,1024,52);for(let x=40;x<1000;x+=84){gx.fillStyle='#e9e9e4';gx.fillRect(x,26,6,52);}
  for(const dx of [230,700]){gx.fillStyle='#cfd2d4';gx.fillRect(dx,18,96,96);gx.fillStyle='#1d2730';gx.fillRect(dx+8,26,36,62);gx.fillRect(dx+52,26,36,62);}
  gx.fillStyle='#f39800';gx.fillRect(0,86,1024,10);gx.fillStyle='#d7261e';gx.fillRect(0,97,1024,4);gx.fillStyle='#4a4f55';gx.fillRect(0,113,1024,15);
  const st=ctex(c);st.repeat.set(1/L,1/3.1);st.offset.set(0,-.45/3.1);const sideM=new THREE.MeshStandardMaterial({map:st,roughness:.35,metalness:.15}),shellM=std('#f0f0ec',.4,.15);
  const sh=new THREE.Shape();sh.moveTo(0,.45);sh.lineTo(L-.35,.45);sh.lineTo(L,.95);sh.lineTo(L,1.75);sh.lineTo(L-.5,3.3);sh.lineTo(L-.95,3.55);sh.lineTo(0,3.55);sh.closePath();
  const geo=new THREE.ExtrudeGeometry(sh,{depth:2.65,bevelEnabled:false});geo.translate(0,0,-1.325);
  for(const s of [1,-1]){const car=new THREE.Group();car.scale.x=s;car.position.x=s*.12;g.add(car);const b=new THREE.Mesh(geo,[sideM,shellM]);b.castShadow=true;car.add(b);
    const pv=new THREE.Group();pv.position.set(L-.25,2.52,0);pv.rotation.z=Math.atan2(.5,1.55);car.add(pv);const ws=new THREE.Mesh(new THREE.PlaneGeometry(2.4,1.5),glassM);ws.rotation.y=Math.PI/2;ws.position.x=.02;pv.add(ws);
    const ds=new THREE.Mesh(new THREE.PlaneGeometry(1.5,.28),new THREE.MeshBasicMaterial({map:decalTex('610  元朗',{w:512,h:96,size:62,color:'#ff9a1f'}),toneMapped:false}));ds.rotation.y=Math.PI/2;ds.scale.x=s;ds.position.set(.03,.55,0);pv.add(ds);
    for(const z of [-.85,.85]){const hl=new THREE.Mesh(new THREE.BoxGeometry(.05,.16,.38),headM);hl.position.set(L+.01,1.25,z);car.add(hl);}
    const sk=new THREE.Mesh(new THREE.BoxGeometry(L-1.2,.4,2.3),std('#2a2e33',.6,.3));sk.position.set(L/2-.3,.3,0);car.add(sk);const ac=new THREE.Mesh(new THREE.BoxGeometry(2.6,.3,1.5),shellM);ac.position.set(L/2-.6,3.7,0);car.add(ac);}
  const outer=new THREE.Group();g.rotation.y=-Math.PI/2;outer.add(g);scene.add(outer);return outer;}
function spawnLrts(){if(!lrtPath)return;for(const [s,dir] of [[lrtPath.len*.3,1],[lrtPath.len*.7,-1]]){lrts.push({g:lrtMesh(),s,dir,speed:0,wait:0,last:-1,x:0,z:0,h:0});}}
function lrtUpdate(t,dt){const P=lrtPath;if(t.wait>0){t.wait-=dt;t.speed=0;}else{let want=11;for(const st of P.stops){const ahead=(st-t.s)*t.dir;if(st!==t.last&&ahead>0&&ahead<35)want=Math.min(want,Math.sqrt(2*1.1*Math.max(0,ahead-.3))+.3);if(st!==t.last&&Math.abs(ahead)<.6&&t.speed<1.3){t.wait=8;t.last=st;}}
    t.speed=want<t.speed?Math.max(want,t.speed-4*dt):lerp(t.speed,want,1-Math.exp(-1.5*dt));t.s+=t.dir*t.speed*dt;if(t.s>P.len-8){t.s=P.len-8;t.dir=-1;t.wait=6;t.last=-1;}if(t.s<8){t.s=8;t.dir=1;t.wait=6;t.last=-1;}}
  const q=posOn(P,t.s);const q2=posOn(P,t.s+t.dir*4);t.x=q.x;t.z=q.z;t.h=Math.atan2(q2.x-q.x,q2.z-q.z);t.g.position.set(q.x,.06,q.z);t.g.rotation.y=t.h;}

/* ---------- traffic on real roads ---------- */
const DRIVE=[];
function roadsNear(x,z,rad,filter){const out=[],seen=new Set();for(let i=Math.floor((x-rad)/GS);i<=Math.floor((x+rad)/GS);i++)for(let j=Math.floor((z-rad)/GS);j<=Math.floor((z+rad)/GS);j++){const L=RGRID.get(gk(i,j));if(!L)continue;for(const k of L){if(seen.has(k))continue;seen.add(k);const r=ROADS[k];if(filter(r))out.push(r);}}return out;}
function pickRoadNear(cx,cz,minD,maxD){const C=roadsNear(cx,cz,maxD,r=>r.cls<=3&&r.len>40);if(!C.length)return null;for(let tries=0;tries<40;tries++){const r=pick(C);const s=R(0,r.len);const q=posOn(r,s);const d=Math.hypot(q.x-cx,q.z-cz);if(d>minD&&d<maxD)return [r,s];}return null;}
function placeOnRoad(v,r,s){v.road=r;v.s=s;v.dir=r.oneway?1:(rnd()<.5?1:-1);v.lane=r.oneway?(r.w>8?pick([-1,1])*r.w/5:0):r.w/4;}
function spawnTraffic(cx,cz){for(const r of ROADS)if(r.cls<=3&&r.len>40)DRIVE.push(r);const colors=['#d9dcdf','#1d2a3a','#7a1f2b','#e7e3da','#2f4f3f','#3b3f46','#b8b9bb','#264d8c'];
  for(let i=0;i<(isMobile?24:40);i++){const rs=pickRoadNear(cx,cz,10,420);if(!rs)continue;const t=rnd();const type=t<.32?'taxi':t<.46?'minibus':t<.54?'bus':'car';const col=type==='taxi'?'#c8102e':type==='minibus'?(rnd()<.5?'#1a7f46':'#c8102e'):type==='bus'?'#d21f2a':pick(colors);
    const v=spawnVehicle(type,col,0,0,0,{ai:true,cruise:type==='bus'?9:R(10,13.5),speed:8});placeOnRoad(v,rs[0],rs[1]);}}
function trafficUpdate(v,dt){const r=v.road;const q=posOn(r,v.s);let fx=q.dx*v.dir,fz=q.dz*v.dir;
  let gap=1e9;for(const o of vehicles){if(o===v)continue;const dx=o.x-v.x,dz=o.z-v.z;const f=dx*fx+dz*fz;if(f<=0||f>40)continue;const lat=Math.abs(dx*fz-dz*fx);if(lat<2.2)gap=Math.min(gap,f-(o.L+v.L)/2);}
  if(!PLAYER.car&&!PLAYER.riding&&(PLAYER.y||0)<2){const dx=PLAYER.x-v.x,dz=PLAYER.z-v.z,f=dx*fx+dz*fz;if(f>-1&&f<24&&Math.abs(dx*fz-dz*fx)<2.6)gap=Math.min(gap,f-v.L/2-1.5);}else if(PLAYER.car&&PLAYER.car!==v){}
  for(const t of lrts){const dx=t.x-v.x,dz=t.z-v.z,f=dx*fx+dz*fz;if(f>0&&f<30&&Math.abs(dx*fz-dz*fx)<3)gap=Math.min(gap,f-v.L/2-8);}
  if(v.stuck>7){gap=1e9;v.stuck-=dt*3;}
  const want=Math.max(0,Math.min(v.cruise,(gap-3)*.9));const prev=v.speed;if(want<.3)v.stuck=(v.stuck||0)+dt;else if(v.stuck>0&&v.stuck<=7)v.stuck=Math.max(0,v.stuck-dt);v.speed=lerp(v.speed,want,1-Math.exp(-(want<v.speed?3.5:1.1)*dt));v.brakeOn=v.speed<prev-.02&&v.speed<v.cruise*.95;
  v.s+=v.dir*v.speed*dt;
  if(v.s<0||v.s>r.len){const end=v.s>r.len?r.pts[r.pts.length-1]:r.pts[0];let nx=null;for(const o of DRIVE){if(o===r||end[0]<o.x0||end[0]>o.x1||end[1]<o.z0||end[1]>o.z1)continue;const a=o.pts[0],b=o.pts[o.pts.length-1];if(Math.hypot(a[0]-end[0],a[1]-end[1])<3){nx=[o,0,1];if(rnd()<.6)break;}else if(!o.oneway&&Math.hypot(b[0]-end[0],b[1]-end[1])<3){nx=[o,o.len,-1];if(rnd()<.6)break;}}
    if(nx){v.road=nx[0];v.s=nx[1];v.dir=nx[2];v.lane=nx[0].oneway?(nx[0].w>8?pick([-1,1])*nx[0].w/5:0):nx[0].w/4;}else{const rs=pickRoadNear(cam.tx,cam.tz,140,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;}else{v.dir=-v.dir;v.s=clamp(v.s,0,r.len);}}}
  const p=posOn(v.road,v.s);fx=p.dx*v.dir;fz=p.dz*v.dir;const px=p.x+fz*v.lane,pz=p.z-fx*v.lane;
  const h=Math.atan2(fx,fz);if(v.x===0&&v.z===0){v.x=px;v.z=pz;v.h=h;}v.x=lerp(v.x,px,1-Math.exp(-6*dt));v.z=lerp(v.z,pz,1-Math.exp(-6*dt));v.h=lerpAngle(v.h,h,1-Math.exp(-7*dt));
  v.vx=fx*v.speed;v.vz=fz*v.speed;v.spin+=v.speed/v.wr*dt;v.pitch=lerp(v.pitch,(prev-v.speed)/Math.max(dt,1e-3)*.004,.1);v.y=TH(v.x,v.z);
  if(Math.hypot(v.x-cam.tx,v.z-cam.tz)>520){const rs=pickRoadNear(cam.tx,cam.tz,160,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;}}
  syncV(v);}

/* ---------- pedestrians on real footways ---------- */
const WALKS=[];const peds=[];
function spawnPeds(n,cx,cz){for(const r of ROADS)if((r.cls===7||r.cls===6)&&r.len>12){const m=posOn(r,r.len/2);if(inWB(m.x,m.z,20)&&!inCamp(m.x,m.z))WALKS.push(r);}const looks=()=>({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47','#222','#8e44ad','#f1c40f','#7f8c8d']),pants:pick(['#2b3550','#222','#5d4b3a','#3a4152','#6b6b6b']),long:rnd()<.4,bag:rnd()<.25?pick(['#c0392b','#1d4fa0','#333']):null});
  for(let i=0;i<n;i++){const p=person(looks());placePed(p,cx,cz,0,260);p.spd=R(1,1.5);peds.push(p);}}
function placePed(p,cx,cz,minD,maxD){for(let t=0;t<40;t++){const r=pick(WALKS);const s=R(0,r.len);const q=posOn(r,s);const d=Math.hypot(q.x-cx,q.z-cz);if(d>=minD&&d<maxD){p.road=r;p.s=s;p.dir=rnd()<.5?1:-1;p.off=R(-.5,.5);return;}}p.road=pick(WALKS);p.s=0;p.dir=1;p.off=0;}
function pedUpdate(p,dt){if(p.down>0){p.down-=dt;if(p.down<=0){p.g.rotation.x=0;p.g.position.y=0;p.hp=100;}return;}if(p.flee>0)p.flee-=dt;const r=p.road;p.s+=p.dir*p.spd*(p.flee>0?3.4:1)*dt;if(p.s>r.len){p.s=r.len;p.dir=-1;}if(p.s<0){p.s=0;p.dir=1;}const q=posOn(r,p.s);const x=q.x-q.dz*p.off,z=q.z+q.dx*p.off;
  const dx=x-camera.position.x,dz=z-camera.position.z,d2=dx*dx+dz*dz;if(d2>330*330){placePed(p,cam.tx,cam.tz,90,250);}p.g.visible=d2<200*200;if(!p.g.visible)return;
  p.g.position.set(x,TH(x,z)+.02,z);p.g.rotation.y=Math.atan2(q.dx*p.dir,q.dz*p.dir);animP(p,p.spd*(p.flee>0?3.4:1),dt);}

/* ---------- player ---------- */
const PLAYER={x:0,z:0,y:0,h:0,vx:0,vz:0,car:null,p:null,spd:0};
const keys={};let inp={x:0,y:0,run:false,hb:false};
function driveStep(v,dt){const fx=Math.sin(v.h),fz=Math.cos(v.h),rx=-fz,rz=fx;let fwd=v.vx*fx+v.vz*fz,lat=v.vx*rx+v.vz*rz;const thr=inp.y,str=-inp.x;
  const MAX=v.type==='bike'?9.5:v.type==='sports'?50:v.type==='taxi'?36:30,ACC=v.type==='bike'?6:v.type==='sports'?17:11;
  if(thr>0)fwd+=ACC*thr*dt*(1-Math.max(0,fwd)/MAX);else if(thr<0){if(fwd>.6)fwd-=22*dt*-thr;else fwd=Math.max(-9,fwd-7*dt*-thr);}else fwd-=Math.sign(fwd)*Math.min(Math.abs(fwd),2.2*dt);
  fwd-=fwd*Math.abs(fwd)*.0009*dt;if(inp.hb)fwd-=Math.sign(fwd)*Math.min(Math.abs(fwd),9*dt);
  const sMax=.62/(1+Math.abs(fwd)*.045);v.steer=lerp(v.steer,str*sMax,1-Math.exp(-9*dt));const yaw=fwd/2.7*Math.tan(v.steer)*(inp.hb?1.35:1);v.h+=yaw*dt;lat*=Math.exp(-(inp.hb?1.6:10)*dt);
  const nfx=Math.sin(v.h),nfz=Math.cos(v.h),nrx=-nfz,nrz=nfx;const pvx=v.vx,pvz=v.vz;v.vx=nfx*fwd+nrx*lat;v.vz=nfz*fwd+nrz*lat;v.x+=v.vx*dt;v.z+=v.vz*dt;v.speed=fwd;
  for(const off of [v.L*.28,-v.L*.28]){const c={x:v.x+nfx*off,z:v.z+nfz*off};const ox=c.x,oz=c.z;const h=pushOut(c,v.W*.55);if(h){v.x+=c.x-ox;v.z+=c.z-oz;const vn=v.vx*h.nx+v.vz*h.nz;if(vn<0){v.vx-=vn*h.nx*1.25;v.vz-=vn*h.nz*1.25;if(vn<-7)shake=Math.min(.5,-vn*.03);}}}
  for(const o of vehicles){if(o===v)continue;const dx=v.x-o.x,dz=v.z-o.z,d=Math.hypot(dx,dz),m=(v.W+o.W)/2+.5+Math.min(v.L,o.L)*.25;if(d<m&&d>0){const nx=dx/d,nz=dz/d;v.x+=nx*(m-d)*.7;v.z+=nz*(m-d)*.7;if(!o.ai){o.x-=nx*(m-d)*.3;o.z-=nz*(m-d)*.3;}const vn=v.vx*nx+v.vz*nz;if(vn<0){v.vx-=vn*nx*1.3;v.vz-=vn*nz*1.3;if(vn<-6)shake=Math.min(.5,-vn*.03);if(o.ai)o.speed*=.3;}}}
  for(const t of lrts){const dx=v.x-t.x,dz=v.z-t.z;const f=Math.abs(dx*Math.sin(t.h)+dz*Math.cos(t.h)),l=dx*Math.cos(t.h)-dz*Math.sin(t.h);if(f<15&&Math.abs(l)<2.4){const s=Math.sign(l)||1;const push=2.4-Math.abs(l);v.x+=Math.cos(t.h)*push*s;v.z-=Math.sin(t.h)*push*s;}}
  const al=((v.vx-pvx)*fx+(v.vz-pvz)*fz)/dt;v.roll=lerp(v.roll,clamp(-yaw*fwd*.006,-.09,.09),1-Math.exp(-6*dt));v.pitch=lerp(v.pitch,clamp(-al*.006,-.06,.06),1-Math.exp(-5*dt));
  v.spin+=fwd/v.wr*dt;v.y=TH(v.x,v.z);v.brakeOn=thr<0&&fwd>.5||inp.hb;}
function walkStep(dt){const p=PLAYER;let mx=0,mz=0;if(inp.x||inp.y){const fx=-Math.sin(cam.yaw),fz=-Math.cos(cam.yaw),rx=Math.cos(cam.yaw),rz=-Math.sin(cam.yaw);mx=fx*inp.y+rx*inp.x;mz=fz*inp.y+rz*inp.x;const l=Math.hypot(mx,mz);if(l>1){mx/=l;mz/=l;}}
  const sp=inp.run?7.6:3.9;p.vx=lerp(p.vx,mx*sp,1-Math.exp(-12*dt));p.vz=lerp(p.vz,mz*sp,1-Math.exp(-12*dt));p.x+=p.vx*dt;p.z+=p.vz*dt;pushOut(p,.35,(p.top||p.plat)?99:0);
  for(const v of vehicles){const dx=p.x-v.x,dz=p.z-v.z,d=Math.hypot(dx,dz),m=v.W/2+.35+v.L*.18;if(d<m&&d>0){p.x=v.x+dx/d*m;p.z=v.z+dz/d*m;}}
  p.spd=Math.hypot(p.vx,p.vz);if(p.spd>.2)p.h=lerpAngle(p.h,Math.atan2(p.vx,p.vz),1-Math.exp(-12*dt));platformConstrain();p.y=playerGround(p);}
function lerpAngle(a,b,t){return a+angDiff(a,b)*t;}
let myTaxi=null;
function nearCar(){let best=null,bd=4.2;for(const v of vehicles){if(v.ai&&v.speed>1)continue;const d=Math.hypot(v.x-PLAYER.x,v.z-PLAYER.z);if(d<bd){bd=d;best=v;}}return best;}
function actCar(){if(PLAYER.car){const v=PLAYER.car;if(Math.abs(v.speed)>6){toast('揸慢啲先落車');return;}const s=Math.sin(v.h),c=Math.cos(v.h);PLAYER.x=v.x-c*(v.W/2+.8);PLAYER.z=v.z+s*(v.W/2+.8);pushOut(PLAYER,.35);PLAYER.car=null;PLAYER.p.g.visible=true;v.speed=0;setHud();return;}
  const v=nearCar();if(!v)return;if(v.ai){v.ai=false;v.speed=0;v.vx=v.vz=0;toast('搶車！司機嚇到彈開');}PLAYER.car=v;PLAYER.p.g.visible=false;cam.lastDrag=-1e9;setHud();}

/* ---------- camera ---------- */
const cam={yaw:0,pitch:.24,tx:0,ty:1.6,tz:0,lastDrag:-1e9,cd:7,zoom:1};let shake=0;
function camUpdate(dt){const car=!!PLAYER.car;const tgt=PLAYER.car||PLAYER;const sp=car?Math.hypot(PLAYER.car.vx,PLAYER.car.vz):0;
  const lx=car?PLAYER.car.vx*.18:0,lz=car?PLAYER.car.vz*.18:0;const ty=car?PLAYER.car.y+1.6:(PLAYER.y||0)+1.55;if(curRoom)cam.pitch=Math.max(cam.pitch,.6);const k=1-Math.exp(-(car?7:12)*dt);cam.tx=lerp(cam.tx,tgt.x+lx,k);cam.tz=lerp(cam.tz,tgt.z+lz,k);cam.ty=lerp(cam.ty,ty,k);
  if(car&&performance.now()-cam.lastDrag>1300&&sp>2.5){const back=Math.atan2(PLAYER.car.vx,PLAYER.car.vz)+Math.PI;cam.yaw=lerpAngle(cam.yaw,PLAYER.car.speed<0?PLAYER.car.h:back,1-Math.exp(-2.4*dt));cam.pitch=lerp(cam.pitch,.2,1-Math.exp(-1.5*dt));}
  const want=Math.min((car?8.6+sp*.06:6.2)*cam.zoom,curRoom?8:999);let d=want;const dx=Math.sin(cam.yaw)*Math.cos(cam.pitch),dy=Math.sin(cam.pitch),dz=Math.cos(cam.yaw)*Math.cos(cam.pitch);
  for(let s=.6;s<want&&!cam.noCol;s+=.45){if(solidAt(cam.tx+dx*s,cam.ty+dy*s,cam.tz+dz*s)){d=Math.max(1.2,s-.45);break;}}
  cam.cd=d<cam.cd?d:lerp(cam.cd,d,1-Math.exp(-3*dt));{const px=cam.tx+dx*cam.cd,pz=cam.tz+dz*cam.cd;camera.position.set(px,Math.max(cam.ty+dy*cam.cd,TH(px,pz)+.6),pz);}
  if(shake>0){shake=Math.max(0,shake-dt);camera.position.x+=R(-1,1)*shake*.4;camera.position.y+=R(-1,1)*shake*.4;}
  camera.lookAt(cam.tx,cam.ty,cam.tz);const fov=55+clamp(sp,0,36)*.42;if(Math.abs(camera.fov-fov)>.05){camera.fov=lerp(camera.fov,fov,1-Math.exp(-4*dt));camera.updateProjectionMatrix();}
  sky.position.copy(camera.position);stars.position.copy(camera.position);}

/* ---------- time of day ---------- */
const TOD={
  day:{el:55,az:-.7,sun:'#fff1dc',si:2.7,hs:'#bcd8ff',hg:'#8c7d68',hi:1.05,top:'#3a7cd0',hor:'#cfe2f0',fog:'#c8d9e6',fn:90,ff:640,exp:.8,bloom:.12,neon:.3,win:0,lamp:0,pool:0,shop:.12,head:0,stars:0,ss:1,tl:2.2},
  dusk:{el:8,az:-1.2,sun:'#ffa45a',si:4.4,hs:'#8f98d8',hg:'#4a3a40',hi:.62,top:'#2a4590',hor:'#ff9e66',fog:'#d6957f',fn:80,ff:620,exp:1.05,bloom:.55,neon:2.2,win:.75,lamp:1.6,pool:.5,shop:1.1,head:1.5,stars:0,ss:1.3,tl:3},
  night:{el:36,az:2.3,sun:'#8ea6ff',si:.2,hs:'#4a5f9e',hg:'#2a221c',hi:.62,top:'#030817',hor:'#17244a',fog:'#121a33',fn:40,ff:440,exp:1.2,bloom:.95,neon:5.5,win:1.6,lamp:5,pool:1.25,shop:2.2,head:3,stars:1,ss:.25,tl:4}};
const C=(h)=>lin(h);const cur={};let todFrom=null,todTo=null,todT=1,todName='dusk';
function snap(p){return {el:p.el,az:p.az,sun:C(p.sun),si:p.si,hs:C(p.hs),hg:C(p.hg),hi:p.hi,top:C(p.top),hor:C(p.hor),fog:C(p.fog),fn:p.fn,ff:p.ff,exp:p.exp,bloom:p.bloom,neon:p.neon,win:p.win,lamp:p.lamp,pool:p.pool,shop:p.shop,head:p.head,stars:p.stars,ss:p.ss,tl:p.tl};}
function setTod(n,instant){todName=n;todFrom=Object.assign({},cur.el!=null?cur:snap(TOD[n]));for(const k in todFrom)if(todFrom[k]&&todFrom[k].isColor)todFrom[k]=todFrom[k].clone();todTo=snap(TOD[n]);todT=instant?1:0;
  for(const [id,k] of [['#tDay','day'],['#tDusk','dusk'],['#tNight','night']])$(id).setAttribute('aria-pressed',String(k===n));applyTod(instant?1:0);envDirty=true;}
let envDirty=true;
function applyTod(t){const e=t*t*(3-2*t);for(const k in todTo){const a=todFrom[k],b=todTo[k];if(b&&b.isColor){cur[k]=(cur[k]&&cur[k].isColor?cur[k]:new THREE.Color()).copy(a).lerp(b,e);}else cur[k]=lerp(a,b,e);}
  const el=cur.el*Math.PI/180;const dir=new THREE.Vector3(Math.cos(el)*Math.sin(cur.az),Math.sin(el),Math.cos(el)*Math.cos(cur.az));
  sun.userData.dir=dir;sun.color.copy(cur.sun);sun.intensity=cur.si;hemi.color.copy(cur.hs);hemi.groundColor.copy(cur.hg);hemi.intensity=cur.hi;
  skyU.top.value.copy(cur.top);skyU.hor.value.copy(cur.hor);skyU.sunC.value.copy(cur.sun);skyU.sunDir.value.copy(dir);skyU.sunSize.value=cur.ss;
  scene.fog.color.copy(cur.fog);scene.fog.near=cur.fn;scene.fog.far=cur.ff;renderer.toneMappingExposure=cur.exp;if(finalPass)finalPass.uniforms.exposure.value=cur.exp;if(bloom)bloom.strength=cur.bloom;
  if(TX.signMat)TX.signMat.emissiveIntensity=cur.neon;if(TX.shopMat)TX.shopMat.emissiveIntensity=cur.shop;for(const m of WIN_MATS)m.emissiveIntensity=cur.win;
  if(lampHeadMat)lampHeadMat.emissiveIntensity=cur.lamp;if(poolMat)poolMat.opacity=cur.pool;headM.emissiveIntensity=cur.head;tailM.emissiveIntensity=cur.head*.8;stars.material.opacity=cur.stars;
  scene.traverse(o=>{if(o.isMesh&&o.userData.taxiSign)o.material.emissiveIntensity=cur.head+.4;});
  if(headSpot){headSpot.intensity=cur.head*9;}}

/* ---------- HUD & input ---------- */
let toastT=0;function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');toastT=2.4;}
function setHud(){$('#speedo').style.opacity=PLAYER.car?1:0;$('#tAct').textContent=PLAYER.car?'落車':'上車';$('#tRun').textContent=PLAYER.car?'手掣':'跑';}
addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyE'||e.code==='Enter')act();if(e.code==='Digit1')setTod('day');if(e.code==='Digit2')setTod('dusk');if(e.code==='Digit3')setTod('night');if(e.code==='Space')e.preventDefault();});
addEventListener('keyup',e=>{keys[e.code]=false;});addEventListener('blur',()=>{for(const k in keys)keys[k]=false;});
let drag=null;
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&e.clientX<innerWidth*.4)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};try{canvas.setPointerCapture(e.pointerId);}catch(_){}});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;cam.yaw-=(e.clientX-drag.x)*.006;cam.pitch=clamp(cam.pitch+(e.clientY-drag.y)*.004,-.15,1.2);drag.x=e.clientX;drag.y=e.clientY;cam.lastDrag=performance.now();});
const endDrag=e=>{if(drag&&drag.id===e.pointerId)drag=null;};canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
canvas.addEventListener('wheel',e=>{cam.zoom=clamp(cam.zoom*(e.deltaY>0?1.1:.9),.55,2.4);e.preventDefault();},{passive:false});
const joy=$('#joy'),knob=$('#knob');let joyId=null,joyV={x:0,y:0},tRun=false;
joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;try{joy.setPointerCapture(e.pointerId);}catch(_){}moveJoy(e);});
joy.addEventListener('pointermove',e=>{if(e.pointerId===joyId)moveJoy(e);});
const endJoy=e=>{if(e.pointerId!==joyId)return;joyId=null;joyV={x:0,y:0};knob.style.transform='';};joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy);
function moveJoy(e){const r=joy.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2);const l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}joyV={x,y:-y};knob.style.transform=`translate(${x*36}px,${y*36}px)`;}
$('#tAct').addEventListener('pointerdown',e=>{e.preventDefault();act();});
{const b=$('#tRun');b.addEventListener('pointerdown',e=>{e.preventDefault();tRun=true;b.classList.add('on');});const up=()=>{tRun=false;b.classList.remove('on');};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up);}
function readInput(){let x=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),y=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0);if(joyId!==null){x=joyV.x;y=joyV.y;}
  inp.x=clamp(x,-1,1);inp.y=clamp(y,-1,1);inp.run=!!(keys.ShiftLeft||keys.ShiftRight)||(!PLAYER.car&&tRun);inp.hb=!!keys.Space||(!!PLAYER.car&&tRun);}
$('#tDay').onclick=()=>setTod('day');$('#tDusk').onclick=()=>setTod('dusk');$('#tNight').onclick=()=>setTod('night');
$('#tQual').onclick=()=>{quality=quality?0:1;$('#tQual').textContent='畫質：'+(quality?'高':'慳電');renderer.setPixelRatio(Math.min(devicePixelRatio,quality?1.75:1.25));renderer.setSize(innerWidth,innerHeight);sun.shadow.mapSize.set(quality?2048:1024,quality?2048:1024);if(sun.shadow.map){sun.shadow.map.dispose();sun.shadow.map=null;}setupPost();applyTod(1);};
