  missionUpdate(dt);fightUpdate(dt);pursuitUpdate(dt);skewTick(dt);roomsUpdate(dt);trainUpdate(dt);platformPeople(dt);v3Update(dt);{const hid=curRoom||PLAYER.dress?'hidden':'';const mi=$('#mini');if(mi.style.visibility!==hid)mi.style.visibility=hid;}
