  for(const n of Object.values(NPC)){if(!n.g||!n.g.visible||n===NPC.box)continue;const d=Math.hypot(PLAYER.x-n.g.position.x,PLAYER.z-n.g.position.z);if(d<10)n.g.rotation.y=lerpAngle(n.g.rotation.y,Math.atan2(PLAYER.x-n.g.position.x,PLAYER.z-n.g.position.z),.1);}
  {const gl=cur.lamp>.5?1.2:cur.lamp>.1?.6:.15;for(const m of GLOW)m.emissiveIntensity=gl;}
