  PLAYER.x=spot.x;PLAYER.z=spot.z;PLAYER.y=spot.y!=null?spot.y:TH(spot.x,spot.z);pushOut(PLAYER,.4,PLAYER.y);cam.tx=PLAYER.x;cam.tz=PLAYER.z;if(S.m===0)goHome(true);
