/* ---------- terrain hills (Yuen Long Park, Pok Oi Hospital) ---------- */
const HILLS=[];
(function(){const tw=D.b.find(b=>b[2]===2);let tx=-1092,tz=284;if(tw){const f=tw[3];let sx=0,sz=0,n=0;for(let i=0;i<f.length;i+=2){sx+=f[i];sz+=f[i+1];n++;}tx=sx/n;tz=sz/n;}
  HILLS.push({x:tx,z:tz+8,rx:132,rz:176,peak:20,grass:false});})();
function TH(x,z){let y=0;for(const h of HILLS){const dx=(x-h.x)/h.rx,dz=(z-h.z)/h.rz,d2=dx*dx+dz*dz;if(d2<1){const d=Math.sqrt(d2);y+=h.peak*(.5+.5*Math.cos(Math.PI*d));}}return y;}
let RIBH=true;
function buildHills(){const nm=(()=>{const [c,g]=cvs(256,256);noiseFill(g,256,256,'#c9c9c9',7000,.04,.14,3);return ctex(c,true);})();
  const mat=new THREE.MeshStandardMaterial({map:nm,vertexColors:true,roughness:1,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});
  const parks=D.park.map(flat2),cg=lin('#5f8a43'),cc=lin('#8f8d84'),cl=new THREE.Color();
  for(const h of HILLS){const st=5,nx=Math.ceil(2*h.rx/st),nz=Math.ceil(2*h.rz/st);const pos=[],col=[],uv=[],idx=[];
    for(let j=0;j<=nz;j++)for(let i=0;i<=nx;i++){const x=h.x-h.rx+i*st,z=h.z-h.rz+j*st;pos.push(x,TH(x,z)-.03,z);uv.push(x/6,-z/6);cl.copy(h.grass||parks.some(p=>inPoly(x,z,p))?cg:cc);col.push(cl.r,cl.g,cl.b);}
    const V=(i,j)=>j*(nx+1)+i;for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){const a=V(i,j),b=V(i+1,j),c=V(i+1,j+1),d=V(i,j+1);if(pos[a*3+1]<.08&&pos[b*3+1]<.08&&pos[c*3+1]<.08&&pos[d*3+1]<.08)continue;idx.push(a,d,c,a,c,b);}
    const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();
    const m=new THREE.Mesh(g,mat);m.receiveShadow=true;scene.add(m);}}
function playerGround(p){if(p.plat)return PLAT_Y;if(p.top)return TOWER_TOP_Y;return TH(p.x,p.z);}
