/* ---------- shop faces: reserve Man Kee and banks before drawing ---------- */
let GATE=null,WKF=null;const BANKF=[],SIGNPTS=[];
function computeGate(){const sch=D.lab.find(l=>l[0]==='趙聿修紀念中學')||[0,D.spawn[0],D.spawn[1]];const nr=nearestRoad(sch[1],sch[2],120,r=>r.name==='元朗體育路'&&r.cls<=4)||nearestRoad(sch[1],sch[2],200,r=>r.cls<=4);
  if(!nr){GATE={x:D.spawn[0],z:D.spawn[1],rd:[0,1],nr:null};return;}const rd=nr.dir;const nx=-rd[1],nz=rd[0];const side=((sch[1]-nr.x)*nx+(sch[2]-nr.z)*nz)>0?1:-1;GATE={x:nr.x+nx*side*(nr.r.w/2+2.2),z:nr.z+nz*side*(nr.r.w/2+2.2),rd,nr,side,nx,nz};}
function reserveFaces(){const gx=GATE.x,gz=GATE.z;const cand=SHOPF.filter(f=>f.L>=5&&f.L<=22&&f.h>=6).map(f=>[f,Math.hypot(f.x-gx,f.z-gz)]).filter(q=>q[1]>25).sort((a,b)=>a[1]-b[1]);if(cand.length){WKF=cand[0][0];WKF.reserved='wk';}
  const main=SHOPF.filter(f=>!f.reserved&&f.L>=8&&f.L<=26&&f.h>=8&&f.cls<=1).sort((a,b)=>b.L-a.L);for(const f of main){if(BANKF.length>=2)break;if(Math.hypot(f.x-gx,f.z-gz)<60)continue;if(BANKF.some(b=>Math.hypot(b.x-f.x,b.z-f.z)<220))continue;f.reserved='bank';BANKF.push(f);}}
function signFree(x,z,y0,y1,r=2.6){for(const s of SIGNPTS){if(Math.hypot(s[0]-x,s[1]-z)<r&&y0<s[3]+.3&&y1>s[2]-.3)return false;}return true;}
function drawShopFace(f){const {a,c,n,L,h,base}=f;const o=.11;const units=Math.max(1,Math.round(L/6)),k0=Math.floor(R(0,4)),row=Math.floor(R(0,8));const pa=[a[0]+n[0]*o,a[1]+n[2]*o],pc=[c[0]+n[0]*o,c[1]+n[2]*o];
  shopB.quad(pa,pc,base,base+Math.min(4.2,h),n,k0*.25,(k0+units)*.25,1-(row+1)/8,1-row/8);
  if(h<6)return;const d=1.3,ang=Math.atan2(c[0]-a[0],c[1]-a[1]);const cx=(a[0]+c[0])/2+n[0]*d/2,cz=(a[1]+c[1])/2+n[2]*d/2;detailB.geo(new THREE.BoxGeometry(d,.2,Math.max(.5,L-.5)),new THREE.Matrix4().makeRotationY(ang).setPosition(cx,base+4.25,cz));
  if(f.signs){const tg=[n[2],0,-n[0]];const slots=Math.floor((L-2)/2.6);const used=[];for(let k=0;k<slots;k++){if(rnd()>.42)continue;const t=(1+k*2.6+1.3)/L;if(t<.08||t>.92)continue;const vert=rnd()<.6,cell=vert?pick(SIGNS.v):pick(SIGNS.h);const W=vert?1.2:2.9,HH=vert?4.6:1;const out=.45;
      const y0=base+(vert?R(5.2,Math.max(5.3,Math.min(h-5.4,18))):R(5.2,Math.max(5.3,Math.min(h-2,20))));const px=lerp(a[0],c[0],t),pz=lerp(a[1],c[1],t);const mx=px+n[0]*(out+W/2),mz=pz+n[2]*(out+W/2);
      if(!signFree(mx,mz,y0,y0+HH))continue;SIGNPTS.push([mx,mz,y0,y0+HH]);const p0=[px+n[0]*out,pz+n[2]*out],p1=[px+n[0]*(out+W),pz+n[2]*(out+W)];
      signB.quad(p0,p1,y0,y0+HH,tg,cell[0],cell[1],cell[2],cell[3]);signB.quad(p0,p1,y0,y0+HH,[-tg[0],0,-tg[2]],cell[0],cell[1],cell[2],cell[3]);
      detailB.geo(new THREE.BoxGeometry(out,.06,.06),new THREE.Matrix4().makeRotationY(Math.atan2(n[0],n[2])+Math.PI/2).setPosition(px+n[0]*out/2,y0+HH-.3,pz+n[2]*out/2));}}
  const nAC=Math.floor(L/3.4*(h-4.2)/3*.22);for(let i=0;i<nAC;i++){const t=R(.08,.92),fl=Math.floor(R(0,(h-6)/3));const x=lerp(a[0],c[0],t)+n[0]*.25,z=lerp(a[1],c[1],t)+n[2]*.25,y=base+6+fl*3;if(!signFree(x,z,y-.3,y+.3,1.6))continue;put('ac',x,y,z,Math.atan2(n[0],n[2]));}}
function facePanel(f,tex,emi,h=4.2,out=.12){const {a,c,n,base}=f;const pa=[a[0]+n[0]*out,a[1]+n[2]*out],pc=[c[0]+n[0]*out,c[1]+n[2]*out];const B=new Batch();B.quad(pa,pc,base,base+h,n,0,1,0,1);
  const m=new THREE.MeshStandardMaterial({map:tex,emissiveMap:emi||null,emissive:emi?new THREE.Color(1,1,1):new THREE.Color(0,0,0),emissiveIntensity:emi?1:0,roughness:.5});if(emi)GLOW.push(m);return B.mesh(m,false);}
function wenKeeFront(f){const W=Math.min(2048,Math.round(f.L*80)),Hh=336;const [c,g]=cvs(W,Hh),[e,ge]=cvs(W,Hh);ge.fillStyle='#000';ge.fillRect(0,0,W,Hh);
  g.fillStyle='#b3121f';g.fillRect(0,0,W,96);g.fillStyle='#ffe9a8';g.font=`900 70px ${FSERIF}`;g.textAlign='center';g.textBaseline='middle';g.fillText('文記家庭用品',W/2,52,W-40);g.fillStyle='#f6d23a';g.fillRect(0,92,W,6);
  ge.fillStyle='#ffe9a8';ge.font=g.font;ge.textAlign='center';ge.textBaseline='middle';ge.fillText('文記家庭用品',W/2,52,W-40);
  g.fillStyle='#2a1f16';g.fillRect(0,98,W,238);g.fillStyle='#f3e6c8';g.fillRect(14,110,W-28,226);ge.globalAlpha=.55;ge.fillStyle='#f3e6c8';ge.fillRect(14,110,W-28,226);ge.globalAlpha=1;
  const items=['#c0392b','#2e86de','#f1c40f','#27ae60','#e67e22','#8e44ad','#95a5a6','#d35400'];
  for(let x=24;x<W-30;x+=46){g.fillStyle='#6b4a2b';g.fillRect(x,118,2,40);const col=pick(items);g.fillStyle=col;g.beginPath();g.arc(x+1,170,14,0,TAU);g.fill();g.fillStyle='rgba(0,0,0,.2)';g.fillRect(x-12,166,26,4);}
  for(let y=210;y<330;y+=40){g.fillStyle='rgba(80,55,30,.6)';g.fillRect(20,y,W-40,5);for(let x=26;x<W-40;x+=24){g.fillStyle=pick(items);g.fillRect(x,y-22,R(12,20),22);}}
  g.fillStyle='#d8d2c4';g.fillRect(0,98,12,238);g.fillRect(W-12,98,12,238);const dx=W/2-60;g.fillStyle='rgba(30,22,16,.85)';g.fillRect(dx,230,120,106);ge.fillStyle='#000';ge.fillRect(dx,230,120,106);
  f.panel=facePanel(f,ctex(c),ctex(e));
  if(f.h>=6){const d=1.5,ang=Math.atan2(f.c[0]-f.a[0],f.c[1]-f.a[1]);const cx=(f.a[0]+f.c[0])/2+f.n[0]*d/2,cz=(f.a[1]+f.c[1])/2+f.n[2]*d/2;const aw=new THREE.Mesh(new THREE.BoxGeometry(d,.12,f.L-.3),std('#c8102e',.6));aw.position.set(cx,f.base+4.32,cz);aw.rotation.y=ang;aw.castShadow=true;scene.add(aw);}
  // goods on the pavement: buckets and brooms
  for(let k=0;k<5;k++){const t=R(.12,.88),x=lerp(f.a[0],f.c[0],t)+f.n[0]*1.1,z=lerp(f.a[1],f.c[1],t)+f.n[2]*1.1;const b=new THREE.Mesh(new THREE.CylinderGeometry(.22,.17,.36,10),std(pick(items),.6));b.position.set(x,f.base+.18,z);b.castShadow=true;scene.add(b);}}
function bankFront(f,i){const W=Math.min(2048,Math.round(f.L*80)),Hh=336;const [c,g]=cvs(W,Hh),[e,ge]=cvs(W,Hh);ge.fillStyle='#000';ge.fillRect(0,0,W,Hh);
  g.fillStyle='#0f2a52';g.fillRect(0,0,W,96);g.fillStyle='#ffffff';g.font=`900 60px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.fillText('元朗儲蓄銀行',W/2,44,W-40);g.font=`700 24px ${FS}`;g.fillStyle='#c9a227';g.fillText('YUEN LONG SAVINGS BANK',W/2,80,W-40);
  ge.fillStyle='#ffffff';ge.font=`900 60px ${FS}`;ge.textAlign='center';ge.textBaseline='middle';ge.fillText('元朗儲蓄銀行',W/2,44,W-40);
  g.fillStyle='#c9cdd2';g.fillRect(0,96,W,240);g.fillStyle='#1d2730';g.fillRect(20,110,W-40,226);g.fillStyle='rgba(220,235,245,.25)';for(let x=24;x<W-30;x+=90)g.fillRect(x,114,40,218);
  g.fillStyle='#c9cdd2';for(let x=20;x<W-20;x+=180)g.fillRect(x,110,8,226);ge.globalAlpha=.7;ge.fillStyle='#e9f2ff';ge.fillRect(20,110,W-40,226);ge.globalAlpha=1;
  const atx=W-150;g.fillStyle='#0f2a52';g.fillRect(atx,150,110,170);g.fillStyle='#7fd1ff';g.fillRect(atx+20,170,70,50);ge.fillStyle='#7fd1ff';ge.fillRect(atx+20,170,70,50);
  f.panel=facePanel(f,ctex(c),ctex(e));}

/* ---------- interiors ---------- */
const ROOMS={};let curRoom=null,roomBase=6000;
function roomFloorTex(a,b,s=8){const [c,g]=cvs(256,256);g.fillStyle=a;g.fillRect(0,0,256,256);const n=s;for(let y=0;y<n;y++)for(let x=0;x<n;x++){g.fillStyle=(x+y)%2?a:b;g.fillRect(x*256/n+1,y*256/n+1,256/n-2,256/n-2);}return ctex(c,true);}
function addSolid(x0,z0,x1,z1,h){const o={h,top:h,base:0,t:9,flag:0,pts:[[x0,z0],[x1,z0],[x1,z1],[x0,z1]],area:(x1-x0)*(z1-z0),x0,z0,x1,z1};const idx=BL.length;BL.push(o);gridAdd(GRID,o,idx);}
function makeRoom(id,o){const x0=roomBase,z0=0;roomBase+=320;const w=o.w,d=o.d,wh=o.wh||4.4;const r={id,name:o.name,x0,z0,x1:x0+w,z1:z0+d,w,d,inter:[],lights:[],people:[],cx:x0+w/2,cz:z0+d/2};
  const fl=new THREE.Mesh(new THREE.PlaneGeometry(w,d),new THREE.MeshStandardMaterial({map:o.floor,roughness:.35,metalness:.05}));o.floor.repeat.set(w/4,d/4);fl.rotation.x=-Math.PI/2;fl.position.set(r.cx,.01,r.cz);fl.receiveShadow=true;scene.add(fl);
  const wm=std(o.wall||'#ece8df',.8),sk=std(o.skirt||'#6b5236',.6);
  for(const [a,b,c2,d2] of [[x0-.3,z0-.3,x0+w+.3,z0],[x0-.3,z0+d,x0+w+.3,z0+d+.3],[x0-.3,z0,x0,z0+d],[x0+w,z0,x0+w+.3,z0+d]]){const m=new THREE.Mesh(new THREE.BoxGeometry(c2-a,wh,d2-b),wm);m.position.set((a+c2)/2,wh/2,(b+d2)/2);m.receiveShadow=true;scene.add(m);const k=new THREE.Mesh(new THREE.BoxGeometry(c2-a+.02,.5,d2-b+.02),sk);k.position.set((a+c2)/2,.25,(b+d2)/2);scene.add(k);addSolid(a,b,c2,d2,wh);}
  r.spawn={x:x0+w/2,z:z0+d-2.2,h:Math.PI};r.door={x:x0+w/2,z:z0+d-.8};
  const dm=new THREE.Mesh(new THREE.PlaneGeometry(3,2.6),std('#2a3036',.3,.4));dm.position.set(r.door.x,1.3,z0+d-.02);dm.rotation.y=Math.PI;scene.add(dm);const ex=textPlane('出口 EXIT',1.6,.45,{bg:'#1a7f46',fg:'#fff',glow:true,font:FS});ex.position.set(r.door.x,2.95,z0+d-.03);ex.rotation.y=Math.PI;scene.add(ex);
  r.inter.push({at:()=>r.door,r:2.2,label:'離開',ok:()=>curRoom===r,act:()=>exitRoom()});
  ROOMS[id]=r;return r;}
function roomBox(r,w,h,d,x,z,mat,solid=true,y=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(r.x0+x,y+h/2,r.z0+z);m.castShadow=true;m.receiveShadow=true;scene.add(m);if(solid)addSolid(r.x0+x-w/2,r.z0+z-d/2,r.x0+x+w/2,r.z0+z+d/2,y+h);return m;}
function roomSign(r,text,x,z,y,w,h,o,ry=0){const t=textPlane(text,w,h,o);t.position.set(r.x0+x,y,r.z0+z);t.rotation.y=ry;scene.add(t);return t;}
function roomPerson(r,p,x,z,h,walk){p.g.position.set(r.x0+x,0,r.z0+z);p.g.rotation.y=h;p.walk=walk;p.home=[r.x0+x,r.z0+z];p.tx=p.home[0];p.tz=p.home[1];p.wt=R(0,3);r.people.push(p);return p;}
function enterRoom(id,back){const r=ROOMS[id];if(!r)return;if(PLAYER.car){toast('落車先入得');return;}fadeTo(r.name,()=>{curRoom=r;PLAYER.back=back;PLAYER.x=r.spawn.x;PLAYER.z=r.spawn.z;PLAYER.y=0;PLAYER.h=r.spawn.h;PLAYER.vx=PLAYER.vz=0;cam.tx=PLAYER.x;cam.tz=PLAYER.z;cam.yaw=0;cam.pitch=.75;cam.cd=6;if(r.onEnter)r.onEnter();},900);}
function exitRoom(to){const b=to||PLAYER.back;fadeTo('',()=>{curRoom=null;PLAYER.plat=null;PLAYER.x=b.x;PLAYER.z=b.z;PLAYER.y=TH(b.x,b.z);PLAYER.h=b.h||0;cam.tx=b.x;cam.tz=b.z;cam.yaw=(b.h||0)+Math.PI;cam.pitch=.24;},700);}
function roomsUpdate(dt){if(!curRoom)return;const r=curRoom;PLAYER.x=clamp(PLAYER.x,r.x0+.5,r.x1-.5);PLAYER.z=clamp(PLAYER.z,r.z0+.5,r.z1-.5);
  for(const p of r.people){if(!p.walk){animP(p,0,dt);continue;}p.wt-=dt;if(p.wt<=0){p.wt=R(3,8);p.tx=clamp(p.home[0]+R(-8,8),r.x0+1.5,r.x1-1.5);p.tz=clamp(p.home[1]+R(-6,6),r.z0+1.5,r.z1-3);}
    const g=p.g,dx=p.tx-g.position.x,dz=p.tz-g.position.z,d=Math.hypot(dx,dz);let sp=0;if(d>.3){sp=1.2;const o={x:g.position.x+dx/d*sp*dt,z:g.position.z+dz/d*sp*dt};pushOut(o,.35);g.position.x=o.x;g.position.z=o.z;g.rotation.y=Math.atan2(dx,dz);}animP(p,sp,dt);}
  lampLights.forEach((L,i)=>{const p=r.lights[i];if(!p){L.intensity=0;return;}L.position.set(p[0],3.9,p[1]);L.intensity=.45;});}
function buildBank(){const r=makeRoom('bank',{name:'元朗儲蓄銀行',w:24,d:16,floor:roomFloorTex('#b9ab94','#a89a82',6),wall:'#cfc6b4',skirt:'#5a3d26'});
  const wood=std('#7a5232',.5),glass=new THREE.MeshStandardMaterial({color:lin('#cfe6ee'),transparent:true,opacity:.25,roughness:.05,depthWrite:false});
  roomBox(r,18,1.15,1.1,12,3.2,wood);const gl=new THREE.Mesh(new THREE.BoxGeometry(18,1.2,.04),glass);gl.position.set(r.x0+12,1.8,r.z0+2.7);scene.add(gl);
  for(let i=0;i<5;i++){roomBox(r,.06,1.2,1.1,3+i*4.5,3.2,std('#c9ccd0',.3,.8),false,1.15);}
  roomSign(r,'元朗儲蓄銀行',12,.32,3.4,8,1.1,{bg:'#0f2a52',fg:'#ffffff',glow:true,font:FS});roomSign(r,'YUEN LONG SAVINGS BANK',12,.33,2.65,6,.35,{bg:'#0f2a52',fg:'#c9a227',font:FS});
  for(let i=0;i<4;i++){const t=npc('櫃位職員',{shirt:'#f4f4f0',pants:'#2a2f3a'},r.x0+5+i*4.5,r.z0+1.9,0,'#7ec8ff',i===0);roomPerson(r,t,5+i*4.5,1.9,0,false);}
  for(const x of [2.5,21.5]){roomBox(r,1,1.9,.6,x,.6,std('#0f2a52',.4,.2));const sc=new THREE.Mesh(new THREE.PlaneGeometry(.6,.4),new THREE.MeshBasicMaterial({color:0x7fd1ff,toneMapped:false}));sc.position.set(r.x0+x,1.4,r.z0+.92);scene.add(sc);roomSign(r,'ATM',x,.92,2.05,.6,.22,{bg:'#c9a227',fg:'#0f2a52',font:FS});}
  for(let k=0;k<6;k++){const p=new THREE.Mesh(new THREE.CylinderGeometry(.05,.07,1,8),std('#c9a227',.3,.8));p.position.set(r.x0+9+k*1.4,.5,r.z0+7);scene.add(p);}
  const rope=new THREE.Mesh(new THREE.BoxGeometry(7,.05,.05),std('#7a1f2b',.6));rope.position.set(r.x0+12.5,.9,r.z0+7);scene.add(rope);
  for(const x of [5,19]){roomBox(r,3.6,.45,.9,x,12,std('#3a4a5e',.7));}
  for(let i=0;i<3;i++){const c=npc('客',{shirt:pick(['#c0392b','#2e86de','#7f8c8d']),pants:'#333'},0,0,0,'#ccc',false);roomPerson(r,c,10+i*1.3,8,Math.PI,false);}
  const g=npc('護衛員',{shirt:'#2f3a4f',pants:'#2f3a4f'},0,0,0,'#9cc8ff');addCap(g,'#111');roomPerson(r,g,20,13.5,Math.PI*.8,false);
  r.lights=[[r.x0+6,r.z0+5],[r.x0+18,r.z0+5],[r.x0+12,r.z0+11]];
  r.inter.push({at:()=>({x:r.x0+12,z:r.z0+4.6}),r:3.4,label:'櫃位：存錢／提錢',ok:()=>curRoom===r,act:bankCounter});
  r.inter.push({at:()=>({x:r.x0+2.5,z:r.z0+1.6}),r:1.8,label:'用櫃員機（提 $200）',ok:()=>curRoom===r,act:()=>{if((S.bank||0)>=200){S.bank-=200;addMoney(200,true);toast('提咗 $200，戶口仲有 $'+S.bank);}else toast('戶口唔夠錢（結餘 $'+(S.bank||0)+'）');save();}});}
function bankCounter(){ask('櫃位職員',`你好！戶口結餘：$${S.bank||0}，你身上現金：$${S.money}。存咗入銀行嘅錢，暈低或者俾人拉都唔會唔見。`,['存晒現金','提 $500','提晒','唔使喇'],k=>{
  if(k===0){if(S.money<=0){toast('你冇現金');return;}S.bank=(S.bank||0)+S.money;S.money=0;toast('存咗入戶口，結餘 $'+S.bank);}
  else if(k===1){const v=Math.min(500,S.bank||0);if(!v){toast('戶口冇錢');return;}S.bank-=v;S.money+=v;toast('提咗 $'+v);}
  else if(k===2){const v=S.bank||0;if(!v){toast('戶口冇錢');return;}S.bank=0;S.money+=v;toast('提咗 $'+v);}save();});}
function buildMall(){const r=makeRoom('mall',{name:'形點 YOHO MALL',w:46,d:32,floor:roomFloorTex('#bdb7ad','#ada79c',4),wall:'#d6d1c7',skirt:'#8b8476',wh:10});
  const bandB=new Batch(),x0=r.x0,z0=r.z0,w=r.w,d=r.d;const rowOf=()=>Math.floor(R(0,8));
  const wallBand=(a,b,n,y)=>{const L=Math.hypot(b[0]-a[0],b[1]-a[1]);const u=Math.max(1,Math.round(L/6)),k0=Math.floor(R(0,4)),row=rowOf();bandB.quad(a,b,y,y+4.2,n,k0*.25,(k0+u)*.25,1-(row+1)/8,1-row/8);};
  for(const y of [0,5.4]){wallBand([x0+.05,z0+.05],[x0+w-.05,z0+.05],[0,0,1],y);wallBand([x0+.05,z0+d-.05],[x0+w/2-3,z0+d-.05],[0,0,-1],y);wallBand([x0+w/2+3,z0+d-.05],[x0+w-.05,z0+d-.05],[0,0,-1],y);wallBand([x0+.05,z0+.05],[x0+.05,z0+d-.05],[1,0,0],y);wallBand([x0+w-.05,z0+.05],[x0+w-.05,z0+d-.05],[-1,0,0],y);}
  bandB.mesh(TX.shopMat,false);
  const slab=std('#e6e2da',.6);for(const [a,b,c2,d2] of [[0,0,w,3.2],[0,d-3.2,w,d],[0,0,3.2,d],[w-3.2,0,w,d]]){const m=new THREE.Mesh(new THREE.BoxGeometry(c2-a,.35,d2-b),slab);m.position.set(x0+(a+c2)/2,5.2,z0+(b+d2)/2);m.castShadow=true;scene.add(m);}
  const gl=new THREE.MeshStandardMaterial({color:lin('#cfe6ee'),transparent:true,opacity:.3,roughness:.05,depthWrite:false});for(const [a,b,c2,d2] of [[3.2,3.2,w-3.2,3.3],[3.2,d-3.3,w-3.2,d-3.2],[3.2,3.2,3.3,d-3.2],[w-3.3,3.2,w-3.2,d-3.2]]){const m=new THREE.Mesh(new THREE.BoxGeometry(c2-a,1.05,d2-b),gl);m.position.set(x0+(a+c2)/2,5.9,z0+(b+d2)/2);scene.add(m);}
  for(const s of [-1,1]){const esc=new THREE.Mesh(new THREE.BoxGeometry(1.4,.4,9),std('#c9ccd0',.3,.8));esc.position.set(x0+w/2+s*2.2,2.7,z0+d/2);esc.rotation.x=s*.53;esc.castShadow=true;scene.add(esc);addSolid(x0+w/2+s*2.2-.8,z0+d/2-4.5,x0+w/2+s*2.2+.8,z0+d/2+4.5,1.2);}
  roomBox(r,4,.8,4,10,16,std('#6a8a5a',.9));for(let k=0;k<3;k++){const t=new THREE.Mesh(new THREE.IcosahedronGeometry(1,1),std('#3f7d3a',.8,0,{flatShading:true}));t.position.set(x0+9+k,1.6,z0+15.5+(k%2));scene.add(t);}
  roomSign(r,'形點 YOHO MALL',w/2,.12,8.4,10,1.4,{bg:'#0e2a4a',fg:'#ffffff',glow:true,font:FS});
  // kiosks
  const kiosk=(x,z,text,col)=>{roomBox(r,3,1.1,1.6,x,z,std(col,.5));const s=textPlane(text,2.8,.5,{bg:'#111',fg:'#ffd23f',glow:true,font:FS});s.position.set(x0+x,2.4,z0+z);scene.add(s);const p=new THREE.Mesh(new THREE.BoxGeometry(.06,1.3,.06),std('#333',.5));p.position.set(x0+x,1.75,z0+z);scene.add(p);};
  kiosk(34,10,'珍珠奶茶','#b5651d');kiosk(34,22,'時裝店','#2a3a5a');kiosk(22,9,'遊戲機中心','#6d1f8f');
  r.inter.push({at:()=>({x:x0+34,z:z0+11.8}),r:2.6,label:'買杯珍珠奶茶（$28，+30 血）',ok:()=>curRoom===r,act:()=>{if(S.money<28){toast('唔夠錢');return;}addMoney(-28,true);S.hp=Math.min(100,S.hp+30);toast('啜啜啜…+30 血');}});
  r.inter.push({at:()=>({x:x0+34,z:z0+23.8}),r:2.6,label:'時裝店：試新衫',ok:()=>curRoom===r,act:toggleOutfit});
  r.inter.push({at:()=>({x:x0+22,z:z0+10.8}),r:2.6,label:'打一局夾公仔（$10）',ok:()=>curRoom===r,act:()=>{if(S.money<10){toast('唔夠錢');return;}addMoney(-10,true);const v=rnd();if(v<.6)toast('夾唔到…');else if(v<.92){addMoney(20,true);toast('夾到公仔！賣返 $20');}else{addMoney(80,true);toast('夾到限量版！賣返 $80');}}});
  r.spawn={x:x0+w/2,z:z0+d-2.4,h:Math.PI};
  for(let i=0;i<12;i++){const girl=rnd()<.5;const p=rnd()<.35?uniformPerson(girl):person({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47','#222','#f1c40f']),pants:pick(['#2b3550','#222','#5d4b3a']),long:girl,bag:rnd()<.4?pick(['#c0392b','#1d4fa0']):null});roomPerson(r,p,R(6,40),R(6,26),R(0,TAU),true);}
  r.lights=[[x0+12,z0+8],[x0+34,z0+8],[x0+12,z0+24],[x0+34,z0+24],[x0+23,z0+16]];}
function toggleOutfit(){const P=PLAYER;const old=P.p;const casual=!P.casual;const np=casual?person({shirt:'#2b2f36',pants:'#3a4a6a',hair:'#121212',bag:'#1d4fa0'}):uniformPerson(false,{hair:'#121212',bag:'#1d4fa0'});
  np.g.position.copy(old.g.position);np.g.rotation.y=old.g.rotation.y;scene.remove(old.g);P.p=np;P.casual=casual;setupWeapons();updateWeapon();toast(casual?'換咗便服':'換返校服');}
/* MTR: Tuen Ma line (viaduct) with Yuen Long and Long Ping stations */
const MTR={path:null,st:{},train:null};
function chainPath(ways){const key=p=>Math.round(p[0]/3)+','+Math.round(p[1]/3);const ends=new Map();ways.forEach((w,i)=>{for(const e of [0,1]){const k=key(e?w[w.length-1]:w[0]);if(!ends.has(k))ends.set(k,[]);ends.get(k).push([i,e]);}});let best=null;
  for(let st=0;st<ways.length;st++)for(const e0 of [0,1]){const used=new Set([st]);let path=e0?ways[st].slice().reverse():ways[st].slice();for(let guard=0;guard<100;guard++){const tail=path[path.length-1],prev=path[path.length-2]||path[0];const L=(ends.get(key(tail))||[]).filter(([i])=>!used.has(i));if(!L.length)break;let pw=null,bd=-2;
      for(const [i,e] of L){const w=e?ways[i].slice().reverse():ways[i];const nx=w[Math.min(1,w.length-1)];const d1=[tail[0]-prev[0],tail[1]-prev[1]],d2=[nx[0]-tail[0],nx[1]-tail[1]];const dot=(d1[0]*d2[0]+d1[1]*d2[1])/((Math.hypot(...d1)*Math.hypot(...d2))||1);if(dot>bd){bd=dot;pw=[i,w];}}if(bd<.5)break;used.add(pw[0]);path=path.concat(pw[1].slice(1));}
    let len=0;for(let i=1;i<path.length;i++)len+=Math.hypot(path[i][0]-path[i-1][0],path[i][1]-path[i-1][1]);if(!best||len>best.len)best={pts:path,len};}
  const cum=[0];for(let i=1;i<best.pts.length;i++)cum.push(cum[i-1]+Math.hypot(best.pts[i][0]-best.pts[i-1][0],best.pts[i][1]-best.pts[i-1][1]));return {pts:best.pts,cum,len:best.len};}
function nearestS(P,x,z){let bs=0,bd=1e9;for(let s=0;s<=P.len;s+=2){const q=posOn(P,s);const d=Math.hypot(q.x-x,q.z-z);if(d<bd){bd=d;bs=s;}}return bs;}
function buildMTR(){const ways=D.rail.map(flat2).filter(w=>w.length>=2);if(!ways.length)return;const west=ways.filter(w=>w[0][0]>w[w.length-1][0]);const P=chainPath(west.length?west:ways);
  // keep the westbound track running east -> west (s grows towards Tin Shui Wai) whatever chain order comes out
  if(P.pts[0][0]<P.pts[P.pts.length-1][0]){P.pts.reverse();P.cum=[0];for(let i=1;i<P.pts.length;i++)P.cum.push(P.cum[i-1]+Math.hypot(P.pts[i][0]-P.pts[i-1][0],P.pts[i][1]-P.pts[i-1][1]));}MTR.path=P;
  const defs=[['yl','元朗','Yuen Long','元朗站'],['lp','朗屏','Long Ping','朗屏站']];
  for(const [id,zh,en,lab] of defs){const L=D.lab.find(l=>l[0]===lab);if(!L)continue;const vp=D.plat.filter(p=>p[0]).map(p=>flat2(p[1])).map(p=>[p.reduce((a,q)=>a+q[0],0)/p.length,p.reduce((a,q)=>a+q[1],0)/p.length]).sort((a,b)=>Math.hypot(a[0]-L[1],a[1]-L[2])-Math.hypot(b[0]-L[1],b[1]-L[2]))[0]||[L[1],L[2]];
    const s=nearestS(P,vp[0],vp[1]);const q0=posOn(P,s);const lat=(vp[0]-q0.x)*(-q0.dz)+(vp[1]-q0.z)*q0.dx;const sg=lat<0?-1:1;const st={id,zh,en,s,s0:Math.max(4,s-55),s1:Math.min(P.len-4,s+55),off:3.9*sg,sg};MTR.st[id]=st;
    // platform slab, canopy, edge line, signs
    const pts=[],pts2=[];for(let t=st.s0;t<=st.s1;t+=4){const q=posOn(P,t);pts.push([q.x-q.dz*st.off,q.z+q.dx*st.off]);pts2.push([q.x-q.dz*(st.off-1.55*st.sg),q.z+q.dx*(st.off-1.55*st.sg)]);}
    RIBH=false;const pb=new Batch();ribbon(pb,pts,3.4,PLAT_Y-.05,false);const sb=new Batch();ribbon(sb,pts2,.3,PLAT_Y-.03,false);const cb=new Batch();ribbon(cb,pts,4.6,PLAT_Y+3.4,false);RIBH=true;
    pb.mesh(std('#d5d1c8',.7),true);sb.mesh(std('#f2c300',.5),false);const cm=cb.mesh(std('#4f4a47',.6,.3),true);if(cm)cm.material.side=THREE.DoubleSide;
    for(let t=st.s0+6;t<st.s1;t+=12){const q=posOn(P,t);const x=q.x-q.dz*(st.off+.9*st.sg),z=q.z+q.dx*(st.off+.9*st.sg);const col=new THREE.Mesh(new THREE.BoxGeometry(.25,3.4,.25),std('#7a2a1a',.6));col.position.set(x,PLAT_Y+1.7,z);scene.add(col);
      if(((t-st.s0)/12|0)%2===0){const sg=textPlane(zh+'  '+en,2.6,.5,{bg:'#9a3b26',fg:'#fff',font:FS,glow:true});sg.position.set(x,PLAT_Y+2.6,z);sg.rotation.y=Math.atan2(q.dx,q.dz)+Math.PI/2;scene.add(sg);const sg2=sg.clone();sg2.rotation.y+=Math.PI;scene.add(sg2);}
      if(((t-st.s0)/12|0)%3===1){const bn=new THREE.Mesh(new THREE.BoxGeometry(1.6,.45,.5),std('#9aa3ab',.4,.6));bn.position.set(q.x-q.dz*(st.off+.6*st.sg),PLAT_Y+.22,q.z+q.dx*(st.off+.6*st.sg));bn.rotation.y=Math.atan2(q.dx,q.dz);scene.add(bn);}}
    // street entrance
    const nr=nearestRoad(L[1],L[2],90,r=>r.cls>=6)||nearestRoad(L[1],L[2],140,r=>r.cls<=5);const ex=nr?{x:nr.x,z:nr.z}:{x:L[1],z:L[2]};const e2=freeSpot(ex.x,ex.z);st.street={x:e2.x,z:e2.z,h:0};
    const kg=new THREE.Group();kg.position.set(e2.x,TH(e2.x,e2.z),e2.z);scene.add(kg);for(const sx of [-1.4,1.4]){const p=new THREE.Mesh(new THREE.BoxGeometry(.18,3,.18),std('#5a5f66',.4,.6));p.position.set(sx,1.5,0);kg.add(p);}
    const rf=new THREE.Mesh(new THREE.BoxGeometry(3.4,.25,1.6),std('#9a3b26',.6));rf.position.y=3.1;rf.castShadow=true;kg.add(rf);const ksg=textPlane(zh+'站  '+en,3.2,.5,{bg:'#ffffff',fg:'#9a3b26',font:FS,glow:true});ksg.position.set(0,2.75,.82);kg.add(ksg);const sgb=ksg.clone();sgb.position.z=-.82;sgb.rotation.y=Math.PI;kg.add(sgb);
    addLabel(zh+'站（暫停開放）',e2.x,e2.z,8,'mtr');
    buildConcourse(st);}
  buildTrain();
  // platform people
  for(const st of Object.values(MTR.st)){st.people=[];for(let i=0;i<8;i++){const t=R(st.s0+6,st.s1-6),q=posOn(P,t);const p=rnd()<.4?uniformPerson(rnd()<.5):person({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47','#222']),pants:pick(['#2b3550','#222','#5d4b3a']),long:rnd()<.4});const off=st.off+st.sg*R(-1,1.1);
    p.g.position.set(q.x-q.dz*off,PLAT_Y,q.z+q.dx*off);p.g.rotation.y=Math.atan2(-q.dz,q.dx)+(rnd()<.5?0:Math.PI);p.mt={s:t,off,dir:rnd()<.5?1:-1,walk:rnd()<.35};st.people.push(p);}}}
function buildConcourse(st){const r=makeRoom('mtr_'+st.id,{name:'港鐵'+st.zh+'站 大堂',w:30,d:16,floor:roomFloorTex('#a9a6a0','#9c9993',10),wall:'#d4d0c6',skirt:'#9a3b26'});const x0=r.x0,z0=r.z0;
  const band=new THREE.Mesh(new THREE.BoxGeometry(30,.4,.05),std('#9a3b26',.6));band.position.set(x0+15,3,z0+.06);scene.add(band);
  roomSign(r,st.zh+'  '+st.en,15,.1,3.65,7,.8,{bg:'#ffffff',fg:'#9a3b26',font:FS,glow:true});roomSign(r,'往月台 To Platforms ↑',8,.1,2.3,4,.5,{bg:'#1a1a1a',fg:'#ffd23f',font:FS,glow:true});
  for(let i=0;i<7;i++){roomBox(r,.32,1.05,1.4,6+i*2.2,7,std('#b9bec4',.25,.85));const l=new THREE.Mesh(new THREE.BoxGeometry(.12,.06,.12),new THREE.MeshBasicMaterial({color:i%3?0x34e06a:0xff3030,toneMapped:false}));l.position.set(x0+6+i*2.2,1.1,z0+7.6);scene.add(l);}
  roomBox(r,3,1.05,.6,24.5,7,std('#b9bec4',.25,.85));
  for(const x of [24,27]){roomBox(r,1.2,1.9,.6,x,.6,std('#9a3b26',.5));const sc=new THREE.Mesh(new THREE.PlaneGeometry(.7,.45),new THREE.MeshBasicMaterial({color:0x9fe0ff,toneMapped:false}));sc.position.set(x0+x,1.4,z0+.92);scene.add(sc);}
  // route map board
  const [c,g]=cvs(1024,256);g.fillStyle='#ffffff';g.fillRect(0,0,1024,256);g.fillStyle='#9a3b26';g.fillRect(40,120,944,14);const stops=[['天水圍','未開通'],['朗屏',''],['元朗',''],['錦上路','未開通']];
  stops.forEach((s,i)=>{const x=110+i*270;g.fillStyle=s[1]?'#bbb':'#9a3b26';g.beginPath();g.arc(x,127,22,0,TAU);g.fill();g.fillStyle='#fff';g.beginPath();g.arc(x,127,10,0,TAU);g.fill();g.fillStyle=s[1]?'#999':'#111';g.font=`900 40px ${FS}`;g.textAlign='center';g.fillText(s[0],x,80);if(s[1]){g.fillStyle='#c8102e';g.font=`700 26px ${FS}`;g.fillText(s[1],x,190);}if(s[0]===st.zh){g.fillStyle='#c8102e';g.font=`900 24px ${FS}`;g.fillText('你在此',x,225);}});
  g.fillStyle='#9a3b26';g.font=`900 30px ${FS}`;g.textAlign='left';g.fillText('屯馬綫 Tuen Ma Line',40,40);const map=new THREE.Mesh(new THREE.PlaneGeometry(6,1.5),new THREE.MeshStandardMaterial({map:ctex(c),roughness:.5}));map.position.set(x0+15,1.9,z0+.08);scene.add(map);
  for(let i=0;i<6;i++){const girl=rnd()<.5;const p=rnd()<.4?uniformPerson(girl):person({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0']),pants:pick(['#2b3550','#222']),long:girl});roomPerson(r,p,R(4,26),R(9,14),R(0,TAU),true);}
  const s2=npc('港鐵職員',{shirt:'#f4f4f0',pants:'#2a2f3a'},0,0,0,'#9a3b26');roomPerson(r,s2,27.5,9,Math.PI,false);
  r.lights=[[x0+8,z0+5],[x0+22,z0+5],[x0+15,z0+12]];
  r.inter.push({at:()=>({x:x0+12.6,z:z0+8.6}),r:6.5,label:'拍卡入閘上月台（$5）',ok:()=>curRoom===r,act:()=>{if(S.money<5){toast('唔夠錢入閘');return;}addMoney(-5,true);sfx('ding');toPlatform(st);}});
  r.inter.push({at:()=>({x:x0+15,z:z0+1.6}),r:3,label:'睇路線圖',ok:()=>curRoom===r,act:()=>say([['港鐵職員','屯馬綫依家行元朗同朗屏兩個站。'],['港鐵職員',S.free?'天水圍站仲喺工程中，下一期先開通，敬請期待！':'天水圍方向未開通，你完成主線之後先開放，記住喇。']])});
  st.room=r;r.onEnter=()=>{};}
function toPlatform(st){fadeTo('上緊扶手電梯…',()=>{curRoom=null;const q=posOn(MTR.path,st.s);PLAYER.plat=st;PLAYER.x=q.x-q.dz*st.off;PLAYER.z=q.z+q.dx*st.off;PLAYER.y=PLAT_Y;cam.tx=PLAYER.x;cam.tz=PLAYER.z;cam.yaw=Math.atan2(q.dz,-q.dx);cam.pitch=.25;},900);}
function platformConstrain(){const st=PLAYER.plat;if(!st||PLAYER.riding)return;const P=MTR.path;let bs=st.s,bd=1e9;for(let s=st.s0;s<=st.s1;s+=1){const q=posOn(P,s);const d=(q.x-PLAYER.x)**2+(q.z-PLAYER.z)**2;if(d<bd){bd=d;bs=s;}}
  bs=clamp(bs,st.s0+2,st.s1-2);const q=posOn(P,bs);const lat=(PLAYER.x-q.x)*(-q.dz)+(PLAYER.z-q.z)*q.dx;const l=clamp(lat,Math.min(st.off-1.35*st.sg,st.off+1.45*st.sg),Math.max(st.off-1.35*st.sg,st.off+1.45*st.sg));PLAYER.x=q.x-q.dz*l;PLAYER.z=q.z+q.dx*l;PLAYER.y=PLAT_Y;}
function carMesh(){const g=new THREE.Group(),L=20;const silver=std('#d5d9de',.3,.7),line=std('#9a3b26',.5,.2);
  const b=new THREE.Mesh(profileGeo([[-L/2,.2],[L/2,.2],[L/2,3.4],[-L/2,3.4]],3.1,.18),silver);b.castShadow=true;g.add(b);
  const w=new THREE.Mesh(new THREE.BoxGeometry(3.14,.9,L-2.4),glassM);w.position.y=2.25;g.add(w);const st=new THREE.Mesh(new THREE.BoxGeometry(3.15,.28,L-.4),line);st.position.y=1.35;g.add(st);
  for(const s of [-1,1])for(const z of [-6,-1.5,3,7.5]){const d=new THREE.Mesh(new THREE.BoxGeometry(.02,2.4,1.5),std('#9aa0a6',.3,.7));d.position.set(s*1.58,1.45,z);g.add(d);}
  const sk=new THREE.Mesh(new THREE.BoxGeometry(2.8,.5,L-1),std('#2a2e33',.6));sk.position.y=.1;g.add(sk);return g;}
function buildTrain(){const P=MTR.path;if(!P||!MTR.st.yl||!MTR.st.lp)return;const cars=[];for(let i=0;i<4;i++){const m=carMesh();scene.add(m);cars.push(m);}
  const front=new THREE.Mesh(new THREE.PlaneGeometry(2.4,.4),new THREE.MeshBasicMaterial({map:ledTex('屯馬綫  元朗 ⇄ 朗屏'),toneMapped:false}));front.position.set(0,3.0,10.21);cars[0].add(front);
  const a=MTR.st.yl.s,b=MTR.st.lp.s;MTR.train={cars,s:a,from:a,to:b,wait:14,speed:0,at:'yl'};}
function trainUpdate(dt){const T=MTR.train;if(!T)return;const P=MTR.path;
  if(T.wait>0){T.wait-=dt;T.speed=0;if(T.wait<=0){T.from=T.s;const nxt=T.at==='yl'?'lp':'yl';T.to=MTR.st[nxt].s;T.at=null;T.next=nxt;sfx('bell',.4);}}
  else{const dir=Math.sign(T.to-T.s);const rem=Math.abs(T.to-T.s);const want=Math.min(27,Math.sqrt(2*1.1*rem)+.5);T.speed=lerp(T.speed,want,1-Math.exp(-.8*dt));T.s+=dir*T.speed*dt;
    if(rem<.6){T.s=T.to;T.at=T.next;T.wait=11;T.speed=0;if(PLAYER.riding==='mtr')arriveTrain(MTR.st[T.at]);}}
  const dirv=T.to>=T.s?1:-1;for(let i=0;i<T.cars.length;i++){const s=clamp(T.s-(i-1.5)*20.4,1,P.len-1),q=posOn(P,s),q2=posOn(P,clamp(s+1,0,P.len));T.cars[i].position.set(q.x,12.25,q.z);T.cars[i].rotation.y=Math.atan2(q2.x-q.x,q2.z-q.z);}
  if(PLAYER.riding==='mtr'){const q=posOn(P,T.s);PLAYER.x=q.x;PLAYER.z=q.z;PLAYER.y=13;}}
function boardTrain(){PLAYER.riding='mtr';PLAYER.plat=null;PLAYER.p.g.visible=false;toast('上咗車，下一站：'+MTR.st[MTR.train.at==='yl'?'lp':'yl'].zh);}
function arriveTrain(st){PLAYER.riding=null;PLAYER.p.g.visible=true;const q=posOn(MTR.path,st.s+8);PLAYER.plat=st;PLAYER.x=q.x-q.dz*st.off;PLAYER.z=q.z+q.dx*st.off;PLAYER.y=PLAT_Y;toast('到站：'+st.zh);sfx('ding');}
function mtrInteracts(){
  for(const st of Object.values(MTR.st)){INTER.push({at:()=>st.street,r:3,label:st.zh+'站（暫停開放）',ok:()=>!PLAYER.car&&!curRoom,act:()=>say([['港鐵職員','唔好意思，'+st.zh+'站暫時關閉維修，遲啲先再開放。']])});
    INTER.push({at:()=>({x:PLAYER.x,z:PLAYER.z,y:PLAT_Y}),y:PLAT_Y,r:5,label:'上車（往'+(st.id==='yl'?'朗屏':'元朗')+'）',ok:()=>PLAYER.plat===st&&MTR.train&&MTR.train.at===st.id&&MTR.train.wait>1.5,act:boardTrain});
    INTER.push({at:()=>{const q=posOn(MTR.path,st.s);return {x:q.x-q.dz*st.off,z:q.z+q.dx*st.off,y:PLAT_Y};},y:PLAT_Y,r:2.5,label:'出閘離開',ok:()=>PLAYER.plat===st&&!PLAYER.riding,act:()=>{exitRoom({x:st.street.x,z:st.street.z+1.5,h:0});PLAYER.plat=null;}});
    if(st.id==='lp')INTER.push({at:()=>{const q=posOn(MTR.path,st.s1-10);return {x:q.x-q.dz*st.off,z:q.z+q.dx*st.off,y:PLAT_Y};},y:PLAT_Y,r:4,label:'搭往天水圍',ok:()=>PLAYER.plat===st,act:()=>say([['車站廣播',S.free?'往天水圍嘅列車暫停服務：天水圍站工程進行中，下一期開通，敬請期待！':'往天水圍方向未開通。完成主線之後先會開放。']])});}}
function platformPeople(dt){const P=MTR.path;if(!P)return;for(const st of Object.values(MTR.st))for(const p of st.people||[]){if(p.mt.walk){p.mt.s+=p.mt.dir*1.1*dt;if(p.mt.s>st.s1-4||p.mt.s<st.s0+4)p.mt.dir*=-1;const q=posOn(P,p.mt.s);p.g.position.set(q.x-q.dz*p.mt.off,PLAT_Y,q.z+q.dx*p.mt.off);p.g.rotation.y=Math.atan2(q.dx*p.mt.dir,q.dz*p.mt.dir);animP(p,1.1,dt);}}}

/* ---------- street entrances for banks and malls ---------- */
function buildEntrances(){
  BANKF.forEach((f,i)=>{bankFront(f,i);const door={x:f.x+f.n[0]*1.8,z:f.z+f.n[2]*1.8};INTER.push({at:()=>door,r:2.6,label:'入元朗儲蓄銀行',ok:()=>!PLAYER.car&&!curRoom,act:()=>enterRoom('bank',{x:door.x+f.n[0]*.8,z:door.z+f.n[2]*.8,h:Math.atan2(f.n[0],f.n[2])})});addLabel('銀行',door.x,door.z,9,'bank');});
  const yh=D.lab.find(l=>l[0]==='形點');if(yh){const b=nearestB(yh[1],yh[2]);if(b){const d=door(b);const p={x:d.x,z:d.z};INTER.push({at:()=>p,r:3,label:'入形點商場',ok:()=>!PLAYER.car&&!curRoom,act:()=>enterRoom('mall',{x:p.x+d.e.nx,z:p.z+d.e.nz,h:Math.atan2(d.e.nx,d.e.nz)})});
    const dm=new THREE.Mesh(new THREE.PlaneGeometry(4,3),std('#1d2730',.1,.6));dm.position.set(d.e.x+d.e.nx*.08,TH(d.e.x,d.e.z)+1.5,d.e.z+d.e.nz*.08);dm.rotation.y=Math.atan2(d.e.nx,d.e.nz);scene.add(dm);}}}
function spawnStudents(){const L=LOC.gate;for(let i=0;i<22;i++){const p=uniformPerson(rnd()<.5);placePed(p,L.x,L.z,0,120);p.spd=R(.9,1.4);p.student=true;peds.push(p);}}

/* ================= v3 core: data clean-up, world bounds, physics, camera, map, vehicles ================= */
const CAMP={OX:-743.4,OZ:234,x0:-732.4,x1:-626.4,z0:231.6,z1:291.4};
const HOMEP={x0:-845,z0:205,x1:-815,z1:235,h:93};
const LANE={x0:-515,x1:-506,z0:-62,z1:-6,xc:-510.6};
const WB={x0:-3600,x1:1860,z0:-3250,z1:1080};
function inCamp(x,z,m=0){return x>CAMP.x0-m&&x<CAMP.x1+m&&z>CAMP.z0-m&&z<CAMP.z1+m;}
function inWB(x,z,m=0){return x>WB.x0+m&&x<WB.x1-m&&z>WB.z0+m&&z<WB.z1-m;}
function exclAt(x,z){return (x>-874&&x<-795&&z>239&&z<296)||inCamp(x,z,1.5)||(x>LANE.x0-1&&x<LANE.x1+1&&z>LANE.z0-2&&z<LANE.z1+4)||(x>HOMEP.x0-6&&x<HOMEP.x1+8&&z>HOMEP.z0-6&&z<HOMEP.z1+6);}

/* ---------- data clean-up before anything is built ---------- */
function v3Pre(){
  {const [c,g]=cvs(256,256);noiseFill(g,256,256,'#8d8c87',6000,.04,.11,3);for(let i=0;i<5;i++){g.fillStyle=`rgba(40,36,30,${R(.02,.045)})`;g.beginPath();g.arc(R(0,256),R(0,256),R(30,80),0,TAU);g.fill();}TX.concrete=ctex(c,true);}
  const cen=f=>{let x=0,z=0;const n=f.length/2;for(let i=0;i<f.length;i+=2){x+=f[i];z+=f[i+1];}return [x/n,z/n];};
  const inHome=(x,z)=>x>HOMEP.x0-4&&x<HOMEP.x1+4&&z>HOMEP.z0-4&&z<HOMEP.z1+4;
  D.b=D.b.filter(b=>{const c=cen(b[3]);return !inCamp(c[0],c[1])&&!inHome(c[0],c[1]);});
  // drop duplicate / near-duplicate footprints of the same height: their roofs and walls flicker against each other
  const bb=D.b.map((b,i)=>{const f=b[3];let x0=1e9,z0=1e9,x1=-1e9,z1=-1e9;for(let k=0;k<f.length;k+=2){x0=Math.min(x0,f[k]);x1=Math.max(x1,f[k]);z0=Math.min(z0,f[k+1]);z1=Math.max(z1,f[k+1]);}return {i,x0,z0,x1,z1,h:b[0],a:(x1-x0)*(z1-z0),keep:b[2]===2};}).sort((a,b)=>b.a-a.a);
  const G=new Map(),kept=[],drop=new Set();const ck=(i,j)=>i*100003+j;
  for(const o of bb){let dup=false;if(!o.keep){outer:for(let i=Math.floor(o.x0/40);i<=Math.floor(o.x1/40);i++)for(let j=Math.floor(o.z0/40);j<=Math.floor(o.z1/40);j++){for(const k of (G.get(ck(i,j))||[])){const q=kept[k];const ix=Math.min(o.x1,q.x1)-Math.max(o.x0,q.x0),iz=Math.min(o.z1,q.z1)-Math.max(o.z0,q.z0);if(ix>0&&iz>0&&ix*iz>.6*o.a&&Math.abs(o.h-q.h)<1.5){dup=true;break outer;}}}}
    if(dup){drop.add(o.i);continue;}const idx=kept.length;kept.push(o);for(let i=Math.floor(o.x0/40);i<=Math.floor(o.x1/40);i++)for(let j=Math.floor(o.z0/40);j<=Math.floor(o.z1/40);j++){const k=ck(i,j);if(!G.has(k))G.set(k,[]);G.get(k).push(idx);}}
  D.b=D.b.filter((b,i)=>!drop.has(i));
  cleanMap();
  const H=HOMEP;D.b.push([H.h,1,0,[H.x0,H.z0,H.x1,H.z0,H.x1,H.z1,H.x0,H.z1]]);
  D.pitch=D.pitch.filter(f=>{const c=cen(f);return !inCamp(c[0],c[1]);});
  D.r=D.r.filter(r=>{if(r[0]<5)return true;const f=r[4];for(let i=0;i<f.length;i+=2)if(!inCamp(f[i],f[i+1],-1)&&!(f[i]>LANE.x0-1&&f[i]<LANE.x1+1&&f[i+1]>LANE.z0&&f[i+1]<LANE.z1))return true;return false;});
  // the Tuen Ma viaduct ends at the west edge of the playable map (the Tin Shui Wai section is not open yet)
  const RX0=(typeof TSWZ!=='undefined'?TSWZ.railX0:WB.x0);D.rail=D.rail.map(f=>{const out=[];let cur=[];for(let i=0;i<f.length;i+=2){const x=f[i],z=f[i+1];const inside=x>=RX0;if(i>0){const px=f[i-2],pz=f[i-1];const pin=px>=RX0;if(pin!==inside){const t=(RX0-px)/(x-px);const cx=RX0,cz=pz+(z-pz)*t;cur.push(cx,cz);if(!inside){out.push(cur);cur=[];}}}if(inside)cur.push(x,z);}if(cur.length)out.push(cur);return out.sort((a,b)=>b.length-a.length)[0]||[];}).filter(f=>f.length>=4);}

/* ---------- map clean-up: buildings through the viaduct, roads through buildings, half-overlapping blocks ---------- */
const MAPSTAT={};
function cleanMap(){const B=D.b.map((b,i)=>{const f=b[3];const pts=[];let x0=1e9,z0=1e9,x1=-1e9,z1=-1e9;for(let k=0;k<f.length;k+=2){pts.push([f[k],f[k+1]]);x0=Math.min(x0,f[k]);x1=Math.max(x1,f[k]);z0=Math.min(z0,f[k+1]);z1=Math.max(z1,f[k+1]);}let a=0;for(let k=0;k<pts.length;k++){const p=pts[k],q=pts[(k+1)%pts.length];a+=p[0]*q[1]-q[0]*p[1];}return {i,h:b[0],t:b[1],flag:b[2],pts,x0,z0,x1,z1,area:Math.abs(a/2)};});
  const G=new Map();const ck=(i,j)=>i*100003+j;for(const o of B)for(let i=Math.floor(o.x0/30);i<=Math.floor(o.x1/30);i++)for(let j=Math.floor(o.z0/30);j<=Math.floor(o.z1/30);j++){const k=ck(i,j);if(!G.has(k))G.set(k,[]);G.get(k).push(o);}
  const near=(x,z)=>G.get(ck(Math.floor(x/30),Math.floor(z/30)))||[];
  const segD=(x,z,p)=>{let best=1e9;for(let k=0;k<p.length;k++){const a=p[k],c=p[(k+1)%p.length];const ex=c[0]-a[0],ez=c[1]-a[1],l2=ex*ex+ez*ez||1e-9;const t=clamp(((x-a[0])*ex+(z-a[1])*ez)/l2,0,1);best=Math.min(best,Math.hypot(x-a[0]-ex*t,z-a[1]-ez*t));}return best;};
  const kill=new Set();const sample=(f,step,fn)=>{for(let k=2;k<f.length;k+=2){const ax=f[k-2],az=f[k-1],bx=f[k],bz=f[k+1];const L=Math.hypot(bx-ax,bz-az);for(let s=0;s<L;s+=step){const t=s/L;fn(ax+(bx-ax)*t,az+(bz-az)*t);}}};
  // 1. anything standing in the Tuen Ma viaduct corridor
  let nr=0;for(const f of D.rail)sample(f,2,(x,z)=>{for(const o of near(x,z)){if(kill.has(o.i)||o.flag===2)continue;if(x<o.x0-6||x>o.x1+6||z<o.z0-6||z>o.z1+6)continue;if(inPoly(x,z,o.pts)||segD(x,z,o.pts)<4.5){kill.add(o.i);nr++;}}});
  // 2. main roads running through a building
  const hit=new Map();for(const r of D.r){if(r[0]>3)continue;sample(r[4],2,(x,z)=>{for(const o of near(x,z)){if(x<o.x0||x>o.x1||z<o.z0||z>o.z1)continue;if(inPoly(x,z,o.pts))hit.set(o,(hit.get(o)||0)+2);}});}
  let nroad=0;for(const [o,len] of hit){if(len>=6&&!kill.has(o.i)&&o.flag!==2){kill.add(o.i);nroad++;}}
  // 3. blocks that half-overlap a neighbour (one wall cutting through another): drop the smaller
  let nov=0;for(const o of B){if(kill.has(o.i)||o.flag===2)continue;const seen=new Set();for(let i=Math.floor(o.x0/30);i<=Math.floor(o.x1/30);i++)for(let j=Math.floor(o.z0/30);j<=Math.floor(o.z1/30);j++)for(const q of G.get(ck(i,j))||[]){if(q===o||seen.has(q)||kill.has(q.i)||q.area<o.area)continue;seen.add(q);
      if(q.x0>o.x1||q.x1<o.x0||q.z0>o.z1||q.z1<o.z0)continue;let n=0,inn=0;const st=Math.max(.8,Math.sqrt(o.area)/14);for(let x=o.x0+st/2;x<o.x1;x+=st)for(let z=o.z0+st/2;z<o.z1;z+=st){if(!inPoly(x,z,o.pts))continue;n++;if(inPoly(x,z,q.pts))inn++;}
      if(!n)continue;const fr=inn/n;if(fr>.12&&(fr<.88||o.h<q.h-.5)){kill.add(o.i);nov++;break;}}}
  D.b=D.b.filter((b,i)=>!kill.has(i));MAPSTAT.rail=nr;MAPSTAT.road=nroad;MAPSTAT.overlap=nov;}
/* ---------- solids with a vertical range, standing on things ---------- */
function addSolidPts(pts,y0,top,o={}){let x0=1e9,z0=1e9,x1=-1e9,z1=-1e9;for(const p of pts){x0=Math.min(x0,p[0]);x1=Math.max(x1,p[0]);z0=Math.min(z0,p[1]);z1=Math.max(z1,p[1]);}
  let area=0;for(let i=0;i<pts.length;i++){const a=pts[i],c=pts[(i+1)%pts.length];area+=a[0]*c[1]-c[0]*a[1];}
  const b=Object.assign({h:top,top,base:y0,y0:y0>0.05?y0:null,t:9,flag:0,pts,area:area/2,x0,z0,x1,z1,nomap:true},o);const idx=BL.length;BL.push(b);gridAdd(GRID,b,idx);return b;}
function addSolidBox(x0,z0,x1,z1,y0,top,o){return addSolidPts([[x0,z0],[x1,z0],[x1,z1],[x0,z1]],y0,top,o);}
function pushOut(o,r,y=0,step=0){let hit=null;for(const b of queryB(o.x,o.z,r)){if(b.soft||y>(b.top??b.h)-.05-step||(b.y0!=null&&y<b.y0-.05))continue;if(o.x<b.x0-r||o.x>b.x1+r||o.z<b.z0-r||o.z>b.z1+r)continue;
    const p=b.pts;let best=1e9,bx=0,bz=0;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[j],c=p[i];const ex=c[0]-a[0],ez=c[1]-a[1];const l2=ex*ex+ez*ez||1e-9;const t=clamp(((o.x-a[0])*ex+(o.z-a[1])*ez)/l2,0,1);const px=a[0]+ex*t,pz=a[1]+ez*t;const d=(o.x-px)**2+(o.z-pz)**2;if(d<best){best=d;bx=px;bz=pz;}}
    const inside=inPoly(o.x,o.z,p),d=Math.sqrt(best);if(inside||d<r){let nx=o.x-bx,nz=o.z-bz;const l=Math.hypot(nx,nz)||1e-6;nx/=l;nz/=l;if(inside){nx=-nx;nz=-nz;}const push=inside?d+r:r-d;o.x+=nx*push;o.z+=nz*push;hit={nx,nz};}}
  if(y<11)for(const pl of PILLARS){const dx=o.x-pl[0],dz=o.z-pl[1],d=Math.hypot(dx,dz),m=r+.9;if(d<m&&d>0){o.x=pl[0]+dx/d*m;o.z=pl[1]+dz/d*m;hit={nx:dx/d,nz:dz/d};}}
  return hit;}
function solidAt(x,y,z){for(const b of queryB(x,z,.2)){if(b.soft)continue;if(y<(b.top??b.h)+.3&&(b.y0==null||y>b.y0-.3)&&x>b.x0&&x<b.x1&&z>b.z0&&z<b.z1&&inPoly(x,z,b.pts))return true;}return false;}
function groundAt(x,z,y){let g=TH(x,z);for(const b of queryB(x,z,.05)){if(b.soft||b.noStand)continue;const t=b.top??b.h;if(t>g&&t<=y+.45&&x>b.x0&&x<b.x1&&z>b.z0&&z<b.z1&&inPoly(x,z,b.pts))g=t;}return g;}
function playerGround(p){if(p.plat)return PLAT_Y;if(p.top)return TOWER_TOP_Y;if(!p.ind&&!curRoom&&(p.y||0)<1&&inWater(p.x,p.z))return -1.05;return groundAt(p.x,p.z,p.y||0);}
function platformConstrain(){const st=PLAYER.plat;if(!st||PLAYER.riding)return;const P=MTR.path;let bs=st.s,bd=1e9;for(let s=st.s0;s<=st.s1;s+=1){const q=posOn(P,s);const d=(q.x-PLAYER.x)**2+(q.z-PLAYER.z)**2;if(d<bd){bd=d;bs=s;}}
  bs=clamp(bs,st.s0+2,st.s1-2);const q=posOn(P,bs);const lat=(PLAYER.x-q.x)*(-q.dz)+(PLAYER.z-q.z)*q.dx;const l=clamp(lat,Math.min(st.off-1.35*st.sg,st.off+1.45*st.sg),Math.max(st.off-1.35*st.sg,st.off+1.45*st.sg));PLAYER.x=q.x-q.dz*l;PLAYER.z=q.z+q.dx*l;}

/* ---------- walking: jump, double-jump somersault, world edge ---------- */
let jumpReq=false,edgeT=0;
function edgeClamp(o,isCar){if(curRoom||o.x>5000)return false;let hit=false;if(o.x<WB.x0){o.x=WB.x0;hit=true;}if(o.x>WB.x1){o.x=WB.x1;hit=true;}if(o.z<WB.z0){o.z=WB.z0;hit=true;}if(o.z>WB.z1){o.z=WB.z1;hit=true;}
  if(hit){if(isCar){o.vx*=-.3;o.vz*=-.3;o.speed*=.3;}if(edgeT<=0){toast(o.x<=WB.x0||o.x>=WB.x1?'到咗地圖盡頭喇（西鐵橋尾）':'到咗地圖盡頭喇');edgeT=4;}}return hit;}
function walkStep(dt){const p=PLAYER;if(p.vy==null){p.vy=0;p.grounded=true;p.jumps=0;p.peak=p.y||0;}
  const lock=!!(p.dress||p.dance||p.seated||p.brushT>0||(KF.lock>0));let mx=0,mz=0;
  if(!lock&&(inp.x||inp.y)){const fx=-Math.sin(cam.yaw),fz=-Math.cos(cam.yaw),rx=Math.cos(cam.yaw),rz=-Math.sin(cam.yaw);mx=fx*inp.y+rx*inp.x;mz=fz*inp.y+rz*inp.x;const l=Math.hypot(mx,mz);if(l>1){mx/=l;mz/=l;}}
  p.swim=!p.plat&&!p.top&&p.grounded&&inWater(p.x,p.z)&&p.y<-.5;const sp=(p.swim?(inp.run?3.6:2.4):inp.run?7.6:3.9)*spdMul(),k=p.grounded?12:3.2;p.vx=lerp(p.vx,mx*sp,1-Math.exp(-k*dt));p.vz=lerp(p.vz,mz*sp,1-Math.exp(-k*dt));
  if(KF.lunge>0){const l=Math.min(KF.lunge,dt*9);KF.lunge-=l;p.x+=Math.sin(p.h)*l;p.z+=Math.cos(p.h)*l;}
  p.x+=p.vx*dt;p.z+=p.vz*dt;pushOut(p,.35,(p.top||p.plat)?99:p.y,p.grounded?.45:0);
  if(p.y<TH(p.x,p.z)+1.4)for(const v of vehicles){const dx=p.x-v.x,dz=p.z-v.z,d=Math.hypot(dx,dz),m=v.W/2+.35+v.L*.18;if(d<m&&d>0){p.x=v.x+dx/d*m;p.z=v.z+dz/d*m;}}
  edgeClamp(p,false);
  p.spd=Math.hypot(p.vx,p.vz);if(p.spd>.2&&!lock)p.h=lerpAngle(p.h,Math.atan2(p.vx,p.vz),1-Math.exp(-12*dt));platformConstrain();
  const g=playerGround(p);
  if(jumpReq){jumpReq=false;if(!lock&&!curRoom){const jm=1-rpg().fat*.22;if(p.grounded){p.vy=6.4*jm;p.grounded=false;p.jumps=1;p.peak=p.y;sfx('swing',.5);}else if(p.jumps===1){p.vy=6.7*jm;p.jumps=2;p.flip=.0001;voice('flip');}}}
  if(p.grounded&&p.vy<=0){if(p.y-g>.45){p.grounded=false;p.peak=p.y;}else{p.y=g;p.vy=0;}}
  if(!p.grounded){p.vy-=24*dt;p.y+=p.vy*dt;if(p.vy>0){const c=ceilAt(p.x,p.z,p.y);if(c!=null&&p.y+1.78>c){p.y=c-1.78;p.vy=0;}}p.peak=Math.max(p.peak,p.y);if(p.y<=g){const drop=p.peak-g;p.y=g;p.vy=0;p.grounded=true;p.jumps=0;p.flip=0;if(g<-.5&&drop>.6){sfx('splash');splashFx(p.x,p.z);}else if(drop>7&&!curRoom)hurtPlayer(Math.round((drop-7)*(drop>40?20:4.5)));else if(drop>1.2)sfx('hit',.25);}}}
function ceilAt(x,z,y){let c=null;for(const b of queryB(x,z,.2)){if(b.soft||b.y0==null||b.y0<y+.3)continue;if(x>b.x0&&x<b.x1&&z>b.z0&&z<b.z1&&inPoly(x,z,b.pts))c=c==null?b.y0:Math.min(c,b.y0);}return c;}
addEventListener('keydown',e=>{if(e.code!=='Space'||!started||PLAYER.car||dlgQ||modal||busy||mapOpen||PLAYER.dress||PLAYER.dance)return;if(!e.repeat)jumpReq=true;});

/* ---------- camera: indoor cut-away, stable shadows ---------- */
function camUpdate(dt){const car=!!PLAYER.car;const tgt=PLAYER.car||PLAYER;const sp=car?Math.hypot(PLAYER.car.vx,PLAYER.car.vz):0;const ind=!!(curRoom||PLAYER.ind);
  if(PLAYER.dress){dressCam(dt);return;}if(PLAYER.dance){danceCam();return;}
  const lx=car?PLAYER.car.vx*.18:0,lz=car?PLAYER.car.vz*.18:0;const ty=car?PLAYER.car.y+1.6:(PLAYER.y||0)+1.55;if(ind)cam.pitch=Math.max(cam.pitch,PLAYER.ind==='home'?.5:.6);const k=1-Math.exp(-(car?7:12)*dt);cam.tx=lerp(cam.tx,tgt.x+lx,k);cam.tz=lerp(cam.tz,tgt.z+lz,k);cam.ty=lerp(cam.ty,ty,1-Math.exp(-(PLAYER.grounded===false?6:12)*dt));
  if(car&&performance.now()-cam.lastDrag>1300&&sp>2.5){const back=Math.atan2(PLAYER.car.vx,PLAYER.car.vz)+Math.PI;cam.yaw=lerpAngle(cam.yaw,PLAYER.car.speed<0?PLAYER.car.h:back,1-Math.exp(-2.4*dt));cam.pitch=lerp(cam.pitch,.2,1-Math.exp(-1.5*dt));}
  const want=Math.min((car?8.6+sp*.06:6.2)*cam.zoom,ind?8.5:999);let d=want;const dx=Math.sin(cam.yaw)*Math.cos(cam.pitch),dy=Math.sin(cam.pitch),dz=Math.cos(cam.yaw)*Math.cos(cam.pitch);
  if(!ind)for(let s=.6;s<want&&!cam.noCol;s+=.45){if(solidAt(cam.tx+dx*s,cam.ty+dy*s,cam.tz+dz*s)){d=Math.max(1.2,s-.45);break;}}
  cam.cd=d<cam.cd?lerp(cam.cd,d,1-Math.exp(-16*dt)):lerp(cam.cd,d,1-Math.exp(-3*dt));{const px=cam.tx+dx*cam.cd,pz=cam.tz+dz*cam.cd;camera.position.set(px,Math.max(cam.ty+dy*cam.cd,TH(px,pz)+.6),pz);}
  if(shake>0){shake=Math.max(0,shake-dt);camera.position.x+=R(-1,1)*shake*.4;camera.position.y+=R(-1,1)*shake*.4;}
  camera.lookAt(cam.tx,cam.ty,cam.tz);const fov=(typeof fovBase==="function"?fovBase():55)+clamp(sp,0,36)*.42;if(Math.abs(camera.fov-fov)>.05){camera.fov=lerp(camera.fov,fov,1-Math.exp(-4*dt));camera.updateProjectionMatrix();}
  sky.position.copy(camera.position);stars.position.copy(camera.position);}
camera.near=.4;camera.updateProjectionMatrix();
const _sx=new THREE.Vector3(),_sy=new THREE.Vector3(),_sz=new THREE.Vector3();
function sunFollow(){const dir=sun.userData.dir||new THREE.Vector3(0,1,0);const cy=PLAYER.car?0:Math.max(0,(PLAYER.y||0)-1);
  // snap the shadow camera to whole shadow-map texels in light space, so shadows don't crawl or jump while moving
  _sz.copy(dir).normalize();_sx.set(0,1,0).cross(_sz);if(_sx.lengthSq()<1e-6)_sx.set(1,0,0);_sx.normalize();_sy.copy(_sz).cross(_sx).normalize();
  const c=sun.shadow.camera,tex=(c.right-c.left)/sun.shadow.mapSize.x;const T=new THREE.Vector3(cam.tx,cy,cam.tz);const a=Math.round(T.dot(_sx)/tex)*tex,b=Math.round(T.dot(_sy)/tex)*tex,cz=T.dot(_sz);
  T.copy(_sx).multiplyScalar(a).addScaledVector(_sy,b).addScaledVector(_sz,cz);sun.target.position.copy(T);sun.position.copy(T).addScaledVector(_sz,180);sun.target.updateMatrixWorld();}

/* ---------- glitch fixes: labels that blink, name tags through walls ---------- */
function labelsUpdate(){const boxes=[];const order=LABELS.map(L=>[L,camera.position.distanceTo(_v.set(L.x,L.y,L.z))-(L.vis?60:0)]).sort((a,b)=>a[1]-b[1]).map(q=>q[0]);
  for(const L of order){_v.set(L.x,L.y+TH(L.x,L.z),L.z);const d=camera.position.distanceTo(_v);_v.project(camera);let vis=!curRoom&&!PLAYER.ind&&!PLAYER.plat&&!PLAYER.dress&&!PLAYER.dance&&_v.z<1&&d<900&&Math.abs(_v.x)<1.1&&Math.abs(_v.y)<1.1;const sx=(_v.x*.5+.5)*innerWidth,sy=(-_v.y*.5+.5)*innerHeight;
    if(vis){const w=L.name.length*14+20;for(const b of boxes)if(Math.abs(b[0]-sx)<(b[2]+w)/2+4&&Math.abs(b[1]-sy)<28){vis=false;break;}if(vis)boxes.push([sx,sy,w]);}
    if(L.vis!==vis){L.vis=vis;L.el.style.display=vis?'':'none';}if(vis){L.el.style.transform=`translate(-50%,-100%) translate(${sx.toFixed(1)}px,${sy.toFixed(1)}px)`;const op=String(clamp(1.3-d/800,.35,1).toFixed(2));if(L.op!==op){L.op=op;L.el.style.opacity=op;}}}}
function nameTag(text,color){const [c,g]=cvs(320,72);g.font=`900 36px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.lineWidth=7;g.strokeStyle='rgba(0,0,0,.85)';g.strokeText(text,160,38);g.fillStyle=color;g.fillText(text,160,38);
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:ctex(c),depthTest:true,depthWrite:false,transparent:true,fog:false}));s.scale.set(1.9,.43,1);s.position.y=2.3;s.renderOrder=10;return s;}

/* ---------- vehicles: sports car and 7-seater, merged into few draw calls ---------- */
function vehicleModel3(type,color){let m;if(type==='bike')return bikeModel(color);if(type==='sports'||type==='mpv')m=vehicleModelX(type,color);else m=vehicleModel2(type,color);mergeBody(m.body);return m;}
function vehicleModelX(type,color){const g=new THREE.Group(),body=new THREE.Group();g.add(body);let L,W,wr,wx=[];
  const add=(geo,m,x=0,y=0,z=0)=>{const me=new THREE.Mesh(geo,m);me.position.set(x,y,z);me.castShadow=true;me.receiveShadow=true;body.add(me);return me;};
  const dark=std('#16181b',.6,.2),blackT=std('#0d0e10',.5),bump=std('#2a2c2f',.55,.1),chrome=std('#c9ccd0',.25,.9);const pm=paint(color);
  const plate=(z,rear,y=.5)=>add(new THREE.BoxGeometry(.52,.13,.02),std(rear?'#f2c300':'#f4f4f0',.4),0,y,z);
  if(type==='sports'){L=4.42;W=1.9;wr=.34;
    add(profileGeo([[-2.21,.3],[2.21,.3],[2.24,.56],[2.0,.7],[.7,.84],[-1.5,.9],[-2.18,.86],[-2.21,.62]],W,.12),pm);
    add(profileGeo([[.72,.82],[.05,1.2],[-.85,1.21],[-1.42,.9]],W-.3,.06),glassM);
    add(new THREE.BoxGeometry(W-.38,.05,.9),pm,0,1.22,-.4);
    add(new THREE.BoxGeometry(W-.1,.05,.32),dark,0,1.02,-2.02);for(const s of [-1,1])add(new THREE.BoxGeometry(.06,.18,.06),dark,s*.6,.93,-2.0);
    add(new THREE.BoxGeometry(W+.02,.13,.24),bump,0,.36,2.12);add(new THREE.BoxGeometry(W+.02,.13,.24),bump,0,.36,-2.12);add(new THREE.BoxGeometry(W-.6,.1,.04),dark,0,.47,2.22);
    for(const s of [-1,1]){add(new THREE.BoxGeometry(.48,.08,.04),headM,s*(W/2-.32),.6,2.2);add(new THREE.BoxGeometry(.5,.07,.04),tailM,s*(W/2-.3),.72,-2.2);add(new THREE.BoxGeometry(.04,.12,1.2),dark,s*(W/2+.005),.52,.05);add(new THREE.BoxGeometry(.08,.06,.14),pm,s*(W/2+.04),.98,.55);
      add(new THREE.CylinderGeometry(.045,.045,.1,10),chrome,s*.35,.33,-2.24).rotation.x=Math.PI/2;}
    plate(2.25,false,.42);plate(-2.25,true,.5);wx=[[W/2-.12,1.38],[-W/2+.12,1.38],[W/2-.12,-1.3],[-W/2+.12,-1.3]];}
  else{L=4.95;W=1.85;wr=.36;
    add(profileGeo([[-2.47,.36],[2.47,.36],[2.5,.78],[2.3,1.0],[1.55,1.18],[.95,1.88],[-2.35,1.92],[-2.47,1.75]],W,.12),pm);
    add(new THREE.BoxGeometry(W+.02,.62,3.1),glassM,0,1.5,-.55);const ws=add(new THREE.BoxGeometry(W-.18,.7,.05),glassM,0,1.52,1.3);ws.rotation.x=-.75;add(new THREE.BoxGeometry(W-.2,.5,.05),glassM,0,1.5,-2.46);
    for(const z of [-1.55,-.35,.65])for(const s of [-1,1])add(new THREE.BoxGeometry(.03,.62,.12),pm,s*(W/2+.012),1.5,z);
    add(new THREE.BoxGeometry(W-.3,.06,2.6),dark,0,1.95,-.6);for(const s of [-1,1])add(new THREE.BoxGeometry(.05,.06,2.4),chrome,s*.62,2.0,-.6);
    add(new THREE.BoxGeometry(W-.5,.34,.05),chrome,0,.86,2.49);add(new THREE.BoxGeometry(W+.02,.2,.22),bump,0,.48,2.42);add(new THREE.BoxGeometry(W+.02,.2,.22),bump,0,.48,-2.42);
    for(const s of [-1,1]){add(new THREE.BoxGeometry(.38,.15,.04),headM,s*(W/2-.3),.96,2.48);add(new THREE.BoxGeometry(.12,.5,.04),tailM,s*(W/2-.1),1.3,-2.48);add(new THREE.BoxGeometry(.04,.16,L-1.3),blackT,s*(W/2+.005),.5,0);add(new THREE.BoxGeometry(.02,.02,1.1),chrome,s*(W/2+.012),1.1,-1.0);}
    plate(2.53,false,.62);plate(-2.53,true,.7);wx=[[W/2-.13,1.55],[-W/2+.13,1.55],[W/2-.13,-1.5],[-W/2+.13,-1.5]];}
  for(const [x,z] of wx){const w=wheel(wr,.3);w.position.set(x,wr,z);g.add(w);w.userData.front=z>0;}
  return {g,body,L,W,wr,wheels:g.children.filter(c=>c!==body)};}
function mergeBody(body){const groups=new Map();for(const c of body.children){if(!c.isMesh||c.userData.taxiSign||c.material.isMeshBasicMaterial)continue;if(!groups.has(c.material))groups.set(c.material,[]);groups.get(c.material).push(c);}
  for(const [mat,list] of groups){if(list.length<2)continue;const B=new Batch();for(const m of list){m.updateMatrix();const geo=m.geometry.index?m.geometry:m.geometry;if(!geo.attributes.uv)continue;B.geo(geo,m.matrix);body.remove(m);}
    const me=new THREE.Mesh(B.build(),mat);me.castShadow=mat!==glassM;me.receiveShadow=true;body.add(me);}}
function spawnTraffic(cx,cz){for(const r of ROADS)if(r.cls<=3&&r.len>40){const m=posOn(r,r.len/2);if(inWB(m.x,m.z,30))DRIVE.push(r);}
  const colors=['#d9dcdf','#1d2a3a','#7a1f2b','#e7e3da','#2f4f3f','#3b3f46','#b8b9bb','#264d8c','#f1f1ef','#121417'];
  for(let i=0;i<(isMobile?34:60);i++){const rs=pickRoadNear(cx,cz,10,420);if(!rs)continue;const t=rnd();
    const type=t<.26?'taxi':t<.38?'minibus':t<.44?'bus':t<.58?'mpv':t<.66?'sports':'car';
    const col=type==='taxi'?'#c8102e':type==='minibus'?(rnd()<.5?'#1a7f46':'#c8102e'):type==='bus'?'#d21f2a':type==='sports'?pick(['#e8a317','#c8102e','#1f6fd1','#f2f2f2','#17a34a','#111']):type==='mpv'?pick(['#f1f1ef','#121417','#9aa0a6','#2b2f36']):pick(colors);
    const v=spawnVehicle(type,col,0,0,0,{ai:true,cruise:type==='bus'?9:type==='sports'?R(13,16):R(10,13.5),speed:8});placeOnRoad(v,rs[0],rs[1]);}}
function pickRoadNear(cx,cz,minD,maxD){const C=roadsNear(cx,cz,maxD,r=>r.cls<=3&&r.len>40&&DRIVE.includes(r));if(!C.length)return null;for(let tries=0;tries<40;tries++){const r=pick(C);const s=R(0,r.len);const q=posOn(r,s);const d=Math.hypot(q.x-cx,q.z-cz);if(d>minD&&d<maxD&&inWB(q.x,q.z,20))return [r,s];}return null;}

/* ---------- full-screen map: drag, zoom, legend, markers ---------- */
const BM={cx:0,cz:0,zoom:1,pts:new Map(),pinch:0};
const POI_DEF=[['home','家','#ff3d5e','屋企'],['gate','校','#36d6a2','趙中'],['wenkee','文','#ffd23f','文記'],['skewer','串','#ff8a3d','串燒街'],['market','市','#7ec8ff','街市'],['hospital','✚','#ffffff','醫院'],['godown','坤','#b04040','坤記貨倉'],['fisher','釣','#9cd7ff','釣魚佬']];
function toggleMap(){if(!started||modal||PLAYER.dress||PLAYER.dance)return;mapOpen=!mapOpen;$('#bigmap').hidden=!mapOpen;if(mapOpen){const o=PLAYER.car||PLAYER;BM.cx=o.x;BM.cz=o.z;BM.zoom=Math.max(.8,BM.zoom);buildLegend();drawBigMap();}}
function buildLegend(){const items=POI_DEF.filter(p=>LOC[p[0]]).map(p=>`<i style="background:${p[2]}">${p[1]}</i><span>${p[3]}</span>`);items.unshift('<i style="background:#fff;color:#111">▲</i><span>你</span><i style="background:#ffd23f">★</i><span>任務目標</span>');
  items.push('<i style="background:#9a3b26;color:#fff">港</i><span>港鐵站</span><i style="background:#0f2a52;color:#fff">$</i><span>銀行</span><i style="background:#e0a845">餅</i><span>老婆餅 '+(S.cakes?S.cakes.length:0)+'/'+CAKES.length+'</span>');$('#legend').innerHTML=items.join('');}
function drawBigMap(){const c=$('#bigmapc');const dpr=Math.min(2,devicePixelRatio||1);const W=Math.round(innerWidth*dpr),H=Math.round(innerHeight*dpr);if(c.width!==W||c.height!==H){c.width=W;c.height=H;}const g=c.getContext('2d');
  g.setTransform(1,0,0,1,0,0);g.fillStyle='#11141a';g.fillRect(0,0,W,H);const sc=BM.zoom*dpr*.55;
  g.save();g.translate(W/2,H/2);g.scale(sc,sc);g.translate(-BM.cx,-BM.cz);g.imageSmoothingEnabled=true;g.drawImage(MM.big,MM.x0,MM.z0,MM.big.width/MM.s,MM.big.height/MM.s);
  g.strokeStyle='rgba(255,61,94,.75)';g.lineWidth=3/sc*dpr;g.setLineDash([12/sc*dpr,8/sc*dpr]);g.strokeRect(WB.x0,WB.z0,WB.x1-WB.x0,WB.z1-WB.z0);g.setLineDash([]);g.restore();
  const toS=(x,z)=>[W/2+(x-BM.cx)*sc,H/2+(z-BM.cz)*sc];g.textAlign='center';g.textBaseline='middle';
  const boxes=[];const fits=(x,y,w,h)=>{for(const b of boxes)if(Math.abs(b[0]-x)<(b[2]+w)/2&&Math.abs(b[1]-y)<(b[3]+h)/2)return false;boxes.push([x,y,w,h]);return true;};
  const pin=(x,z,col,txt,fg)=>{const [sx,sy]=toS(x,z);const r=12*dpr;g.fillStyle=col;g.beginPath();g.arc(sx,sy,r,0,TAU);g.fill();g.lineWidth=2*dpr;g.strokeStyle='#111';g.stroke();g.fillStyle=fg||'#111';g.font=`900 ${Math.round(12*dpr)}px ${FS}`;g.fillText(txt,sx,sy+1);boxes.push([sx,sy,r*2,r*2]);};
  for(const p of POI_DEF){const L=LOC[p[0]];if(L)pin(L.x,L.z,p[2],p[1],p[0]==='godown'?'#fff':null);}
  for(const st of Object.values(MTR.st))if(st.street)pin(st.street.x,st.street.z,'#9a3b26','港','#fff');
  for(const f of BANKF)pin(f.x+f.n[0]*2,f.z+f.n[2]*2,'#0f2a52','$','#fff');
  if(BM.zoom>.7)for(const c of CAKES)if(!c.got){const [sx,sy]=toS(c.x,c.z);g.fillStyle='#e0a845';g.beginPath();g.arc(sx,sy,4.5*dpr,0,TAU);g.fill();}
  if(BM.zoom>.55){g.font=`900 ${Math.round(13*dpr)}px ${FS}`;for(const L of LABELS){if(L.el.classList.contains('home'))continue;const [sx,sy]=toS(L.x,L.z);const w=g.measureText(L.name).width+10*dpr,h=18*dpr;if(sx<-w||sx>W+w||sy<-h||sy>H+h||!fits(sx,sy-16*dpr,w,h))continue;g.lineWidth=4*dpr;g.strokeStyle='rgba(0,0,0,.75)';g.strokeText(L.name,sx,sy-16*dpr);g.fillStyle='rgba(243,239,230,.92)';g.fillText(L.name,sx,sy-16*dpr);}}
  const t=target();if(t){const [sx,sy]=toS(t.x,t.z);g.font=`900 ${Math.round(30*dpr)}px sans-serif`;g.lineWidth=5*dpr;g.strokeStyle='#111';g.strokeText('★',sx,sy);g.fillStyle='#ffd23f';g.fillText('★',sx,sy);}
  const o=PLAYER.car||PLAYER;const [px,py]=toS(o.x,o.z);g.save();g.translate(px,py);g.rotate(Math.PI-(PLAYER.car?PLAYER.car.h:PLAYER.h));g.fillStyle='#fff';g.strokeStyle='#111';g.lineWidth=3*dpr;g.beginPath();g.moveTo(0,-15*dpr);g.lineTo(10*dpr,11*dpr);g.lineTo(0,5*dpr);g.lineTo(-10*dpr,11*dpr);g.closePath();g.stroke();g.fill();g.restore();
  $('#bmScale').textContent=Math.round(100/(BM.zoom*.55))+' 米';}
function setupBigMap(){const c=$('#bigmapc');
  c.addEventListener('pointerdown',e=>{BM.pts.set(e.pointerId,{x:e.clientX,y:e.clientY});try{c.setPointerCapture(e.pointerId);}catch(_){}if(BM.pts.size===2){const [a,b]=[...BM.pts.values()];BM.pinch=Math.hypot(a.x-b.x,a.y-b.y);}});
  c.addEventListener('pointermove',e=>{const p=BM.pts.get(e.pointerId);if(!p)return;const dx=e.clientX-p.x,dy=e.clientY-p.y;p.x=e.clientX;p.y=e.clientY;
    if(BM.pts.size===2){const [a,b]=[...BM.pts.values()];const d=Math.hypot(a.x-b.x,a.y-b.y);if(BM.pinch)BM.zoom=clamp(BM.zoom*d/BM.pinch,.2,8);BM.pinch=d;return;}BM.cx-=dx/(BM.zoom*.55);BM.cz-=dy/(BM.zoom*.55);});
  const up=e=>{BM.pts.delete(e.pointerId);BM.pinch=0;};c.addEventListener('pointerup',up);c.addEventListener('pointercancel',up);
  c.addEventListener('wheel',e=>{e.preventDefault();BM.zoom=clamp(BM.zoom*(e.deltaY>0?.88:1.14),.2,8);},{passive:false});
  $('#bmIn').onclick=()=>BM.zoom=clamp(BM.zoom*1.4,.2,8);$('#bmOut').onclick=()=>BM.zoom=clamp(BM.zoom/1.4,.2,8);$('#bmCtr').onclick=()=>{const o=PLAYER.car||PLAYER;BM.cx=o.x;BM.cz=o.z;};$('#bmClose').onclick=()=>{if(mapOpen)toggleMap();};
  $('#mini').addEventListener('click',()=>{if(!mapOpen)toggleMap();});$('#hudMap').onclick=()=>toggleMap();}

/* ================= v3 campus: Chiu Lut Sau Memorial Secondary School, rebuilt from the earlier version ================= */
const CX=x=>x+CAMP.OX,CZ=z=>z+CAMP.OZ;
const CBM=new Map();let campusRoot=null;
function cgrp(){if(!campusRoot){campusRoot=new THREE.Group();scene.add(campusRoot);}return campusRoot;}
function boxUV(w,h,d,tw,th){const g=new THREE.BoxGeometry(w,h,d);if(!tw)return g;const uv=g.attributes.uv;const dims=[[d,h],[d,h],[w,d],[w,d],[w,h],[w,h]];for(let f=0;f<6;f++)for(let k=0;k<4;k++){const i=f*4+k;uv.setXY(i,uv.getX(i)*dims[f][0]/tw,uv.getY(i)*dims[f][1]/th);}return g;}
function cb(x0,z0,x1,z1,y0,y1,mat,o={}){const grp=o.parent||cgrp();const key=grp.uuid+'|'+mat.uuid+'|'+(o.cast===false?0:1);let e=CBM.get(key);if(!e){e={B:new Batch(),mat,grp,cast:o.cast!==false};CBM.set(key,e);}
  const w=x1-x0,h=y1-y0,d=z1-z0;const tw=mat.userData&&mat.userData.tw,th=mat.userData&&mat.userData.th;e.B.geo(boxUV(w,h,d,tw,th),new THREE.Matrix4().setPosition(CX((x0+x1)/2),(y0+y1)/2,CZ((z0+z1)/2)));
  if(o.col)addSolidBox(CX(x0),CZ(z0),CX(x1),CZ(z1),o.cy0!=null?o.cy0:y0,o.cy1!=null?o.cy1:y1,{noStand:o.noStand});}
function cSolid(x0,z0,x1,z1,y0,y1,o){return addSolidBox(CX(x0),CZ(z0),CX(x1),CZ(z1),y0,y1,o);}
function cFlat(x0,z0,x1,z1,y,mat,parent){const m=new THREE.Mesh(new THREE.PlaneGeometry(x1-x0,z1-z0),mat);m.rotation.x=-Math.PI/2;m.position.set(CX((x0+x1)/2),y,CZ((z0+z1)/2));m.receiveShadow=true;(parent||cgrp()).add(m);return m;}
function cFlush(){for(const e of CBM.values()){if(!e.B.v)continue;const me=new THREE.Mesh(e.B.build(),e.mat);me.castShadow=e.cast;me.receiveShadow=true;e.grp.add(me);}CBM.clear();}
function cSign(mesh,x,y,z,ry,parent){mesh.position.set(CX(x),y,CZ(z));mesh.rotation.y=ry||0;(parent||cgrp()).add(mesh);return mesh;}
function vText(text,w,h,o={}){const n=text.length;const [c,g]=cvs(160,Math.round(160*h/w));g.fillStyle=o.bg||'#f4f1e6';g.fillRect(0,0,c.width,c.height);if(o.border){g.strokeStyle=o.border;g.lineWidth=8;g.strokeRect(4,4,c.width-8,c.height-8);}
  g.fillStyle=o.fg||'#2a6b4a';const cell=c.height/n;g.font=`900 ${Math.round(Math.min(cell*.82,120))}px ${o.font||FSERIF}`;g.textAlign='center';g.textBaseline='middle';for(let i=0;i<n;i++)g.fillText(text[i],80,cell*(i+.5));
  return new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshStandardMaterial({map:ctex(c),roughness:.6}));}
function plainTex(fn,w=256,h=256,rep=true){const [c,g]=cvs(w,h);fn(g,w,h);return ctex(c,rep);}
function repMat(tex,rx,ry,o={}){const t=tex.clone();t.needsUpdate=true;t.repeat.set(rx,ry);return new THREE.MeshStandardMaterial(Object.assign({map:t,roughness:.5},o));}
const CT={};
function campusTextures(){
  CT.tile=plainTex((g,w,h)=>{g.fillStyle='#d9d4c8';g.fillRect(0,0,w,h);for(let y=0;y<4;y++)for(let x=0;x<4;x++){g.fillStyle=(x+y)%2?'#e4dfd3':'#cfc9bb';g.fillRect(x*64+1,y*64+1,62,62);}});
  CT.wood=plainTex((g,w,h)=>{g.fillStyle='#b98a57';g.fillRect(0,0,w,h);for(let y=0;y<h;y+=32){g.fillStyle=`rgba(80,45,15,${R(.08,.2)})`;g.fillRect(0,y,w,2);for(let k=0;k<6;k++){g.fillStyle=`rgba(255,230,190,${R(.03,.1)})`;g.fillRect(R(0,w),y+R(4,28),R(40,140),2);}}});
  CT.curtain=plainTex((g,w,h)=>{const gr=g.createLinearGradient(0,0,w,0);for(let i=0;i<=8;i++)gr.addColorStop(i/8,i%2?'#7a0d18':'#b3192b');g.fillStyle=gr;g.fillRect(0,0,w,h);});
  CT.court=plainTex((g,w,h)=>{g.fillStyle='#2e6b58';g.fillRect(0,0,w,h);g.fillStyle='#b5523a';g.fillRect(40,30,w-80,h-60);g.strokeStyle='#f2efe6';g.lineWidth=5;g.strokeRect(40,30,w-80,h-60);g.beginPath();g.moveTo(w/2,30);g.lineTo(w/2,h-30);g.stroke();g.beginPath();g.arc(w/2,h/2,58,0,TAU);g.stroke();
    for(const s of [0,1]){const x=s?w-40:40;g.beginPath();g.arc(x,h/2,150,s?Math.PI/2:-Math.PI/2,s?Math.PI*1.5:Math.PI/2);g.stroke();g.strokeRect(s?w-40-110:40,h/2-55,110,110);}},1024,840,false);
  CT.mural=plainTex((g,w,h)=>{const cols=['#e86a12','#2a6fdb','#1d8a4c','#f2c300','#c8102e','#6d1f8f'];g.fillStyle='#f4f1e6';g.fillRect(0,0,w,h);for(let i=0;i<14;i++){g.fillStyle=pick(cols);g.beginPath();g.arc(R(0,w),R(0,h),R(30,90),0,TAU);g.fill();}g.fillStyle='#1d2440';g.font=`900 64px ${FS}`;g.textAlign='center';g.fillText('明善誠新　趙中加油',w/2,h/2+20);},1024,136,false);}

const SCH={FH:3.6,NF:6,rooms:[[-1.7,10],[10,21],[21,32],[32,43]],floors:[],cf:-1,base:'',panic:0,panicOn:false,chars:[],boards:[],roof:null,inner:null,lineT:3,said:{},oldRoof:null,hallRoof:null,ready:false};
const FORM='一二三四五六',CLS='ABCD';
const SUBJ=['中文','英文','數學','通識','物理','化學','生物','經濟','中史','歷史','地理','ICT','體育','音樂','視藝','BAFS'];
const PERIODS=[[540,580,1],[580,620,2],[620,640,'小息'],[640,680,3],[680,720,4],[720,760,5],[760,820,'午飯'],[820,860,6],[860,900,7]];
const MY_SEAT={x:23.2,z:28.75,y:18};const DESK_X=[19.0,20.4,23.2,24.6];
const ANGRY=['喂！你邊班㗎？！而家上緊堂呀！','出去！即刻同我出去！','你唔使上堂㗎？！行出去！','你係咪行錯課室呀？出去！'];
const SCARED=['救命呀！佢有武器呀！','走呀！癲咗喇！','老師救命呀！','媽咪呀！','報警呀！快啲走！'];
function flLabel(f){return f===0?'地下':f+'樓';}
function roomName(f,k){return (f+1)+CLS[k];}
function hm(m){m=Math.floor(m);return String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
function schoolPeriod(){const m=((gameMin%1440)+1440)%1440;for(const p of PERIODS)if(m>=p[0]&&m<p[1]){const L=typeof p[2]==='number';return {lesson:L,n:L?p[2]:0,start:p[0],end:p[1],label:L?'第'+p[2]+'堂':p[2],kind:L?'lesson':'break'};}
  if(m>=450&&m<540)return {lesson:false,label:'未上堂',kind:'pre',end:540};return {lesson:false,label:'放學',kind:'off'};}
function subjOf(f,k,n){return SUBJ[(f*7+k*3+n*5)%SUBJ.length];}
function deskSpots(k){const a=SCH.rooms[k][0],o=[];for(let r=0;r<4;r++)for(let c=0;c<4;c++)o.push([DESK_X[c],a+3.2+r*1.9]);return o;}
const L2W=(x,z)=>({x:CX(x),z:CZ(z)});
function campusLocal(x,z){return [x-CAMP.OX,z-CAMP.OZ];}
function inBlockA(x,z){const [lx,lz]=campusLocal(x,z);return lx>17.3&&lx<31.1&&lz>-1.7&&lz<53.7;}
function inOldBlock(x,z){return false;}
function inHall(x,z){return !!(SCH.hallR&&curRoom===SCH.hallR);}
function HALLW(x,z){const r=ROOMS.hall;return r?{x:x+r.x0-47,z:z+r.z0+52}:L2W(x,z);}

/* a light student/teacher model: few meshes, no shadows */
const liteGeo={torso:new THREE.CylinderGeometry(.21,.18,.6,8),hip:new THREE.CylinderGeometry(.19,.2,.22,8),leg:new THREE.CylinderGeometry(.085,.07,.8,6).translate(0,-.4,0),arm:new THREE.CylinderGeometry(.06,.05,.62,6).translate(0,-.31,0),head:new THREE.SphereGeometry(.15,10,8),hair:new THREE.SphereGeometry(.158,10,6,0,TAU,0,Math.PI*.55),tie:new THREE.BoxGeometry(.06,.3,.02),collar:new THREE.BoxGeometry(.2,.17,.02)};
function litePerson(o){const g=new THREE.Group(),b=new THREE.Group();g.add(b);const skin=std(pick(['#e8bf98','#d9a77f','#f0caa6']),.7),top=std(o.shirt,.85),bot=std(o.pants,.85),hair=std(o.hair||'#141414',.6);
  const P=(geo,m,x,y,z,p=b)=>{const me=new THREE.Mesh(geo,m);me.position.set(x,y,z);p.add(me);return me;};
  P(liteGeo.torso,top,0,1.2,0).scale.z=.72;P(liteGeo.hip,bot,0,.88,0).scale.z=.75;
  const legs=[-1,1].map(s=>{const l=new THREE.Group();l.position.set(s*.1,.86,0);b.add(l);P(liteGeo.leg,o.girl?skin:bot,0,0,0,l);return l;});
  const arms=[-1,1].map(s=>{const a=new THREE.Group();a.position.set(s*.27,1.46,0);a.rotation.z=s*.08;b.add(a);P(liteGeo.arm,top,0,0,0,a);return a;});
  const head=P(liteGeo.head,skin,0,1.68,0);head.scale.set(1,1.1,1);P(liteGeo.hair,hair,0,1.7,-.01);
  if(o.uni){P(liteGeo.collar,std('#f6f6f2',.8),0,1.43,.156);P(liteGeo.tie,std(UNI.tie,.6),0,1.33,.166);if(o.girl){const sk=new THREE.Mesh(new THREE.CylinderGeometry(.2,.31,.44,10),std(UNI.skirt,.85));sk.position.set(0,.73,0);b.add(sk);}}
  if(o.glasses){const gl=new THREE.Mesh(new THREE.BoxGeometry(.26,.05,.02),std('#111',.4));gl.position.set(0,1.7,.15);b.add(gl);}
  scene.add(g);return {g,b,legs,arms,head,ph:R(0,TAU)};}
function seatPose(p,on){if(on){p.b.position.y=-.42;p.legs[0].rotation.x=p.legs[1].rotation.x=-1.45;p.arms[0].rotation.x=p.arms[1].rotation.x=-.7;}else{p.b.position.y=0;p.legs[0].rotation.x=p.legs[1].rotation.x=0;p.arms[0].rotation.x=p.arms[1].rotation.x=0;}}
function studentLite(){const girl=rnd()<.5;return litePerson({shirt:UNI.blazer,pants:UNI.pants,hair:pick(['#121212','#1d1612','#22180f']),girl,uni:true});}
/* bake a posed static figure into shared batches */
const BAKE=new Map();function bakeFigure(p,parent){p.g.updateMatrixWorld(true);p.g.traverse(m=>{if(!m.isMesh)return;const key=(parent||cgrp()).uuid+'|'+m.material.uuid;let e=BAKE.get(key);if(!e){e={B:new Batch(),mat:m.material,grp:parent||cgrp()};BAKE.set(key,e);}e.B.geo(m.geometry,m.matrixWorld);});scene.remove(p.g);}
function bakeFlush(){for(const e of BAKE.values()){if(!e.B.v)continue;const me=new THREE.Mesh(e.B.build(),e.mat);me.castShadow=false;me.receiveShadow=true;e.grp.add(me);}BAKE.clear();}

