function textTexS(text,bg,fg){return cachedTex('tt'+text+bg+fg,()=>{const [c,g]=cvs(512,160);g.fillStyle=bg;g.fillRect(0,0,512,160);g.fillStyle=fg;g.font=`900 96px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.fillText(text,256,84,490);return ctex(c);});}
