    const t=litePerson({shirt:pick(['#dfe8f2','#e8e0cf','#cfe0d8','#f0d8d8']),pants:pick(['#444444','#2b3550','#5a4a3a']),hair:pick(['#2a2a2a','#555555','#111111']),glasses:rnd()<.6,girl:false});
