  const chip=$('#perChip');const show=started&&inCamp(P.x,P.z,4)&&!P.car;if(chip.hidden===show)chip.hidden=!show;const per=schoolPeriod();
  if(show){const t='6C・'+per.label+(per.lesson?' '+subjOf(5,2,per.n):'')+(per.end?'（到 '+hm(per.end)+'）':'');if(chip.textContent!==t)chip.textContent=t;}
  if(pf>=0){const [lx,lz]=campusLocal(P.x,P.z);let pr=-1;if(lx<26.5)for(let k=0;k<4;k++){const [a,b]=SCH.rooms[k];if(lz>a&&lz<b)pr=k;}SCH.pr=pr;SCH.place=pr>=0?roomName(pf,pr)+' 課室・'+flLabel(pf):flLabel(pf)+(lz>43?' 樓梯口':' 走廊');}else SCH.place=pOld?'地下課室':pHall?'學校禮堂':inCamp(P.x,P.z)?'趙聿修紀念中學':null;
  if(!inCamp(P.x,P.z,40)){for(const p of SCH.chars)p.c.g.visible=false;SCH.base='';return;}
  schoolPool();setSchoolFloor(pf>=0?pf:0);
