const HOME_T={bag:[164.1,-38.7],brush:[166.7,-27.9],lift:[141.6,-35],wardrobe:[165.8,-38.2],bed:[165,-44.4]};
function homeAt(k,y){const t=HOME_T[k];return {x:HX(t[0]),z:HZ(t[1]),y:y!=null?y:HOMEP.h};}
function liftRide(txt,done){sfx('ding');fadeTo('𨋢 '+txt,done,1100);}
function homeObjective(){if(!S.flags.bag)return ['拎書包（喺睡房張書枱度）','bag'];if(!S.flags.brush)return ['去廁所刷牙','brush'];return ['出門口搭𨋢落樓','lift'];}
function setupHomeInteracts(){
  INTER.push({at:()=>homeAt('bag'),r:2,label:'拎書包',ok:()=>S.m===0&&!S.flags.bag&&PLAYER.ind==='home',act:()=>{S.flags.bag=true;HOME.bag.visible=false;applyOutfit();toast('拎咗書包，孭好喇');sfx('ding');refreshHomeObj();}});
  INTER.push({at:()=>homeAt('brush'),r:1.8,label:'刷牙',ok:()=>S.m===0&&!S.flags.brush&&PLAYER.ind==='home',act:()=>{if(!S.flags.bag){say([['阿媽','書包都未拎，刷咩牙呀！先拎書包！']]);return;}startBrush();}});
  INTER.push({at:()=>homeAt('lift'),r:1.8,label:'搭𨋢落地下',ok:()=>PLAYER.ind==='home',act:()=>{if(S.m===0&&(!S.flags.bag||!S.flags.brush)){say([['阿媽',!S.flags.bag?'書包呢？！返嚟拎書包！':'未刷牙唔准出門口！']]);return;}
    liftRide('30樓 → 地下',()=>{const h=LOC.home;PLAYER.ind=null;PLAYER.x=h.x+1.5;PLAYER.z=h.z;PLAYER.y=h.y;PLAYER.vy=0;PLAYER.h=Math.PI/2;cam.tx=PLAYER.x;cam.tz=PLAYER.z;cam.ty=PLAYER.y+1.5;cam.yaw=-Math.PI/2;cam.pitch=.25;if(S.m===0){setStep(1);toast('趕返學！對面馬路就係趙中');}});}});
  INTER.push({at:()=>LOC.home,r:2.4,label:'搭𨋢返屋企（30樓）',ok:()=>!PLAYER.car&&!PLAYER.ind,act:()=>liftRide('地下 → 30樓',()=>goHome(false))});
  INTER.push({at:()=>homeAt('wardrobe'),r:1.9,label:'開衣櫃換衫',ok:()=>PLAYER.ind==='home',act:()=>openDress('衣櫃')});
  INTER.push({at:()=>homeAt('bed'),r:2,label:'瞓一覺（去到第二朝）',ok:()=>PLAYER.ind==='home'&&S.m!==0&&(S.free||S.m>=16),act:()=>fadeTo('Zzz…',()=>{gameMin=7*60;S.hp=100;toast('早晨！瞓飽咗');},1600)});}
function goHome(bed){const t=bed?homeAt('bed'):LOC.homeIn;PLAYER.ind='home';PLAYER.x=t.x;PLAYER.z=t.z;PLAYER.y=HOMEP.h;PLAYER.vy=0;PLAYER.grounded=true;PLAYER.h=bed?0:Math.PI/2;cam.tx=t.x;cam.tz=t.z;cam.ty=HOMEP.h+1.55;cam.yaw=bed?Math.PI*.75:-Math.PI/2;cam.pitch=.6;}
function refreshHomeObj(){if(S.m===0)$('#mObj').textContent=homeObjective()[0];}
function homeUpdate(){const P=PLAYER;const ih=!P.car&&!curRoom&&inHome(P.x,P.z,P.y||0);if(ih)P.ind='home';else if(P.ind==='home')P.ind=null;HOME.roof.visible=!ih;}

/* ---------- outfits ---------- */
const OUTFIT_DEF={hair:'short',hairC:'#121212',top:'uni',topC:'#1f2b4d',bot:'pants',botC:'#4f545b',shoeC:'#111111',hat:'none',hatC:'#c8102e',glasses:'none',bag:'back',bagC:'#1d4fa0'};
const DRESS_CATS=[
  {k:'top',n:'上衣',items:[['uni','冬季校服'],['summer','夏季校服'],['tee','T恤'],['hoodie','衛衣'],['shirt','恤衫'],['jacket','飛機褸']],col:'topC',cols:['#1f2b4d','#f4f4f0','#111111','#c8102e','#2e86de','#27ae60','#f1c40f','#e67e22','#8e44ad','#7f8c8d']},
  {k:'bot',n:'褲／裙',items:[['pants','長褲'],['jeans','牛仔褲'],['shorts','短褲'],['skirt','校裙']],col:'botC',cols:['#4f545b','#2b3550','#111111','#e9e4da','#5d4b3a','#3b5b8c','#7a1f2b']},
  {k:'hair',n:'髮型',items:[['short','短髮'],['long','長髮'],['spiky','刺蝟頭'],['bun','丸子頭'],['bald','光頭']],col:'hairC',cols:['#121212','#3a2416','#7a4a22','#d9b45a','#c8102e','#2e5fb5','#e8e8e8']},
  {k:'hat',n:'帽',items:[['none','冇帽'],['cap','鴨舌帽'],['bucket','漁夫帽'],['beanie','冷帽']],col:'hatC',cols:['#c8102e','#111111','#f4f4f0','#1d4fa0','#f1c40f','#27ae60']},
  {k:'glasses',n:'眼鏡',items:[['none','冇'],['round','圓框眼鏡'],['sun','太陽眼鏡']]},
  {k:'bag',n:'袋',items:[['none','冇'],['back','書包'],['sling','斜孭袋']],col:'bagC',cols:['#1d4fa0','#111111','#c8102e','#f1c40f','#27ae60','#e67e22']},
  {k:'shoe',n:'鞋',items:[['s','波鞋']],col:'shoeC',cols:['#111111','#f4f4f0','#c8102e','#1d4fa0','#f1c40f','#7a4a22']}];
function buildOutfitModel(o){o=Object.assign({},OUTFIT_DEF,o||{});const topC=o.top==='uni'?UNI.blazer:o.top==='summer'?'#f4f4f0':o.topC;const botC=o.bot==='jeans'?(o.botC==='#4f545b'?'#3b5b8c':o.botC):o.bot==='skirt'?UNI.skirt:o.botC;
  const p=person({shirt:topC,pants:botC,hair:o.hairC,long:false,bag:null,shoe:o.shoeC,skin:'#e8bf98'});const B=p.b;const ch=B.children;const torso=ch[0],head=ch[6],hairM=ch[7];const skin=head.material;
  const add=(geo,m,x,y,z,parent=B)=>{const me=new THREE.Mesh(geo,m);me.position.set(x,y,z);me.castShadow=true;parent.add(me);return me;};
  const sleeves=short=>{for(const a of p.arms){a.children[0].material=short?skin:std(topC,.85);if(short)add(new THREE.CylinderGeometry(.075,.068,.24,8).translate(0,-.12,0),std(topC,.85),0,0,0,a);}};
  if(o.top==='uni'){add(new THREE.BoxGeometry(.2,.17,.02),std('#f6f6f2',.8),0,1.43,.156);for(const s of [-1,1]){const l=add(new THREE.BoxGeometry(.06,.3,.02),std('#16203a',.7),s*.08,1.36,.16);l.rotation.z=s*.32;}add(new THREE.BoxGeometry(.06,.3,.02),std(UNI.tie,.6),0,1.33,.166);add(new THREE.BoxGeometry(.075,.085,.02),std(UNI.badge,.4,.3),-.1,1.32,.16);}
  else if(o.top==='summer'){sleeves(true);add(new THREE.BoxGeometry(.2,.06,.02),std('#f6f6f2',.8),0,1.47,.15);add(new THREE.BoxGeometry(.05,.28,.02),std(UNI.tie,.6),0,1.33,.157);add(new THREE.BoxGeometry(.075,.085,.02),std(UNI.badge,.4,.3),-.1,1.32,.152);}
  else if(o.top==='tee'){sleeves(true);const [c,g]=cvs(128,128);g.fillStyle=topC;g.fillRect(0,0,128,128);g.fillStyle=topC==='#f4f4f0'?'#c8102e':'#ffffff';g.font=`900 52px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.fillText('元朗',64,66);const pl=add(new THREE.PlaneGeometry(.26,.26),new THREE.MeshStandardMaterial({map:ctex(c),roughness:.8}),0,1.22,.158);}
  else if(o.top==='hoodie'){const hood=add(new THREE.TorusGeometry(.15,.06,6,12,Math.PI),std(topC,.9),0,1.5,-.08);hood.rotation.x=Math.PI/2+.3;add(new THREE.BoxGeometry(.24,.12,.03),std(topC,.9),0,1.04,.16);for(const s of [-1,1])add(new THREE.BoxGeometry(.012,.16,.012),std('#f4f4f0',.6),s*.05,1.34,.16);}
  else if(o.top==='shirt'){add(new THREE.BoxGeometry(.22,.07,.03),std(topC,.7),0,1.47,.13);for(let k=0;k<4;k++)add(new THREE.BoxGeometry(.018,.018,.01),std('#ddd',.4),0,1.38-k*.1,.158);}
  else if(o.top==='jacket'){const j=add(new THREE.CylinderGeometry(.23,.2,.58,10,1,true,.35,TAU-.7),std(topC,.6),0,1.2,0);j.scale.z=.75;j.material.side=THREE.DoubleSide;torso.material=std('#f4f4f0',.85);add(new THREE.TorusGeometry(.13,.035,6,12),std(topC,.6),0,1.5,0).rotation.x=Math.PI/2;
    for(const a of p.arms)a.children[0].material=std(topC,.6);}
  if(o.bot==='shorts'||o.bot==='skirt'){for(const l of p.legs){l.children[0].material=skin;if(o.bot==='shorts')add(new THREE.CylinderGeometry(.1,.095,.34,8).translate(0,-.17,0),std(botC,.85),0,0,0,l);}if(o.bot==='skirt'){const sk=add(new THREE.CylinderGeometry(.2,.31,.44,14),std(botC,.85),0,.73,0);}}
  if(o.hair==='bald')hairM.visible=false;else if(o.hair==='long')add(new THREE.BoxGeometry(.3,.38,.1),hairM.material,0,1.55,-.12);
  else if(o.hair==='spiky'){for(let k=0;k<7;k++){const a=k/7*TAU;const c=add(new THREE.ConeGeometry(.05,.16,5),hairM.material,Math.cos(a)*.08,1.84,Math.sin(a)*.08-.02);c.rotation.set(Math.sin(a)*.5,0,-Math.cos(a)*.5);}}
  else if(o.hair==='bun')add(new THREE.SphereGeometry(.075,10,8),hairM.material,0,1.85,-.09);
  if(o.hat==='cap'){add(new THREE.SphereGeometry(.165,14,8,0,TAU,0,Math.PI*.5),std(o.hatC,.6),0,1.74,0);add(new THREE.BoxGeometry(.24,.025,.16),std(o.hatC,.6),0,1.76,.17);}
  else if(o.hat==='bucket'){add(new THREE.CylinderGeometry(.14,.16,.12,14),std(o.hatC,.8),0,1.83,0);add(new THREE.CylinderGeometry(.26,.26,.02,16),std(o.hatC,.8),0,1.77,0);}
  else if(o.hat==='beanie'){add(new THREE.SphereGeometry(.17,14,8,0,TAU,0,Math.PI*.55),std(o.hatC,.9),0,1.73,0).scale.y=1.15;add(new THREE.SphereGeometry(.045,8,6),std('#f4f4f0',.9),0,1.94,0);}
  if(o.glasses==='round'){for(const s of [-1,1]){const r=add(new THREE.TorusGeometry(.045,.008,6,14),std('#222',.4,.4),s*.06,1.7,.15);}add(new THREE.BoxGeometry(.04,.008,.008),std('#222',.4),0,1.71,.155);}
  else if(o.glasses==='sun'){add(new THREE.BoxGeometry(.26,.06,.02),std('#0b0b0b',.1,.6),0,1.7,.155);}
  if(o.bag==='back')add(new THREE.BoxGeometry(.32,.4,.16),std(o.bagC,.7),0,1.2,-.22);
  else if(o.bag==='sling'){const st=add(new THREE.BoxGeometry(.035,.62,.02),std('#222',.6),0,1.25,.165);st.rotation.z=.75;add(new THREE.BoxGeometry(.2,.16,.08),std(o.bagC,.7),.2,.98,.1);}
  return p;}
function applyOutfit(){const P=PLAYER;const old=P.p;const o=Object.assign({},S.outfit);if(S.m===0&&!S.flags.bag)o.bag='none';const np=buildOutfitModel(o);if(old){np.g.position.copy(old.g.position);np.g.rotation.y=old.g.rotation.y;scene.remove(old.g);}P.p=np;np.g.visible=!P.car&&P.riding!=='mtr';setupWeapons();updateWeapon();applyBody(np);}
function toggleOutfit(){openDress('時裝店');}

/* ---------- dressing mode ---------- */
const DR={cat:0,spin:0,yaw:0,orig:null,cx:0,cz:0};
function openDress(where){if(PLAYER.car)return;const P=PLAYER;DR.orig=JSON.parse(JSON.stringify(S.outfit));DR.where=where;
  if(P.ind==='home'){const c={x:HX(164.6),z:HZ(-42.5)};P.x=c.x;P.z=c.z;P.y=HOMEP.h;DR.yaw=-Math.PI/2;}else{DR.yaw=cam.yaw+Math.PI;}
  P.vx=P.vz=0;P.dress=true;DR.spin=0;document.body.classList.add('dressing');$('#dress').hidden=false;renderDress();voice('dress');}
function closeDress(keep){const P=PLAYER;if(!keep&&DR.orig){S.outfit=DR.orig;applyOutfit();}P.dress=false;document.body.classList.remove('dressing');$('#dress').hidden=true;camera.clearViewOffset();cam.yaw=DR.yaw;cam.pitch=.5;save();if(keep)toast('換好衫喇！');}
function renderDress(){const cat=DRESS_CATS[DR.cat];const o=S.outfit;
  $('#dTabs').innerHTML=DRESS_CATS.map((c,i)=>`<button class="dtab${i===DR.cat?' on':''}" data-cat="${i}">${c.n}</button>`).join('');
  const curK=cat.k==='shoe'?'s':o[cat.k];
  $('#dItems').innerHTML=cat.items.map(([id,n])=>`<button class="ditem${curK===id?' on':''}" data-item="${id}"><span class="dic">${dressIcon(cat.k,id)}</span><span>${n}</span></button>`).join('');
  $('#dCols').innerHTML=cat.col?cat.cols.map(c=>`<button class="dcol${o[cat.col]===c?' on':''}" data-col="${c}" style="background:${c}" aria-label="顏色 ${c}"></button>`).join(''):'';
  $('#dCols').hidden=!cat.col||(cat.k==='top'&&(o.top==='uni'||o.top==='summer'))||(cat.k==='bot'&&o.bot==='skirt')||(cat.k==='hat'&&o.hat==='none')||(cat.k==='bag'&&o.bag==='none')||(cat.k==='hair'&&o.hair==='bald');}
function dressIcon(k,id){const m={top:{uni:'🧥',summer:'👔',tee:'👕',hoodie:'🧥',shirt:'👔',jacket:'🧥'},bot:{pants:'👖',jeans:'👖',shorts:'🩳',skirt:'👗'},hair:{short:'💇',long:'💁',spiky:'🦔',bun:'🍡',bald:'🥚'},hat:{none:'✖',cap:'🧢',bucket:'👒',beanie:'🧶'},glasses:{none:'✖',round:'👓',sun:'🕶️'},bag:{none:'✖',back:'🎒',sling:'👜'},shoe:{s:'👟'}};return (m[k]&&m[k][id])||'•';}
function setupDress(){const d=$('#dress');
  d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const cat=DRESS_CATS[DR.cat];
    if(b.dataset.cat){DR.cat=+b.dataset.cat;renderDress();return;}
    if(b.dataset.item){if(cat.k!=='shoe')S.outfit[cat.k]=b.dataset.item;applyOutfit();renderDress();sfx('ding',.4);return;}
    if(b.dataset.col){S.outfit[cat.col]=b.dataset.col;applyOutfit();renderDress();return;}
    if(b.id==='dRand'){for(const c of DRESS_CATS){if(c.k!=='shoe')S.outfit[c.k]=pick(c.items)[0];if(c.col)S.outfit[c.col]=pick(c.cols);}applyOutfit();renderDress();sfx('ding',.4);return;}
    if(b.id==='dReset'){S.outfit=Object.assign({},OUTFIT_DEF);applyOutfit();renderDress();return;}
    if(b.id==='dDone'){closeDress(true);return;}if(b.id==='dCancel'){closeDress(false);return;}});
  let drag=null;const cv=$('#gl');cv.addEventListener('pointerdown',e=>{if(PLAYER.dress)drag={x:e.clientX};});addEventListener('pointermove',e=>{if(drag&&PLAYER.dress){DR.spin+=(e.clientX-drag.x)*.012;drag.x=e.clientX;DR.held=1.5;}});addEventListener('pointerup',()=>{drag=null;});
  for(const [id,s] of [['dRotL',-1],['dRotR',1]])$('#'+id).addEventListener('pointerdown',e=>{e.preventDefault();DR.spin+=s*Math.PI/4;DR.held=2;});
  addEventListener('keydown',e=>{if(!PLAYER.dress)return;if(e.code==='Escape')closeDress(false);if(e.code==='ArrowLeft'){DR.spin-=.3;DR.held=2;}if(e.code==='ArrowRight'){DR.spin+=.3;DR.held=2;}});}
function dressCam(dt){const P=PLAYER;if((DR.held||0)>0)DR.held-=dt;else DR.spin+=dt*.5;P.h=DR.yaw+DR.spin;const a=DR.yaw;const port=innerWidth<=760;const d=port?(innerHeight>innerWidth?5.4:3.6):2.9;
  camera.position.set(P.x+Math.sin(a)*d,(P.y||0)+1.3,P.z+Math.cos(a)*d);camera.lookAt(P.x,(P.y||0)+1.0,P.z);if(Math.abs(camera.fov-50)>.1){camera.fov=50;camera.updateProjectionMatrix();}
  const W=innerWidth,H=innerHeight;if(W>760)camera.setViewOffset(W,H,Math.round(W*.2),0,W,H);else camera.setViewOffset(W,H,0,Math.round(H*.25),W,H);
  sky.position.copy(camera.position);stars.position.copy(camera.position);}

/* ================= v3 fx: kung-fu moves, somersault, Cantonese voice ================= */
const KF={combo:0,t:0,lock:0,lunge:0,anim:null,pend:null,guard:0};
function attack(){if(dlgQ||modal||busy||PLAYER.car||!started||PLAYER.dress||PLAYER.dance||PLAYER.seated||mapOpen||PLAYER.brushT>0)return;if(atkCd>0){KF.buf=true;return;}KF.buf=false;
  const w=WEAPONS[S.wpn];const air=PLAYER.grounded===false;let mv;
  if(w.gun)mv={k:'gun',dur:.25,cd:w.cd,dmg:w.dmg,range:w.range,at:.02};
  else if(w.id!=='fist')mv={k:'swing',dur:.36,cd:w.cd,dmg:w.dmg,range:w.range,at:.16,lunge:.3};
  else if(air)mv={k:'fly',dur:.5,cd:.45,dmg:42,range:2.6,at:.12,lunge:2.4,say:'飛踢！',kb:2};
  else{KF.combo=KF.t>0?(KF.combo+1)%4:0;mv=[{k:'jab',dur:.22,cd:.2,dmg:16,range:1.9,at:.08,lunge:.3,say:'喝！'},{k:'cross',dur:.26,cd:.24,dmg:22,range:2.0,at:.1,lunge:.45,say:'哈！'},{k:'kick',dur:.42,cd:.36,dmg:32,range:2.5,at:.16,lunge:.55,say:'呀打！',kb:1.6},{k:'palm',dur:.5,cd:.55,dmg:46,range:2.3,at:.2,lunge:1.0,say:'睇招！',kb:2.6}][KF.combo];}
  KF.anim={k:mv.k,t:0,dur:mv.dur,combo:KF.combo};KF.t=.8;KF.guard=4;atkCd=mv.cd;KF.lunge=mv.lunge||0;if(mv.k==='fly'){PLAYER.vy=Math.max(PLAYER.vy,1.5);}
  sfx(w.gun?'gun':'swing');if(mv.say&&(mv.k!=='jab'||rnd()<.5))voice('shout',mv.say);
  // pick a target and face it
  const cands=[...FIGHT.filter(f=>f.hp>0),...COPS.filter(c=>c.down<=0),...peds.filter(p=>!(p.down>0)&&p.g.visible),...(typeof extraTargets==='function'?extraTargets():[])];let tgt=null,td=w.gun?w.range:3.2;
  const fx=Math.sin(PLAYER.h),fz=Math.cos(PLAYER.h);for(const t of cands){const tx=t.g.position.x,tz=t.g.position.z;if(Math.abs(t.g.position.y-(PLAYER.y||0))>2.2)continue;const dx=tx-PLAYER.x,dz=tz-PLAYER.z,d=Math.hypot(dx,dz);if(d>td)continue;if(w.gun&&(dx*fx+dz*fz)/(d||1)<.8)continue;td=d;tgt=t;}
  if(tgt)PLAYER.h=Math.atan2(tgt.g.position.x-PLAYER.x,tgt.g.position.z-PLAYER.z);
  KF.pend={t:mv.at,mv,tgt};if(inCamp(PLAYER.x,PLAYER.z,2)&&(w.id!=='fist'||rnd()<.3))schoolScare();}
function kfResolve(){const {mv,tgt}=KF.pend;KF.pend=null;if(!tgt)return;const d=Math.hypot(tgt.g.position.x-PLAYER.x,tgt.g.position.z-PLAYER.z);if(d>mv.range+.4)return;
  hitTarget(tgt,Math.round(mv.dmg*powMul()));bodyChange(-.0005,.0015,true);if(mv.kb&&FIGHT.includes(tgt)){tgt.kx*=mv.kb;tgt.kz*=mv.kb;}shake=Math.max(shake,mv.k==='palm'||mv.k==='fly'?.22:.1);hitFx(tgt.g.position.x,(tgt.g.position.y||0)+1.3,tgt.g.position.z,mv.k);}
const HITFX=[];let hitTexs=null;
function hitFx(x,y,z,k){if(!hitTexs){hitTexs=['啪！','砰！','嘭！','咚！'].map(t=>{const [c,g]=cvs(256,128);g.font=`900 84px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.lineWidth=12;g.strokeStyle='#1a0d00';g.strokeText(t,128,66);const gr=g.createLinearGradient(0,20,0,110);gr.addColorStop(0,'#fff6b0');gr.addColorStop(1,'#ff9a1f');g.fillStyle=gr;g.fillText(t,128,66);return ctex(c);});
    const [c,g]=cvs(128,128);const gr=g.createRadialGradient(64,64,0,64,64,64);gr.addColorStop(0,'rgba(255,255,230,1)');gr.addColorStop(.35,'rgba(255,220,120,.8)');gr.addColorStop(1,'rgba(255,160,40,0)');g.fillStyle=gr;g.fillRect(0,0,128,128);hitTexs.burst=ctex(c);}
  const b=new THREE.Sprite(new THREE.SpriteMaterial({map:hitTexs.burst,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false}));b.position.set(x,y,z);b.scale.set(.6,.6,1);scene.add(b);HITFX.push({m:b,t:.25,max:.25,burst:true});
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:pick(hitTexs),transparent:true,depthWrite:false,depthTest:false,toneMapped:false}));s.position.set(x+R(-.3,.3),y+.6,z);s.scale.set(1.3,.65,1);s.renderOrder=11;scene.add(s);HITFX.push({m:s,t:.6,max:.6});}
function hitFxUpdate(dt){for(let i=HITFX.length-1;i>=0;i--){const f=HITFX[i];f.t-=dt;const u=1-f.t/f.max;if(f.burst){const k=.6+u*2.2;f.m.scale.set(k,k,1);f.m.material.opacity=1-u;}else{f.m.position.y+=dt*1.2;f.m.material.opacity=Math.min(1,f.t*3);}if(f.t<=0){scene.remove(f.m);f.m.material.dispose();HITFX.splice(i,1);}}}
function kfUpdate(dt){if(KF.t>0)KF.t-=dt;if(KF.lock>0)KF.lock-=dt;if(KF.guard>0)KF.guard-=dt;if(KF.anim){KF.anim.t+=dt;if(KF.pend&&KF.anim.t>=KF.pend.t)kfResolve();if(KF.anim.t>=KF.anim.dur)KF.anim=null;}else if(KF.pend)kfResolve();if(KF.buf&&atkCd<=0)attack();hitFxUpdate(dt);}
/* player body pose on top of the walk cycle */
function playerPose(dt){const P=PLAYER,p=P.p;if(!p||P.car)return;const b=p.b,L=p.legs,A=p.arms;
  if(P.seated){seatPose(p,true);return;}
  if(P.dress){b.rotation.set(0,0,0);b.position.set(0,0,0);for(const q of [...L,...A])q.rotation.x=0;A[0].rotation.x=Math.sin(performance.now()/700)*.08;A[1].rotation.x=-Math.sin(performance.now()/700)*.08;return;}
  b.rotation.set(0,0,0);b.position.z=0;if(P.bikePose){P.bikePose=false;b.position.y=0;for(const q of [...L,...A])q.rotation.z=0;}
  if(P.swim){const t=performance.now()/1000,mv=P.spd>.4;b.rotation.x=mv?.55:.1;b.position.z=mv?.3:0;A[0].rotation.x=mv?-Math.PI-Math.sin(t*5)*1.6:-1.4+Math.sin(t*3)*.4;A[1].rotation.x=mv?-Math.PI+Math.sin(t*5)*1.6:-1.4-Math.sin(t*3)*.4;A[0].rotation.z=-.3;A[1].rotation.z=.3;L[0].rotation.x=Math.sin(t*8)*.4;L[1].rotation.x=-Math.sin(t*8)*.4;return;}
  if(P.grounded===false){L[0].rotation.x=-.65;L[1].rotation.x=.35;A[0].rotation.x=-.9;A[1].rotation.x=.4;}
  if(P.flip>0){P.flip=Math.min(1,P.flip+dt/.55);const a=P.flip*TAU,c=.95;b.rotation.x=a;b.position.y=c-c*Math.cos(a);b.position.z=-c*Math.sin(a);L[0].rotation.x=L[1].rotation.x=-1.35;A[0].rotation.x=A[1].rotation.x=-1.1;if(P.flip>=1)P.flip=0;return;}
  const an=KF.anim;
  if(an){const u=clamp(an.t/an.dur,0,1),e=Math.sin(u*Math.PI);
    if(an.k==='jab'){A[0].rotation.x=-1.55*e-.3;A[1].rotation.x=-.9;b.rotation.y=.35*e;}
    else if(an.k==='cross'){A[1].rotation.x=-1.6*e-.3;A[0].rotation.x=-.9;b.rotation.y=-.4*e;}
    else if(an.k==='kick'){L[1].rotation.x=-1.55*e;L[0].rotation.x=.15*e;b.rotation.x=-.22*e;A[0].rotation.x=-1.0;A[1].rotation.x=-.4;b.rotation.y=-.2*e;}
    else if(an.k==='palm'){A[0].rotation.x=A[1].rotation.x=-1.5*e-.2;b.rotation.x=.18*e;L[0].rotation.x=-.5*e;L[1].rotation.x=.4*e;}
    else if(an.k==='fly'){L[1].rotation.x=-1.45;L[0].rotation.x=.7;A[0].rotation.x=.9;A[1].rotation.x=.6;b.rotation.x=-.32;}
    else if(an.k==='swing'){A[1].rotation.x=-2.7+2.4*u;b.rotation.y=-.3*e;}
    else if(an.k==='gun'){A[1].rotation.x=-1.55;}}
  else if(KF.guard>0&&P.grounded!==false&&WEAPONS[S.wpn].id==='fist'){const s=Math.min(1,KF.guard);A[0].rotation.x=lerp(A[0].rotation.x,-1.1,s);A[1].rotation.x=lerp(A[1].rotation.x,-.75,s);}}

/* ---------- Cantonese voice (device speech engine) ---------- */
const VOICE={ok:typeof speechSynthesis!=='undefined'&&typeof SpeechSynthesisUtterance!=='undefined',v:null,on:true,warned:false,lastShout:0};
const VPARAM={'阿媽':[1.08,1.14],'新聞主播':[.95,.92],'鄧Sir':[.85,1.1],'Miss邱':[1.2,1.1],'陳Sir':[.9,1],'校長':[.75,.9],'訓導主任':[.8,1.1],'門口阿Sir':[.95,1],'阿明':[1.2,1.12],'阿明（電話）':[1.2,1.12],'流浮山刀手':[.85,1.15],'坤哥':[.6,.92],'黃Sir':[.7,.95],'婆婆':[1.5,.85],'文記老闆':[.9,1.05],'魚販':[1,1.05],'釣魚佬':[.85,.95],'你':[1.1,1.1],'旁白':[1,1],'老師':[.95,1.05],'同學':[1.3,1.2],'客人':[1.1,1.1],'差佬':[.8,1.05],'港鐵職員':[1.05,1],'車站廣播':[1.1,.95],'櫃位職員':[1.2,1]};
function pickVoice(){if(!VOICE.ok)return;const vs=speechSynthesis.getVoices();VOICE.v=vs.find(v=>/^(zh[-_]HK|yue)/i.test(v.lang))||vs.find(v=>/cantonese|粵|廣東|hong kong/i.test(v.name))||null;VOICE.list=vs.length;}
if(VOICE.ok){pickVoice();try{speechSynthesis.onvoiceschanged=pickVoice;}catch(e){}}
function speak(text,pitch=1,rate=1,interrupt=true,vol=1){if(!VOICE.ok||!VOICE.on||AU.muted||TEST)return;const t=String(text).replace(/（[^）]*）/g,'').replace(/\([^)]*\)/g,'').replace(/[…]+/g,'，').trim();if(!t||/^[，。！？、\s]*$/.test(t))return;
  try{if(interrupt)speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='zh-HK';if(VOICE.v)u.voice=VOICE.v;u.pitch=clamp(pitch,.1,2);u.rate=clamp(rate,.5,1.6);u.volume=vol;speechSynthesis.speak(u);
    if(!VOICE.v&&!VOICE.warned&&VOICE.list){VOICE.warned=true;toast('你部機未裝廣東話語音，會用預設聲音讀');}}catch(e){}}
const VOICED=new Set(['細路仔阿仔','鄧Sir','Miss邱','阿媽','陳Sir','校長','訓導主任','門口阿Sir','阿明','阿明（電話）','流浮山刀手','坤哥','黃Sir','婆婆','文記老闆','魚販','釣魚佬','鄧Sir','Miss邱','你']);
function voiceLine(who,text){if(!VOICED.has(who))return;const p=VPARAM[who]||[R(.85,1.25),1.05];speak(text,p[0],p[1],true);}
function voice(kind,text){const now=performance.now();
  if(kind==='shout'){if(now-VOICE.lastShout<350)return;VOICE.lastShout=now;speak(text,1.15,1.35,true,.9);}
  else if(kind==='flip')speak(pick(['嘿！','睇我！','哈！']),1.2,1.4,true,.8);
  else if(kind==='hurt'){if(now-VOICE.lastShout<900)return;VOICE.lastShout=now;speak(pick(['哎呀！','好痛呀！','嘩！']),1.1,1.3,true,.9);}
  else if(kind==='steal')speak(pick(['借你架車用吓！','落車！我趕時間！','唔好意思呀大佬！']),1.1,1.25,true);
  else if(kind==='dress')speak(pick(['換套新衫先！','今日著咩好呢？']),1.1,1.1,true,.8);
  else if(kind==='cake')speak(pick(['嘩，老婆餅！','又搵到一個老婆餅！']),1.15,1.2,true,.9);
  else if(kind==='busted')speak('唔好拉我呀！',1.1,1.3,true);}
function toggleVoice(){VOICE.on=!VOICE.on;if(!VOICE.on&&VOICE.ok)try{speechSynthesis.cancel();}catch(e){}$('#tVoice').textContent=VOICE.on?'語音：開':'語音：關';toast(VOICE.on?'廣東話語音：開':'廣東話語音：關');if(VOICE.on)voiceLine('你','語音開咗喇！');}

addEventListener('pointerdown',function unlockTTS(){if(VOICE.ok&&!TEST){try{const u=new SpeechSynthesisUtterance(' ');u.volume=0;u.lang='zh-HK';speechSynthesis.speak(u);}catch(e){}}removeEventListener('pointerdown',unlockTTS);});

/* ================= v3 street life: skewer street beside Yuen Long Plaza, 老婆餅 hunt, fishing, taxi job ================= */
const LANE_ROOT={g:null,smoke:[],lanterns:[]};
function wbox(x0,z0,x1,z1,y0,y1,mat,o={}){const grp=LANE_ROOT.g;const key=grp.uuid+'|'+mat.uuid;let e=CBM.get(key);if(!e){e={B:new Batch(),mat,grp,cast:o.cast!==false};CBM.set(key,e);}
  e.B.geo(new THREE.BoxGeometry(x1-x0,y1-y0,z1-z0),new THREE.Matrix4().setPosition((x0+x1)/2,(y0+y1)/2,(z0+z1)/2));if(o.col)addSolidBox(x0,z0,x1,z1,y0,y1);}
function buildSkewerStreet(){LANE_ROOT.g=new THREE.Group();scene.add(LANE_ROOT.g);const G=LANE_ROOT.g;
  const steel=std('#b9b9b4',.3,.6),dark=std('#2a2622',.7),wood=std('#7a5232',.6),grillM=new THREE.MeshStandardMaterial({color:lin('#331a10'),emissive:lin('#ff5a1a'),emissiveIntensity:1.3,roughness:.6});GLOW.push(grillM);
  const awn=['#c8102e','#1d4fa0','#e86a12','#0f7a4c','#6d1f8f','#b3121f'].map(c=>std(c,.7));
  const foods=['魚蛋','燒賣','雞翼','腸仔','牛丸','串燒','車仔麵','碗仔翅','雞蛋仔','煎釀三寶','臭豆腐','蛋撻'];
  const xc=LANE.xc;
  const zs=[-13,-21.5,-30,-38.5,-47,-55.5];
  LOC.skewer=null;
  const X2=(a,b)=>[Math.min(a,b),Math.max(a,b)];
  for(const side of [-1,1]){for(let i=0;i<zs.length;i++){const z=zs[i];const n=side<0?1:-1;const rear=side<0?LANE.x0+.15:LANE.x1-.15,front=rear+n*2.2;const granny=side<0&&i===2;
      let q=X2(front-n*.9,front);wbox(q[0],z-2.8,q[1],z+2.8,0,1.05,steel,{col:true});
      q=X2(rear,rear+n*.5);wbox(q[0],z-2.8,q[1],z+2.8,0,2.2,dark,{col:true});
      q=X2(front-n*.8,front-n*.15);wbox(q[0],z-2.4,q[1],z+2.4,1.05,1.12,grillM,{cast:false});
      const aw=awn[(i*2+(side>0?1:0))%awn.length];q=X2(rear,front+n*.9);wbox(q[0],z-3.1,q[1],z+3.1,2.62,2.74,granny?std('#ffd23f',.6):aw);
      for(const dz of [-2.9,2.9])wbox(front+n*.8-.05,z+dz-.05,front+n*.8+.05,z+dz+.05,0,2.62,dark,{cast:false});
      const sg=textPlane(granny?'婆婆串燒':foods[(i*3+(side>0?5:0))%foods.length],2.6,.62,{bg:granny?'#c8102e':'#111',fg:granny?'#fff':'#ffd23f',glow:true});sg.position.set(front+n*.86,2.28,z);sg.rotation.y=n>0?Math.PI/2:-Math.PI/2;G.add(sg);
      for(let k=0;k<6;k++){const m=new THREE.Mesh(new THREE.CylinderGeometry(.03,.03,.7,4),std('#d9a066',.7));m.position.set(front-n*.48,1.17,z-1.8+k*.7);m.rotation.z=Math.PI/2;m.rotation.y=R(-.2,.2);G.add(m);const ball=new THREE.Mesh(new THREE.SphereGeometry(.07,6,5),std(pick(['#e8b04a','#d9534f','#c97a2b','#7a5230']),.6));ball.position.copy(m.position);G.add(ball);}
      LANE_ROOT.smoke.push({x:front-n*.48,z,y:1.4});
      if(granny){LOC.skewer={x:front+n*1.4,z};LOC.skH=Math.atan2(-n,0);LOC.grannyPos={x:rear+n*.95,z};}
      else{const cook=litePerson({shirt:pick(['#f4f4f0','#c8102e','#2a3a5a','#e8d6b0']),pants:'#333',hair:pick(['#222','#777','#ccc'])});cook.g.position.set(rear+n*.95,0,z+R(-1,1));cook.g.rotation.y=n>0?Math.PI/2:-Math.PI/2;LANE_ROOT.cooks=(LANE_ROOT.cooks||[]).concat(cook);}
      if(rnd()<.75){const c=litePerson({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47','#8e44ad']),pants:pick(['#2b3550','#222','#5d4b3a']),girl:rnd()<.4,uni:false});c.g.position.set(front+n*R(1.1,1.5),0,z+R(-2,2));c.g.rotation.y=n>0?-Math.PI/2:Math.PI/2;LANE_ROOT.cust=(LANE_ROOT.cust||[]).concat(c);}}}
  // entrance arch from Castle Peak Road
  const za=-7.5;wbox(LANE.x0-.2,za-.3,LANE.x0+.4,za+.3,0,6,std('#7a1010',.6),{col:true});wbox(LANE.x1-.4,za-.3,LANE.x1+.2,za+.3,0,6,std('#7a1010',.6),{col:true});wbox(LANE.x0-.4,za-.35,LANE.x1+.4,za+.35,5.1,6.3,std('#7a1010',.6));
  for(const s of [-1,1]){const t=textPlane('串燒街',5.6,1.0,{bg:'#7a1010',fg:'#ffd23f',border:'#ffd23f',glow:true});t.position.set(xc,5.7,za+s*.37);t.rotation.y=s>0?0:Math.PI;G.add(t);const t2=textPlane('元朗廣場側　美食小巷',4,.32,{bg:'#7a1010',fg:'#ffe9a8',font:FS,glow:true});t2.position.set(xc,5.2,za+s*.37);t2.rotation.y=s>0?0:Math.PI;G.add(t2);}
  // red lanterns and string lights across the lane
  const lanM=new THREE.MeshStandardMaterial({color:lin('#8a0b0b'),emissive:lin('#ff3b30'),emissiveIntensity:1.4,roughness:.5});GLOW.push(lanM);const bulbM=new THREE.MeshStandardMaterial({color:lin('#332'),emissive:lin('#ffd08a'),emissiveIntensity:2,roughness:.5});GLOW.push(bulbM);
  const lb=new Batch(),bb=new Batch();for(let z=-10;z>-60;z-=5.2){const l=new THREE.SphereGeometry(.33,10,8);l.scale(1,1.25,1);lb.geo(l,new THREE.Matrix4().setPosition(xc+((z/5.2|0)%2?.9:-.9),4.4,z));lb.geo(new THREE.CylinderGeometry(.18,.18,.1,8),new THREE.Matrix4().setPosition(xc+((z/5.2|0)%2?.9:-.9),4.85,z));}
  for(let z=-9;z>-60;z-=.9){for(const x of [LANE.x0+.8,LANE.x1-.8])bb.geo(new THREE.SphereGeometry(.06,5,4),new THREE.Matrix4().setPosition(x+Math.sin(z)*.1,3.5+Math.sin(z*.7)*.15,z));}
  for(let k=0;k<7;k++){const z=-12-k*7.5;bb.geo(new THREE.SphereGeometry(.06,5,4),new THREE.Matrix4().setPosition(xc,4.9,z));for(let s=0;s<9;s++){const x=LANE.x0+.8+s*(LANE.x1-LANE.x0-1.6)/8;bb.geo(new THREE.SphereGeometry(.055,5,4),new THREE.Matrix4().setPosition(x,4.9-Math.sin(s/8*Math.PI)*.45,z));}}
  {const m=new THREE.Mesh(lb.build(),lanM);G.add(m);const m2=new THREE.Mesh(bb.build(),bulbM);G.add(m2);}
  cFlush();
  // smoke puffs above the grills
  const [c,g]=cvs(64,64);const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,'rgba(235,235,235,.55)');gr.addColorStop(1,'rgba(235,235,235,0)');g.fillStyle=gr;g.fillRect(0,0,64,64);const smT=ctex(c);
  LANE_ROOT.puffs=[];for(let i=0;i<36;i++){const s=new THREE.Sprite(new THREE.SpriteMaterial({map:smT,transparent:true,depthWrite:false,opacity:0}));const src=pick(LANE_ROOT.smoke);s.position.set(src.x,src.y+R(0,2),src.z);s.userData={src,t:R(0,2.4)};G.add(s);LANE_ROOT.puffs.push(s);}
  addLabel('串燒街',xc,-30,7,'');}
function laneUpdate(dt){const near=Math.hypot(PLAYER.x-LANE.xc,PLAYER.z+34)<160&&!curRoom&&!PLAYER.ind;LANE_ROOT.g.visible=near||true;for(const p of LANE_ROOT.puffs){p.visible=near;if(!near)continue;const u=p.userData;u.t+=dt;if(u.t>2.4){u.t=0;u.src=pick(LANE_ROOT.smoke);}const k=u.t/2.4;p.position.set(u.src.x+Math.sin(u.t*2+u.src.z)*.2,u.src.y+k*2.6,u.src.z+k*.3);const s=.4+k*1.4;p.scale.set(s,s,1);p.material.opacity=.5*(1-k)*Math.min(1,u.t*4);}
  if(near){const t=performance.now()/1000;for(const c of LANE_ROOT.cooks||[]){c.arms[1].rotation.x=-1.1+Math.sin(t*5+c.g.position.z)*.35;}for(const c of LANE_ROOT.cust||[]){c.head.rotation.y=Math.sin(t*.7+c.g.position.z)*.4;}}}

/* ---------- 老婆餅 hunt ---------- */
const CAKES=[];
function makeCakes(){const spots=[];const add=(x,z,y)=>spots.push([x,z,y]);
  if(towerC)add(towerC.x+3.5,towerC.z,TOWER_TOP_Y+1);add(CX(67.5),CZ(17));add(CX(30),CZ(48.4),18+1);add(HALLW(73,-46).x,HALLW(73,-46).z,1.2+1);add(HX(152.5),HZ(-44),HOMEP.h+1);add(LANE.xc,-58);
  if(LOC.canal)add(LOC.canal.x+3,LOC.canal.z+3);if(LOC.market)add(LOC.market.x+2,LOC.market.z);if(LOC.hospital)add(LOC.hospital.x+4,LOC.hospital.z+4);if(LOC.godown)add(LOC.godown.x+6,LOC.godown.z);
  for(const st of Object.values(MTR.st))if(st.street)add(st.street.x+3,st.street.z+3);
  let guard=0;while(spots.length<20&&guard++<400){const r=pick(ROADS.filter(q=>q.cls<=2));const q=posOn(r,R(0,r.len));const x=q.x-q.dz*(r.w/2+2.4),z=q.z+q.dx*(r.w/2+2.4);if(!inWB(x,z,80)||solidAt(x,1,z)||exclAt(x,z))continue;if(spots.some(s=>Math.hypot(s[0]-x,s[1]-z)<160))continue;add(x,z);}
  const geo=new THREE.CylinderGeometry(.5,.5,.16,22);const top=new THREE.MeshStandardMaterial({color:lin('#e0a845'),emissive:lin('#7a4a00'),emissiveIntensity:.6,roughness:.5});const ring=new THREE.MeshBasicMaterial({color:0xffd23f,transparent:true,opacity:.5,toneMapped:false,depthWrite:false});
  spots.forEach(([x,z,y],i)=>{const g=new THREE.Group();const m=new THREE.Mesh(geo,top);m.rotation.x=Math.PI/2;g.add(m);const r=new THREE.Mesh(new THREE.RingGeometry(.62,.72,24),ring);g.add(r);const yy=y!=null?y:TH(x,z)+1;g.position.set(x,yy,z);scene.add(g);const got=(S.cakes||[]).includes(i);g.visible=!got;CAKES.push({g,x,z,y:yy,i,got});});}
function cakesUpdate(dt){const t=performance.now()/1000;const o=PLAYER.car||PLAYER;const py=PLAYER.car?TH(o.x,o.z):(PLAYER.y||0);
  for(const c of CAKES){if(c.got)continue;c.g.rotation.y+=dt*2;c.g.position.y=c.y+Math.sin(t*3+c.i)*.15;if(Math.abs(c.x-o.x)<4&&Math.abs(c.z-o.z)<4&&Math.hypot(c.x-o.x,c.z-o.z)<(PLAYER.car?3:1.5)&&Math.abs(py+1-c.y)<2.2){c.got=true;c.g.visible=false;S.cakes=S.cakes||[];S.cakes.push(c.i);addMoney(50,true);gainXP(15);sfx('gold');voice('cake');const n=CAKES.filter(q=>q.got).length;toast(`搵到老婆餅！ ${n}/${CAKES.length}　+$50`);if(n===CAKES.length){addMoney(1000,true);toast('集齊晒老婆餅！獎 $1000');}save();}}}
function resetCakes(){S.cakes=S.cakes||[];for(const c of CAKES){c.got=S.cakes.includes(c.i);c.g.visible=!c.got;}}

/* ---------- fishing by the nullah ---------- */
const FISH_TYPES=[{n:'泥鯭',p:[25,62],d:.6},{n:'黃腳鱲',p:[62,125],d:.8},{n:'烏頭',p:[50,100],d:.7},{n:'鯽魚',p:[38,75],d:.6},{n:'塘虱',p:[75,150],d:.9},{n:'羅非魚',p:[30,70],d:.65}];
let fishG=null;
function openFishing(){openModal('fish',`<div class="mh">明渠釣魚</div><div class="mq" id="fq">㩒住「拋竿」儲力，放手拋出去</div><canvas id="fishc" width="360" height="460"></canvas><div class="mrow"><button class="mbtn" id="fishBtn">拋竿</button><span class="pr" id="fishCash"></span><button class="mbtn ghost" id="fishQuit">收竿走人</button></div>`);
  fishG={phase:'cast',power:0,pdir:1,hold:false,bob:0,t:0,fish:null,fy:.5,fv:0,zy:.3,zv:0,prog:.3,total:0};
  const btn=$('#fishBtn');const down=e=>{e.preventDefault();fishG.hold=true;fishPress();};const up=e=>{e&&e.preventDefault();if(!fishG)return;fishG.hold=false;fishRelease();};
  btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',()=>{if(fishG&&fishG.hold)up();});
  const cv=$('#fishc');cv.addEventListener('pointerdown',down);cv.addEventListener('pointerup',up);
  $('#fishQuit').onclick=()=>{const t=fishG.total;fishG=null;closeModal();say([['釣魚佬',t>0?`今日收穫唔錯喎，賺咗 $${t}！`:'得閒再嚟啦𡃁仔！']]);};}
function fishPress(){const f=fishG;if(!f)return;if(f.phase==='bite'){f.phase='reel';const r=rnd();f.fish=r<.06?{n:'金色鯉魚',p:[800,2000],d:1.6,gold:true}:pick(FISH_TYPES);f.fy=.5;f.zy=.35;f.prog=.3;f.fv=0;$('#fq').textContent='上釣！㩒住令綠色條上升，包住條魚！';$('#fishBtn').textContent='㩒住拉';sfx('hit',.3);}
  else if(f.phase==='done'){f.phase='cast';f.power=0;$('#fq').textContent='㩒住「拋竿」儲力，放手拋出去';$('#fishBtn').textContent='拋竿';}}
function fishRelease(){const f=fishG;if(!f)return;if(f.phase==='cast'&&f.power>0){f.phase='wait';f.t=R(1.5,4.5)*(1.3-f.power*.6);$('#fq').textContent='等魚上釣…';$('#fishBtn').textContent='等緊…';}}
function fishTick(dt){const f=fishG;if(!f||modal!=='fish')return;
  if(f.phase==='cast'&&f.hold){f.power+=f.pdir*dt*1.2;if(f.power>1){f.power=1;f.pdir=-1;}if(f.power<0){f.power=0;f.pdir=1;}}
  if(f.phase==='wait'){f.t-=dt;f.bob=Math.sin(performance.now()/300)*3;if(f.t<=0){f.phase='bite';f.t=1.1;$('#fq').textContent='有魚食餌！快㩒！';$('#fishBtn').textContent='拉！';sfx('ding');}}
  else if(f.phase==='bite'){f.t-=dt;f.bob=Math.sin(performance.now()/40)*6;if(f.t<=0){f.phase='done';$('#fq').textContent='慢咗，條魚食咗餌走咗！㩒掣再嚟';$('#fishBtn').textContent='再拋';}}
  else if(f.phase==='reel'){const d=f.fish.d;if(rnd()<dt*1.6*d)f.fv=R(-1,1)*d*1.3;f.fy=clamp(f.fy+f.fv*dt,.03,.97);if(f.fy<=.03||f.fy>=.97)f.fv*=-1;
    f.zv+=(f.hold?2.6:-2.2)*dt;f.zv*=.96;f.zy=clamp(f.zy+f.zv*dt,0,1-.24);if(f.zy<=0||f.zy>=.76)f.zv*=-.3;
    const inZone=f.fy>=f.zy&&f.fy<=f.zy+.24;f.prog+=(inZone?.32:-.22)*dt;
    if(f.prog>=1){const amt=Math.round(R(f.fish.p[0],f.fish.p[1]));f.total+=amt;addMoney(amt,true);gainXP(8);f.phase='done';$('#fq').textContent=(f.fish.gold?'金色魚！':'')+`釣到 ${f.fish.n}，賣 $${amt}`;$('#fishBtn').textContent='再拋';sfx(f.fish.gold?'gold':'ok');$('#fishCash').textContent='今日 +$'+f.total;}
    else if(f.prog<=0){f.phase='done';$('#fq').textContent='條線鬆咗，魚走甩咗！';$('#fishBtn').textContent='再拋';sfx('bad');}}
  drawFish();}
function drawFish(){const f=fishG;const c=$('#fishc');if(!c)return;const g=c.getContext('2d');const W=360,H=460;const now=performance.now();
  const sky=g.createLinearGradient(0,0,0,160);sky.addColorStop(0,'#f6a76a');sky.addColorStop(1,'#ffd7a0');g.fillStyle=sky;g.fillRect(0,0,W,160);
  g.fillStyle='#7d8a96';for(let i=0;i<12;i++){const h=40+((i*37)%70);g.fillRect(i*30,140-h,22,h);}
  const sea=g.createLinearGradient(0,150,0,H);sea.addColorStop(0,'#4f7a6e');sea.addColorStop(1,'#1d3a33');g.fillStyle=sea;g.fillRect(0,150,W,H-150);
  g.strokeStyle='rgba(255,255,255,.16)';for(let i=0;i<8;i++){g.beginPath();g.moveTo(0,170+i*30+Math.sin(now/600+i)*3);g.lineTo(W,170+i*30+Math.cos(now/700+i)*3);g.stroke();}
  g.fillStyle='#8f8d84';g.fillRect(0,290,130,26);g.strokeStyle='#222';g.lineWidth=3;g.beginPath();g.moveTo(40,290);g.quadraticCurveTo(140,120,210,90);g.stroke();
  const bx2=150+(f.phase==='cast'?0:f.power*150),by=160+f.bob;g.strokeStyle='rgba(255,255,255,.8)';g.lineWidth=1;g.beginPath();g.moveTo(210,90);g.lineTo(f.phase==='cast'?210:bx2,f.phase==='cast'?140:by);g.stroke();
  if(f.phase!=='cast'){g.fillStyle='#e2412f';g.beginPath();g.arc(bx2,by,6,0,TAU);g.fill();g.fillStyle='#fff';g.fillRect(bx2-6,by-2,12,3);}
  if(f.phase==='bite'){g.fillStyle='#ffd23f';g.font='900 46px sans-serif';g.fillText('!',bx2-8,by-18);}
  if(f.phase==='cast'){g.fillStyle='rgba(0,0,0,.5)';g.fillRect(20,410,320,22);const pg=g.createLinearGradient(20,0,340,0);pg.addColorStop(0,'#3fc27a');pg.addColorStop(1,'#e2412f');g.fillStyle=pg;g.fillRect(20,410,320*f.power,22);g.strokeStyle='#fff';g.strokeRect(20,410,320,22);g.fillStyle='#fff';g.font=`700 14px ${FS}`;g.fillText('力度',22,404);}
  if(f.phase==='reel'){const X=290,Y=190,BH=250;g.fillStyle='rgba(0,0,0,.55)';g.fillRect(X,Y,34,BH);g.fillStyle='rgba(63,194,122,.7)';g.fillRect(X+2,Y+BH*(1-f.zy-.24),30,BH*.24);
    const fy=Y+BH*(1-f.fy);g.fillStyle=f.fish.gold?'#ffd23f':'#9cd7ff';g.beginPath();g.ellipse(X+17,fy,11,7,0,0,TAU);g.fill();g.beginPath();g.moveTo(X+28,fy);g.lineTo(X+34,fy-6);g.lineTo(X+34,fy+6);g.fill();
    g.fillStyle='rgba(0,0,0,.55)';g.fillRect(X+40,Y,10,BH);g.fillStyle=f.prog>.66?'#3fc27a':f.prog>.33?'#ffd23f':'#e2412f';g.fillRect(X+40,Y+BH*(1-f.prog),10,BH*f.prog);g.fillStyle='#fff';g.font=`700 15px ${FS}`;g.fillText(f.fish.gold?'金色魚！':'有嘢上釣',20,200);}}

/* ---------- taxi job ---------- */
const TAXI={on:false,phase:null,pax:null,target:null,dest:null,t:0,d0:0,car:null,wait:0};
function taxiDests(){const L=LOC;const d=[['趙中',L.gate],['文記',L.wenkee],['串燒街',L.skewer],['同益街市',L.market],['博愛醫院',L.hospital],['金朗大廈',L.home]];for(const st of Object.values(MTR.st))if(st.street)d.push([st.zh+'站',st.street]);const yh=D.lab.find(l=>l[0]==='形點');if(yh)d.push(['形點',{x:yh[1],z:yh[2]}]);const pk=D.lab.find(l=>l[0]==='元朗劇院');if(pk)d.push(['元朗劇院',{x:pk[1],z:pk[2]}]);return d.filter(q=>q[1]);}
function toggleTaxi(){const v=PLAYER.car;if(!v||v.type!=='taxi'){toast('要揸的士先接到客');return;}if(TAXI.on){endTaxi('收工');return;}TAXI.on=true;TAXI.car=v;newFare();toast('開工！去接客（再㩒 T 收工）');}
function endTaxi(msg){if(TAXI.pax){scene.remove(TAXI.pax.g);TAXI.pax=null;}TAXI.on=false;TAXI.phase=null;TAXI.target=null;$('#jobChip').hidden=true;if(msg)toast(msg);}
function newFare(){const C=[];for(const r of roadsNear(PLAYER.x,PLAYER.z,240,q=>q.cls<=3&&q.len>30)){const q=posOn(r,R(0,r.len));const x=q.x-q.dz*(r.w/2+1.4),z=q.z+q.dx*(r.w/2+1.4);const d=Math.hypot(x-PLAYER.x,z-PLAYER.z);if(d>70&&d<230&&inWB(x,z,40)&&!solidAt(x,1,z))C.push([x,z]);}
  if(!C.length){endTaxi('附近冇客');return;}const p=pick(C);const pax=npc('客人',{shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0']),pants:'#333'},p[0],p[1],0,'#ffd23f');TAXI.pax=pax;TAXI.phase='pickup';TAXI.target={x:p[0],z:p[1],r:8};$('#jobChip').hidden=false;$('#jobChip').textContent='的士：去接客';}
function taxiUpdate(dt){if(!TAXI.on)return;if(PLAYER.car!==TAXI.car){endTaxi('落咗車，張單取消咗');return;}const v=TAXI.car;const d=Math.hypot(v.x-TAXI.target.x,v.z-TAXI.target.z);
  if(TAXI.phase==='pickup'){const p=TAXI.pax;if(p){p.g.rotation.y=Math.atan2(v.x-p.g.position.x,v.z-p.g.position.z);p.arms[1].rotation.x=-2.6+Math.sin(performance.now()/180)*.4;}
    if(d<8&&Math.abs(v.speed)<2.5){scene.remove(p.g);TAXI.pax=null;const ds=taxiDests().filter(q=>Math.hypot(q[1].x-v.x,q[1].z-v.z)>150);const q=pick(ds.length?ds:taxiDests());TAXI.dest=q;TAXI.target={x:q[1].x,z:q[1].z,r:10};TAXI.phase='drop';TAXI.t=0;TAXI.d0=Math.hypot(q[1].x-v.x,q[1].z-v.z);
      const line=pick(['唔該去','司機，去','趕時間呀，去','麻煩你去'])+q[0]+'！';subtitle('客人',line);sfx('ding');$('#jobChip').textContent='的士：去'+q[0];}}
  else if(TAXI.phase==='drop'){TAXI.t+=dt;if(d<12&&Math.abs(v.speed)<2.5){const fare=Math.round((27+TAXI.d0*.12+Math.max(0,TAXI.d0/9-TAXI.t)*1.2)*2);addMoney(fare,true);gainXP(10);toast(`收車錢 $${fare}`+(TAXI.t<TAXI.d0/9?'（有貼士）':''));sfx('coin');voiceLine('客人',pick(['唔該晒司機！','唔使找喇！','揸得幾快喎！']));TAXI.phase='next';TAXI.wait=2;$('#jobChip').textContent='的士：等下一張單';}}
  else if(TAXI.phase==='next'){TAXI.wait-=dt;if(TAXI.wait<=0)newFare();}}

/* ================= v3 main: per-frame hooks and boot ================= */
const MAPPOLY=[];
function v3Build(){buildCampus();buildHomeFlat();buildSkewerStreet();buildWenKeeRoom();v3cBuild();v3dBuild();v3eBuild();v3iBuild();v3jBuild();v3kBuild();}
function v3GameBoot(){setupSchoolInteracts();setupHomeInteracts();setupBigMap();setupDress();makeCakes();
  // fisherman on the nullah bank
  if(LOC.canal){const c=LOC.canalC||LOC.canal;const dx=LOC.canal.x-c.x,dz=LOC.canal.z-c.z,l=Math.hypot(dx,dz)||1;const fx=c.x+dx/l*9+dz/l*14,fz=c.z+dz/l*9-dx/l*14;const o=freeSpot(fx,fz);LOC.fisher={x:o.x,z:o.z};
    NPC.fisher=npc('釣魚佬',{shirt:'#3d6b4f',pants:'#3a3a3a',hair:'#666'},o.x,o.z,Math.atan2(c.x-o.x,c.z-o.z),'#9cd7ff');addCap(NPC.fisher,'#c9b27a');const rod=new THREE.Mesh(new THREE.CylinderGeometry(.015,.03,3.2,5),std('#222',.4));rod.position.set(0,-.2,1.2);rod.rotation.x=1.05;NPC.fisher.arms[1].add(rod);NPC.fisher.arms[1].rotation.x=-.9;
    INTER.push({npc:NPC.fisher,r:2.6,label:'同釣魚佬傾偈（釣魚）',ok:()=>!PLAYER.car,act:()=>ask('釣魚佬','𡃁仔，明渠都有魚㗎。要唔要試吓？',['釣！','唔使喇'],k=>{if(k===0)openFishing();else say([['釣魚佬','後生仔冇耐性，唉。']]);})});}
  $('#prompt').addEventListener('click',()=>{if(PLAYER.car&&PLAYER.car.type==='taxi')toggleTaxi();else act();});
  $('#tJump').addEventListener('pointerdown',e=>{e.preventDefault();if(started&&!PLAYER.car&&!dlgQ&&!modal&&!busy)jumpReq=true;});
  $('#tVoice').onclick=toggleVoice;$('#tGear').onclick=()=>$('#tod').classList.toggle('open');$('#hudMap').hidden=false;
  addEventListener('keydown',e=>{if(!started)return;if(e.code==='KeyT')toggleTaxi();if(e.code==='KeyV')toggleVoice();});
  // light rail rides
  INTER.push({at:()=>{const t=lrtNear();return t?{x:PLAYER.x,z:PLAYER.z}:null;},r:9,label:'上輕鐵（$5）',ok:()=>!PLAYER.car&&!PLAYER.riding&&!curRoom&&!PLAYER.ind&&!!lrtNear(),act:()=>{if(S.money<5){toast('唔夠錢搭輕鐵');return;}const t=lrtNear();addMoney(-5,true);sfx('ding');PLAYER.riding='lrt';PLAYER.tram=t;PLAYER.p.g.visible=false;PLAYER.tramStop=t.last;toast('上咗輕鐵，到站撳 E 落車');}});
  INTER.push({at:()=>({x:PLAYER.x,z:PLAYER.z}),r:1,label:'落輕鐵',ok:()=>PLAYER.riding==='lrt'&&PLAYER.tram.wait>0,act:()=>{const t=PLAYER.tram;PLAYER.riding=null;PLAYER.tram=null;PLAYER.p.g.visible=true;const s=Math.sin(t.h),c=Math.cos(t.h);PLAYER.x=t.x+c*3.4;PLAYER.z=t.z-s*3.4;pushOut(PLAYER,.4);PLAYER.y=TH(PLAYER.x,PLAYER.z);toast('落咗輕鐵');}});
  BOOTQ.push(v3bBoot,v3cBoot,v3dBoot,v3eBoot,v3fBoot,v3hBoot,v3iBoot,v3jBoot,v3mBoot,v3nBoot,v3oBoot,v3pBoot,v3qBoot,v3rBoot,v3sBoot,v3tBoot,v3uBoot,v3vBoot,v3wBoot,v3xBoot,v3yBoot,v3zBoot,v4aBoot,v4bBoot,v4cBoot,v5aBoot,v6aBoot,v6bBoot,v6cBoot,v7aBoot,v7cBoot,v7dBoot,v7eBoot,v7fBoot,v8aBoot,v8bBoot,v9aBoot,v9dBoot,v9eBoot,v10aBoot,v10bBoot,v10cBoot,applyOutfit);}
const BOOTQ=[];
function lrtNear(){for(const t of lrts){if(t.wait>1.2&&Math.hypot(t.x-PLAYER.x,t.z-PLAYER.z)<9)return t;}return null;}
function v3Update(dt){if(edgeT>0)edgeT-=dt;const P=PLAYER;
  shadowLod(dt);homeUpdate();schoolUpdate(dt);laneUpdate(dt);cakesUpdate(dt);taxiUpdate(dt);fishTick(dt);kfUpdate(dt);playerPose(dt);v3bUpdate(dt);v3cUpdate(dt);v3dUpdate(dt);v3eUpdate(dt);v3fUpdate(dt);v3hUpdate(dt);v3iUpdate(dt);v3jUpdate(dt);v3kUpdate(dt);v3lUpdate(dt);v3mUpdate(dt);v3nUpdate(dt);v3oUpdate(dt);v3pUpdate(dt);v3qUpdate(dt);v3rUpdate(dt);v3sUpdate(dt);v3tUpdate(dt);v3uUpdate(dt);v3vUpdate(dt);v3xUpdate(dt);nwUpdate(dt);v4aUpdate(dt);v4cUpdate(dt);v5aUpdate(dt);v6aUpdate(dt);v6bUpdate(dt);v6cUpdate(dt);v7aUpdate(dt);v7cUpdate(dt);v7eUpdate(dt);
  if(P.car)edgeClamp(P.car,true);
  if(P.riding==='lrt'&&P.tram){P.x=P.tram.x;P.z=P.tram.z;P.y=0;P.vy=0;if(P.tram.wait>0&&P.tram.last!==P.tramStop){P.tramStop=P.tram.last;toast('到站喇，撳 E 落車');sfx('bell',.5);}}
  if(mapOpen)drawBigMap();
  // indoor lights at night: reuse the pooled lamp lights around the player
  if(P.ind&&!curRoom){const night=cur.lamp>1.8;lampLights.forEach((L,i)=>{if(!night||i>3){L.intensity=0;return;}const a=i/4*TAU+.6;L.position.set(P.x+Math.cos(a)*4,(P.y||0)+2.9,P.z+Math.sin(a)*4);L.intensity=.45;});}
  const jc=$('#jobChip');if(!TAXI.on&&!jc.hidden)jc.hidden=true;}
let shT=0;
function shadowLod(dt){shT-=dt;if(shT>0)return;shT=.5;const cx=camera.position.x,cz=camera.position.z;const list=[...peds,...(SCH.yard||[]),...COPS,...FIGHT];
  for(const p of list){if(!p.g)continue;const want=(p.g.position.x-cx)**2+(p.g.position.z-cz)**2<60*60;if(p.shOn===want)continue;p.shOn=want;p.g.traverse(m=>{if(m.isMesh)m.castShadow=want;});}
  for(const v of vehicles){const want=(v.x-cx)**2+(v.z-cz)**2<76*76;if(v.shOn===want)continue;v.shOn=want;v.g.traverse(m=>{if(m.isMesh&&m.material!==glassM)m.castShadow=want;});}}
function placeName(){const P=PLAYER;if(P.ind==='home')return '金朗大廈 30樓（屋企）';if(SCH.place)return SCH.place;if(P.x>LANE.x0-1&&P.x<LANE.x1+1&&P.z>LANE.z0&&P.z<LANE.z1+2)return '串燒街（元朗廣場側）';return null;}

/* ================= v3b: weather & sky cycle, music, swimming, bike, Man Kee walk-in, court games ================= */
/* ---------- water ---------- */
const WSEG=[],WGRID=new Map();
function buildWaterIndex(){for(const [w,f] of D.water){if(w<4)continue;for(let i=2;i<f.length;i+=2){const s=[f[i-2],f[i-1],f[i],f[i+1],w];const idx=WSEG.length;WSEG.push(s);const x0=Math.min(s[0],s[2])-w,x1=Math.max(s[0],s[2])+w,z0=Math.min(s[1],s[3])-w,z1=Math.max(s[1],s[3])+w;for(let a=Math.floor(x0/40);a<=Math.floor(x1/40);a++)for(let b=Math.floor(z0/40);b<=Math.floor(z1/40);b++){const k=a*100003+b;if(!WGRID.has(k))WGRID.set(k,[]);WGRID.get(k).push(idx);}}}}
function onRoad(x,z,m=1.2){const nr=nearestRoad(x,z,14,r=>r.cls<=6);return !!(nr&&nr.d<nr.r.w/2+m);}
function inWater(x,z){const L=WGRID.get(Math.floor(x/40)*100003+Math.floor(z/40));if(!L)return false;for(const i of L){const s=WSEG[i];const ex=s[2]-s[0],ez=s[3]-s[1],l2=ex*ex+ez*ez||1e-9;const t=clamp(((x-s[0])*ex+(z-s[1])*ez)/l2,0,1);const d=Math.hypot(x-s[0]-ex*t,z-s[1]-ez*t);if(d<s[4]/2-.4){return !onRoad(x,z,.3);}}return false;}
const RIPPLE=[];let rippleTex=null;
function splashFx(x,z,small){if(!rippleTex){const [c,g]=cvs(128,128);g.strokeStyle='rgba(255,255,255,.9)';g.lineWidth=6;g.beginPath();g.arc(64,64,52,0,TAU);g.stroke();rippleTex=ctex(c);}
  const m=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:rippleTex,transparent:true,depthWrite:false,toneMapped:false}));m.rotation.x=-Math.PI/2;m.position.set(x,.05,z);scene.add(m);RIPPLE.push({m,t:0,max:small?.9:1.3,s:small?1.6:3});}
function rippleUpdate(dt){for(let i=RIPPLE.length-1;i>=0;i--){const r=RIPPLE[i];r.t+=dt;const u=r.t/r.max;const k=.4+u*r.s;r.m.scale.set(k,k,1);r.m.material.opacity=(1-u)*.8;if(u>=1){scene.remove(r.m);r.m.material.dispose();RIPPLE.splice(i,1);}}}
let swimT=0;
function swimUpdate(dt){const P=PLAYER;if(P.car){const v=P.car;if(!v.lastDry)v.lastDry={x:v.x,z:v.z};if(inWater(v.x,v.z)){v.x=v.lastDry.x;v.z=v.lastDry.z;v.vx*=-.2;v.vz*=-.2;v.speed=0;if(edgeT<=0){toast('架車落唔到水！');edgeT=3;}}else{v.lastDry.x=v.x;v.lastDry.z=v.z;}return;}
  if(P.swim){swimT-=dt;if(swimT<=0){swimT=P.spd>.5?.5:1.1;splashFx(P.x,P.z,true);}}}

/* ---------- continuous sky + weather (like the earlier version) ---------- */
TOD.dawn=Object.assign({},TOD.dusk,{el:9,az:1.9,sun:'#ffc38a',si:3.2,top:'#3b5aa8',hor:'#ffb48c',fog:'#d8b2a0',exp:1,bloom:.4,neon:1.2,win:.45,lamp:.9,pool:.3,shop:.7,head:.8,stars:.1});
const SKYK=[[0,'night'],[5.1,'night'],[6.3,'dawn'],[7.6,'day'],[16.6,'day'],[18.0,'dusk'],[19.3,'night'],[24,'night']];const SN={};
const Wx={sched:[],rain:0,wet:0,cloud:.2,rainbow:0,lastHour:-1,was:false,bowUntil:0,day:-1};
function genWeather(){Wx.sched=[];let h=0;while(h<24){const r=Math.random();const st=r<.2?'rain':r<.48?'cloud':'sun';const len=st==='rain'?1+Math.floor(Math.random()*2):1;for(let k=0;k<len&&h<24;k++)Wx.sched[h++]=st;}Wx.sched[7]='sun';Wx.sched[8]='cloud';}
const WICON={sun:'☀️',cloud:'⛅',rain:'🌧️',bow:'🌈'};
function renderForecast(){const el=$('#fc');if(!el)return;const h=Math.floor(gameMin/60);let html='';for(let k=0;k<4;k++){const hh=(h+k)%24;let st=Wx.sched[hh]||'sun';if(k===0&&Wx.rainbow>.1)st='bow';html+=`<span class="${k?'':'now'}">${WICON[st]}<i>${String(hh).padStart(2,'0')}</i></span>`;}el.innerHTML=html;}
let rainLines=null,rainbow=null,ROADMATS=[];const RAIN_N=isMobile?1100:2400;
function setupWeather(){genWeather();for(const k of ['day','dawn','dusk','night'])SN[k]=snap(TOD[k]);
  const g=new THREE.BufferGeometry();const a=new Float32Array(RAIN_N*6);for(let i=0;i<RAIN_N;i++){const x=R(-35,35),y=R(0,30),z=R(-35,35);a.set([x,y,z,x+.05,y-.75,z],i*6);}g.setAttribute('position',new THREE.BufferAttribute(a,3));
  rainLines=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color:0xbfd4e6,transparent:true,opacity:0,depthWrite:false}));rainLines.frustumCulled=false;scene.add(rainLines);
  rainbow=new THREE.Group();['#ff3b30','#ff9500','#ffcc00','#34c759','#30b0c7','#5856d6','#af52de'].forEach((c,i)=>{rainbow.add(new THREE.Mesh(new THREE.TorusGeometry(330-i*6,3,6,80,Math.PI),new THREE.MeshBasicMaterial({color:lin(c),transparent:true,opacity:0,depthWrite:false,fog:false,toneMapped:false})));});scene.add(rainbow);rainbow.visible=false;
  scene.traverse(o=>{if(o.isMesh&&o.material&&o.material.map===TX.asphalt&&!ROADMATS.includes(o.material))ROADMATS.push(o.material);});
  const st=$('#stats');if(st&&!$('#fc')){const d=document.createElement('div');d.id='fc';st.appendChild(d);}renderForecast();}
const _ca=new THREE.Color(),_grey=lin('#8a939b'),_grey2=lin('#a3abb2');let envClock=0,envRainAt=0;
function skyUpdate(dt){if(!SN.day)return;const h=((gameMin/60)%24+24)%24;let a=SKYK[0],b=SKYK[1];for(let i=0;i<SKYK.length-1;i++)if(h>=SKYK[i][0]&&h<SKYK[i+1][0]){a=SKYK[i];b=SKYK[i+1];break;}
  let t=(h-a[0])/((b[0]-a[0])||1);t=t*t*(3-2*t);const A=SN[a[1]],B=SN[b[1]];
  for(const k in A){const x=A[k],y=B[k];if(x&&x.isColor){cur[k]=(cur[k]&&cur[k].isColor?cur[k]:new THREE.Color()).copy(x).lerp(y,t);}else if(k==='az'){cur[k]=x+angDiff(x,y)*t;}else cur[k]=lerp(x,y,t);}
  // weather
  const hr=Math.floor(h);if(hr!==Wx.lastHour){Wx.lastHour=hr;if(hr===0)genWeather();renderForecast();}
  const ws=Wx.sched[hr]||'sun';const curRoomIn=!!curRoom;Wx.rain=lerp(Wx.rain,ws==='rain'?1:0,1-Math.exp(-.35*dt));Wx.cloud=lerp(Wx.cloud,ws==='rain'?1:ws==='cloud'?.6:.15,1-Math.exp(-.3*dt));
  if(Wx.rain>.2)Wx.wet=Math.min(1,Wx.wet+dt*.08);else Wx.wet=Math.max(0,Wx.wet-dt*.01);if(Wx.rain>.5)Wx.was=true;
  if(Wx.was&&Wx.rain<.15){Wx.was=false;if(h>7&&h<17.5){Wx.rainbow=1;Wx.bowUntil=gameMin+90;renderForecast();toast('落完雨，出咗彩虹！');}}
  if(Wx.rainbow>0&&gameMin>Wx.bowUntil){Wx.rainbow=Math.max(0,Wx.rainbow-dt*.2);if(!Wx.rainbow)renderForecast();}
  const r=Wx.rain,cl=Wx.cloud;
  cur.top.lerp(_grey,r*.7).multiplyScalar(1-r*.4);cur.hor.lerp(_grey2,r*.65).multiplyScalar(1-r*.3);cur.fog.lerp(_grey2,r*.6).multiplyScalar(1-r*.25);
  cur.si*=(1-r*.82)*(1-cl*.3);cur.hi*=(1+r*.25);cur.fn=lerp(cur.fn,30,r);cur.ff=lerp(cur.ff,300,r);cur.exp*=(1+r*.08);cur.ss*=(1-r);cur.stars*=(1-cl*.8);
  if(r>.3){cur.win=Math.max(cur.win,.5*r);cur.neon=Math.max(cur.neon,1.4*r);cur.shop=Math.max(cur.shop,.8*r);cur.head=Math.max(cur.head,1*r);cur.lamp=Math.max(cur.lamp,1.2*r*Math.min(1,cur.win+.4));}
  applyCur();
  if(rainLines){const on=r>.03&&!curRoomIn&&!PLAYER.ind;rainLines.visible=on;rainLines.material.opacity=r*.4;if(on){const p=rainLines.geometry.attributes.position.array;const fall=32*dt;for(let i=0;i<RAIN_N;i++){const o=i*6;p[o+1]-=fall;p[o+4]-=fall;if(p[o+4]<-6){const y=R(22,30);p[o+1]=y;p[o+4]=y-.75;}}rainLines.geometry.attributes.position.needsUpdate=true;rainLines.position.set(camera.position.x,camera.position.y-12,camera.position.z);}}
  for(const m of ROADMATS){m.roughness=lerp(.9,.25,Wx.wet);m.metalness=lerp(0,.3,Wx.wet);}
  if(rainbow){rainbow.visible=Wx.rainbow>.01&&!curRoomIn;if(rainbow.visible){const ang=clamp((h-6)/12.5,0,1)*Math.PI;const sx=Math.cos(ang);rainbow.position.set(PLAYER.x-sx*520,-40,PLAYER.z-160);rainbow.lookAt(PLAYER.x,-40,PLAYER.z);rainbow.children.forEach(m=>m.material.opacity=Wx.rainbow*.22);}}
  rainSound(r*(curRoomIn||PLAYER.ind?.25:1));
  envClock+=dt;if(envClock>8||Math.abs(r-envRainAt)>.15){envClock=0;envRainAt=r;envDirty=true;}}
function applyCur(){const el=cur.el*Math.PI/180;const dir=sun.userData.dir||new THREE.Vector3();dir.set(Math.cos(el)*Math.sin(cur.az),Math.sin(el),Math.cos(el)*Math.cos(cur.az));sun.userData.dir=dir;
  sun.color.copy(cur.sun);sun.intensity=cur.si;hemi.color.copy(cur.hs);hemi.groundColor.copy(cur.hg);hemi.intensity=cur.hi;
  skyU.top.value.copy(cur.top);skyU.hor.value.copy(cur.hor);skyU.sunC.value.copy(cur.sun);skyU.sunDir.value.copy(dir);skyU.sunSize.value=cur.ss;
  scene.fog.color.copy(cur.fog);scene.fog.near=cur.fn;scene.fog.far=cur.ff;renderer.toneMappingExposure=cur.exp;if(bloom)bloom.strength=cur.bloom;
  if(TX.signMat)TX.signMat.emissiveIntensity=cur.neon;if(TX.shopMat)TX.shopMat.emissiveIntensity=cur.shop;for(const m of WIN_MATS)m.emissiveIntensity=cur.win;
  if(lampHeadMat)lampHeadMat.emissiveIntensity=cur.lamp;if(poolMat)poolMat.opacity=cur.pool;headM.emissiveIntensity=cur.head;tailM.emissiveIntensity=cur.head*.8;stars.material.opacity=cur.stars;if(headSpot)headSpot.intensity=cur.head*9;
  for(const v of vehicles){if(v.type!=='taxi')continue;if(v.sign===undefined){v.sign=null;v.body.traverse(o=>{if(o.isMesh&&o.userData.taxiSign)v.sign=o;});}if(v.sign)v.sign.material.emissiveIntensity=cur.head+.4;}
  const n=$('#tDay');if(n){const k=cur.lamp>2?'night':cur.lamp>.4?'dusk':'day';if(n.dataset.k!==k){n.dataset.k=k;for(const [id,kk] of [['#tDay','day'],['#tDusk','dusk'],['#tNight','night']])$(id).setAttribute('aria-pressed',String(kk===k));}}}
function setTod(n,instant){if(started||SN.day){gameMin={day:12*60,dusk:17.9*60,night:21*60,dawn:6.4*60}[n]||gameMin;Wx.lastHour=-1;if(SN.day){skyUpdate(0);}envDirty=true;return;}
  todName=n;todFrom=Object.assign({},cur.el!=null?cur:snap(TOD[n]));for(const k in todFrom)if(todFrom[k]&&todFrom[k].isColor)todFrom[k]=todFrom[k].clone();todTo=snap(TOD[n]);todT=instant?1:0;applyTod(instant?1:0);envDirty=true;}
let rainNode=null;
function rainSound(level){if(!AU.ctx||!AU.noise)return;if(!rainNode){const c=AU.ctx;const s=c.createBufferSource();s.buffer=AU.noise;s.loop=true;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=1800;const g=c.createGain();g.gain.value=0;s.connect(f);f.connect(g);g.connect(AU.sfx);s.start();rainNode=g;}rainNode.gain.setTargetAtTime(level*.12,AU.ctx.currentTime,.5);}

