function buildWenKeeRoom(){const r=makeRoom('wenkee',{name:'文記家庭用品',w:16,d:12,floor:roomFloorTex('#cdbb9f','#bba98d',6),wall:'#e7dcc8',skirt:'#7a1f1f',wh:4.2});const x0=r.x0,z0=r.z0;
  roomSign(r,'文記家庭用品',8,.12,3.45,7,1.05,{bg:'#b3121f',fg:'#ffe9a8',border:'#ffe9a8',glow:true});
  const wood=std('#8a6a44',.7),cols=['#c8102e','#2a6fdb','#1d8a4c','#f2c300','#e86a12','#f2f2f2','#9b5de5','#2bb3a3'];
  const goods=[];for(const [x,z,w,d] of [[1,6,1.2,9],[15,6,1.2,9],[6,.8,6,1]]){roomBox(r,w,3,d,x,z,wood);for(let lv=0;lv<4;lv++){const n=Math.floor((w>d?w:d)/.55);for(let k=0;k<n;k++){const px=w>d?x-w/2+.3+k*.55:x+(x<8?.45:-.45),pz=w>d?z+.45:z-d/2+.3+k*.55;goods.push([x0+px,.45+lv*.72,z0+pz,pick(cols)]);}}}
  const im=new THREE.InstancedMesh(new THREE.BoxGeometry(.4,.42,.32),std('#ffffff',.6),goods.length);const o=new THREE.Object3D();goods.forEach((q,i)=>{o.position.set(q[0],q[1]+.21,q[2]);o.rotation.y=R(-.3,.3);o.updateMatrix();im.setMatrixAt(i,o.matrix);im.setColorAt(i,lin(q[3]));});im.castShadow=true;scene.add(im);
  for(const [x,z] of [[6,6.5],[10,6.5]]){roomBox(r,2.4,.6,1.6,x,z,std('#6b4b32',.6));for(let k=0;k<6;k++){const b=new THREE.Mesh(new THREE.CylinderGeometry(.32,.24,.3,12),std(pick(cols),.5));b.position.set(x0+x-.8+(k%3)*.8,.75+Math.floor(k/3)*.25,z0+z-.35+(k>2?.7:0));b.castShadow=true;scene.add(b);}}
  for(let x=3;x<14;x+=1.6)for(const z of [4,7.5]){const b=new THREE.Mesh(new THREE.CylinderGeometry(.28,.2,.36,12),std(pick(cols),.5));b.position.set(x0+x,3.4,z0+z);scene.add(b);const s=new THREE.Mesh(new THREE.CylinderGeometry(.01,.01,.6,4),std('#333',.5));s.position.set(x0+x,3.85,z0+z);scene.add(s);}
  for(let k=0;k<7;k++){const m=new THREE.Mesh(new THREE.CylinderGeometry(.03,.03,1.5,5),std('#8a6a44',.7));m.position.set(x0+13.6,.75,z0+9+k*.3);m.rotation.z=.15;scene.add(m);const h=new THREE.Mesh(new THREE.BoxGeometry(.3,.3,.12),std(pick(cols),.7));h.position.set(x0+13.75,.15,z0+9+k*.3);scene.add(h);}
  roomBox(r,4,1.05,1.2,11,3.2,std('#6b4b32',.6));roomBox(r,4.1,.07,1.3,11,3.2,std('#d8c7a6',.4),false,1.05);const reg=new THREE.Mesh(new THREE.BoxGeometry(.5,.3,.4),std('#333',.4,.3));reg.position.set(x0+12,1.25,z0+3.2);scene.add(reg);
  r.lights=[[x0+5,z0+5],[x0+11,z0+5],[x0+8,z0+9]];r.spawn={x:x0+8,z:z0+10.6,h:Math.PI};
  r.inter.push({at:()=>({x:x0+11,z:z0+4.6}),r:2.6,label:'同文記老闆傾偈／買嘢',ok:()=>curRoom===r,act:()=>ask('文記老闆',pick(['後生仔，想買啲乜？刷膠雞毛掃水喉通乜都有！','又係你呀？今日有新貨㗎！','學生仔，睇啱就買，算你平啲！']),['睇吓有乜賣','傾吓偈','唔使喇'],k=>{if(k===0)openWenKee();else if(k===1)say([['文記老闆',pick(['我喺元朗開咗三十年舖喇，你阿媽細細個都嚟我度買嘢。','最近坤哥班人周圍收保護費，你小心啲呀。','明渠嗰邊有個釣魚佬，成日嚟買魚絲。'])]]);})});
  return r;}

/* ---------- bicycle ---------- */
function bikeModel(color){const g=new THREE.Group(),body=new THREE.Group();g.add(body);const fr=std(color,.4,.5),blk=std('#1a1a1a',.6);
  const tube=(x1,y1,z1,x2,y2,z2,r=.03,m=fr)=>{const a=new THREE.Vector3(x1,y1,z1),b=new THREE.Vector3(x2,y2,z2);const L=a.distanceTo(b);const me=new THREE.Mesh(new THREE.CylinderGeometry(r,r,L,6),m);me.position.copy(a).add(b).multiplyScalar(.5);me.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),b.clone().sub(a).normalize());me.castShadow=true;body.add(me);};
  tube(0,.36,-.55,0,.95,-.18);tube(0,.36,-.55,0,.42,.05);tube(0,.42,.05,0,.95,-.18);tube(0,.95,-.18,0,.92,.45);tube(0,.42,.05,0,.92,.45);tube(0,.92,.45,0,.36,.55,.028);tube(0,.92,.45,0,1.08,.42,.025,blk);
  tube(-.26,1.08,.42,.26,1.08,.42,.02,blk);const seat=new THREE.Mesh(new THREE.BoxGeometry(.14,.05,.26),blk);seat.position.set(0,.99,-.2);body.add(seat);const bk=new THREE.Mesh(new THREE.BoxGeometry(.3,.14,.24),std('#7a5232',.7));bk.position.set(0,.98,.62);body.add(bk);
  const ws=[];for(const z of [-.55,.55]){const w=new THREE.Group();const t=new THREE.Mesh(new THREE.TorusGeometry(.33,.035,6,20),blk);t.rotation.y=Math.PI/2;w.add(t);const h=new THREE.Mesh(new THREE.CylinderGeometry(.05,.05,.08,8),std('#c9ccd0',.3,.8));h.rotation.z=Math.PI/2;w.add(h);for(let k=0;k<6;k++){const sp=new THREE.Mesh(new THREE.BoxGeometry(.01,.62,.01),std('#c9ccd0',.3,.8));sp.rotation.x=k/6*Math.PI;w.add(sp);}w.position.set(0,.375,z);g.add(w);w.userData.front=z>0;ws.push(w);}body.position.y=.015;
  return {g,body,L:1.8,W:.6,wr:.36,wheels:ws};}

/* ---------- court NPCs: Mr Tang (basketball) and Miss Yau (cheer dance) ---------- */
const CHEER=[];
function setupCourt(){const q1=L2W(86,24);NPC.tang=npc('鄧Sir',{shirt:'#c8102e',pants:'#c8102e',hair:'#111'},q1.x,q1.z,-Math.PI/2,'#ffb07a');
  const wh=new THREE.Mesh(new THREE.BoxGeometry(.05,.05,.1),std('#c9ccd0',.3,.8));wh.position.set(0,1.3,.17);NPC.tang.b.add(wh);const ball=new THREE.Mesh(new THREE.SphereGeometry(.12,12,10),std('#e36414',.6));ball.position.set(0,-.7,.1);NPC.tang.arms[0].add(ball);NPC.tang.arms[0].rotation.x=-.5;
  const q2=L2W(48,33);NPC.yau=npc('Miss邱',{shirt:'#ff7eb6',pants:'#ff7eb6',hair:'#2a1a12',long:true},q2.x,q2.z,Math.PI/2,'#ff9db0');
  for(let i=0;i<4;i++){const q=L2W(51+i*1.6,30.5+(i%2)*1.2);const p=litePerson({shirt:'#f4f4f0',pants:'#1d8a4c',hair:pick(['#121212','#2a1a12']),girl:true,uni:false});const sk=new THREE.Mesh(new THREE.CylinderGeometry(.2,.32,.38,12),std('#1d8a4c',.7));sk.position.y=.76;p.b.add(sk);
    for(const a of p.arms){const pp=new THREE.Mesh(new THREE.IcosahedronGeometry(.13,0),std(i%2?'#ffd23f':'#36d6a2',.7));pp.position.y=-.68;a.add(pp);}p.g.position.set(q.x,0,q.z);p.g.rotation.y=Math.PI/2;p.base={x:q.x,z:q.z};p.ph=i*.7;CHEER.push(p);}
  INTER.push({npc:NPC.tang,r:2.6,label:'同鄧Sir傾偈（投籃挑戰）',ok:()=>!PLAYER.car,act:()=>ask('鄧Sir','喂同學！夠唔夠膽同我玩 45 秒投籃挑戰？入得多有獎！',['嚟！','唔玩喇'],k=>{if(k===0)openBasket();else say([['鄧Sir','冇膽就算，多啲做運動呀！']]);})});
  INTER.push({npc:NPC.yau,r:2.6,label:'同Miss邱傾偈（啦啦隊跳舞）',ok:()=>!PLAYER.car,act:()=>ask('Miss邱','啦啦隊練緊舞，你要唔要跟住節拍一齊跳？',['跳！','下次先'],k=>{if(k===0)startDance();else say([['Miss邱','得閒再嚟練啦！']]);})});}
function cheerUpdate(dt){const near=Math.hypot(PLAYER.x-CX(55),PLAYER.z-CZ(32))<90;const t=DANCE.on?danceBeat():performance.now()/1000*2.07;
  for(const p of CHEER){p.g.visible=near;if(!near)continue;const b=t+p.ph*0;const k=Math.floor(b)%4,f=b%1,e=Math.sin(f*Math.PI);
    const A=p.arms;if(k===0){A[0].rotation.set(-2.9,0,-.3);A[1].rotation.set(-2.9,0,.3);}else if(k===1){A[0].rotation.set(-1.6,0,-.9*e);A[1].rotation.set(-.2,0,.2);}else if(k===2){A[1].rotation.set(-1.6,0,.9*e);A[0].rotation.set(-.2,0,-.2);}else{A[0].rotation.set(-2.6*e,0,-.5);A[1].rotation.set(-2.6*e,0,.5);}
    p.b.position.y=Math.abs(Math.sin(b*Math.PI))*.12;p.legs[0].rotation.x=k===3?-.6*e:0;}
  if(NPC.yau&&NPC.yau.g.visible){const A=NPC.yau.arms;A[0].rotation.x=-1.2+Math.sin(t*Math.PI)*.4;A[1].rotation.x=-1.2-Math.sin(t*Math.PI)*.4;}}

/* ---------- basketball challenge ---------- */
const BB={on:false};
function openBasket(){openModal('bball',`<div class="mh">鄧Sir 投籃挑戰・45 秒</div><div class="mq" id="bbq">㩒住儲力，放手投籃！遠過虛線有三分</div><canvas id="bbc" width="360" height="470"></canvas><div class="mrow"><button class="mbtn" id="bbBtn">㩒住投籃</button><span class="pr" id="bbScore">0 分</span><button class="mbtn ghost" id="bbQuit">唔玩喇</button></div>`);
  Object.assign(BB,{on:true,t:45,score:0,made:0,shots:0,streak:0,hold:false,power:0,pdir:1,ball:null,sx:R(40,200),msg:'',msgT:0});
  const btn=$('#bbBtn'),cv=$('#bbc');const down=e=>{e.preventDefault();if(!BB.ball)BB.hold=true;};const up=e=>{e&&e.preventDefault();if(BB.hold){BB.hold=false;bbShoot();}};
  for(const el of [btn,cv]){el.addEventListener('pointerdown',down);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);}
  BB.key=e=>{if(e.code==='Space'&&!e.repeat&&modal==='bball'){e.preventDefault();if(e.type==='keydown')down(e);else up(e);}};addEventListener('keydown',BB.key);addEventListener('keyup',BB.key);
  $('#bbQuit').onclick=()=>bbEnd(true);}
function bbShoot(){const p=BB.power;const sp=430+p*330,an=1.0;BB.ball={x:BB.sx+14,y:380,vx:Math.cos(an)*sp,vy:-Math.sin(an)*sp,touched:false,three:BB.sx<110,done:false,trail:[]};BB.shots++;sfx('swing',.5);}
function bbEnd(quit){if(!BB.on)return;BB.on=false;removeEventListener('keydown',BB.key);removeEventListener('keyup',BB.key);closeModal();const s=BB.score;const pay=s*4;if(pay)addMoney(pay,true);gainXP(s*2+5);bodyChange(-.015-BB.shots*.001,.01+BB.shots*.0015,true);
  say([['鄧Sir',s>=24?`${s} 分？！你嚟籃球隊啦！獎你 $${pay}！`:s>=12?`${s} 分，唔錯喎！獎你 $${pay}，繼續練！`:s>0?`${s} 分…多啲落嚟練波啦。$${pay} 買支水飲。`:'一球都唔入？下次再嚟！']]);}
function bbTick(dt){if(!BB.on||modal!=='bball')return;BB.t-=dt;if(BB.msgT>0)BB.msgT-=dt;
  if(BB.hold){BB.power+=BB.pdir*dt*1.15;if(BB.power>1){BB.power=1;BB.pdir=-1;}if(BB.power<0){BB.power=0;BB.pdir=1;}}
  const b=BB.ball;if(b){const n=3;for(let k=0;k<n;k++){const h=dt/n;b.vy+=900*h;const px=b.x,py=b.y;b.x+=b.vx*h;b.y+=b.vy*h;
      for(const rx of [282,318]){const dx=b.x-rx,dy=b.y-150,d=Math.hypot(dx,dy);if(d<13&&d>0){const nx=dx/d,ny=dy/d;const vn=b.vx*nx+b.vy*ny;if(vn<0){b.vx-=1.6*vn*nx;b.vy-=1.6*vn*ny;b.touched=true;sfx('hit',.15);}b.x=rx+nx*13;b.y=150+ny*13;}}
      if(b.x+10>324&&b.y>78&&b.y<172&&b.vx>0){b.vx=-Math.abs(b.vx)*.55;b.touched=true;sfx('hit',.2);}
      if(!b.done&&py<150&&b.y>=150&&b.vy>0&&b.x>286&&b.x<314){b.done=true;const pts=b.three?3:2;const bonus=!b.touched?1:0;BB.streak++;BB.score+=pts+bonus+(BB.streak>=3?1:0);BB.made++;BB.msg=(b.three?'三分波！':'入咗！')+(bonus?' 空心！':'')+(BB.streak>=3?' 手感發熱🔥':'');BB.msgT=1.2;sfx('ok');}}
    b.trail.push([b.x,b.y]);if(b.trail.length>10)b.trail.shift();
    if(b.y>460||b.x<-20||b.x>380){if(!b.done){BB.streak=0;BB.msg='唔入…';BB.msgT=.8;}BB.ball=null;BB.power=0;BB.pdir=1;BB.sx=R(40,210);}}
  $('#bbScore').textContent=BB.score+' 分';if(BB.t<=0&&!BB.ball){bbEnd(false);return;}drawBB();}
function drawBB(){const c=$('#bbc');if(!c)return;const g=c.getContext('2d');const W=360,H=470;const gr=g.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#2b3a55');gr.addColorStop(1,'#151b29');g.fillStyle=gr;g.fillRect(0,0,W,H);
  g.fillStyle='#b5523a';g.fillRect(0,420,W,50);g.strokeStyle='#f2efe6';g.lineWidth=2;g.setLineDash([6,6]);g.beginPath();g.moveTo(124,420);g.lineTo(124,470);g.stroke();g.setLineDash([]);g.fillStyle='#f2efe6';g.font=`700 12px ${FS}`;g.fillText('三分線',100,415);
  g.fillStyle='#f4f4f4';g.fillRect(324,78,8,94);g.strokeStyle='#c8102e';g.lineWidth=2;g.strokeRect(326,110,6,30);g.fillStyle='#333';g.fillRect(332,150,6,270);
  g.strokeStyle='#e36414';g.lineWidth=4;g.beginPath();g.moveTo(282,150);g.lineTo(318,150);g.stroke();g.strokeStyle='rgba(255,255,255,.7)';g.lineWidth=1;for(let k=0;k<5;k++){g.beginPath();g.moveTo(284+k*8,152);g.lineTo(290+k*5,180);g.stroke();}
  const sx=BB.sx;g.fillStyle='#1f2b4d';g.fillRect(sx,372,22,40);g.fillStyle='#e8bf98';g.beginPath();g.arc(sx+11,362,10,0,TAU);g.fill();g.fillStyle='#4f545b';g.fillRect(sx+2,410,8,12);g.fillRect(sx+12,410,8,12);
  if(!BB.ball){g.fillStyle='#e36414';g.beginPath();g.arc(sx+14,352,10,0,TAU);g.fill();g.fillStyle='rgba(0,0,0,.5)';g.fillRect(20,440,200,16);const pg=g.createLinearGradient(20,0,220,0);pg.addColorStop(0,'#3fc27a');pg.addColorStop(.6,'#ffd23f');pg.addColorStop(1,'#e2412f');g.fillStyle=pg;g.fillRect(20,440,200*BB.power,16);g.strokeStyle='#fff';g.strokeRect(20,440,200,16);}
  else{const b=BB.ball;g.fillStyle='rgba(227,100,20,.25)';for(const p of b.trail){g.beginPath();g.arc(p[0],p[1],6,0,TAU);g.fill();}g.fillStyle='#e36414';g.beginPath();g.arc(b.x,b.y,10,0,TAU);g.fill();g.strokeStyle='#5a2a0a';g.lineWidth=1.5;g.beginPath();g.moveTo(b.x-10,b.y);g.lineTo(b.x+10,b.y);g.stroke();}
  g.fillStyle='#ffd23f';g.font=`900 22px ${FS}`;g.textAlign='left';g.fillText('⏱ '+Math.max(0,Math.ceil(BB.t))+'s',14,30);g.fillText('入 '+BB.made+'/'+BB.shots,14,58);
  if(BB.msgT>0){g.textAlign='center';g.font=`900 28px ${FS}`;g.fillStyle=`rgba(255,210,63,${Math.min(1,BB.msgT*2)})`;g.fillText(BB.msg,W/2-20,250);}g.textAlign='left';}

/* ---------- cheer dance rhythm game ---------- */
const DANCE={on:false,bpm:124,dur:40,notes:[],lane:['←','↓','↑','→'],keys:{ArrowLeft:0,ArrowDown:1,ArrowUp:2,ArrowRight:3,KeyD:0,KeyF:1,KeyJ:2,KeyK:3},pose:-1,poseT:0};
function dNow(){return AU.ctx?AU.ctx.currentTime-DANCE.t0:performance.now()/1000-DANCE.t0p;}
function danceBeat(){return Math.max(0,dNow())*DANCE.bpm/60;}
function startDance(){if(DANCE.on)return;const P=PLAYER;const c=L2W(55,28.2);P.x=c.x;P.z=c.z;P.y=0;P.vx=P.vz=0;P.h=-Math.PI/2;
  const FORM=[[57.4,26.1],[57.4,30.3],[59.4,24.3],[59.4,32.1]];for(let i=0;i<CHEER.length;i++){const q=L2W(FORM[i][0],FORM[i][1]);CHEER[i].g.position.set(q.x,0,q.z);CHEER[i].g.rotation.y=-Math.PI/2;}
  const spb=60/DANCE.bpm;DANCE.notes=[];let lastL=0;for(let b=4;b<DANCE.dur/spb-2;b++){const bar=Math.floor(b/4);const pat=[[0,3],[1,2],[0,1,2,3],[3,0]][bar%4];const l=pat[b%pat.length];DANCE.notes.push({t:b*spb,l,hit:false,miss:false});lastL=l;if(b%2===1&&rnd()<.3+Math.min(.3,b/200))DANCE.notes.push({t:(b+.5)*spb,l:(l+2)%4,hit:false,miss:false});}
  Object.assign(DANCE,{on:true,score:0,combo:0,maxC:0,perf:0,good:0,miss:0,judge:'',judgeT:0,nextSched:0,pose:-1});
  if(AU.ctx){DANCE.t0=AU.ctx.currentTime+1.5;}DANCE.t0p=performance.now()/1000+1.5;
  P.dance=true;document.body.classList.add('dancing');$('#dance').hidden=false;sizeDance();toast('跟住節拍撳 ←↓↑→（或者 D F J K／撳下面四條軌）');voiceLine('Miss邱','五、六、七、八，跳！');}
function sizeDance(){const c=$('#dancec');const dpr=Math.min(2,devicePixelRatio||1);const w=Math.min(innerWidth-16,520),h=Math.round(Math.min(innerHeight*.46,380));c.style.width=w+'px';c.style.height=h+'px';c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}
function danceHit(l){if(!DANCE.on)return;const t=dNow();let best=null,bd=.2;for(const n of DANCE.notes){if(n.hit||n.miss||n.l!==l)continue;const d=Math.abs(n.t-t);if(d<bd){bd=d;best=n;}}DANCE.lanePress=DANCE.lanePress||[0,0,0,0];DANCE.lanePress[l]=.15;
  if(!best){DANCE.combo=0;return;}best.hit=true;const pf=bd<.075;DANCE.combo++;DANCE.maxC=Math.max(DANCE.maxC,DANCE.combo);DANCE.score+=(pf?100:50)+Math.min(50,DANCE.combo*2);if(pf)DANCE.perf++;else DANCE.good++;DANCE.judge=pf?'PERFECT':'GOOD';DANCE.judgeT=.5;DANCE.pose=l;DANCE.poseT=.35;}
function danceSchedule(){if(!AU.ctx)return;musicInit();const spb=60/DANCE.bpm,sd=spb/2;const c=AU.ctx;const bass=[45,45,52,50,48,48,43,47];const mel=[76,_,79,_,81,_,79,76,74,_,76,_,72,_,74,_];
  while(DANCE.nextSched*sd<DANCE.dur&&DANCE.t0+DANCE.nextSched*sd<c.currentTime+.25){const i=DANCE.nextSched,t=DANCE.t0+i*sd;if(t>=c.currentTime-.02){if(i%2===0)mkick(t,.5);if(i%4===2)mnoise(t,.12,.18,1800,'bandpass');mnoise(t,.03,.06,8500);
      if(i%2===0)mtone(mtof(bass[(i/2|0)%8]),t,sd*1.6,'sawtooth',.06);const m=mel[i%16];if(m&&i>=8)mtone(mtof(m),t,sd*1.4,'square',.04);if(i%16===0)[64,67,71].forEach(n=>mtone(mtof(n),t,spb*3.5,'triangle',.025));}DANCE.nextSched++;}}
function danceTick(dt){if(!DANCE.on)return;danceSchedule();const t=dNow();if(DANCE.judgeT>0)DANCE.judgeT-=dt;if(DANCE.poseT>0)DANCE.poseT-=dt;if(DANCE.lanePress)for(let i=0;i<4;i++)DANCE.lanePress[i]=Math.max(0,DANCE.lanePress[i]-dt);
  for(const n of DANCE.notes)if(!n.hit&&!n.miss&&t-n.t>.18){n.miss=true;DANCE.miss++;DANCE.combo=0;DANCE.judge='MISS';DANCE.judgeT=.4;}
  drawDance(t);if(t>DANCE.dur+.5)endDance(false);}
function endDance(quit){if(!DANCE.on)return;DANCE.on=false;PLAYER.dance=false;document.body.classList.remove('dancing');$('#dance').hidden=true;camera.clearViewOffset();cam.pitch=.3;
  for(const p of CHEER){p.g.position.x=p.base.x;p.g.position.z=p.base.z;p.g.rotation.y=Math.PI/2;}
  const tot=DANCE.notes.length||1,acc=(DANCE.perf+DANCE.good*.6)/tot;const gr=acc>.9?'S':acc>.75?'A':acc>.55?'B':'C';const pay=quit?0:Math.round(DANCE.score/40);if(pay)addMoney(pay,true);if(!quit){gainXP(Math.round(DANCE.score/120)+5);bodyChange(-.025,.015,true);}
  say([['Miss邱',quit?'唔緊要，下次再練！':gr==='S'?`評級 S！最高連擊 ${DANCE.maxC}！你一定要入啦啦隊！獎你 $${pay}`:gr==='A'?`評級 A，好有節奏感！獎你 $${pay}`:gr==='B'?`評級 B，有少少跟唔切，多啲練習！$${pay} 獎勵你`:`評級 C…跟住拍子數一二三四啦。$${pay}`]]);}
function drawDance(t){const c=$('#dancec');if(!c)return;const g=c.getContext('2d');const W=c.width,H=c.height,dpr=W/parseFloat(c.style.width);g.clearRect(0,0,W,H);g.fillStyle='rgba(10,12,20,.55)';g.fillRect(0,0,W,H);
  const lw=W/4,hitY=H-56*dpr,speed=H*.9/1.6;const cols=['#ff5c8a','#36d6a2','#ffd23f','#6fb8ff'];
  for(let i=0;i<4;i++){g.fillStyle=`rgba(255,255,255,${.04+(DANCE.lanePress?DANCE.lanePress[i]*2:0)})`;g.fillRect(i*lw+2*dpr,0,lw-4*dpr,H);g.strokeStyle=cols[i];g.lineWidth=3*dpr;g.beginPath();g.arc(i*lw+lw/2,hitY,22*dpr,0,TAU);g.stroke();g.fillStyle=cols[i];g.font=`900 ${20*dpr}px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.fillText(DANCE.lane[i],i*lw+lw/2,hitY+1);}
  for(const n of DANCE.notes){if(n.hit)continue;const y=hitY-(n.t-t)*speed;if(y<-30||y>H+30)continue;g.globalAlpha=n.miss?.25:1;g.fillStyle=cols[n.l];g.beginPath();g.arc(n.l*lw+lw/2,y,19*dpr,0,TAU);g.fill();g.fillStyle='#111';g.fillText(DANCE.lane[n.l],n.l*lw+lw/2,y+1);g.globalAlpha=1;}
  g.textAlign='left';g.fillStyle='#fff';g.font=`900 ${18*dpr}px ${FS}`;g.fillText(DANCE.score+' 分',10*dpr,22*dpr);g.fillStyle='#ffd23f';g.fillText('連擊 '+DANCE.combo,10*dpr,46*dpr);g.textAlign='right';g.fillStyle='#fff';g.fillText(t<0?'準備…'+Math.ceil(-t):Math.max(0,Math.ceil(DANCE.dur-t))+'s',W-10*dpr,22*dpr);
  if(DANCE.judgeT>0){g.textAlign='center';g.font=`900 ${30*dpr}px ${FS}`;g.fillStyle=DANCE.judge==='PERFECT'?'#ffd23f':DANCE.judge==='GOOD'?'#36d6a2':'#ff5c5c';g.globalAlpha=Math.min(1,DANCE.judgeT*3);g.fillText(DANCE.judge,W/2,H*.35);g.globalAlpha=1;}}
function setupDance(){addEventListener('keydown',e=>{if(!DANCE.on)return;if(e.code==='Escape'){endDance(true);return;}const l=DANCE.keys[e.code];if(l!=null&&!e.repeat){e.preventDefault();danceHit(l);}});
  const c=$('#dancec');c.addEventListener('pointerdown',e=>{e.preventDefault();const r=c.getBoundingClientRect();danceHit(clamp(Math.floor((e.clientX-r.left)/r.width*4),0,3));});$('#dQuit').onclick=()=>endDance(true);addEventListener('resize',()=>{if(DANCE.on)sizeDance();});}
function dancePose(dt){const P=PLAYER,p=P.p;if(!P.dance||!p)return;const b=danceBeat(),A=p.arms,L=p.legs;const bounce=Math.abs(Math.sin(b*Math.PI));p.b.position.y=bounce*.1;p.b.rotation.set(0,0,0);
  const k=DANCE.poseT>0?DANCE.pose:Math.floor(b)%4;const POSES=[[[-2.9,-.4],[-.3,.2],-.15],[[-1.2,-1.3],[-1.2,1.3],0],[[-3,-.2],[-3,.2],.1],[[-.3,-.2],[-2.9,.4],.15]];const q=POSES[k<0?0:k];
  A[0].rotation.x=lerp(A[0].rotation.x,q[0][0],.35);A[0].rotation.z=lerp(A[0].rotation.z,q[0][1],.35);A[1].rotation.x=lerp(A[1].rotation.x,q[1][0],.35);A[1].rotation.z=lerp(A[1].rotation.z,q[1][1],.35);p.b.rotation.z=q[2];
  L[0].rotation.x=k===1?-.5*bounce:0;L[1].rotation.x=k===2?-.5*bounce:0;}
function danceCam(){const P=PLAYER;const a=-Math.PI/2;camera.position.set(P.x+Math.sin(a)*7.5,2.3,P.z+Math.cos(a)*7.5);camera.lookAt(P.x+1.2,1.1,P.z);const W=innerWidth,H=innerHeight;camera.setViewOffset(W,H,0,Math.round(H*.18),W,H);if(Math.abs(camera.fov-50)>.1){camera.fov=50;camera.updateProjectionMatrix();}sky.position.copy(camera.position);stars.position.copy(camera.position);}

/* ---------- bike riding pose, mission arrow, minimap target, unstuck ---------- */
function bikeRide(){const P=PLAYER,v=P.car;if(!v||v.type!=='bike')return;const p=P.p;p.g.visible=true;p.g.position.set(v.x,v.y,v.z);p.g.rotation.set(0,v.h,0);p.b.position.set(0,.1,-.24);p.b.rotation.set(.3,0,-v.roll*2);const s=v.spin*.9;
  p.legs[0].rotation.x=-.75+Math.sin(s)*.38;p.legs[1].rotation.x=-.75-Math.sin(s)*.38;p.legs[0].rotation.z=.06;p.legs[1].rotation.z=-.06;p.arms[0].rotation.x=p.arms[1].rotation.x=-1.05;p.arms[0].rotation.z=.12;p.arms[1].rotation.z=-.12;P.bikePose=true;}
function mDistArrow(t,d){const el=$('#mDist');if(d<=15){if(el.textContent)el.textContent='';return;}const ang=Math.atan2(t.x-PLAYER.x,t.z-PLAYER.z);const rel=-(ang-(cam.yaw+Math.PI));const deg=Math.round(rel*180/Math.PI/15)*15;const txt=`<span class="arr" style="transform:rotate(${deg}deg)">⬆</span> ${Math.round(d)} 米`;if(el.dataset.t!==txt){el.dataset.t=txt;el.innerHTML=txt;}}
function minimapDraw(){const c=MM.c;if(!c)return;const g=c.getContext('2d'),Sz=c.width,px=(PLAYER.car||PLAYER).x,pz=(PLAYER.car||PLAYER).z;g.save();g.fillStyle='#1b1f27';g.fillRect(0,0,Sz,Sz);g.translate(Sz/2,Sz/2);g.rotate(cam.yaw);const k=1.6;g.scale(k,k);
  g.drawImage(MM.big,-(px-MM.x0)*MM.s,-(pz-MM.z0)*MM.s);g.restore();
  const t=target();if(t){let dx=(t.x-px)*MM.s*k,dz=(t.z-pz)*MM.s*k;const cs=Math.cos(cam.yaw),sn=Math.sin(cam.yaw);let rx=dx*cs-dz*sn,rz=dx*sn+dz*cs;const R0=Sz/2-14,l=Math.hypot(rx,rz);if(l>R0){rx*=R0/l;rz*=R0/l;}g.fillStyle='#ffd23f';g.strokeStyle='#111';g.lineWidth=3;g.font='900 22px sans-serif';g.textAlign='center';g.textBaseline='middle';g.strokeText('★',Sz/2+rx,Sz/2+rz);g.fillText('★',Sz/2+rx,Sz/2+rz);}
  g.save();g.translate(Sz/2,Sz/2);const hd=PLAYER.car?PLAYER.car.h:PLAYER.h;g.rotate(Math.PI-(hd-cam.yaw));g.fillStyle='#ff3d5e';g.strokeStyle='#fff';g.lineWidth=1.5;g.beginPath();g.moveTo(0,-8);g.lineTo(6,7);g.lineTo(0,3.5);g.lineTo(-6,7);g.closePath();g.fill();g.stroke();g.restore();
  g.fillStyle='rgba(243,239,230,.9)';g.font='800 11px "Barlow Condensed",sans-serif';g.textAlign='center';g.textBaseline='alphabetic';g.fillText('N',Sz/2+Math.sin(cam.yaw)*(Sz/2-12),Sz/2-Math.cos(cam.yaw)*(Sz/2-12)+4);}
function unstuck(){if(!started||PLAYER.car||curRoom||dlgQ||modal||busy)return;const P=PLAYER;if(P.ind==='home'){const t=LOC.homeIn;P.x=t.x;P.z=t.z;P.y=HOMEP.h;toast('返到屋企門口');return;}
  const nr=nearestRoad(P.x,P.z,200,r=>r.cls>=5)||nearestRoad(P.x,P.z,400,r=>true);if(!nr)return;P.x=nr.x;P.z=nr.z;P.plat=null;P.top=false;pushOut(P,.4);P.y=TH(P.x,P.z);P.vy=0;P.grounded=true;cam.tx=P.x;cam.tz=P.z;toast('已經送你返最近嘅行人路');}

/* ---------- traffic / pedestrian route sanity ---------- */
function routeBlocked(r,limit){let n=0,bad=0;for(let s=1;s<r.len;s+=4){const q=posOn(r,s);n++;if(solidAt(q.x,1,q.z))bad++;}return n>0&&bad/n>limit;}

/* ---------- boot & per-frame ---------- */
function v3bBoot(){buildWaterIndex();setupWeather();setupCourt();setupDance();
  const bq={x:HX(176.5),z:HZ(-29)};LOC.bike=bq;const bk=spawnVehicle('bike','#2e86de',bq.x,bq.z,Math.PI/2);bk.isBike=true;
  const wk=ROOMS.wenkee;if(wk&&NPC.wk){scene.remove(NPC.wk.g);scene.add(NPC.wk.g);roomPerson(wk,NPC.wk,11,1.9,0,false);}
  $('#tDay').onclick=()=>setTod('day');$('#tDusk').onclick=()=>setTod('dusk');$('#tNight').onclick=()=>setTod('night');
  addEventListener('keydown',e=>{if(!started)return;if(e.code==='KeyR')unstuck();});const us=$('#tStuck');if(us)us.onclick=unstuck;
  for(let i=DRIVE.length-1;i>=0;i--)if(routeBlocked(DRIVE[i],.12))DRIVE.splice(i,1);for(let i=WALKS.length-1;i>=0;i--)if(routeBlocked(WALKS[i],.2))WALKS.splice(i,1);
  for(const p of peds)if(p.road&&!WALKS.includes(p.road)&&WALKS.length)placePed(p,PLAYER.x,PLAYER.z,0,260);
  for(const v of vehicles)if(v.ai&&v.road&&!DRIVE.includes(v.road)){const rs=pickRoadNear(PLAYER.x,PLAYER.z,30,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;}}}
function v3bUpdate(dt){swimUpdate(dt);rippleUpdate(dt);brushUpdate(dt);tvUpdate(dt);cheerUpdate(dt);bbTick(dt);danceTick(dt);dancePose(dt);bikeRide();musicUpdate();}

/* ================= v3c: RPG growth, park + Tetris battle, open shops, room decorating, bathroom ================= */
/* ---------- RPG: level, XP, body (fat / muscle) ---------- */
function rpg(){if(!S.rpg)S.rpg={lv:1,xp:0,fat:.15,mus:.1};return S.rpg;}
function xpNeed(lv){return 100+lv*60;}
function gainXP(n,why){if(!started||!n)return;const r=rpg();r.xp+=Math.round(n);let up=false;while(r.xp>=xpNeed(r.lv)){r.xp-=xpNeed(r.lv);r.lv++;up=true;}
  if(up){sfx('gold');toast(`升級！Lv ${r.lv}　力量同體力提升`);voiceLine('你',pick(['升咗級喇！','我又勁咗！']));}else if(why)toast(`+${Math.round(n)} XP　${why}`);hudLv();save();}
function bodyChange(df,dm,silent){const r=rpg();const f0=r.fat,m0=r.mus;r.fat=clamp(r.fat+df,0,1);r.mus=clamp(r.mus+dm,0,1);
  if(Math.abs(r.fat-(r.bf||0))>.015||Math.abs(r.mus-(r.bm||0))>.015){r.bf=r.fat;r.bm=r.mus;applyBody(PLAYER.p);}
  if(!silent){if(df>.004)toast('食飽飽…體重 ↑');else if(dm>.004)toast('做運動！肌肉 ↑');}hudLv();}
function powMul(){const r=rpg();return 1+(r.lv-1)*.05+r.mus*.5;}
function spdMul(){const r=rpg();return clamp(1-r.fat*.28+r.mus*.06,.7,1.1);}
function applyBody(p){if(!p||!p.b)return;const r=rpg();const fat=r.fat,mus=r.mus;const b=p.b,ch=b.children;const torso=ch[0],hip=ch[1];
  const zf=1+fat*.75+mus*.12;torso.scale.set(1+fat*.55+mus*.28,1,.72*zf);hip.scale.set(1+fat*.55,1,.75*(1+fat*.6));
  for(const a of p.arms){const m=a.children[0];m.scale.set(1+mus*.75+fat*.35,1,1+mus*.75+fat*.35);a.position.x=Math.sign(a.position.x)*(.27+fat*.09+mus*.05);}
  for(const l of p.legs){const m=l.children[0];m.scale.set(1+fat*.45+mus*.35,1,1+fat*.45+mus*.35);l.position.x=Math.sign(l.position.x)*(.1+fat*.04);}
  for(const m of ch){if(m===torso||m===hip||!m.isMesh||p.arms.includes(m)||p.legs.includes(m))continue;const y=m.position.y;if(y<.95||y>1.56)continue;if(m.userData.bz==null)m.userData.bz=m.position.z;if(Math.abs(m.userData.bz)>.1)m.position.z=m.userData.bz*zf;}
  if(!p.belly){p.belly=new THREE.Mesh(new THREE.SphereGeometry(.2,14,10),torso.material);b.add(p.belly);}p.belly.visible=fat>.3;const k=Math.max(0,fat-.3)/.7;p.belly.position.set(0,1.02,.04+k*.06);p.belly.scale.set(1+k*.45,.9,.75+k*.45);
  if(!p.delts){p.delts=[-1,1].map(s=>{const d=new THREE.Mesh(new THREE.SphereGeometry(.1,10,8),torso.material);d.position.set(s*.25,1.45,0);b.add(d);return d;});}for(const d of p.delts){d.visible=mus>.35;d.scale.setScalar(.8+mus*.8);d.position.x=Math.sign(d.position.x)*(.25+mus*.06+fat*.08);}}
function hudLv(){const r=rpg();let el=$('#lv');if(!el){const st=$('#stats');if(!st)return;el=document.createElement('button');el.id='lv';el.onclick=openCharSheet;st.insertBefore(el,st.firstChild);}
  const t=`Lv${r.lv}`;if(el.dataset.t!==t){el.dataset.t=t;el.textContent=t;}const bar=$('#xpbar')||(()=>{const d=document.createElement('div');d.id='xpbar';d.innerHTML='<i></i>';$('#stats').appendChild(d);return d;})();bar.firstChild.style.width=Math.round(r.xp/xpNeed(r.lv)*100)+'%';}
function bodyWord(f){return f<.12?'好瘦':f<.3?'標準':f<.55?'有啲肉':f<.8?'肥嘟嘟':'超級肥';}function musWord(m){return m<.15?'冇乜肌肉':m<.4?'有少少肌':m<.7?'幾大隻':'超級大隻';}
function openCharSheet(){if(!started||modal)return;const r=rpg();const bar=(v,c)=>`<div class="cbar"><i style="width:${Math.round(v*100)}%;background:${c}"></i></div>`;
  openModal('char',`<div class="mh">角色資料</div><div class="mq">Lv ${r.lv}　<span style="font-size:14px;color:var(--dim)">XP ${r.xp} / ${xpNeed(r.lv)}</span></div>${bar(r.xp/xpNeed(r.lv),'var(--amber)')}
  <div class="row"><div class="nm"><b>體型：${bodyWord(r.fat)}</b><span>食嘢會肥，跑步、游水、踩單車、打波、跳舞會瘦</span></div></div>${bar(r.fat,'#ff8a5c')}
  <div class="row"><div class="nm"><b>肌肉：${musWord(r.mus)}</b><span>做運動同打交會大隻，出拳更痛</span></div></div>${bar(r.mus,'#36d6a2')}
  <div class="row"><div class="nm"><b>力量 ×${powMul().toFixed(2)}　速度 ×${spdMul().toFixed(2)}</b><span>升級、肌肉提升力量；太肥會跑得慢、跳得矮</span></div></div>
  <div class="mrow"><span></span><button class="mbtn" id="charClose">知道</button></div>`);$('#charClose').onclick=closeModal;}
let runAcc=0;function rpgUpdate(dt){const P=PLAYER;if(!started)return;let ex=0;
  if(P.car&&P.car.type==='bike')ex=Math.abs(P.car.speed)*dt*1.4;else if(!P.car&&!P.riding&&P.spd>5.5&&P.grounded!==false)ex=P.spd*dt;else if(P.swim&&P.spd>.6)ex=P.spd*dt*2.2;
  if(ex>0){runAcc+=ex;if(runAcc>60){runAcc-=60;bodyChange(-.006,.004,true);gainXP(3);}}}

/* ---------- park under the home tower: playground, kids, Game Boy Tetris ---------- */
const PARK={x0:-872,x1:-797,z0:241,z1:294};const KIDS=[];
function pbox(B,w,h,d,x,y,z,ry=0){B.geo(new THREE.BoxGeometry(w,h,d),new THREE.Matrix4().makeRotationY(ry).setPosition(x,y,z));}
function buildPark(){const P=PARK,G=new THREE.Group();scene.add(G);PARK.g=G;const cx=(P.x0+P.x1)/2,cz=(P.z0+P.z1)/2,W=P.x1-P.x0,Dd=P.z1-P.z0;
  const gt=(()=>{const [c,g]=cvs(256,256);noiseFill(g,256,256,'#6a9a48',7000,.05,.15,3);return ctex(c,true);})();gt.repeat.set(W/8,Dd/8);
  const grass=new THREE.Mesh(new THREE.PlaneGeometry(W,Dd),new THREE.MeshStandardMaterial({map:gt,roughness:1,polygonOffset:true,polygonOffsetFactor:-5,polygonOffsetUnits:-5}));grass.rotation.x=-Math.PI/2;grass.position.set(cx,.03,cz);grass.receiveShadow=true;G.add(grass);
  const pathM=std('#d9d2c4',.85,0,{polygonOffset:true,polygonOffsetFactor:-6,polygonOffsetUnits:-6}),mulch=std('#8a4a3a',.95,0,{polygonOffset:true,polygonOffsetFactor:-7,polygonOffsetUnits:-7});
  const flat=(x0,z0,x1,z1,m,y=.045)=>{const me=new THREE.Mesh(new THREE.PlaneGeometry(x1-x0,z1-z0),m);me.rotation.x=-Math.PI/2;me.position.set((x0+x1)/2,y,(z0+z1)/2);me.receiveShadow=true;G.add(me);};
  flat(P.x0+3,P.z0+3,P.x1-3,P.z0+5.4,pathM);flat(P.x0+3,P.z1-5.4,P.x1-3,P.z1-3,pathM);flat(P.x0+3,P.z0+3,P.x0+5.4,P.z1-3,pathM);flat(P.x1-5.4,P.z0+3,P.x1-3,P.z1-3,pathM);flat(P.x1-5.4,P.z0-6,P.x1-3,P.z0+3,pathM);
  // playground on rubber mulch
  const px=P.x0+28,pz=cz;flat(px-14,pz-10,px+14,pz+10,mulch,.05);
  const B=new Map();const bt=(m)=>{if(!B.has(m))B.set(m,new Batch());return B.get(m);};
  const post=std('#2e6fd0',.5,.3),deck=std('#ffd23f',.6),roofC=[std('#36a852',.6),std('#2e86de',.6),std('#e2412f',.6)],slide=std('#e2412f',.4),rail=std('#2bb3a3',.5,.3);
  const towers=[[px-6,pz-3],[px,pz-3],[px+6,pz-3]];
  towers.forEach(([x,z],i)=>{for(const [dx,dz] of [[-1,-1],[1,-1],[-1,1],[1,1]])pbox(bt(post),.16,3.6,.16,x+dx*1.1,1.8,z+dz*1.1);pbox(bt(deck),2.4,.15,2.4,x,1.55,z);addSolidBox(x-1.2,z-1.2,x+1.2,z+1.2,1.35,1.62);
    const rf=new THREE.Mesh(new THREE.ConeGeometry(1.85,1.2,4),roofC[i]);rf.rotation.y=Math.PI/4;rf.position.set(x,4.2,z);rf.castShadow=true;G.add(rf);
    for(const s of [-1,1])pbox(bt(rail),2.4,.08,.08,x,2.45,z+s*1.18);for(let k=0;k<4;k++)pbox(bt(rail),.06,.9,.06,x-.9+k*.6,2.0,z+1.18);
    for(const [dx,dz] of [[-1,-1],[1,-1],[-1,1],[1,1]])addSolidBox(x+dx*1.1-.1,z+dz*1.1-.1,x+dx*1.1+.1,z+dz*1.1+.1,0,3.6);});
  for(let i=0;i<2;i++){const x=px-3+i*6;pbox(bt(std('#a86b3a',.7)),3.6,.1,1.1,x,1.55,pz-3);for(const s of [-1,1])pbox(bt(rail),3.6,.07,.07,x,2.2,pz-3+s*.55);addSolidBox(x-1.8,pz-3.55,x+1.8,pz-2.45,1.35,1.62);}
  // slides and steps
  const sl=new THREE.Mesh(new THREE.BoxGeometry(.9,.08,4.2),slide);sl.position.set(px-6,.85,pz+1.6);sl.rotation.x=-.4;sl.castShadow=true;G.add(sl);for(const s of [-1,1]){const e=new THREE.Mesh(new THREE.BoxGeometry(.06,.25,4.2),slide);e.position.set(px-6+s*.45,.98,pz+1.6);e.rotation.x=-.4;G.add(e);}
  const tube=new THREE.Mesh(new THREE.CylinderGeometry(.5,.5,4.4,14,1,true),std('#ffb53f',.4));tube.material.side=THREE.DoubleSide;tube.position.set(px+6,.9,pz+1.8);tube.rotation.x=Math.PI/2-.38;tube.castShadow=true;G.add(tube);
  for(let k=0;k<4;k++){pbox(bt(std('#5a6470',.6)),1.2,.12,.6,px,.25+k*.38,pz-.3+k*-.62);addSolidBox(px-.6,pz-.6-k*.62,px+.6,pz-k*.62,0,.31+k*.38,{noStand:false});}
  const cw=new THREE.Mesh(new THREE.BoxGeometry(2.2,1.6,.12),std('#2e6fd0',.6));cw.position.set(px+3,.8,pz-1.75);cw.rotation.x=.25;G.add(cw);for(let k=0;k<10;k++){const h=new THREE.Mesh(new THREE.SphereGeometry(.07,6,5),std(pick(['#ffd23f','#e2412f','#36d6a2','#ff7eb6']),.6));h.position.set(px+3+R(-.9,.9),R(.2,1.5),pz-1.62);G.add(h);}
  // swings
  const sx=px+11,sz=pz+5;for(const s of [-1,1]){pbox(bt(std('#e2412f',.5,.3)),.14,3.2,.14,sx-2.8*s,1.55,sz-.7);pbox(bt(std('#e2412f',.5,.3)),.14,3.2,.14,sx-2.8*s,1.55,sz+.7);}pbox(bt(std('#e2412f',.5,.3)),5.8,.16,.16,sx,3.12,sz);
  for(const s of [-1,1])addSolidBox(sx-2.8*s-.1,sz-.8,sx-2.8*s+.1,sz+.8,0,3.2);
  PARK.swings=[];for(let i=0;i<3;i++){const sw=new THREE.Group();sw.position.set(sx-1.7+i*1.7,3.05,sz);G.add(sw);for(const s of [-1,1]){const c=new THREE.Mesh(new THREE.CylinderGeometry(.015,.015,2.5,4),std('#999',.4,.8));c.position.set(s*.25,-1.25,0);sw.add(c);}const seat=new THREE.Mesh(new THREE.BoxGeometry(.6,.06,.3),std('#222',.6));seat.position.y=-2.5;sw.add(seat);PARK.swings.push(sw);}
  // spring riders, see-saw, sandpit
  for(const [x,z,c] of [[px-11,pz+6,'#36d6a2'],[px-8.5,pz+7.5,'#ff7eb6']]){pbox(bt(std('#888',.4,.8)),.12,.5,.12,x,.25,z);const body=new THREE.Mesh(new THREE.SphereGeometry(.45,12,8),std(c,.5));body.scale.set(1.4,.8,.8);body.position.set(x,.75,z);G.add(body);const hd=new THREE.Mesh(new THREE.SphereGeometry(.25,10,8),std(c,.5));hd.position.set(x+.6,1.05,z);G.add(hd);}
  PARK.seesaw=new THREE.Mesh(new THREE.BoxGeometry(4,.1,.35),std('#ffd23f',.6));PARK.seesaw.position.set(px-9,.55,pz-7);G.add(PARK.seesaw);pbox(bt(std('#555',.5,.5)),.3,.5,.3,px-9,.25,pz-7);
  flat(px+7,pz-9.5,px+13,pz-5,std('#e6d29a',1,0,{polygonOffset:true,polygonOffsetFactor:-8,polygonOffsetUnits:-8}),.06);for(const [a,b,c2,d2] of [[px+6.8,pz-9.7,px+13.2,pz-9.4],[px+6.8,pz-5.1,px+13.2,pz-4.8],[px+6.8,pz-9.7,px+7.1,pz-4.8],[px+12.9,pz-9.7,px+13.2,pz-4.8]])pbox(bt(std('#7a5232',.7)),c2-a,.3,d2-b,(a+c2)/2,.15,(b+d2)/2);
  // benches, picnic shelter, entrance sign, lamps
  const wood=std('#8a5a32',.7),iron=std('#333',.5,.5);const bench=(x,z,ry)=>{pbox(bt(wood),1.8,.08,.5,x,.48,z,ry);pbox(bt(wood),1.8,.4,.06,x-Math.sin(ry)*.25,.75,z-Math.cos(ry)*.25,ry);pbox(bt(iron),.08,.48,.5,x+Math.cos(ry)*.8,.24,z-Math.sin(ry)*.8,ry);pbox(bt(iron),.08,.48,.5,x-Math.cos(ry)*.8,.24,z+Math.sin(ry)*.8,ry);addSolidBox(x-.9,z-.3,x+.9,z+.3,0,.52);};
  PARK.benchGB={x:P.x0+12,z:P.z0+8};bench(PARK.benchGB.x,PARK.benchGB.z,Math.PI);bench(P.x0+12,P.z1-8,0);bench(P.x1-12,P.z1-8,0);bench(P.x1-14,P.z0+8,Math.PI);
  const shx=P.x1-14,shz=cz;for(const [dx,dz] of [[-2.5,-2],[2.5,-2],[-2.5,2],[2.5,2]]){pbox(bt(wood),.2,2.6,.2,shx+dx,1.3,shz+dz);addSolidBox(shx+dx-.1,shz+dz-.1,shx+dx+.1,shz+dz+.1,0,2.6);}const rf=new THREE.Mesh(new THREE.ConeGeometry(4.4,1.4,4),std('#6b3a2a',.8));rf.rotation.y=Math.PI/4;rf.position.set(shx,3.3,shz);rf.castShadow=true;G.add(rf);
  pbox(bt(wood),3,.08,1.1,shx,.78,shz);addSolidBox(shx-1.5,shz-.55,shx+1.5,shz+.55,0,.82);for(const s of [-1,1]){pbox(bt(wood),3,.06,.35,shx,.45,shz+s*.9);}
  {const t=textPlane('金朗公園',3.2,.8,{bg:'#3a5a2a',fg:'#ffe9a8',border:'#ffe9a8'});t.position.set(P.x1-3,1.6,P.z0+1.4);t.rotation.y=Math.PI/2;G.add(t);pbox(bt(wood),.12,1.6,.12,P.x1-3,.8,P.z0-.1);pbox(bt(wood),.12,1.6,.12,P.x1-3,.8,P.z0+2.9);}
  for(const [m,b] of B){const me=new THREE.Mesh(b.build(),m);me.castShadow=true;me.receiveShadow=true;G.add(me);}
  for(let i=0;i<16;i++){const ang=i/16*TAU;const x=cx+Math.cos(ang)*(W/2-1.6)*R(.9,1),z=cz+Math.sin(ang)*(Dd/2-1.4)*R(.9,1);if(Math.abs(x-px)<16&&Math.abs(z-pz)<12)continue;put('trunk',x,0,z,0);put('tree',x,0,z,R(0,TAU),[R(.9,1.3),R(.9,1.4),R(.9,1.3)],lin(pick(['#3f7d3a','#4f8f3f','#2f6b3a','#5c9446'])));addSolidBox(x-.25,z-.25,x+.25,z+.25,0,3);}
  MAPPOLY.push({pts:[[P.x0,P.z0],[P.x1,P.z0],[P.x1,P.z1],[P.x0,P.z1]],col:'#2d4a32'});LOC.park={x:P.x1-6,z:cz};PARK.px=px;PARK.pz=pz;}
function kid(o){const p=litePerson(Object.assign({shirt:pick(['#ffd23f','#e2412f','#2e86de','#36d6a2','#ff7eb6','#f4f4f0']),pants:pick(['#2b3550','#5d4b3a','#222']),hair:pick(['#121212','#2a1a12']),girl:rnd()<.5},o||{}));p.g.scale.setScalar(.66);return p;}
function setupParkKids(){const P=PARK,px=P.px,pz=P.pz;
  PARK.swings.forEach((sw,i)=>{if(i===1)return;const k=kid();k.mode='swing';k.sw=sw;k.ph=i*1.3;seatPose(k,true);KIDS.push(k);});
  for(let i=0;i<5;i++){const k=kid();k.mode='run';k.home=[px+R(-12,12),pz+R(-8,8)];k.g.position.set(k.home[0],0,k.home[1]);k.tx=k.home[0];k.tz=k.home[1];k.wt=0;KIDS.push(k);}
  for(const s of [-1,1]){const k=kid();k.mode='seesaw';k.side=s;seatPose(k,true);KIDS.push(k);}
  for(let i=0;i<2;i++){const k=kid();k.mode='sand';k.g.position.set(px+9+i*2,0,pz-7.2);k.g.rotation.y=i?-1.2:1.2;seatPose(k,true);k.legs[0].rotation.x=k.legs[1].rotation.x=-1.2;k.b.position.y=-.6;KIDS.push(k);}
  // the Game Boy kid on the bench
  const b=PARK.benchGB;const gk=npc('細路仔阿仔',{shirt:'#2e86de',pants:'#2b3550',hair:'#121212'},b.x,b.z+.1,0,'#9cd7ff');gk.g.scale.setScalar(.7);seatPose(gk,true);gk.b.position.y=-.42+.2;
  const gb=new THREE.Group();const bd=new THREE.Mesh(new THREE.BoxGeometry(.2,.3,.06),std('#c8c4bc',.6));gb.add(bd);const sc=new THREE.Mesh(new THREE.PlaneGeometry(.13,.11),new THREE.MeshBasicMaterial({color:lin('#9bbc0f'),toneMapped:false}));sc.position.set(0,.06,.031);gb.add(sc);gb.position.set(0,1.05,.42);gb.rotation.x=-.5;gk.b.add(gb);gk.arms[0].rotation.x=gk.arms[1].rotation.x=-1.0;gk.arms[0].rotation.z=.35;gk.arms[1].rotation.z=-.35;NPC.gbkid=gk;
  const k2=kid({shirt:'#e2412f'});k2.g.position.set(b.x+.8,0,b.z+.1);k2.g.rotation.y=0;seatPose(k2,true);k2.mode='watch';KIDS.push(k2);
  INTER.push({npc:gk,r:2.4,label:'同阿仔傾偈（Game Boy 俄羅斯方塊）',ok:()=>!PLAYER.car,act:()=>ask('細路仔阿仔','哥哥，你識唔識玩俄羅斯方塊？同我對打，贏咗我就俾 $100 你！',['嚟！','唔玩喇'],k=>{if(k===0)openTetris();else say([['細路仔阿仔','驚輸呀？哈哈！']]);})});}
function kidsUpdate(dt){const near=Math.hypot(PLAYER.x-(PARK.x0+PARK.x1)/2,PLAYER.z-(PARK.z0+PARK.z1)/2)<110&&!PLAYER.ind&&!curRoom;if(!PARK.g)return;PARK.g.visible=true;const t=performance.now()/1000;
  const sws=PARK.swings;sws.forEach((sw,i)=>{sw.rotation.x=Math.sin(t*1.8+i*1.3)*(i===1?.12:.55);});
  if(PARK.seesaw)PARK.seesaw.rotation.z=Math.sin(t*1.4)*.22;
  for(const k of KIDS){k.g.visible=near;if(!near)continue;
    if(k.mode==='swing'){const sw=k.sw;const a=sw.rotation.x;const p=new THREE.Vector3(0,-2.5,0).applyEuler(sw.rotation).add(sw.position);k.g.position.set(p.x,p.y-.08,p.z+.05);k.g.rotation.set(a,Math.PI,0);}
    else if(k.mode==='seesaw'){const s=PARK.seesaw;const a=s.rotation.z;k.g.position.set(s.position.x+k.side*1.7*Math.cos(a),s.position.y+k.side*1.7*Math.sin(a)-.15,s.position.z);k.g.rotation.y=k.side>0?-Math.PI/2:Math.PI/2;}
    else if(k.mode==='run'){k.wt-=dt;if(k.wt<=0){k.wt=R(1.5,4);k.tx=k.home[0]+R(-7,7);k.tz=k.home[1]+R(-6,6);}const g=k.g,dx=k.tx-g.position.x,dz=k.tz-g.position.z,d=Math.hypot(dx,dz);let sp=0;if(d>.3){sp=2.6;const o={x:g.position.x+dx/d*sp*dt,z:g.position.z+dz/d*sp*dt};pushOut(o,.25);g.position.x=o.x;g.position.z=o.z;g.rotation.y=Math.atan2(dx,dz);}animP(k,sp,dt);}
    else if(k.mode==='sand'){k.arms[0].rotation.x=-1+Math.sin(t*3+k.g.position.x)*.4;}
    else if(k.mode==='watch'){k.head.rotation.y=-.6+Math.sin(t*.8)*.1;}}}

/* ---------- Tetris battle vs CPU (Game Boy style) ---------- */
const TET={on:false};const TP={I:[[0,1],[1,1],[2,1],[3,1]],O:[[1,0],[2,0],[1,1],[2,1]],T:[[1,0],[0,1],[1,1],[2,1]],S:[[1,0],[2,0],[0,1],[1,1]],Z:[[0,0],[1,0],[1,1],[2,1]],J:[[0,0],[0,1],[1,1],[2,1]],L:[[2,0],[0,1],[1,1],[2,1]]};
function tRot(cells,r,k){let c=cells.map(q=>q.slice());const n=k==='I'?4:k==='O'?3:3;for(let i=0;i<r;i++)c=c.map(([x,y])=>[n-1-y,x]);if(k==='O')return TP.O;return c;}
function tBag(b){if(!b.bag||!b.bag.length){b.bag=['I','O','T','S','Z','J','L'];for(let i=b.bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b.bag[i],b.bag[j]]=[b.bag[j],b.bag[i]];}}return b.bag.pop();}
function tNewBoard(cpu){const b={g:Array.from({length:20},()=>Array(10).fill(0)),cpu,score:0,lines:0,garb:0,dead:false,fall:0,next:null,bag:null};b.next=tBag(b);tSpawn(b);return b;}
function tCells(b,p){p=p||b.p;return tRot(TP[p.k],p.r,p.k).map(([x,y])=>[x+p.x,y+p.y]);}
function tFits(b,p){for(const [x,y] of tCells(b,p)){if(x<0||x>9||y>19)return false;if(y>=0&&b.g[y][x])return false;}return true;}
function tSpawn(b){const k=b.next;b.next=tBag(b);b.p={k,r:0,x:3,y:-1};if(!tFits(b,b.p)){b.p.y=-2;if(!tFits(b,b.p)){b.dead=true;}}if(b.cpu)b.plan=null;}
function tLock(b,o){for(const [x,y] of tCells(b)){if(y<0){b.dead=true;continue;}b.g[y][x]=TET.colorOf[b.p.k];}let n=0;for(let y=19;y>=0;y--){if(b.g[y].every(v=>v)){b.g.splice(y,1);b.g.unshift(Array(10).fill(0));n++;y++;}}
  if(n){b.lines+=n;b.score+=[0,100,300,500,800][n];const send=[0,0,1,2,4][n];if(send){if(b.garb>0){const c=Math.min(b.garb,send);b.garb-=c;o.garb+=send-c;}else o.garb+=send;}sfx(n>=4?'gold':'ok',.5);if(!b.cpu&&n>=2){TET.msg=n>=4?'TETRIS！':n+' 行！';TET.msgT=1;}}
  else if(b.garb>0){const g=b.garb;b.garb=0;for(let i=0;i<g;i++){b.g.shift();const row=Array(10).fill(8);row[Math.floor(Math.random()*10)]=0;b.g.push(row);}if(!b.cpu)sfx('bad',.5);}
  tSpawn(b);}
function tMove(b,dx,dy,dr,o){const p=Object.assign({},b.p,{x:b.p.x+dx,y:b.p.y+dy,r:(b.p.r+(dr||0)+4)%4});if(tFits(b,p)){b.p=p;return true;}if(dr){for(const k of [1,-1,2,-2]){const q=Object.assign({},p,{x:p.x+k});if(tFits(b,q)){b.p=q;return true;}}}if(dy>0&&o)tLock(b,o);return false;}
function tDrop(b,o){while(tMove(b,0,1,0,null));tLock(b,o);}
function tEval(g){const h=[];let holes=0;for(let x=0;x<10;x++){let top=20;for(let y=0;y<20;y++)if(g[y][x]){top=y;break;}h.push(20-top);for(let y=top+1;y<20;y++)if(!g[y][x])holes++;}let agg=0,bump=0;for(let x=0;x<10;x++){agg+=h[x];if(x)bump+=Math.abs(h[x]-h[x-1]);}return {agg,bump,holes,maxh:Math.max(...h)};}
function tPlan(b){const res=[];for(let r=0;r<4;r++)for(let x=-2;x<10;x++){const p={k:b.p.k,r,x,y:b.p.y};if(!tFits(b,p))continue;while(tFits(b,Object.assign({},p,{y:p.y+1})))p.y++;const g=b.g.map(row=>row.slice());let ok=true;for(const [cx,cy] of tCells(b,p)){if(cy<0){ok=false;break;}g[cy][cx]=1;}if(!ok)continue;let lines=0;for(let y=0;y<20;y++)if(g[y].every(v=>v))lines++;const e=tEval(g);res.push({r,x,s:-.51*e.agg+.76*lines-.36*e.holes-.18*e.bump-(e.maxh>15?2:0)});}
  res.sort((a,b2)=>b2.s-a.s);const pickI=Math.random()<TET.cpuErr?Math.min(res.length-1,1+Math.floor(Math.random()*6)):0;return res[pickI]||{r:0,x:3};}
function openTetris(){openModal('tetris',`<div class="mh">GAME BOY・俄羅斯方塊對戰</div><canvas id="tetc" width="520" height="340"></canvas><div class="tbtns"><button class="mbtn ghost" data-t="L">◀</button><button class="mbtn ghost" data-t="R">▶</button><button class="mbtn ghost" data-t="U">⟳</button><button class="mbtn ghost" data-t="D">▼</button><button class="mbtn" data-t="H">⤓</button></div><div class="mrow"><span style="font-size:12px;color:var(--dim)">←→ 移動　↑ 轉　↓ 加速　Space 落底</span><button class="mbtn ghost" id="tetQuit">認輸</button></div>`);
  TET.colorOf={I:1,O:2,T:3,S:4,Z:5,J:6,L:7};Object.assign(TET,{on:true,me:tNewBoard(false),ai:tNewBoard(true),t:0,grav:.8,cpuT:.9,cpuStep:.3,cpuErr:.4,msg:'',msgT:0,over:false,endT:0});
  TET.key=e=>{if(modal!=='tetris'||TET.over)return;const k=e.code;const m=TET.me,o=TET.ai;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Space','KeyX','KeyZ'].includes(k))e.preventDefault();if(k==='ArrowLeft')tMove(m,-1,0);else if(k==='ArrowRight')tMove(m,1,0);else if(k==='ArrowUp'||k==='KeyX')tMove(m,0,0,1);else if(k==='KeyZ')tMove(m,0,0,-1);else if(k==='ArrowDown'){tMove(m,0,1,0,o);m.fall=0;}else if(k==='Space'&&!e.repeat)tDrop(m,o);};addEventListener('keydown',TET.key);
  $('#modal').querySelectorAll('[data-t]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();const m=TET.me,o=TET.ai;if(TET.over)return;const t=b.dataset.t;if(t==='L')tMove(m,-1,0);if(t==='R')tMove(m,1,0);if(t==='U')tMove(m,0,0,1);if(t==='D'){tMove(m,0,1,0,o);m.fall=0;}if(t==='H')tDrop(m,o);}));
  $('#tetQuit').onclick=()=>tetEnd(false,true);}
function tetEnd(win,quit){if(!TET.on)return;TET.on=false;removeEventListener('keydown',TET.key);closeModal();if(win){addMoney(100,true);gainXP(50,'Tetris 贏咗');say([['細路仔阿仔','嘩…你好勁呀哥哥！$100 俾你，下次再嚟同我打！']]);}else{gainXP(10);say([['細路仔阿仔',quit?'未打完就走？我贏咗喎！':'哈哈，我贏咗！哥哥你要多啲練習！']]);}}
function tetTick(dt){if(!TET.on||modal!=='tetris')return;const m=TET.me,a=TET.ai;if(TET.over){TET.endT-=dt;if(TET.endT<=0)tetEnd(TET.win);drawTet();return;}
  TET.t+=dt;if(TET.msgT>0)TET.msgT-=dt;const lvl=Math.min(8,Math.floor(TET.t/25));const grav=Math.max(.12,.8-lvl*.08);TET.cpuStep=Math.max(.17,.3-lvl*.015);TET.cpuErr=Math.max(.24,.4-lvl*.02);
  m.fall+=dt;if(m.fall>grav){m.fall=0;tMove(m,0,1,0,a);}
  a.fall+=dt;if(!a.plan&&!a.dead){a.plan=tPlan(a);TET.cpuT=R(.5,1.1);}TET.cpuT-=dt;if(TET.cpuT<=0&&a.plan&&!a.dead){TET.cpuT=TET.cpuStep;const pl=a.plan;if(a.p.r!==pl.r)tMove(a,0,0,1);else if(a.p.x<pl.x){if(!tMove(a,1,0))pl.x=a.p.x;}else if(a.p.x>pl.x){if(!tMove(a,-1,0))pl.x=a.p.x;}else{if(!tMove(a,0,1,0,m))a.fall=99;}}
  if(a.fall>grav){a.fall=0;if(a.p&&!a.dead)tMove(a,0,1,0,m);}
  if(m.dead||a.dead){TET.over=true;TET.win=!m.dead;TET.endT=1.6;TET.msg=TET.win?'你贏咗！':'你輸咗…';TET.msgT=2;sfx(TET.win?'gold':'bad');}drawTet();}
function drawTet(){const c=$('#tetc');if(!c)return;const g=c.getContext('2d');const C=['#9bbc0f','#0f380f','#306230','#0f380f','#306230','#0f380f','#306230','#0f380f','#8bac0f'];g.fillStyle='#c4c0b4';g.fillRect(0,0,520,340);
  const board=(b,x0,label)=>{g.fillStyle='#8a8a8a';g.fillRect(x0-8,22,156,300);g.fillStyle='#9bbc0f';g.fillRect(x0,30,140,280);const cell=(x,y,v)=>{if(y<0)return;g.fillStyle=v===8?'#306230':'#0f380f';g.fillRect(x0+x*14+1,30+y*14+1,12,12);g.fillStyle='#8bac0f';g.fillRect(x0+x*14+4,30+y*14+4,6,6);};
    for(let y=0;y<20;y++)for(let x=0;x<10;x++)if(b.g[y][x])cell(x,y,b.g[y][x]);if(b.p&&!b.dead){let gp=Object.assign({},b.p);while(tFits(b,Object.assign({},gp,{y:gp.y+1})))gp.y++;g.globalAlpha=.25;for(const [x,y] of tCells(b,gp))cell(x,y,1);g.globalAlpha=1;for(const [x,y] of tCells(b))cell(x,y,1);}
    g.fillStyle='#1d1d1d';g.font=`900 14px ${FS}`;g.textAlign='center';g.fillText(label,x0+70,16);if(b.garb>0){g.fillStyle='#c8102e';g.fillRect(x0-6,310-b.garb*14,4,b.garb*14);}};
  board(TET.me,30,'你');board(TET.ai,350,'阿仔（CPU）');
  g.fillStyle='#1d1d1d';g.textAlign='center';g.font=`900 13px ${FS}`;g.fillText('下一個',260,46);const nx=(b,y0)=>{for(const [x,y] of tRot(TP[b.next],0,b.next)){g.fillStyle='#0f380f';g.fillRect(232+x*12,y0+y*12,10,10);}};nx(TET.me,58);nx(TET.ai,128);g.font=`700 11px ${FS}`;g.fillText('你',260,110);g.fillText('阿仔',260,180);
  g.font=`900 13px ${FS}`;g.fillText('行數',260,212);g.font=`900 18px ${FS}`;g.fillText(TET.me.lines+' : '+TET.ai.lines,260,234);g.font=`700 11px ${FS}`;g.fillText('速度 '+(1+Math.min(8,Math.floor(TET.t/25))),260,258);
  if(TET.msgT>0){g.fillStyle='rgba(15,56,15,.85)';g.fillRect(130,140,260,50);g.fillStyle='#9bbc0f';g.font=`900 26px ${FS}`;g.fillText(TET.msg,260,174);}g.textAlign='left';}

/* ---------- open shops: cafe, bakery, convenience store, furniture ---------- */
const OPENF=[];const FOOD={cafe:{name:'元朗冰室',who:'冰室伙記',items:[['菠蘿油',12,15,.02],['凍檸茶',16,8,.01],['餐蛋麵',32,35,.04],['焗豬扒飯',48,60,.07],['雜果沙律',30,20,-.01]]},bakery:{name:'新香園餅家',who:'餅家姐姐',items:[['蛋撻',8,10,.02],['雞尾包',9,10,.02],['老婆餅',12,12,.03],['全麥包',10,10,0]]},store:{name:'OK 便利店',who:'店員',items:[['礦泉水',6,6,0],['運動飲品',10,15,0],['薯片',12,5,.03],['朱古力',10,8,.025],['杯麵',15,25,.03]]}};
function reserveFaces(){const gx=GATE.x,gz=GATE.z;const cand=SHOPF.filter(f=>f.L>=5&&f.L<=22&&f.h>=6).map(f=>[f,Math.hypot(f.x-gx,f.z-gz)]).filter(q=>q[1]>25).sort((a,b)=>a[1]-b[1]);if(cand.length){WKF=cand[0][0];WKF.reserved='wk';}
  const main=SHOPF.filter(f=>!f.reserved&&f.L>=8&&f.L<=26&&f.h>=8&&f.cls<=1).sort((a,b)=>b.L-a.L);for(const f of main){if(BANKF.length>=2)break;if(Math.hypot(f.x-gx,f.z-gz)<60)continue;if(BANKF.some(b=>Math.hypot(b.x-f.x,b.z-f.z)<220))continue;f.reserved='bank';BANKF.push(f);}
  const taken=[WKF,...BANKF].filter(Boolean);const types=['cafe','bakery','store','furn','hobby'];const pool=SHOPF.filter(f=>!f.reserved&&f.L>=7&&f.L<=20&&f.h>=6&&f.cls<=3).map(f=>[f,Math.hypot(f.x-gx,f.z-gz)]).filter(q=>q[1]>70&&q[1]<650).sort((a,b)=>a[1]-b[1]);
  for(const [f] of pool){if(OPENF.length>=types.length)break;if([...taken,...OPENF].some(o=>Math.hypot(o.x-f.x,o.z-f.z)<45))continue;f.reserved=types[OPENF.length];f.kind=f.reserved;OPENF.push(f);}}
function shopFront(f,name,sub,bg,fg){const W=Math.min(2048,Math.round(f.L*80)),Hh=336;const [c,g]=cvs(W,Hh),[e,ge]=cvs(W,Hh);ge.fillStyle='#000';ge.fillRect(0,0,W,Hh);
  g.fillStyle=bg;g.fillRect(0,0,W,96);g.fillStyle=fg;g.font=`900 62px ${FSERIF}`;g.textAlign='center';g.textBaseline='middle';g.fillText(name,W/2,46,W-40);g.font=`700 22px ${FS}`;g.fillText(sub,W/2,82,W-40);ge.fillStyle='#fff';ge.font=`900 62px ${FSERIF}`;ge.textAlign='center';ge.textBaseline='middle';ge.fillText(name,W/2,46,W-40);
  g.fillStyle='#2a2622';g.fillRect(0,96,W,240);g.fillStyle='#f6ead0';g.fillRect(16,110,W-32,226);ge.globalAlpha=.6;ge.fillStyle='#fff3d6';ge.fillRect(16,110,W-32,226);ge.globalAlpha=1;
  g.fillStyle='rgba(60,40,20,.5)';for(let x=24;x<W-30;x+=60){g.fillRect(x,150,40,6);g.fillRect(x,220,40,6);}const dx=W/2-60;g.fillStyle='rgba(30,22,16,.85)';g.fillRect(dx,220,120,116);ge.fillStyle='#000';ge.fillRect(dx,220,120,116);
  g.fillStyle='#c8102e';g.font=`900 26px ${FS}`;g.fillText('營業中 OPEN',W/2,170,W-40);ge.fillStyle='#ff4040';ge.font=`900 26px ${FS}`;ge.fillText('營業中 OPEN',W/2,170,W-40);
  f.panel=facePanel(f,ctex(c),ctex(e));}
function foodMenu(kind){const F=FOOD[kind];const r=rpg();openModal('shop',`<div class="mh">${F.name}</div><div class="mq">${F.who}：食咩呀？</div>${F.items.map((it,i)=>`<div class="row"><div class="sw" style="background:linear-gradient(135deg,#e8b04a,#c97a2b)"></div><div class="nm"><b>${it[0]}</b><span>+${it[2]} 血　${it[3]>0?'體重 +':it[3]<0?'健康 ✓':'唔會肥'}</span></div><div class="pr">$${it[1]}</div><button class="mbtn" data-eat="${i}" ${S.money<it[1]?'disabled':''}>食</button></div>`).join('')}<div class="mrow"><span class="pr">$${S.money}</span><button class="mbtn ghost" id="shopClose">走</button></div>`);
  $('#modal').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='shopClose'){closeModal();return;}if(b.dataset.eat){const it=F.items[+b.dataset.eat];if(S.money<it[1])return;addMoney(-it[1],true);S.hp=Math.min(100,S.hp+it[2]);bodyChange(it[3],0);gainXP(2);sfx('coin');toast(`食咗${it[0]}，好味！+${it[2]} 血`);foodMenu(kind);}};}
function buildShopRoom(id,name,o){const r=makeRoom(id,{name,w:16,d:12,floor:roomFloorTex(o.f1,o.f2,6),wall:o.wall,skirt:o.skirt,wh:4});roomSign(r,name,8,.12,3.3,7,1,{bg:o.bg,fg:o.fg,glow:true});return r;}
function buildOpenShops(){for(const f of OPENF){const n={cafe:['元朗冰室','茶餐廳・奶茶・菠蘿油','#0f6a5a','#fff6d0'],bakery:['新香園餅家','蛋撻・老婆餅・麵包','#c46a12','#fff6d0'],store:['OK 便利店','24 小時營業','#e2412f','#ffffff'],furn:['好家居傢俬','床單・地氈・燈・裝飾','#2b3a55','#ffd23f'],hobby:['奇趣天地','白龍・骨鐮紳士・浪人','#4b2a7a','#ffd23f']}[f.kind];shopFront(f,n[0],n[1],n[2],n[3]);
    const door={x:f.x+f.n[0]*1.9,z:f.z+f.n[2]*1.9};LOC[f.kind]=door;addLabel(n[0],door.x,door.z,8,'');const back={x:door.x+f.n[0]*.8,z:door.z+f.n[2]*.8,h:Math.atan2(f.n[0],f.n[2])};
    if(f.kind==='cafe')INTER.push({at:()=>door,r:2.8,label:'入元朗冰室',ok:()=>!PLAYER.car&&!curRoom,act:()=>enterRoom('cafe',back)});
    else if(f.kind==='hobby')INTER.push({at:()=>door,r:2.8,label:'入奇趣天地',ok:()=>!PLAYER.car&&!curRoom&&!MECH.on,act:()=>enterRoom('hobby',back)});
    else if(f.kind==='furn')INTER.push({at:()=>door,r:2.8,label:'入好家居傢俬',ok:()=>!PLAYER.car&&!curRoom,act:()=>enterRoom('furn',back)});
    else INTER.push({at:()=>door,r:2.8,label:'買嘢食（'+n[0]+'）',ok:()=>!PLAYER.car&&!curRoom,act:()=>foodMenu(f.kind)});}
  POI_DEF.push(['cafe','食','#0f6a5a','冰室'],['bakery','餅','#c46a12','餅家'],['store','便','#e2412f','便利店'],['furn','傢','#2b3a55','傢俬舖'],['hobby','奇','#7a3cc8','奇趣天地'],['park','園','#5c9446','公園']);}
function buildCafeRoom(){const r=buildShopRoom('cafe','元朗冰室',{f1:'#e9e1cf',f2:'#c9d9cf',wall:'#e8efe6',skirt:'#0f6a5a',bg:'#0f6a5a',fg:'#fff6d0'});const x0=r.x0,z0=r.z0;
  for(let i=0;i<3;i++)for(const s of [0,1]){const x=3+i*4.4,z=4.5+s*4;roomBox(r,1.6,.75,1.1,x,z,std('#f4f1e6',.3));roomBox(r,1.7,.9,.45,x,z-1,std('#2f6b5a',.6));roomBox(r,1.7,.9,.45,x,z+1,std('#2f6b5a',.6));const cup=new THREE.Mesh(new THREE.CylinderGeometry(.06,.05,.12,8),std('#c97a2b',.4));cup.position.set(x0+x+.3,.81,z0+z);scene.add(cup);}
  roomBox(r,4,1.05,1,12.5,2.2,std('#7a5232',.6));const st=npc('冰室伙記',{shirt:'#f4f4f0',pants:'#222'},0,0,0,'#9cd7ff');roomPerson(r,st,12.5,1.2,0,false);
  for(let k=0;k<3;k++){const m=textPlane(['奶茶 $16','菠蘿油 $12','焗豬扒飯 $48'][k],2,.45,{bg:'#fff6d0',fg:'#0f6a5a',font:FS});m.position.set(x0+3+k*2.4,2.6,z0+.1);scene.add(m);}
  r.lights=[[x0+4,z0+5],[x0+12,z0+5],[x0+8,z0+9]];r.inter.push({at:()=>({x:x0+12.5,z:z0+3.4}),r:2.6,label:'同伙記叫嘢食',ok:()=>curRoom===r,act:()=>foodMenu('cafe')});}

/* ---------- furniture catalogue and bedroom decorating ---------- */
const FURN=[{slot:'poster',n:'海報',items:[['p_anime','動漫海報',30],['p_band','樂隊海報',30],['p_night','香港夜景海報',40]]},{slot:'neon',n:'霓虹燈',items:[['n_yl','「元朗」霓虹燈牌',260],['n_heart','心心霓虹燈',220]]},
  {slot:'rug',n:'地氈',items:[['r_red','紅色地氈',80],['r_blue','藍色地氈',80],['r_rainbow','彩虹圓地氈',120]]},{slot:'bean',n:'豆袋梳化',items:[['b_yellow','黃色豆袋',150],['b_purple','紫色豆袋',150]]},
  {slot:'lamp',n:'燈',items:[['l_floor','落地燈',120],['l_lava','熔岩燈',90]]},{slot:'shelf',n:'櫃',items:[['s_book','書架',200],['s_fig','公仔櫃',180]]},{slot:'tv',n:'電視',items:[['t_game','電視＋遊戲機',500]]},
  {slot:'plant',n:'植物',items:[['pl_mon','龜背竹',60],['pl_cac','仙人掌',25]]},{slot:'chair',n:'椅',items:[['c_game','電競椅',350]]},{slot:'sheet',n:'床單',items:[['sh_blue','藍色床單',0],['sh_pink','粉紅床單',60],['sh_dino','恐龍床單',80]]}];
function furnS(){if(!S.furn)S.furn={owned:['sh_blue'],placed:{sheet:'sh_blue'}};return S.furn;}
function itemOf(id){for(const c of FURN)for(const it of c.items)if(it[0]===id)return [c,it];return null;}
function buildFurnRoom(){const r=buildShopRoom('furn','好家居傢俬',{f1:'#d9cdb8',f2:'#cbbfa8',wall:'#efe9df',skirt:'#2b3a55',bg:'#2b3a55',fg:'#ffd23f'});const x0=r.x0,z0=r.z0;
  const disp=[[3,4,'#c8102e'],[7,4,'#2e86de'],[11,4,'#ffd23f'],[3,8,'#8e44ad'],[7,8,'#27ae60']];for(const [x,z,c] of disp){roomBox(r,2.6,.08,2,x,z,std(c,.9),false);const bb=new THREE.Mesh(new THREE.SphereGeometry(.5,12,8),std(c,.8));bb.scale.y=.6;bb.position.set(x0+x,.3,z0+z);scene.add(bb);}
  roomBox(r,1,2.2,.4,14,6,std('#7a5232',.6));roomBox(r,3,1,1,11,8.6,std('#7a5232',.6));const st=npc('傢俬舖老闆',{shirt:'#2b3a55',pants:'#222'},0,0,0,'#ffd23f');roomPerson(r,st,11,9.6,Math.PI,false);
  r.lights=[[x0+4,z0+5],[x0+12,z0+5],[x0+8,z0+9]];r.inter.push({at:()=>({x:x0+11,z:z0+7.4}),r:2.6,label:'睇傢俬目錄',ok:()=>curRoom===r,act:openFurnShop});}
function openFurnShop(){const F=furnS();openModal('shop',`<div class="mh">好家居傢俬</div><div class="mq">老闆：買咗返屋企，喺睡房「裝修間房」就擺得出嚟！</div>${FURN.map(c=>c.items.filter(it=>it[2]>0).map(it=>{const own=F.owned.includes(it[0]);return `<div class="row"><div class="sw" style="background:${furnSw(it[0])}"></div><div class="nm"><b>${it[1]}</b><span>${c.n}</span></div><div class="pr">$${it[2]}</div>${own?'<button class="mbtn ghost" disabled>已擁有</button>':`<button class="mbtn" data-fb="${it[0]}" ${S.money<it[2]?'disabled':''}>買</button>`}</div>`;}).join('')).join('')}<div class="mrow"><span class="pr">$${S.money}</span><button class="mbtn ghost" id="shopClose">走</button></div>`);
  $('#modal').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='shopClose'){closeModal();return;}if(b.dataset.fb){const [c,it]=itemOf(b.dataset.fb);if(S.money<it[2])return;addMoney(-it[2],true);F.owned.push(it[0]);if(!F.placed[c.slot])F.placed[c.slot]=it[0];buildDecor();save();toast('買咗 '+it[1]+'，已經擺咗喺你間房');openFurnShop();}};}
function furnSw(id){const m={p_anime:'#ff7eb6',p_band:'#222',p_night:'#2b3a55',n_yl:'#ff3d5e',n_heart:'#ff7eb6',r_red:'#c8102e',r_blue:'#2e86de',r_rainbow:'linear-gradient(90deg,#e2412f,#ffd23f,#36d6a2,#2e86de)',b_yellow:'#ffd23f',b_purple:'#8e44ad',l_floor:'#f6e7c0',l_lava:'#ff6a2a',s_book:'#7a5232',s_fig:'#c9ccd0',t_game:'#111',pl_mon:'#2f6b3a',pl_cac:'#5c9446',c_game:'#c8102e',sh_blue:'#2f6f86',sh_pink:'#ff9db0',sh_dino:'#7fbf5a'};return m[id]||'#888';}
function openDecor(){const F=furnS();openModal('shop',`<div class="mh">裝修間房</div><div class="mq">揀每個位擺咩傢俬（傢俬喺「好家居傢俬」買）</div>${FURN.map(c=>{const owned=c.items.filter(it=>F.owned.includes(it[0]));return `<div class="row"><div class="nm"><b>${c.n}</b><span>${F.placed[c.slot]?itemOf(F.placed[c.slot])[1][1]:'（空）'}</span></div><div class="dopts">${owned.map(it=>`<button class="mbtn${F.placed[c.slot]===it[0]?'':' ghost'}" data-dp="${c.slot}|${it[0]}">${it[1]}</button>`).join('')}${c.slot!=='sheet'&&owned.length?`<button class="mbtn ghost" data-dp="${c.slot}|">收起</button>`:''}${owned.length?'':'<span style="font-size:12px;color:var(--dim)">未有</span>'}</div></div>`;}).join('')}<div class="mrow"><span></span><button class="mbtn" id="shopClose">完成</button></div>`);
  $('#modal').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='shopClose'){closeModal();return;}if(b.dataset.dp!=null){const [s,id]=b.dataset.dp.split('|');if(id)F.placed[s]=id;else delete F.placed[s];buildDecor();save();sfx('ding',.4);openDecor();}};}
let DECOR=null;
