/* ================= v3d: morning show TV, car crashes and damage, secret shrine with the thunder-cloud spirit ================= */
const _v3a=new THREE.Vector3();

/* ---------- 香港早晨 on the home TV, louder the closer you are ---------- */
const MORN={a:null,vol:0,primed:false};
function mornAudio(){if(!MORN.a){MORN.a=new Audio('audio/morning.mp3');MORN.a.loop=true;MORN.a.preload='auto';MORN.a.volume=0;}return MORN.a;}
addEventListener('pointerdown',()=>{if(MORN.primed)return;MORN.primed=true;try{const a=mornAudio();a.muted=true;a.play().then(()=>{a.pause();a.muted=false;}).catch(()=>{a.muted=false;});}catch(e){}},{once:false,capture:true});
function morningUpdate(dt){const P=PLAYER;let want=0;
  if(started&&P.ind==='home'&&HOME.tv&&!S.dead&&!curRoom){const tv=HOME.tv.getWorldPosition(_v3a);const d=Math.hypot(tv.x-P.x,tv.z-P.z)+Math.abs(tv.y-((P.y||0)+1.4))*.5;want=clamp(1-(d-1.2)/14,0,1);want*=want;}
  if(AU.muted||modal==='tetris'||PLAYER.dress)want=0;
  MORN.vol=lerp(MORN.vol,want,1-Math.exp(-5*dt));
  if(MORN.vol>.004){const a=mornAudio();a.volume=clamp(MORN.vol*.95,0,1);if(a.paused)a.play().catch(()=>{});}else if(MORN.a&&!MORN.a.paused)MORN.a.pause();
  if(MORN.vol>.15&&MUS.want==='home')MUS.want=null;}

/* ---------- particles: one draw call per blend mode ---------- */
function softDot(){return cachedTex('softdot',()=>{const [c,g]=cvs(64,64);const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,'rgba(255,255,255,1)');gr.addColorStop(.45,'rgba(255,255,255,.55)');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(0,0,64,64);return ctex(c);});}
function makePS(n,add){const geo=new THREE.BufferGeometry();const pos=new Float32Array(n*3),col=new Float32Array(n*4),siz=new Float32Array(n);
  geo.setAttribute('position',new THREE.BufferAttribute(pos,3));geo.setAttribute('acol',new THREE.BufferAttribute(col,4));geo.setAttribute('asize',new THREE.BufferAttribute(siz,1));
  const mat=new THREE.ShaderMaterial({uniforms:{map:{value:softDot()},scale:{value:600}},transparent:true,depthWrite:false,blending:add?THREE.AdditiveBlending:THREE.NormalBlending,
    vertexShader:'attribute vec4 acol;attribute float asize;varying vec4 vc;uniform float scale;void main(){vc=acol;vec4 mv=modelViewMatrix*vec4(position,1.);gl_PointSize=min(asize*scale/max(.1,-mv.z),512.);gl_Position=projectionMatrix*mv;}',
    fragmentShader:'uniform sampler2D map;varying vec4 vc;void main(){vec4 t=texture2D(map,gl_PointCoord);gl_FragColor=vec4(vc.rgb,vc.a*t.a);}'});
  const pts=new THREE.Points(geo,mat);pts.frustumCulled=false;pts.renderOrder=5;scene.add(pts);return {n,geo,pos,col,siz,L:[],pts,mat};}
let PSA=null,PSN=null,FXL=null;
function psInit(){if(PSA)return;PSA=makePS(700,true);PSN=makePS(500,false);FXL=new THREE.PointLight(0xff8a3a,0,26,2);FXL.castShadow=false;scene.add(FXL);}
function emit(ps,o){if(ps.L.length>=ps.n)ps.L.shift();ps.L.push(Object.assign({x:0,y:0,z:0,vx:0,vy:0,vz:0,t:0,life:1,s0:.3,s1:.6,r:1,g:1,b:1,a:1,grav:0,drag:0,a1:0},o));}
function psUpdate(ps,dt){const L=ps.L;let k=0;for(let i=0;i<L.length;i++){const p=L[i];p.t+=dt;if(p.t>=p.life)continue;p.vy-=p.grav*dt;const dr=Math.exp(-p.drag*dt);p.vx*=dr;p.vy*=dr;p.vz*=dr;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;
    if(p.grav>0){const gy=TH(p.x,p.z)+.03;if(p.y<gy){p.y=gy;p.vy*=-.3;p.vx*=.5;p.vz*=.5;}}L[k++]=p;}L.length=k;
  const pos=ps.pos,col=ps.col,siz=ps.siz;for(let i=0;i<ps.n;i++){const p=L[i];if(!p){siz[i]=0;continue;}const u=p.t/p.life;pos[i*3]=p.x;pos[i*3+1]=p.y;pos[i*3+2]=p.z;col[i*4]=p.r;col[i*4+1]=p.g;col[i*4+2]=p.b;col[i*4+3]=p.a*(1-u)+(p.a1||0)*u;siz[i]=p.s0+(p.s1-p.s0)*u;}
  ps.geo.attributes.position.needsUpdate=true;ps.geo.attributes.acol.needsUpdate=true;ps.geo.attributes.asize.needsUpdate=true;
  const h=renderer.domElement.height;ps.mat.uniforms.scale.value=h/(2*Math.tan(camera.fov*Math.PI/360));}
function sparks(x,y,z,n,sp=6){for(let i=0;i<n;i++)emit(PSA,{x,y,z,vx:R(-sp,sp),vy:R(1,sp),vz:R(-sp,sp),life:R(.25,.6),s0:.09,s1:.03,r:1,g:R(.6,.9),b:.3,grav:14});}
function debris(x,y,z,n){for(let i=0;i<n;i++)emit(PSN,{x,y,z,vx:R(-4,4),vy:R(2,6),vz:R(-4,4),life:R(.8,1.6),s0:.12,s1:.1,r:R(.15,.35),g:R(.15,.3),b:R(.15,.3),a:1,grav:16});}
function smokePuff(x,y,z,dark,big=1){const c=dark?R(.06,.14):R(.45,.6);emit(PSN,{x:x+R(-.3,.3),y,z:z+R(-.3,.3),vx:R(-.5,.5)+(Wx.wind||0),vy:R(1.2,2.4),vz:R(-.5,.5),life:R(1.8,3)*big,s0:.9*big,s1:3.6*big,r:c,g:c,b:c*1.05,a:dark?.75:.5,drag:.4});}
function flame(x,y,z,big=1){emit(PSA,{x:x+R(-.5,.5)*big,y,z:z+R(-.5,.5)*big,vx:R(-.4,.4),vy:R(2,4)*big,vz:R(-.4,.4),life:R(.4,.8),s0:1.5*big,s1:.5*big,r:1,g:R(.35,.6),b:.08,a:1,drag:.6});}
let fxlT=0,fxlI=0;function flash(x,y,z,i,t){FXL.position.set(x,y,z);fxlI=Math.max(fxlI,i);fxlT=Math.max(fxlT,t);}

/* ---------- explosion sound ---------- */
function boomSfx(v=1){if(!AU.ctx||AU.muted)return;const c=AU.ctx,t=c.currentTime,d=AU.sfx;noiseHit(t,1.6,.9*v,260,'lowpass',d);noiseHit(t,.35,.5*v,1400,'lowpass',d);tone(48,t,1.2,'sine',.7*v,d);tone(90,t,.4,'triangle',.3*v,d);}
function thudSfx(v=1){if(!AU.ctx||AU.muted)return;const c=AU.ctx,t=c.currentTime,d=AU.sfx;noiseHit(t,.18,.6*v,500,'lowpass',d);tone(85,t,.2,'sine',.6*v,d);}

/* ---------- ragdoll: people knocked flying ---------- */
const FLY=[];
function launch(p,vx,vy,vz){const g=p.g;FLY.push({p,g,vx,vy,vz,wx:R(6,12)*(rnd()<.5?-1:1),wz:R(-4,4),t:0,rest:0,yaw:g.rotation.y});}
function flyUpdate(dt){for(let i=FLY.length-1;i>=0;i--){const f=FLY[i],g=f.g;f.t+=dt;const o={x:g.position.x+f.vx*dt,z:g.position.z+f.vz*dt};const hit=pushOut(o,.3,g.position.y);if(hit){const vn=f.vx*hit.nx+f.vz*hit.nz;if(vn<0){f.vx-=vn*hit.nx*1.4;f.vz-=vn*hit.nz*1.4;f.vx*=.5;f.vz*=.5;thudSfx(.4);}}
    g.position.x=o.x;g.position.z=o.z;f.vy-=20*dt;g.position.y+=f.vy*dt;const gy=TH(o.x,o.z)+.2;
    if(g.position.y<=gy){g.position.y=gy;if(f.vy<-4){f.vy=-f.vy*.28;f.vx*=.55;f.vz*=.55;thudSfx(.35);if(rnd()<.7)blood(o.x,gy+.1,o.z,3);}else{f.vy=0;const k=Math.exp(-7*dt);f.vx*=k;f.vz*=k;f.rest+=dt;}}
    if(f.rest>0){g.rotation.set(-Math.PI/2,f.yaw,0);}else{g.rotation.x+=f.wx*dt;g.rotation.z+=f.wz*dt;}
    if(f.rest>.6||f.t>8){g.rotation.set(-Math.PI/2,f.yaw,0);g.position.y=TH(o.x,o.z)+.2;FLY.splice(i,1);}}}
// a dead pedestrian lies there, then is quietly replaced somewhere else
{const _pu=pedUpdate;pedUpdate=function(p,dt){if(p.dead&&p.down>0&&p.down-dt<=0){p.dead=false;p.down=0;p.g.rotation.set(0,0,0);p.g.position.y=0;p.hp=100;placePed(p,cam.tx,cam.tz,110,260);return;}if(p.dead&&FLY.some(f=>f.p===p))return;return _pu(p,dt);};}

/* ---------- car damage ---------- */
let charM=null;
function carHp(v){return Math.max(0,100-(v.dmg||0));}
function carDamage(v,amt,x,z,y){if(!(amt>0)||v.wreck||v.type==='bike')return;const was=v.dmg||0;v.dmg=Math.min(100,was+amt);
  const cy=y!=null?y:(v.y||0)+.8;sparks(x,cy,z,Math.min(30,6+amt*.8));if(amt>6)debris(x,cy,z,Math.min(14,amt*.4));flash(x,cy+.5,z,2.2,.12);
  const crumple=Math.max(.84,1-v.dmg*.0016);v.body.scale.set(1,1-v.dmg*.0006,crumple);v.body.rotation.z=(v.dentR=(v.dentR||R(-1,1)))*v.dmg*.0006;
  if(v===PLAYER.car){if(was<50&&v.dmg>=50)toast('架車冒煙喇，小心！');hudCar();}
  if(v.dmg>=100&&!v.fire){v.fire=4.5+R(0,1.5);if(v===PLAYER.car){toast('🔥 架車着火喇！快啲落車！');}}}
function hudCar(){let el=$('#carHp');if(!el){el=document.createElement('div');el.id='carHp';el.style.cssText='margin-top:4px;height:6px;width:86px;border-radius:3px;background:rgba(0,0,0,.45);overflow:hidden';el.innerHTML='<i style="display:block;height:100%;width:100%;background:#36d6a2;transition:width .2s"></i>';const sp=$('#speedo');if(sp)sp.appendChild(el);}
  const v=PLAYER.car;if(!v)return;const h=carHp(v);const i=el.firstChild;i.style.width=h+'%';i.style.background=h>55?'#36d6a2':h>25?'#ffb020':'#ff3d5e';}
function wreckCar(v){v.wreck=true;v.fire=0;v.ai=false;v.speed=0;v.wreckT=0;v.smokeT=22;
  if(!charM){charM=std('#1b1918',.95);charM.userData.char=true;}
  v.body.traverse(m=>{if(m.isMesh&&!m.userData.orig){m.userData.orig=m.material;m.material=charM;}});v.body.scale.set(1,.86,.92);v.body.position.y=-.12;
  if(v.wheels)v.wheels.forEach(w=>{w.visible=false;});}
function unwreck(v){v.body.traverse(m=>{if(m.isMesh&&m.userData.orig){m.material=m.userData.orig;delete m.userData.orig;}});v.body.scale.set(1,1,1);v.body.rotation.z=0;v.body.position.y=0;if(v.wheels)v.wheels.forEach(w=>{w.visible=true;});
  v.wreck=false;v.dmg=0;v.fire=0;v.smokeT=0;v.dentR=0;}
function explode(v){const x=v.x,z=v.z,y=(v.y||0)+1;boomSfx();shake=Math.max(shake,.9);flash(x,y+1.5,z,9,1.1);
  for(let i=0;i<46;i++){const a=R(0,TAU),u=R(-.2,1),s=R(3,11);emit(PSA,{x,y:y+R(0,1),z,vx:Math.cos(a)*s*Math.sqrt(1-u*u),vy:Math.abs(u)*s+2,vz:Math.sin(a)*s*Math.sqrt(1-u*u),life:R(.5,1.1),s0:R(1.2,2.4),s1:R(.4,1),r:1,g:R(.45,.75),b:R(.1,.25),a:1,drag:2.2});}
  for(let i=0;i<26;i++)smokePuff(x+R(-1.5,1.5),y+R(0,2),z+R(-1.5,1.5),true,1.6);sparks(x,y,z,40,10);debris(x,y,z,24);
  const inside=v===PLAYER.car;if(inside){actCarForce();hurtPlayer(55);PLAYER.vy=6;}
  const P=PLAYER;if(!P.car&&!inside){const d=Math.hypot(P.x-x,P.z-z);if(d<7){hurtPlayer(Math.round(48*(1-d/7)));P.vy=Math.max(P.vy||0,5*(1-d/7));P.vx+=(P.x-x)/(d||1)*8;P.vz+=(P.z-z)/(d||1)*8;}}
  for(const p of [...peds,...COPS,...FIGHT]){if(!p.g||!p.g.visible)continue;const dx=p.g.position.x-x,dz=p.g.position.z-z,d=Math.hypot(dx,dz);if(d>8||FLY.some(f=>f.p===p))continue;const k=(1-d/8);hitPerson(p,dx/(d||1)*14*k,4+8*k,dz/(d||1)*14*k,true);}
  for(const o of vehicles){if(o===v||o.wreck)continue;const d=Math.hypot(o.x-x,o.z-z);if(d<9){carDamage(o,70*(1-d/9),o.x,o.z);if(!o.ai){o.vx+=(o.x-x)/(d||1)*6;o.vz+=(o.z-z)/(d||1)*6;}else if(d<6){o.ai=false;o.vx=(o.x-x)/(d||1)*5;o.vz=(o.z-z)/(d||1)*5;}}}
  wreckCar(v);addHeat(4);}
function actCarForce(){const P=PLAYER,v=P.car;if(!v)return;const s=Math.sin(v.h),c=Math.cos(v.h);P.x=v.x-c*(v.W/2+1.4);P.z=v.z+s*(v.W/2+1.4);pushOut(P,.35);P.car=null;P.p.g.visible=true;v.speed=0;P.y=TH(P.x,P.z);setHud();const el=$('#carHp');if(el)el.remove();}
// can't drive away in a burnt-out shell
function nearCar(){let best=null,bd=4.2;for(const v of vehicles){if(v.wreck||(v.ai&&v.speed>1))continue;const d=Math.hypot(v.x-PLAYER.x,v.z-PLAYER.z);if(d<bd){bd=d;best=v;}}return best;}
{const _ac=actCar;actCar=function(){const had=PLAYER.car;_ac();if(!had&&PLAYER.car)hudCar();if(had&&!PLAYER.car){const el=$('#carHp');if(el)el.remove();}};}

/* hit a person with a car or a blast: they go flying, harder = further */
function hitPerson(p,vx,vy,vz,kill){if(FIGHT.includes(p)){p.hp=0;if(!p.koXP){p.koXP=true;gainXP(p.boss?40:15);}}
  else if(COPS.includes(p)){p.hp=0;p.down=14;addHeat(3);}
  else{p.hp=0;p.down=kill?28:5;p.dead=!!kill;p.flee=0;if(kill){addHeat(2);if(rnd()<.6)dropCash(p.g.position.x,p.g.position.z,Math.round(5+rnd()*40));}}
  blood(p.g.position.x,1.1,p.g.position.z,kill?10:4);launch(p,vx,vy,vz);}
function carVsPeople(v){const sp=Math.hypot(v.vx,v.vz);if(sp<2.2)return;const fx=Math.sin(v.h),fz=Math.cos(v.h),rx=-fz,rz=fx;
  for(const p of [...peds,...COPS,...FIGHT]){if(!p.g||!p.g.visible||FLY.some(f=>f.p===p))continue;if(peds.includes(p)&&p.down>0)continue;if(COPS.includes(p)&&p.down>0)continue;if(FIGHT.includes(p)&&p.hp<=0)continue;
    const dx=p.g.position.x-v.x,dz=p.g.position.z-v.z;if(dx*dx+dz*dz>(v.L+2)**2)continue;const f=dx*fx+dz*fz,l=dx*rx+dz*rz;if(Math.abs(f)>v.L/2+.35||Math.abs(l)>v.W/2+.35)continue;
    if(Math.abs((p.g.position.y||0)-(v.y||0))>2)continue;
    const kill=sp>6.5&&v.type!=='bike';const ux=v.vx/sp,uz=v.vz/sp,side=Math.sign(l)||1;const hs=sp*R(.95,1.25);
    hitPerson(p,ux*hs+rx*side*sp*.25,kill?2.2+sp*.34:2.5,uz*hs+rz*side*sp*.25,kill);thudSfx(Math.min(1,sp/18));shake=Math.max(shake,Math.min(.35,sp*.012));
    v.vx*=.94;v.vz*=.94;carDamage(v,Math.min(4,sp*.12),p.g.position.x,p.g.position.z);
    if(v===PLAYER.car&&kill&&rnd()<.5)subtitle('途人',pick(['撞死人呀！','報警呀！','救命呀！','咁揸車㗎？！']));
    for(const q of peds){if(q===p||q.down>0)continue;if(Math.hypot(q.g.position.x-p.g.position.x,q.g.position.z-p.g.position.z)<18)q.flee=6;}}}

/* driving with crash damage (replaces the original) */
function driveStep(v,dt){const fx=Math.sin(v.h),fz=Math.cos(v.h),rx=-fz,rz=fx;let fwd=v.vx*fx+v.vz*fz,lat=v.vx*rx+v.vz*rz;const dead=v.wreck;const thr=dead?0:inp.y,str=dead?0:-inp.x;
  const MAX=(v.type==='bike'?17:v.type==='sports'?50:v.type==='taxi'?36:30)*(v.dmg>70?.7:1),ACC=v.type==='bike'?10:v.type==='sports'?17:11;
  if(thr>0)fwd+=ACC*thr*dt*(1-Math.max(0,fwd)/MAX);else if(thr<0){if(fwd>.6)fwd-=22*dt*-thr;else fwd=Math.max(-9,fwd-7*dt*-thr);}else fwd-=Math.sign(fwd)*Math.min(Math.abs(fwd),2.2*dt);
  fwd-=fwd*Math.abs(fwd)*.0009*dt;if(inp.hb)fwd-=Math.sign(fwd)*Math.min(Math.abs(fwd),9*dt);
  const sMax=.62/(1+Math.abs(fwd)*.045);v.steer=lerp(v.steer,str*sMax,1-Math.exp(-9*dt));const yaw=fwd/2.7*Math.tan(v.steer)*(inp.hb?1.35:1);v.h+=yaw*dt;lat*=Math.exp(-(inp.hb?1.6:10)*dt);
  const nfx=Math.sin(v.h),nfz=Math.cos(v.h),nrx=-nfz,nrz=nfx;const pvx=v.vx,pvz=v.vz;v.vx=nfx*fwd+nrx*lat;v.vz=nfz*fwd+nrz*lat;v.x+=v.vx*dt;v.z+=v.vz*dt;v.speed=fwd;
  for(const off of [v.L*.28,-v.L*.28]){const c={x:v.x+nfx*off,z:v.z+nfz*off};const ox=c.x,oz=c.z;const h=pushOut(c,v.W*.55,v.y||0,.32);if(h){v.x+=c.x-ox;v.z+=c.z-oz;const vn=v.vx*h.nx+v.vz*h.nz;if(vn<0){v.vx-=vn*h.nx*1.25;v.vz-=vn*h.nz*1.25;if(vn<-7)shake=Math.min(.5,-vn*.03);if(vn<-5&&(v.hitCd||0)<=0){v.hitCd=.25;sfx('crash',Math.min(1,-vn/20));carDamage(v,(-vn-4)*2.6,c.x-h.nx*v.W*.5,c.z-h.nz*v.W*.5);}}}}
  for(const o of vehicles){if(o===v)continue;const dx=v.x-o.x,dz=v.z-o.z,d=Math.hypot(dx,dz),m=(v.W+o.W)/2+.5+Math.min(v.L,o.L)*.25;if(d<m&&d>0){const nx=dx/d,nz=dz/d;v.x+=nx*(m-d)*.7;v.z+=nz*(m-d)*.7;if(!o.ai){o.x-=nx*(m-d)*.3;o.z-=nz*(m-d)*.3;}
    const ovx=o.ai?Math.sin(o.h)*o.speed:o.vx||0,ovz=o.ai?Math.cos(o.h)*o.speed:o.vz||0;const vn=(v.vx-ovx)*nx+(v.vz-ovz)*nz;
    if(vn<0){const myn=v.vx*nx+v.vz*nz;if(myn<0){v.vx-=myn*nx*1.3;v.vz-=myn*nz*1.3;}if(vn<-6)shake=Math.min(.5,-vn*.03);
      if(vn<-4.5&&(v.hitCd||0)<=0){v.hitCd=.3;const imp=-vn;const cx=(v.x+o.x)/2,cz=(v.z+o.z)/2;sfx('crash',Math.min(1,imp/18));carDamage(v,(imp-3.5)*2.4,cx,cz);carDamage(o,(imp-3.5)*2.8,cx,cz);
        if(o.ai&&imp>9){o.ai=false;o.vx=ovx-nx*imp*.55;o.vz=ovz-nz*imp*.55;o.speed=0;}else if(!o.ai){o.vx=(o.vx||0)-nx*imp*.45;o.vz=(o.vz||0)-nz*imp*.45;}}
      if(o.ai)o.speed*=.3;}}}
  for(const t of lrts){const dx=v.x-t.x,dz=v.z-t.z;const f=Math.abs(dx*Math.sin(t.h)+dz*Math.cos(t.h)),l=dx*Math.cos(t.h)-dz*Math.sin(t.h);if(f<15&&Math.abs(l)<2.4){const s=Math.sign(l)||1;const push=2.4-Math.abs(l);v.x+=Math.cos(t.h)*push*s;v.z-=Math.sin(t.h)*push*s;const sp=Math.hypot(v.vx,v.vz);if(sp>6&&(v.hitCd||0)<=0){v.hitCd=.4;sfx('crash');carDamage(v,sp*1.8,v.x,v.z);v.vx*=.4;v.vz*=.4;}}}
  if(v.hitCd>0)v.hitCd-=dt;
  const al=((v.vx-pvx)*fx+(v.vz-pvz)*fz)/dt;v.roll=lerp(v.roll,clamp(-yaw*fwd*.006,-.09,.09),1-Math.exp(-6*dt));v.pitch=lerp(v.pitch,clamp(-al*.006,-.06,.06),1-Math.exp(-5*dt));
  v.spin+=fwd/v.wr*dt;{const fx2=Math.sin(v.h)*v.L*.3,fz2=Math.cos(v.h)*v.L*.3;const y0=v.y||0;const gF=groundAt(v.x+fx2,v.z+fz2,y0-.13),gB=groundAt(v.x-fx2,v.z-fz2,y0-.13),gC=groundAt(v.x,v.z,y0-.13);const gy=Math.max(gC,(gF+gB)/2);v.y=gy>y0?lerp(y0,gy,1-Math.exp(-25*dt)):Math.max(gy,y0-9*dt);if(v.type==='bike')v.pitch=0;else v.pitch=clamp(v.pitch+Math.atan2(gB-gF,v.L*.6)*.0,-.2,.2);}v.brakeOn=thr<0&&fwd>.5||inp.hb;}

/* parked or shoved cars bump into each other too */
function looseCarHits(v){const sp=Math.hypot(v.vx||0,v.vz||0);if(sp<5)return;for(const o of vehicles){if(o===v||o===PLAYER.car)continue;const dx=v.x-o.x,dz=v.z-o.z,d=Math.hypot(dx,dz),m=(v.W+o.W)/2+.3;if(d<m&&d>0&&(v.hitCd||0)<=0){v.hitCd=.4;const cx=(v.x+o.x)/2,cz=(v.z+o.z)/2;sfx('crash',Math.min(1,sp/18));carDamage(v,sp*1.6,cx,cz);carDamage(o,sp*1.8,cx,cz);if(o.ai){o.ai=false;o.speed=0;}o.vx=(o.vx||0)-dx/d*sp*.5;o.vz=(o.vz||0)-dz/d*sp*.5;v.vx*=.4;v.vz*=.4;}}}
let smokeAcc=0;
function carFxUpdate(dt){smokeAcc+=dt;const tick=smokeAcc>.07;if(tick)smokeAcc=0;const cx=camera.position.x,cz=camera.position.z;let fl=null,fd=1e9;
  for(const v of vehicles){if(v!==PLAYER.car&&!v.ai)looseCarHits(v);if(v.hitCd>0&&v!==PLAYER.car)v.hitCd-=dt;
    const d2=(v.x-cx)**2+(v.z-cz)**2;const hx=v.x+Math.sin(v.h)*v.L*.32,hz=v.z+Math.cos(v.h)*v.L*.32,hy=(v.y||0)+1.1;
    if(v.fire>0){v.fire-=dt;if(d2<160*160){if(tick){for(let k=0;k<4;k++)flame(hx,hy,hz,1.1);smokePuff(hx,hy+1.2,hz,true,1.3);smokePuff(hx,hy+1.6,hz,true,1.3);}if(d2<fd){fd=d2;fl=[hx,hy+1,hz];}}
      if(v===PLAYER.car&&Math.random()<dt*.8)toast('🔥 快啲落車！要爆喇！');if(v.fire<=0){v.fire=0;explode(v);}continue;}
    if(v.wreck){v.wreckT+=dt;if(v.smokeT>0){v.smokeT-=dt;if(tick&&d2<160*160){smokePuff(v.x,(v.y||0)+1,v.z,true,1);if(v.smokeT>14&&rnd()<.5)flame(v.x+R(-1,1),(v.y||0)+.8,v.z+R(-1,1),.6);}}
      if(v.wreckT>50&&d2>110*110){unwreck(v);const rs=pickRoadNear(PLAYER.x,PLAYER.z,120,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;v.ai=true;v.speed=6;v.vx=v.vz=0;}}continue;}
    if(v.dmg>=50&&tick&&d2<140*140&&rnd()<(v.dmg>=75?.9:.45))smokePuff(hx,hy,hz,v.dmg>=75,.8);}
  if(fl){const fk=.7+Math.random()*.5;FXL.position.set(fl[0],fl[1],fl[2]);fxlI=Math.max(fxlI,2.4*fk);}
  if(fxlT>0)fxlT-=dt;FXL.intensity=fxlI;fxlI=fxlT>0?fxlI*Math.exp(-3*dt):0;}

/* ---------- the secret shrine under the banyan (土地廟) ---------- */
const SHRINE={x:0,z:0,found:false,cd:0,ff:null,built:false};
function buildShrine(){const f=D.park[19];if(!f)return;let x=0,z=0,n=f.length/2;for(let k=0;k<f.length;k+=2){x+=f[k];z+=f[k+1];}x/=n;z/=n;const o=freeSpot(x,z);SHRINE.x=o.x;SHRINE.z=o.z;const y=TH(o.x,o.z);
  const G=new THREE.Group();G.position.set(o.x,y,o.z);scene.add(G);SHRINE.g=G;const add=(geo,m,px,py,pz,ry=0)=>{const me=new THREE.Mesh(geo,m);me.position.set(px,py,pz);me.rotation.y=ry;me.castShadow=true;me.receiveShadow=true;G.add(me);return me;};
  const bark=std('#5b4636',.95),leaf=std('#2f5e2c',.85),leaf2=std('#3d7334',.85),red=std('#b3242b',.6),gold=std('#d9a441',.4,.4),stone=std('#9a968c',.9),dark=std('#2a1d16',.8);
  // banyan: fat trunk, aerial roots, huge canopy
  add(new THREE.CylinderGeometry(1.1,1.7,6,10),bark,-3,3,-2.4);for(let i=0;i<14;i++){const a=R(0,TAU),r=R(2.5,7.5);add(new THREE.CylinderGeometry(.06,.1,R(4,6.5),5),bark,-3+Math.cos(a)*r,R(3.4,4.4),-2.4+Math.sin(a)*r);}
  for(let i=0;i<9;i++){const a=i/9*TAU;add(new THREE.IcosahedronGeometry(R(3,4.2),1),i%2?leaf:leaf2,-3+Math.cos(a)*R(3,5.5),R(7,8.6),-2.4+Math.sin(a)*R(3,5.5));}add(new THREE.IcosahedronGeometry(4.6,1),leaf,-3,9.4,-2.4);
  addSolidBox(o.x-4.6,o.z-4,o.x-1.4,o.z-.8,y,y+6);
  // little red shrine with incense
  add(new THREE.BoxGeometry(1.6,.5,1.1),stone,0,.25,0);add(new THREE.BoxGeometry(1.3,1.1,.9),red,0,1.05,0);add(new THREE.BoxGeometry(1.8,.14,1.3),dark,0,1.67,0);
  const roof=add(new THREE.ConeGeometry(1.25,.6,4),std('#2d6b4f',.6),0,2,0,Math.PI/4);roof.scale.z=.75;
  add(new THREE.BoxGeometry(.8,.7,.05),dark,0,1.05,.47);{const t=textPlane('土地',.6,.32,{bg:'#b3242b',fg:'#ffd23f',size:.8});t.position.set(0,1.27,.5);G.add(t);}
  {const t=textPlane('福德正神',.22,.9,{bg:'#ffd23f',fg:'#b3242b',size:.62,cw:256});t.position.set(-.48,1.05,.47);G.add(t);const t2=t.clone();t2.position.x=.48;G.add(t2);}
  add(new THREE.CylinderGeometry(.22,.18,.22,10),gold,0,.62,.75);for(let i=0;i<3;i++){add(new THREE.CylinderGeometry(.012,.012,.5,4),std('#c8102e',.6),-.06+i*.06,.95,.75);const tip=new THREE.Mesh(new THREE.SphereGeometry(.02,6,4),new THREE.MeshBasicMaterial({color:0xff5a1f}));tip.position.set(-.06+i*.06,1.2,.75);G.add(tip);}
  add(new THREE.CylinderGeometry(.09,.08,.3,8),std('#7a4b2a',.6),.42,.65,.7);for(let i=0;i<8;i++)add(new THREE.CylinderGeometry(.008,.008,.34,3),std('#c9a26a',.7),.42+R(-.04,.04),.85,.7+R(-.04,.04));
  for(const s of [-1,1]){add(new THREE.CylinderGeometry(.18,.2,.06,10),std('#8a1b1b',.6),s*1.2,.03,.9);}
  for(const [px,pz] of [[1.8,1.2],[-1.6,1.6],[2.4,-.6]])add(new THREE.DodecahedronGeometry(R(.3,.55),0),stone,px,.2,pz);
  addSolidBox(o.x-.8,o.z-.55,o.x+.8,o.z+.55,y,y+2);
  // fireflies
  const nf=40,pos=new Float32Array(nf*3);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));
  const ff=new THREE.Points(geo,new THREE.PointsMaterial({color:0xfff38a,size:.16,map:softDot(),transparent:true,depthWrite:false,blending:THREE.AdditiveBlending}));ff.frustumCulled=false;G.add(ff);SHRINE.ff={pts:ff,pos,seed:Array.from({length:nf},()=>[R(-7,7),R(.4,3.4),R(-7,7),R(0,TAU)])};
  SHRINE.built=true;
  INTER.push({at:()=>({x:SHRINE.x,z:SHRINE.z+1.4}),r:2.2,label:'喺土地廟上香求籤',ok:()=>!PLAYER.car&&!curRoom,act:shrineDraw});
  TVN.lines.push('市民報稱東面大公園榕樹下晚晚有螢火蟲，傳聞有間好靈嘅土地廟');}
const LOTS=[['上上籤','心想事成，貴人扶持。'],['上籤','守得雲開見月明。'],['中籤','凡事慢慢嚟，唔使急。'],['中籤','出入平安，小心車輛。'],['下籤','今日唔宜打交，宜返屋企食飯。'],['中籤','讀書要專心，考試自然過關。'],['上籤','財運漸旺，路邊執到錢。']];
function shrineDraw(){if(SHRINE.cd>0){toast('等陣先再求過啦');return;}SHRINE.cd=2.2;busy=true;PLAYER.h=Math.PI;toast('🙏 誠心上香，搖搖籤筒…');
  let k=0;const iv=setInterval(()=>{sfx('swing',.25);k++;if(k>=5)clearInterval(iv);},140);
  setTimeout(()=>{busy=false;const have=S.spirit&&(S.spirit.uses>0||SP.out);
    if(!have&&rnd()<.04){sfx('gold');gainXP(80,'神秘寶物');S.spirit={uses:10};SP.out=false;refreshGourd();S.wpn=WEAPONS.findIndex(w=>w.id==='gourd');updateWeapon();save();
      say([['旁白','（籤筒「咔」一聲跌出一支金色嘅籤…）'],['旁白','神枱底下面發出一陣藍光，原來收埋咗一個古老嘅寶葫蘆！'],['旁白','葫蘆入面有隻細細隻嘅雷雲仔，眨下眼望住你。'],['旁白','【得到寶葫蘆】Q 換做寶葫蘆，F 放雷雲仔出嚟幫你打（可以用 10 次），再撳 F 收返。']]);return;}
    const L=pick(LOTS);if(rnd()<.2){dropCash(SHRINE.x+R(-1,1),SHRINE.z+2,R(5,20)|0);}say([['籤文','第'+(1+Math.floor(rnd()*100))+'籤・'+L[0]+'：'+L[1]]]);},900);}
