function zapDraw(){const a=zapLine.geometry.attributes.position.array;const [x,y,z]=SP.zap;for(let i=0;i<14;i++){const u=i/13;const j=(i===0||i===13)?0:.5;a[i*3]=SP.x+(x-SP.x)*u+R(-j,j);a[i*3+1]=SP.y+(y-SP.y)*u+R(-j,j);a[i*3+2]=SP.z+(z-SP.z)*u+R(-j,j);}zapLine.geometry.attributes.position.needsUpdate=true;zapLine.visible=true;}
function spiritUpdate(dt){if(!SP.out||!SP.m){if(zapLine)zapLine.visible=false;return;}const P=PLAYER,o=P.car||P;SP.t+=dt;SP.life-=dt;if(SP.life<=0){spiritRecall();return;}
  const side=P.car?2.2:1.1;const rx=Math.cos(P.car?P.car.h:P.h),rz=-Math.sin(P.car?P.car.h:P.h);const tx=o.x+rx*side,tz=o.z+rz*side,ty=(P.car?(P.car.y||0)+2.4:(P.y||0)+2)+Math.sin(SP.t*2.4)*.18;
  const k=1-Math.exp(-4*dt);SP.x+=(tx-SP.x)*k;SP.y+=(ty-SP.y)*k;SP.z+=(tz-SP.z)*k;const g=SP.m.g;g.position.set(SP.x,SP.y,SP.z);g.scale.setScalar(Math.min(.7,g.scale.x+dt*2));
  let tgt=null,td=16;const cands=[...FIGHT.filter(f=>f.hp>0),...(S.stars>0?COPS.filter(c=>c.down<=0):[])];for(const t of cands){const d=Math.hypot(t.g.position.x-SP.x,t.g.position.z-SP.z);if(d<td){td=d;tgt=t;}}
  const face=tgt?Math.atan2(tgt.g.position.x-SP.x,tgt.g.position.z-SP.z):(P.car?P.car.h:P.h);g.rotation.y=lerpAngle(g.rotation.y,face,1-Math.exp(-6*dt));SP.m.b.rotation.z=Math.sin(SP.t*3)*.08;
  if(SP.t%0.2<dt)emit(PSA,{x:SP.x+R(-.3,.3),y:SP.y+R(-.2,.2),z:SP.z+R(-.3,.3),vx:0,vy:-.3,vz:0,life:.5,s0:.12,s1:.02,r:.6,g:.85,b:1});
  SP.cd-=dt;if(tgt&&SP.cd<=0){SP.cd=1.1;const q=tgt.g.position;zapTo(q.x,q.y+1.2,q.z);sfx('gun',.6);if(AU.ctx&&!AU.muted)noiseHit(AU.ctx.currentTime,.25,.25,3000,'highpass',AU.sfx);sparks(q.x,q.y+1.2,q.z,16,4);flash(q.x,q.y+2,q.z,3.5,.15);
    if(FIGHT.includes(tgt)){hitTarget(tgt,44);if(tgt.hp<=0)tgt.kx=tgt.kz=0;}else if(COPS.includes(tgt)){hitTarget(tgt,60);}}
  if(SP.zapT>0){SP.zapT-=dt;zapDraw();zapLine.material.opacity=Math.max(0,SP.zapT/.18);}else if(zapLine)zapLine.visible=false;}
