/* ---------- traffic: never ghost through the player; honk, and hit you if you jump in front ---------- */
function honk(v){if(!AU.ctx||AU.muted)return;const d=Math.hypot(v.x-PLAYER.x,v.z-PLAYER.z);if(d>40)return;const t=AU.ctx.currentTime,k=Math.max(.15,1-d/40);tone(415,t,.18,'square',.05*k,AU.sfx);tone(523,t,.18,'square',.04*k,AU.sfx);tone(415,t+.25,.3,'square',.05*k,AU.sfx);tone(523,t+.25,.3,'square',.04*k,AU.sfx);}
function trafficUpdate(v,dt){const r=v.road;const q=posOn(r,v.s);let fx=q.dx*v.dir,fz=q.dz*v.dir;
  let gap=1e9,pgap=1e9;for(const o of vehicles){if(o===v)continue;const dx=o.x-v.x,dz=o.z-v.z;const f=dx*fx+dz*fz;if(f<=0||f>40)continue;const lat=Math.abs(dx*fz-dz*fx);if(lat<2.2)gap=Math.min(gap,f-(o.L+v.L)/2);}
  const P=PLAYER;if(!P.car&&!P.riding&&(P.y||0)-TH(P.x,P.z)<2){const dx=P.x-v.x,dz=P.z-v.z,f=dx*fx+dz*fz;if(f>-1&&f<24&&Math.abs(dx*fz-dz*fx)<2.6)pgap=f-v.L/2-1.5;}
  for(const t of lrts){const dx=t.x-v.x,dz=t.z-v.z,f=dx*fx+dz*fz;if(f>0&&f<30&&Math.abs(dx*fz-dz*fx)<3)gap=Math.min(gap,f-v.L/2-8);}
  if(typeof sigGap==='function')gap=Math.min(gap,sigGap(v,fx,fz));
  const far=Math.hypot(v.x-camera.position.x,v.z-camera.position.z)>70;if(v.stuck>7&&far){gap=1e9;v.stuck-=dt*3;}
  const g=Math.min(gap,pgap);const want=Math.max(0,Math.min(v.cruise,(g-3)*.9));const prev=v.speed;
  if(want<.3&&gap<=pgap)v.stuck=(v.stuck||0)+dt;else if(v.stuck>0&&v.stuck<=7)v.stuck=Math.max(0,v.stuck-dt);
  if(pgap<6&&v.speed<1){v.honkT=(v.honkT||0)-dt;if(v.honkT<=0){v.honkT=R(2.5,4.5);honk(v);}}
  v.speed=lerp(v.speed,want,1-Math.exp(-(want<v.speed?3.5:1.1)*dt));v.brakeOn=v.speed<prev-.02&&v.speed<v.cruise*.95;
  v.s+=v.dir*v.speed*dt;
  if(v.s<0||v.s>r.len){const end=v.s>r.len?r.pts[r.pts.length-1]:r.pts[0];let nx=null;for(const o of DRIVE){if(o===r||end[0]<o.x0||end[0]>o.x1||end[1]<o.z0||end[1]>o.z1)continue;const a=o.pts[0],b=o.pts[o.pts.length-1];if(Math.hypot(a[0]-end[0],a[1]-end[1])<3){nx=[o,0,1];if(rnd()<.6)break;}else if(!o.oneway&&Math.hypot(b[0]-end[0],b[1]-end[1])<3){nx=[o,o.len,-1];if(rnd()<.6)break;}}
    if(nx){v.road=nx[0];v.s=nx[1];v.dir=nx[2];v.lane=nx[0].oneway?(nx[0].w>8?pick([-1,1])*nx[0].w/5:0):nx[0].w/4;}else{const rs=pickRoadNear(cam.tx,cam.tz,140,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;}else{v.dir=-v.dir;v.s=clamp(v.s,0,r.len);}}}
  const p=posOn(v.road,v.s);fx=p.dx*v.dir;fz=p.dz*v.dir;const px=p.x+fz*v.lane,pz=p.z-fx*v.lane;
  const h=Math.atan2(fx,fz);if(v.x===0&&v.z===0){v.x=px;v.z=pz;v.h=h;}v.x=lerp(v.x,px,1-Math.exp(-6*dt));v.z=lerp(v.z,pz,1-Math.exp(-6*dt));v.h=lerpAngle(v.h,h,1-Math.exp(-7*dt));
  v.vx=fx*v.speed;v.vz=fz*v.speed;v.spin+=v.speed/v.wr*dt;v.pitch=lerp(v.pitch,(prev-v.speed)/Math.max(dt,1e-3)*.004,.1);v.y=TH(v.x,v.z);
  // a car that still reaches you (you ran out in front of it) knocks you over
  if(!P.car&&!P.riding&&v.speed>2.5&&(P.y||0)-TH(P.x,P.z)<1.5){const dx=P.x-v.x,dz=P.z-v.z,sf=Math.sin(v.h),cf=Math.cos(v.h);const f=dx*sf+dz*cf,l=dx*cf-dz*sf;
    if(Math.abs(f)<v.L/2+.3&&Math.abs(l)<v.W/2+.3){const sp=v.speed;if(MECH.on){v.speed=0;carDamage(v,sp*3,P.x,P.z);sfx('crash',.5);}else if(performance.now()-(P.hitAt||0)>1200){P.hitAt=performance.now();hurtPlayer(Math.round(6+sp*1.6));thudSfx(.8);shake=Math.max(shake,.4);const side=Math.sign(l)||1;P.vx=(sf*sp*.7+cf*side*4);P.vz=(cf*sp*.7-sf*side*4);P.vy=3+sp*.18;P.grounded=false;P.peak=P.y;v.speed*=.25;honk(v);if(rnd()<.6)subtitle('司機',pick(['睇路呀！','你唔要命呀？！','行路唔帶眼！']));}}}
  if(Math.hypot(v.x-cam.tx,v.z-cam.tz)>520){const rs=pickRoadNear(cam.tx,cam.tz,160,420);if(rs){placeOnRoad(v,rs[0],rs[1]);v.x=v.z=0;}}
  syncV(v);}

