/* ---------- boot / update ---------- */
function v3eBuild(){buildHobbyRoom();}
function v3eBoot(){setupHobbyHome();buildHobbyShelf();mechBtns();}
function v3eUpdate(dt){mechUpdate(dt);}

/* ================= v3f: five wanted levels (patrol → cars → PTU guns → SDU + helicopter → Jesus), the Satan cross, inventory ================= */
const HEAT_PER=5,HEAT_MAX=29;
const STAR_INFO=['','巡警追捕','警車出動','衝鋒隊開槍','飛虎隊＋直升機','耶穌降臨'];
function addHeat(n,force){if(!force&&(FIGHT_STEPS.includes(S.m)))return;S.heat=Math.min(HEAT_MAX,S.heat+n);const st=Math.min(5,Math.floor(S.heat/HEAT_PER));if(st!==S.stars){const up=st>S.stars;S.stars=st;S.maxStars=Math.max(S.maxStars,st);drawStars();if(up&&st>0){toast('★'.repeat(st)+'　'+STAR_INFO[st]);sfx(st>=5?'bell':'bad');}}coolT=0;}
function drawStars(){const el=$('#stars');if(el&&el.children.length<5){const s=document.createElement('span');s.textContent='★';s.className='s5';el.appendChild(s);}document.querySelectorAll('#stars span').forEach((s,i)=>s.classList.toggle('on',i<S.stars));}
{const _cp=clearPursuit;clearPursuit=function(){_cp();heliRemove();if(J.on)jesusLeave(true);};}

/* ---------- cops by level ---------- */
const COP_LOOK={patrol:{shirt:'#2f4f6f',pants:'#2f4f6f',name:'差佬',hp:120,cap:'#1d2440'},ptu:{shirt:'#1d2a44',pants:'#1d2a44',name:'衝鋒隊',hp:160,cap:'#2b4fa0',gun:1.25,dmg:5},sdu:{shirt:'#141416',pants:'#141416',name:'飛虎隊',hp:240,cap:'#0c0c0e',gun:.75,dmg:7}};
function copKind(){const w=S.stars;if(w>=4)return rnd()<.65?'sdu':'ptu';if(w>=3)return rnd()<.7?'ptu':'patrol';return 'patrol';}
function spawnCop(){const C=roadsNear(PLAYER.x,PLAYER.z,100,r=>r.cls>=4);if(!C.length)return false;for(let t=0;t<25;t++){const r=pick(C);const q=posOn(r,R(0,r.len));const d=Math.hypot(q.x-PLAYER.x,q.z-PLAYER.z);if(d>40&&d<90){const k=copKind(),L=COP_LOOK[k];
      const p=npc(L.name,{shirt:L.shirt,pants:L.pants},q.x,q.z,0,k==='sdu'?'#c9c9c9':'#9cc8ff');addCap(p,L.cap);p.kind=k;p.hp=L.hp;p.down=0;p.gcd=R(1,2);
      if(L.gun){const gm=new THREE.Mesh(new THREE.BoxGeometry(.07,.09,.5),std('#111',.4,.6));gm.position.set(0,-.62,.2);p.arms[1].add(gm);if(k==='sdu'){const v=new THREE.Mesh(new THREE.BoxGeometry(.46,.5,.32),std('#22252a',.7));v.position.set(0,1.2,0);p.b.add(v);}}
      COPS.push(p);return true;}}return false;}
const SHOTS=[];
function tracer(x0,y0,z0,x1,y1,z1){const geo=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x0,y0,z0),new THREE.Vector3(x1,y1,z1)]);const l=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xffe08a,transparent:true,opacity:1,toneMapped:false}));scene.add(l);SHOTS.push({l,t:.12});}
function copShoot(x,y,z,dmg,spread){const P=PLAYER,o=P.car||P;const hit=rnd()<(P.car?.5:.55)*(MECH.on?.8:1);const tx=o.x+(hit?0:R(-spread,spread)),tz=o.z+(hit?0:R(-spread,spread)),ty=(P.car?(P.car.y||0)+1:(P.y||0)+1.2)+(hit?0:R(-.5,.8));
  tracer(x,y,z,tx,ty,tz);sfx('gun',.35);emit(PSA,{x,y,z,life:.08,s0:.5,s1:.2,r:1,g:.8,b:.4});if(!hit)return;if(P.car){carDamage(P.car,dmg*.9,P.car.x,P.car.z);sparks(tx,ty,tz,6,3);}else{hurtPlayer(dmg);}}
function pursuitUpdate(dt){const w=S.stars,cops=w>=5?0:w;for(let i=SHOTS.length-1;i>=0;i--){const s=SHOTS[i];s.t-=dt;s.l.material.opacity=Math.max(0,s.t/.12);if(s.t<=0){scene.remove(s.l);s.l.geometry.dispose();SHOTS.splice(i,1);}}
  if(cops>0){copSpawnT-=dt;const want=[0,2,4,6,8][cops];if(copSpawnT<=0&&COPS.filter(c=>c.down<=0).length<want){copSpawnT=spawnCop()?(cops>=3?1.4:2.2):.3;}const cars=[0,0,1,2,3][cops];if(PCARS.length<cars&&rnd()<dt*.6)spawnPoliceCar();}
  if(cops>=4)heliEnsure();else heliRemove();
  let nearest=1e9;const o=PLAYER.car||PLAYER;
  for(let i=COPS.length-1;i>=0;i--){const c=COPS[i];const g=c.g;if(c.down>0){c.down-=dt;if(c.down<=0){g.rotation.x=0;g.position.y=0;c.hp=COP_LOOK[c.kind||'patrol'].hp;}continue;}if(cops===0){scene.remove(g);COPS.splice(i,1);continue;}
    let x=g.position.x,z=g.position.z;const dx=o.x-x,dz=o.z-z,d=Math.hypot(dx,dz)||1;nearest=Math.min(nearest,d);const L=COP_LOOK[c.kind||'patrol'];let spd=0;const keep=L.gun?(PLAYER.car?6:9):1.1;
    if(d>keep){spd=PLAYER.car?7.5:c.kind==='sdu'?6.8:6.4;x+=dx/d*spd*dt;z+=dz/d*spd*dt;}const q={x,z};pushOut(q,.4);g.position.set(q.x,TH(q.x,q.z),q.z);g.rotation.y=Math.atan2(dx,dz);animP(c,spd,dt);
    c.gcd-=dt;if(L.gun&&d<30&&c.gcd<=0&&!dlgQ&&!busy&&!S.dead){c.gcd=L.gun*R(.8,1.3);c.arms[1].rotation.x=-1.5;const m=c.arms[1].localToWorld(new THREE.Vector3(0,-.62,.45));copShoot(m.x,m.y,m.z,L.dmg,2.5);}else if(L.gun&&d<30)c.arms[1].rotation.x=-1.5;
    if(!L.gun&&d<1.4&&c.gcd<=0&&!PLAYER.car&&!dlgQ){c.gcd=1.1;c.arms[1].rotation.x=-1.6;setTimeout(()=>{if(c.arms)c.arms[1].rotation.x=0;},150);hurtPlayer(5);}
    if(d>260){scene.remove(g);COPS.splice(i,1);}}
  for(let i=PCARS.length-1;i>=0;i--){const v=PCARS[i];if(cops<2||v.wreck){if(v.wreck){PCARS.splice(i,1);continue;}scene.remove(v.g);vehicles.splice(vehicles.indexOf(v),1);PCARS.splice(i,1);continue;}const tx=o.x,tz=o.z;const d=Math.hypot(tx-v.x,tz-v.z);nearest=Math.min(nearest,d);
    const want=Math.atan2(tx-v.x,tz-v.z);v.h=lerpAngle(v.h,want,1-Math.exp(-2.2*dt));const sp=cops>=3?(d>8?26:d>4?14:2):(d>14?23:d>6?8:0);v.speed=lerp(v.speed,sp,1-Math.exp(-1.5*dt));v.vx=Math.sin(v.h)*v.speed;v.vz=Math.cos(v.h)*v.speed;v.x+=v.vx*dt;v.z+=v.vz*dt;
    for(const off of [1.2,-1.2]){const c={x:v.x+Math.sin(v.h)*off,z:v.z+Math.cos(v.h)*off};const ox=c.x,oz=c.z;if(pushOut(c,1)){v.x+=c.x-ox;v.z+=c.z-oz;v.speed*=.7;}}v.spin+=v.speed/v.wr*dt;
    if(cops>=3&&PLAYER.car&&d<4.2&&v.speed>8&&(v.ramCd||0)<=0){v.ramCd=1.2;sfx('crash',.7);carDamage(PLAYER.car,(v.speed-6)*1.6,(v.x+PLAYER.car.x)/2,(v.z+PLAYER.car.z)/2);PLAYER.car.vx+=Math.sin(v.h)*5;PLAYER.car.vz+=Math.cos(v.h)*5;v.speed*=.3;}if(v.ramCd>0)v.ramCd-=dt;
    const k=Math.floor(performance.now()/120)%2;if(v.bar){v.bar[0].visible=k===0;v.bar[1].visible=k===1;}syncV(v);if(d>320){scene.remove(v.g);vehicles.splice(vehicles.indexOf(v),1);PCARS.splice(i,1);}}
  if(HELI.g){const hd=Math.hypot(HELI.x-o.x,HELI.z-o.z);nearest=Math.min(nearest,hd);heliUpdate(dt);}
  if(J.on){nearest=Math.min(nearest,Math.hypot(J.p.g.position.x-o.x,J.p.g.position.z-o.z)*.5);}
  if(w>0){if(nearest<90&&cops>0)sirenOn();else sirenOff();
    const slow=PLAYER.car?Math.abs(PLAYER.car.speed)<2:true;const close=cops<=3&&(COPS.some(c=>c.down<=0&&Math.hypot(c.g.position.x-PLAYER.x,c.g.position.z-PLAYER.z)<(PLAYER.car?3.5:1.3))||PCARS.some(v=>Math.hypot(v.x-PLAYER.x,v.z-PLAYER.z)<5));
    if(close&&slow&&!dlgQ&&!busy&&!MECH.on){bustT+=dt;if(bustT>1.6)busted();}else bustT=Math.max(0,bustT-dt);
    const coolNeed=w>=5?20:w>=4?14:10;if(nearest>70){coolT+=dt;if(coolT>coolNeed){coolT=0;S.heat=Math.max(0,S.heat-HEAT_PER);const st=Math.floor(S.heat/HEAT_PER);if(st!==S.stars){S.stars=st;drawStars();if(st===0){toast('甩身！');sirenOff();}}}}else coolT=0;}else sirenOff();
  if(w>=5&&!J.on&&!S.dead)jesusCome();if(w<5&&J.on&&!J.dying)jesusLeave(false);}

/* ---------- police helicopter (4★) ---------- */
const HELI={g:null,x:0,z:0,y:30,rot:null,beam:null,gcd:2,ang:0};
function heliEnsure(){if(HELI.g)return;const g=new THREE.Group(),W=std('#f4f6f8',.4,.3),B=std('#1d4fa0',.5,.3),K=std('#202326',.5,.5);
  const body=new THREE.Mesh(new THREE.SphereGeometry(1.4,14,10),W);body.scale.set(1,.85,1.7);g.add(body);const st=new THREE.Mesh(new THREE.BoxGeometry(2.0,.35,3.2),B);st.position.y=-.1;g.add(st);
  const gl=new THREE.Mesh(new THREE.SphereGeometry(1.0,12,8,0,TAU,0,Math.PI/2),new THREE.MeshStandardMaterial({color:lin('#223040'),roughness:.1,metalness:.4}));gl.rotation.x=Math.PI/2;gl.position.set(0,.2,1.5);g.add(gl);
  const tail=new THREE.Mesh(new THREE.CylinderGeometry(.18,.35,4.2,8),W);tail.rotation.x=Math.PI/2;tail.position.set(0,.3,-3.6);g.add(tail);const fin=new THREE.Mesh(new THREE.BoxGeometry(.1,1.2,.8),B);fin.position.set(0,.8,-5.5);g.add(fin);
  for(const s of [-1,1]){const sk=new THREE.Mesh(new THREE.BoxGeometry(.1,.1,3),K);sk.position.set(s*1.0,-1.35,0);g.add(sk);}
  const rot=new THREE.Group();rot.position.y=1.35;g.add(rot);for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.BoxGeometry(.25,.04,7),K);b.rotation.y=i*Math.PI/2;rot.add(b);}const tr=new THREE.Group();tr.position.set(.2,.8,-5.6);g.add(tr);for(let i=0;i<2;i++){const b=new THREE.Mesh(new THREE.BoxGeometry(.04,1.5,.15),K);b.rotation.x=i*Math.PI/2;tr.add(b);}
  {const t=textPlane('POLICE 警察',2.2,.4,{bg:'#1d4fa0',fg:'#fff',size:.7});t.position.set(1.42,0,0);t.rotation.y=Math.PI/2;g.add(t);}
  const beam=new THREE.Mesh(new THREE.CircleGeometry(3.2,32),new THREE.MeshBasicMaterial({color:0xfff3c0,transparent:true,opacity:.22,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false,polygonOffset:true,polygonOffsetFactor:-8,polygonOffsetUnits:-8}));beam.rotation.x=-Math.PI/2;scene.add(beam);
  g.traverse(m=>{if(m.isMesh&&m!==beam)m.castShadow=true;});const o=PLAYER.car||PLAYER;HELI.x=o.x+80;HELI.z=o.z+80;HELI.y=(PLAYER.y||0)+32;g.position.set(HELI.x,HELI.y,HELI.z);scene.add(g);Object.assign(HELI,{g,rot,tr,beam,gcd:3});toast('🚁 警察直升機到咗！');}
function heliRemove(){if(!HELI.g)return;scene.remove(HELI.g);scene.remove(HELI.beam);HELI.g=null;}
