function jesusLeave(silent){if(!J.on)return;const m=J.p;J.on=false;const i=FIGHT.indexOf(m);if(i>=0)FIGHT.splice(i,1);J.leave={m,t:0};if(!silent)toast('耶穌升返上天……通緝降咗');for(const f of J.fx)scene.remove(f.m);J.fx.length=0;bossBar();}
