addEventListener('keydown',e=>{if(!started||e.repeat||e.code!=='KeyH')return;const it=S.items||{};if(!(it.soda>0)){toast('冇汽水存貨');return;}if(S.hp>=100){toast('血滿咗，唔使飲');return;}it.soda--;S.hp=Math.min(100,S.hp+40);sfx('ok');toast('咕嚕咕嚕… +40 血（仲有 '+it.soda+' 支）');save();});
