  // (v16.3: the low edge railings are replaced by full concourse walls with doorways, built in v3t stationWalls)
  YL.gapsN=gapsN;YL.gapsE=gapsE;
  ysign('元朗站 Yuen Long',-U+.2,0,CY+3.8,5,.8,{bg:'#9a3b26',fg:'#fff',face:Math.PI});ysign('元朗站 Yuen Long',U-.2,0,CY+3.8,5,.8,{bg:'#9a3b26',fg:'#fff',face:0});
  // a few commuters in the concourse and interchange
  YL.people=[];for(let i=0;i<14;i++){const lvl=i<8;const p=rnd()<.35?uniformPerson(rnd()<.5):person({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47']),pants:pick(['#2b3550','#222','#5d4b3a']),long:rnd()<.4});
    const u=R(-U+4,U-4),v=lvl?R(-V+2,V-2):R(-V+2,-6);if(lvl&&Math.abs(u)<G+1){i--;scene.remove(p.g);continue;}const c=SW(u,v);p.g.position.set(c.x,lvl?CY:0,c.z);p.yl={u,v,y:lvl?CY:0,tu:u,tv:v,wt:R(0,4)};YL.people.push(p);}
  yflush();
