function ylPeople(dt){if(!YL.people)return;const near=Math.hypot(PLAYER.x-YL.Q.x,PLAYER.z-YL.Q.z)<140;for(const p of YL.people){p.g.visible=near;if(!near)continue;const o=p.yl;o.wt-=dt;if(o.wt<=0){o.wt=R(3,8);o.tu=clamp(o.u+R(-12,12),-YL.U+3,YL.U-3);if(o.y>0&&Math.abs(o.tu)<YL.G+1)o.tu=Math.sign(o.u||1)*(YL.G+2);o.tv=clamp(o.v+R(-5,5),-YL.V+2,o.y>0?YL.V-2:-6);}
    const du=o.tu-o.u,dv=o.tv-o.v,d=Math.hypot(du,dv);let sp=0;if(d>.3){sp=1.2;o.u+=du/d*sp*dt;o.v+=dv/d*sp*dt;}const c=SW(o.u,o.v);p.g.position.set(c.x,o.y,c.z);if(sp)p.g.rotation.y=Math.atan2(YL.D.x*du+YL.N.x*dv,YL.D.z*du+YL.N.z*dv);animP(p,sp,dt);}}
/* gates, escalator drift, platform hand-off */
function ylUpdate(dt){if(!YL.on)return;const P=PLAYER;ylPeople(dt);for(const f of YL.flaps){f.open=Math.max(0,f.open-dt);const k=f.open>0?1:0;f.cur=lerp(f.cur||0,k,1-Math.exp(-12*dt));const p=SW(f.gu,f.v+f.side*(.37+f.cur*.3));f.m.position.x=p.x;f.m.position.z=p.z;f.m.scale.z=1-f.cur*.9;}
  if(P.car||curRoom||P.riding)return;const l=SL(P.x,P.z);const lvl=(P.y||0)>YL.CY-.4&&(P.y||0)<YL.CY+2.5&&Math.abs(l.v)<YL.V&&Math.abs(l.u)<YL.U+.5;
  // ticket gates: crossing into the paid area costs $5
  if(lvl&&YL.lastLvl){const was=Math.abs(YL.lastU)<YL.G,now=Math.abs(l.u)<YL.G;
    if(!was&&now){if(Math.abs(l.v)>4.1){}else if(!YL.paid){if(S.money>=5){addMoney(-5,true);YL.paid=true;sfx('ding');toast('嘟！拍卡入閘 -$5');openFlaps(l);}else{const b=SW(Math.sign(l.u)*(YL.G+.6),l.v);P.x=b.x;P.z=b.z;P.vx=P.vz=0;toast('唔夠錢入閘（要 $5）');sfx('bad');}}}
    else if(was&&!now){if(Math.abs(l.v)<=4.1){YL.paid=false;sfx('ok',.6);openFlaps(l);}}}
  // block walking through the flaps without paying (the glass walls handle the rest)
  if(lvl&&!YL.paid&&Math.abs(Math.abs(l.u)-YL.G)<.7&&Math.abs(l.u)<YL.G&&Math.abs(l.v)<=4.1){}
  YL.lastU=l.u;YL.lastLvl=lvl;
  // escalators: gentle drift upward when standing on them
  for(const e of YL.esc){const ru=l.u-e.u0,rv=l.v-e.v0;const along=ru*e.au+rv*e.av,lat=-ru*e.av+rv*e.au;if(along<0||along>e.L||Math.abs(lat)>e.w/2+.1)continue;const sy=e.y0+(e.y1-e.y0)*along/e.L;if(Math.abs((P.y||0)-sy)>1.2)continue;
    const sp=.9*dt;const mvU=e.au*sp,mvV=e.av*sp;P.x+=YL.D.x*mvU+YL.N.x*mvV;P.z+=YL.D.z*mvU+YL.N.z*mvV;break;}
  // platform hand-off at the top of the platform escalator
  const st=YL.st;if(!P.plat&&(P.y||0)>PLAT_Y-.35&&Math.abs(l.v-st.off)<1.6&&l.u>2.2&&l.u<6){P.plat=st;YL.paid=true;}
  else if(P.plat===st){if(l.u<1.2&&Math.abs(l.v-st.off)<.9&&inp.y!==0){const fx=-Math.sin(cam.yaw),fz=-Math.cos(cam.yaw);const mu=(fx*YL.D.x+fz*YL.D.z)*inp.y;if(mu<-.2){P.plat=null;const p=SW(.9,st.off);P.x=p.x;P.z=p.z;P.y=PLAT_Y;}}}}
function openFlaps(l){for(const f of YL.flaps)if(Math.sign(f.gu)===Math.sign(l.u)&&Math.abs(f.v-l.v)<.9)f.open=1.6;}
/* reopen: remove the closed kiosk of 元朗, open 朗屏's concourse */
function ylReopen(){const i0=INTER.findIndex(it=>typeof it.label==='string'&&it.label==='元朗站（暫停開放）');if(i0>=0){INTER.splice(i0,1);const j=INTER.findIndex((it,k)=>k>=i0&&it.label==='出閘離開');if(j>=0)INTER.splice(j,1);}
  const lp=MTR.st.lp;const k=INTER.findIndex(it=>it.label==='朗屏站（暫停開放）');if(k>=0&&lp&&lp.room){INTER[k].label='入朗屏站';INTER[k].act=()=>enterRoom('mtr_lp',{x:lp.street.x,z:lp.street.z+1.5,h:0});}
  for(const L of LABELS){if(L.name==='元朗站（暫停開放）'){L.el.remove();L.dead=true;}if(L.name==='朗屏站（暫停開放）'){L.name='朗屏站';L.el.textContent='朗屏站';}}
  for(let i=LABELS.length-1;i>=0;i--)if(LABELS[i].dead)LABELS.splice(i,1);
  // arriving at 元朗 by train puts you on the platform inside the paid area
  const _arr=arriveTrain;arriveTrain=function(st){_arr(st);if(st.id==='yl')YL.paid=true;};
  TVN.lines=TVN.lines.map(s=>s.includes('屯馬綫元朗站')?'屯馬綫元朗站已經重開，車站有八個出口，樓下係巴士總站':s);}
function v3hBuild(){}
function v3hBoot(){try{buildYuenLongStation();}catch(e){console.error('YL station',e);}ylReopen();}
function v3hUpdate(dt){ylUpdate(dt);}
/* platforms: project continuously onto the track (the old version snapped to whole metres, so you could hardly walk) */
function platformConstrain(){const st=PLAYER.plat;if(!st||PLAYER.riding)return;const P=MTR.path;let bs=st.s,bd=1e9;for(let s=st.s0;s<=st.s1;s+=1){const q=posOn(P,s);const d=(q.x-PLAYER.x)**2+(q.z-PLAYER.z)**2;if(d<bd){bd=d;bs=s;}}
  {const q=posOn(P,bs);bs+=(PLAYER.x-q.x)*q.dx+(PLAYER.z-q.z)*q.dz;}
  bs=clamp(bs,st.s0+2,st.s1-2);const q=posOn(P,bs);const lat=(PLAYER.x-q.x)*(-q.dz)+(PLAYER.z-q.z)*q.dx;const l=clamp(lat,Math.min(st.off-1.35*st.sg,st.off+1.45*st.sg),Math.max(st.off-1.35*st.sg,st.off+1.45*st.sg));PLAYER.x=q.x-q.dz*l;PLAYER.z=q.z+q.dx*l;PLAYER.y=PLAT_Y;}
/* keep the camera under the platform canopy and the concourse ceiling */
{const _cu=camUpdate;camUpdate=function(dt){const P=PLAYER;let lim=0;if(YL.on&&!P.car&&!curRoom){if(P.plat)lim=1;else{const l=SL(P.x,P.z);if(Math.abs(l.u)<YL.U+1&&Math.abs(l.v)<YL.V+3&&(P.y||0)>YL.CY-.6&&(P.y||0)<YL.CY+3.5)lim=2;}}
  if(!lim)return _cu(dt);const z=cam.zoom;cam.pitch=Math.min(cam.pitch,lim===1?.2:.28);cam.zoom=Math.min(z,lim===1?.68:.85);try{_cu(dt);}finally{cam.zoom=z;}};}

/* ================= v3i: round E
   1. 百鳥塔外螺旋樓梯 + 塔頂觀景台 + 蜘蛛仔（30 秒後咬你 → 蜘蛛絲武器）
   2. 高處跳落：途人尖叫；金朗大廈天台
   3. 蜘蛛絲：射人（綁住）／半空擺盪飛行
   4. 被打嘅人會還手（市民少、老師多、黑社會重手，部分揸刀）
   5. 手提電話：打俾老竇（電動車／單車）、即時新聞（罪案、意外、火警）
   6. 城市隨機事件：打劫、黑社會打人、車撞人、火警；救護車、消防車
   7. 單車：快啲、跳、花式
   8. WASTED 黑白畫面
================= */

/* ---------- small shared helpers ---------- */
function mkPerson(look,x,z,name,color){const p=person(look);p.g.position.set(x,TH(x,z),z);scene.add(p.g);if(name)p.g.add(nameTag(name,color||'#ff6b6b'));p.ph=R(0,6);return p;}
function rmPerson(p){if(p&&p.g){scene.remove(p.g);}}
function knifeMesh(p){const g=new THREE.Group();g.position.y=-.64;const bl=new THREE.Mesh(new THREE.BoxGeometry(.03,.02,.26),std('#d9dde0',.15,.95));bl.position.z=.16;const hd=new THREE.Mesh(new THREE.BoxGeometry(.04,.04,.11),std('#2a1a12',.6));g.add(bl,hd);p.arms[1].add(g);return g;}
function roadS(r,x,z){let best=1e9,bs=0;for(let i=1;i<r.pts.length;i++){const a=r.pts[i-1],c=r.pts[i];const ex=c[0]-a[0],ez=c[1]-a[1],l2=ex*ex+ez*ez||1e-9;const t=clamp(((x-a[0])*ex+(z-a[1])*ez)/l2,0,1);const d=(x-a[0]-ex*t)**2+(z-a[1]-ez*t)**2;if(d<best){best=d;bs=r.cum[i-1]+t*Math.sqrt(l2);}}return bs;}
function punchAnim(p){if(!p.arms)return;p.arms[1].rotation.x=-1.6;setTimeout(()=>{if(p.arms)p.arms[1].rotation.x=0;},160);}
function outdoorOK(){const P=PLAYER;return !curRoom&&!P.ind&&!P.plat&&!P.riding&&!P.seated;}
function camDist(x,z){return Math.hypot(x-camera.position.x,z-camera.position.z);}
function ri_tagName(r){return (r&&r.name)||'元朗街頭';}

/* ======================================================================
   1. 百鳥塔：螺旋樓梯、觀景台、蜘蛛仔
   ====================================================================== */
const TOWER={c:null,tb:0,start:null,deckR:7.75,on:0,spider:null,stage:0,hinted:false,a0:0,aE:0};
function buildTowerStairs(){const tw=BL.find(b=>b.flag===2);if(!tw)return;const cx=(tw.x0+tw.x1)/2,cz=(tw.z0+tw.z1)/2,tb=tw.base,TOP=TOWER_TOP_Y;
  const nr=nearestRoad(cx,cz,200,r=>r.cls>=6);const a0=nr?Math.atan2(nr.z-cz,nr.x-cx):0;
  const N=74,RI=7.6,RO=9.2,turns=2.25,dA=turns*TAU/N;TOWER.c={x:cx,z:cz};TOWER.a0=a0;TOWER.aE=a0+N*dA;
  const P2=(r,a)=>[cx+Math.cos(a)*r,cz+Math.sin(a)*r];const e0=P2(8.4,a0-dA*.5);const g0=Math.min(tb,TH(e0[0],e0[1]));const rise=(TOP-g0)/N;TOWER.tb=g0;
  TOWER.start={x:P2(8.4,a0-dA*1.4)[0],z:P2(8.4,a0-dA*1.4)[1]};
  const stoneM=std('#d9d2c3',.85),railM=std('#c8102e',.5,.2),colM=std('#ece7dc',.7);
  const slab=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),stoneM,N),posts=new THREE.InstancedMesh(new THREE.CylinderGeometry(.035,.035,1,6),railM,N*2+40),bars=new THREE.InstancedMesh(new THREE.BoxGeometry(1,1,1),railM,N*2+20),cols=new THREE.InstancedMesh(new THREE.CylinderGeometry(.12,.12,1,8),colM,60);
  slab.castShadow=slab.receiveShadow=true;cols.castShadow=true;
  const m=new THREE.Matrix4(),q=new THREE.Quaternion(),e=new THREE.Euler(),v=new THREE.Vector3(),sc=new THREE.Vector3();let np=0,nb=0,nc=0;
  const put=(IM,i,x,y,z,ex,ey,sx,sy,sz)=>{e.set(ex,ey,0,'YXZ');q.setFromEuler(e);m.compose(v.set(x,y,z),q,sc.set(sx,sy,sz));IM.setMatrixAt(i,m);};
  for(let i=0;i<N;i++){const a1=a0+i*dA,a2=a1+dA,am=(a1+a2)/2,top=g0+(i+1)*rise;
    const pts=[P2(RI,a1),P2(RO,a1),P2(RO,a2),P2(RI,a2)];addSolidPts(pts,top-.3,top,{tower:true});
    const chord=2*8.4*Math.sin(dA/2);const mid=P2(8.4,am);put(slab,i,mid[0],top-.15,mid[1],0,-am,RO-RI,.3,chord*1.06);
    for(const [r0,r1] of (i>=N-3?[[RO,RO+.15]]:[[RO,RO+.15],[RI-.15,RI]]))addSolidPts([P2(r0,a1),P2(r1,a1),P2(r1,a2),P2(r0,a2)],top-.3,top+1.05,{tower:true,rail:true});
    for(const rr of (i>=N-3?[RO+.07]:[RO+.07,RI-.07])){const p=P2(rr,a1);put(posts,np++,p[0],top+.5,p[1],0,0,1,1.05,1);
      const pm=P2(rr,am);const ch=2*rr*Math.sin(dA/2);put(bars,nb++,pm[0],top+1.02-rise/2,pm[1],-Math.atan2(rise,ch),-am,.06,.06,Math.hypot(ch,rise)*1.02);}
    if(i%5===2&&nc<60){const p=P2(RO-.25,am);const gy=TH(p[0],p[1]);const h=top-.3-gy;if(h>.6){put(cols,nc++,p[0],gy+h/2,p[1],0,0,1,h,1);}}}
  // end rail across the top of the stair
  {const a=TOWER.aE+.02;addSolidPts([P2(RI,a),P2(RO+.15,a),P2(RO+.15,a+.03),P2(RI,a+.03)],TOP-.3,TOP+1.05,{tower:true});const pm=P2(8.4,a);put(bars,nb++,pm[0],TOP+1.02,pm[1],0,-a,RO-RI+.2,.06,.06);}
  // observation deck
  const DR=TOWER.deckR,K=16;const deckPts=[];for(let k=0;k<K;k++)deckPts.push(P2(DR,k/K*TAU+a0));addSolidPts(deckPts,TOP-.4,TOP,{tower:true});
  const deck=new THREE.Mesh(new THREE.CylinderGeometry(DR,DR,.4,K),stoneM);deck.rotation.y=-a0;deck.position.set(cx,TOP-.2,cz);deck.castShadow=deck.receiveShadow=true;scene.add(deck);
  const gapC=TOWER.aE-dA*1.5;const angD=(x,y)=>Math.abs(Math.atan2(Math.sin(x-y),Math.cos(x-y)));
  for(let k=0;k<K;k++){const a1=k/K*TAU+a0,a2=(k+1)/K*TAU+a0,am=(a1+a2)/2;if(angD(am,gapC)<.42)continue;
    addSolidPts([P2(DR-.15,a1),P2(DR,a1),P2(DR,a2),P2(DR-.15,a2)],TOP-.3,TOP+1.1,{tower:true,rail:true});
    const p=P2(DR-.07,a1);put(posts,np++,p[0],TOP+.55,p[1],0,0,1,1.1,1);const pm=P2(DR-.07,am);put(bars,nb++,pm[0],TOP+1.08,pm[1],0,-am,.07,.07,2*DR*Math.sin(Math.PI/K)*1.02);}
  for(let k=0;k<8;k++){const a=k/8*TAU+a0+.2;const p=P2(DR-.45,a);put(cols,nc++,p[0],TOP+1.6,p[1],0,0,1,3.2,1);}
  for(const IM of [slab,posts,bars,cols]){IM.instanceMatrix.needsUpdate=true;scene.add(IM);}
  posts.count=np;bars.count=nb;cols.count=nc;
  const roof=new THREE.Mesh(new THREE.ConeGeometry(8.7,3.4,16),std('#2f6b4a',.6));roof.position.set(cx,TOP+3.2+1.7,cz);roof.rotation.y=-a0;roof.castShadow=true;scene.add(roof);
  const fas=new THREE.Mesh(new THREE.CylinderGeometry(8.75,8.75,.35,16,1,true),std('#c8102e',.5));fas.position.set(cx,TOP+3.25,cz);scene.add(fas);
  {const s=textPlane('百鳥塔 觀景台',2.4,.5,{bg:'#c8102e',fg:'#fff6d0'});const p=P2(9.7,a0-dA*1.4);s.position.set(p[0],TH(p[0],p[1])+2.4,p[1]);s.rotation.y=Math.atan2(Math.cos(a0),Math.sin(a0))+Math.PI;scene.add(s);
   const st=new THREE.Mesh(new THREE.CylinderGeometry(.05,.05,2.2,6),std('#333',.5));st.position.set(p[0],TH(p[0],p[1])+1.1,p[1]);scene.add(st);}
  // the spider
  const sp=new THREE.Group();const bk=std('#141414',.5),rd=std('#9a1010',.5);const ab=new THREE.Mesh(new THREE.SphereGeometry(.05,10,8),bk);ab.scale.set(1,.8,1.3);ab.position.z=-.05;const hd=new THREE.Mesh(new THREE.SphereGeometry(.032,8,6),bk);hd.position.z=.03;const dot=new THREE.Mesh(new THREE.SphereGeometry(.018,6,5),rd);dot.position.set(0,.035,-.06);sp.add(ab,hd,dot);
  const legs=[];for(let s of [-1,1])for(let k=0;k<4;k++){const l=new THREE.Mesh(new THREE.CylinderGeometry(.005,.005,.11,4),bk);l.rotation.z=s*1.1;l.position.set(s*.05,0,.02-k*.025);sp.add(l);legs.push(l);}
  sp.userData.legs=legs;const spA=gapC+Math.PI;const p=P2(DR-.07,spA);sp.position.set(p[0],TOP+1.12,p[1]);sp.scale.setScalar(1.4);scene.add(sp);TOWER.spider=sp;TOWER.spHome=sp.position.clone();}
function onDeck(){const c=TOWER.c,P=PLAYER;return c&&!P.car&&Math.hypot(P.x-c.x,P.z-c.z)<TOWER.deckR&&Math.abs((P.y||0)-TOWER_TOP_Y)<.7;}
function towerUpdate(dt){const sp=TOWER.spider;if(!sp)return;const has=!!(S.weapons&&S.weapons.web);sp.visible=!has||TOWER.stage===3;if(has&&TOWER.stage!==3){TOWER.on=0;return;}
  const t=performance.now()/1000;sp.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(t*14+i)*(TOWER.stage===1?.6:.08));
  if(TOWER.stage===3){TOWER.dT=(TOWER.dT||0)+dt;sp.position.y-=dt*.6;if(TOWER.dT>1.5){sp.visible=false;TOWER.stage=0;TOWER.dT=0;sp.position.copy(TOWER.spHome);}return;}
  if(onDeck()&&!dlgQ){TOWER.on+=dt;if(!TOWER.hinted&&TOWER.on>2){TOWER.hinted=true;toast('（欄杆上面好似有隻好細嘅蜘蛛仔……）');}}else{TOWER.on=0;if(TOWER.stage===1){TOWER.stage=0;sp.position.copy(TOWER.spHome);}}
  if(TOWER.on>22&&TOWER.stage===0)TOWER.stage=1;
  if(TOWER.stage===1){const P=PLAYER;const tgt=new THREE.Vector3(P.x,(P.y||0)+(TOWER.on>28?1.3:.05),P.z);const k=TOWER.on>28?2.2:1.0;sp.position.lerp(tgt,1-Math.exp(-k*dt));sp.lookAt(tgt.x,sp.position.y,tgt.z);
    if(TOWER.on>=30){TOWER.stage=2;spiderBite();}}}
function spiderBite(){const P=PLAYER;sfx('hurt');hurtPlayer(5);shake=.25;$('#hurt').style.opacity=.8;setTimeout(()=>$('#hurt').style.opacity=0,300);
  S.weapons.web=true;save();TOWER.stage=3;
  say([['旁白','（頸後面突然刺咗一下——隻蜘蛛仔咬咗你一啖！）'],['你','哎呀！咩嚟㗎……隻手好似有啲唔同咗……'],['旁白','你得到新武器：蜘蛛絲！'+(isMobile?'用「武器」掣轉做蜘蛛絲，再撳「打」：前面有人就射佢，冇人就向上射絲擺盪飛行。':'撳 Q 轉做蜘蛛絲，再撳 F：前面有人就射佢綁住，冇人就向上射絲擺盪飛行（半空可以連續擺）。')]],()=>{S.wpn=WEAPONS.findIndex(w=>w.id==='web');updateWeapon();});}

/* ======================================================================
   2. 高處跳落 + 尖叫；金朗大廈天台
   ====================================================================== */
const FALL={yelled:false};
function screamSfx(){if(!AU.ctx||AU.muted)return;const c=AU.ctx,t=c.currentTime;for(const [d,f0,f1,v] of [[0,780,1350,.05],[.1,980,1500,.035]]){const o=c.createOscillator();o.type='sawtooth';const g=c.createGain();const f=c.createBiquadFilter();f.type='bandpass';f.frequency.value=1400;f.Q.value=1.2;o.frequency.setValueAtTime(f0,t+d);o.frequency.linearRampToValueAtTime(f1,t+d+.35);o.frequency.linearRampToValueAtTime(f0*.8,t+d+1.1);g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(v,t+d+.06);g.gain.linearRampToValueAtTime(.0001,t+d+1.2);o.connect(f);f.connect(g);g.connect(AU.sfx);o.start(t+d);o.stop(t+d+1.3);}}
function fallScream(){const P=PLAYER;const fly=WEB.safe>0;let n=0;
  for(const p of peds){if(!p.g.visible||p.down>0)continue;const d=Math.hypot(p.g.position.x-P.x,p.g.position.z-P.z);if(d<45&&n<5){n++;if(!fly)p.flee=6;}}
  const camp=inCamp(P.x,P.z,8);if(!n&&!camp)return;
  subtitle(camp?'同學':'途人',fly?pick(['嘩！係咪蜘蛛俠呀？！','佢喺度飛呀！快啲影相！','嘩……好型呀！']):pick(['呀————！！有人跳落嚟呀！','救命呀！有人跌落嚟呀！','呀！！！小心呀！']));
  if(!fly)screamSfx();if(camp&&!fly)schoolScare();}
