WEAPONS.push({id:'web',name:'蜘蛛絲',dmg:26,range:28,cd:.45,web:true});
const WEB={fly:0,safe:0,vx:0,vz:0,anchor:null,lineT:0,line:null,shots:[]};
{const _sw=setupWeapons;setupWeapons=function(){_sw();const g=new THREE.Group();g.position.y=-.6;const b=new THREE.Mesh(new THREE.CylinderGeometry(.062,.062,.06,10),std('#f4f4f0',.6));g.add(b);const s=new THREE.Mesh(new THREE.BoxGeometry(.02,.02,.08),std('#c8102e',.5));s.position.set(0,-.04,.05);g.add(s);g.visible=false;PLAYER.p.arms[1].add(g);wpnMeshes.web=g;};}
function webLine(){if(!WEB.line){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(new Float32Array(6),3));WEB.line=new THREE.Line(geo,new THREE.LineBasicMaterial({color:0xf4f4f0,transparent:true,opacity:.9,toneMapped:false}));WEB.line.frustumCulled=false;scene.add(WEB.line);}return WEB.line;}
function handPos(){const P=PLAYER;return {x:P.x+Math.sin(P.h)*.25,y:(P.y||0)+1.45,z:P.z+Math.cos(P.h)*.25};}
function allTargets(){return [...FIGHT.filter(f=>f.hp>0),...COPS.filter(c=>c.down<=0),...peds.filter(p=>!(p.down>0)&&p.g.visible),...extraTargets()];}
function webAttack(){const P=PLAYER;if(dlgQ||modal||busy||P.car||!started||mapOpen||P.dress||P.seated)return;if(atkCd>0)return;
  if(curRoom||P.ind){toast('室內用唔到蜘蛛絲');return;}atkCd=.45;
  const fx=Math.sin(P.h),fz=Math.cos(P.h);let tgt=null,td=28;
  if(P.grounded!==false){for(const t of allTargets()){const q=t.g.position;const dx=q.x-P.x,dz=q.z-P.z,d=Math.hypot(dx,dz);if(d>td||d<.5)continue;if((dx*fx+dz*fz)/d<.72)continue;if(Math.abs(q.y-(P.y||0))>6)continue;td=d;tgt=t;}}
  sfx('swing',.7);noiseHitSafe(.12,.18,4200);
  if(tgt){const q=tgt.g.position;P.h=Math.atan2(q.x-P.x,q.z-P.z);WEB.shots.push({t:0,tgt,hit:false});return;}
  // swing: shoot a strand up and forward, get yanked along it
  let dx=fx,dz=fz;if(inp.x||inp.y){const cx=-Math.sin(cam.yaw),cz=-Math.cos(cam.yaw),rx=Math.cos(cam.yaw),rz=-Math.sin(cam.yaw);dx=cx*inp.y+rx*inp.x;dz=cz*inp.y+rz*inp.x;const l=Math.hypot(dx,dz)||1;dx/=l;dz/=l;}
  const c=ceilAt(P.x,P.z,P.y||0);if(c!=null&&c-(P.y||0)<6){toast('上面有嘢擋住，射唔到絲');return;}
  P.h=Math.atan2(dx,dz);WEB.anchor={x:P.x+dx*16,y:(P.y||0)+20,z:P.z+dz*16};WEB.lineT=.6;
  P.vy=Math.max(P.vy||0,P.grounded===false?11:13.5);P.grounded=false;P.jumps=2;P.peak=P.y||0;WEB.vx=dx*17;WEB.vz=dz*17;WEB.fly=1.5;WEB.safe=3.2;}
function noiseHitSafe(dur,vol,f){if(!AU.ctx||AU.muted)return;noiseHit(AU.ctx.currentTime,dur,vol,f,'highpass',AU.sfx);}
function cocoon(t,on){if(on){if(!t.cocoon){const m=new THREE.Mesh(new THREE.SphereGeometry(.5,12,10),new THREE.MeshStandardMaterial({color:lin('#f4f4f0'),roughness:.9,transparent:true,opacity:.82}));m.scale.set(.75,1.35,.75);m.position.y=.95;t.g.add(m);t.cocoon=m;}}else if(t.cocoon){t.g.remove(t.cocoon);t.cocoon=null;}}
function webUpdate(dt){const P=PLAYER;if(WEB.safe>0){WEB.safe-=dt;if(P.grounded===false)P.peak=P.y||0;}
  const L=webLine();let show=false;
  if(WEB.lineT>0&&WEB.anchor){WEB.lineT-=dt;const h=handPos(),a=WEB.anchor;L.geometry.attributes.position.array.set([h.x,h.y,h.z,a.x,a.y,a.z]);show=true;}
  for(let i=WEB.shots.length-1;i>=0;i--){const s=WEB.shots[i];s.t+=dt;const q=s.tgt.g.position;const h=handPos();const u=Math.min(1,s.t/.14);
    L.geometry.attributes.position.array.set([h.x,h.y,h.z,h.x+(q.x-h.x)*u,h.y+(q.y+1.1-h.y)*u,h.z+(q.z-h.z)*u]);show=true;
    if(!s.hit&&u>=1){s.hit=true;hitTarget(s.tgt,26);hitFx(q.x,q.y+1.2,q.z,'jab');if(!s.tgt.isJesus){s.tgt.webT=3.5;cocoon(s.tgt,true);}}
    if(s.t>.32)WEB.shots.splice(i,1);}
  L.visible=show;if(show)L.geometry.attributes.position.needsUpdate=true;
  if(WEB.fly>0&&P.car)WEB.fly=0;
  for(const c of COPS)if(c.webT>0){c.webT-=dt;if(c.webT<=0)cocoon(c,false);}}
{const _ws=walkStep;walkStep=function(dt){_ws(dt);const p=PLAYER;if(WEB.fly>0){WEB.fly-=dt;p.x+=WEB.vx*dt;p.z+=WEB.vz*dt;const k=Math.exp(-.6*dt);WEB.vx*=k;WEB.vz*=k;pushOut(p,.35,p.y||0,0);edgeClamp(p,false);if(p.grounded&&WEB.fly<.7)WEB.fly=0;}};}
{const _at=attack;attack=function(){const w=WEAPONS[S.wpn];if(w&&w.web){webAttack();return;}return _at();};}
{const _pp=playerPose;playerPose=function(dt){_pp(dt);const P=PLAYER;if(!P.p||P.car)return;if(WST.on){const u=Math.min(1,WST.t/.8);P.p.b.rotation.x=-1.5*u;P.p.b.position.y=.22*u;for(const a of P.p.arms)a.rotation.x=-.4*u;return;}
  if(WEB.lineT>0||WEB.shots.length)P.p.arms[1].rotation.x=WEB.lineT>0?-2.9:-1.6;};}
/* everything that can be stuck in a web stays put */
{const _pu=pedUpdate;pedUpdate=function(p,dt){if(p.webT>0){p.webT-=dt;if(p.webT<=0)cocoon(p,false);return;}if(p.br)return;return _pu(p,dt);};}
{const _fu=fightUpdate;fightUpdate=function(dt){const keep=FIGHT.filter(f=>f.webT>0).map(f=>[f,f.g.position.x,f.g.position.z,f.cd]);_fu(dt);for(const [f,x,z,cd] of keep){f.webT-=dt;f.g.position.x=x;f.g.position.z=z;f.cd=Math.max(f.cd,.6);if(f.webT<=0)cocoon(f,false);}};}

