  const t=textPlane('消防處 FIRE',2.2,.42,{bg:'#c8161d',fg:'#ffd23f'});for(const s of [-1,1]){const tt=t.clone();tt.position.set(s*(W/2+.04),2.6,L/2-1.1);tt.rotation.y=s*Math.PI/2;body.add(tt);}
  const bar=lightBar(body,0,2.72,L/2-1.1,1.6);const wheels=[];for(const [x,z] of [[W/2-.2,2.6],[-W/2+.2,2.6],[W/2-.2,-1.6],[-W/2+.2,-1.6],[W/2-.2,-2.9],[-W/2+.2,-2.9]]){const w=wheel(wr,.34);w.position.set(x,wr,z);g.add(w);w.userData.front=z>0;wheels.push(w);}
