function lightBar(body,x,y,z,w){const r=new THREE.Mesh(new THREE.BoxGeometry(w/2,.14,.28),new THREE.MeshBasicMaterial({color:0xff2a2a,toneMapped:false}));const b=new THREE.Mesh(new THREE.BoxGeometry(w/2,.14,.28),new THREE.MeshBasicMaterial({color:0x2a6aff,toneMapped:false}));r.position.set(x-w/4,y,z);b.position.set(x+w/4,y,z);body.add(r,b);return [r,b];}
const EMS={list:[],sir:null};
function addVeh(m,type,x,z,h,o){scene.add(m.g);const v=Object.assign({type,g:m.g,body:m.body,wheels:m.wheels,L:m.L,W:m.W,wr:m.wr,x,z,h,speed:0,vx:0,vz:0,steer:0,y:TH(x,z),roll:0,pitch:0,spin:0,flash:m.flash,nozzle:m.nozzle},o||{});syncV(v);vehicles.push(v);return v;}
function rmVeh(v){if(!v)return;scene.remove(v.g);const i=vehicles.indexOf(v);if(i>=0)vehicles.splice(i,1);const j=EMS.list.indexOf(v);if(j>=0)EMS.list.splice(j,1);}
/* drive v along road r towards sStop, starting `back` metres before it */
function routeOn(v,r,sStop,back,cruise){let dir=1,s0=sStop-back;if(r.oneway){s0=Math.max(0,sStop-back);}else if(s0<0){if(sStop+back<=r.len){dir=-1;s0=sStop+back;}else{s0=sStop>r.len/2?0:r.len;dir=s0<sStop?1:-1;}}
  v.script={r,s:s0,dir,stop:sStop,cruise,sp:cruise*.8,lane:r.oneway?(r.w>8?r.w/5:0):r.w/4,arrived:false,leave:false};moverStep(v,0);}
function moverStep(v,dt){const m=v.script;if(!m)return;const rem=(m.stop-m.s)*m.dir;let want=m.cruise;if(!m.leave&&!m.ram&&rem<18)want=Math.max(0,Math.min(want,rem*.85));m.sp=lerp(m.sp,want,1-Math.exp(-2.2*dt));
  m.s+=m.dir*m.sp*dt;if(!m.leave&&(m.stop-m.s)*m.dir<=.25){if(!m.ram){m.s=m.stop;m.sp=0;}m.arrived=true;}
  if(m.leave&&(m.s<0||m.s>m.r.len)){m.gone=true;m.s=clamp(m.s,0,m.r.len);}
  const p=posOn(m.r,m.s);const fx=p.dx*m.dir,fz=p.dz*m.dir;v.x=p.x+fz*m.lane;v.z=p.z-fx*m.lane;v.h=Math.atan2(fx,fz);v.y=TH(v.x,v.z);v.vx=v.vz=0;v.speed=m.sp;v.spin+=m.sp/v.wr*dt;}
function emsSpawn(kind,ev,x,z){const nr=nearestRoad(x,z,90,r=>r.cls<=5&&r.len>25);if(!nr)return null;const r=nr.r;const sStop=r.cum[nr.seg-1]+nr.t*Math.hypot(r.pts[nr.seg][0]-r.pts[nr.seg-1][0],r.pts[nr.seg][1]-r.pts[nr.seg-1][1]);
  const m=emsModel(kind);const v=addVeh(m,kind==='amb'?'ambulance':'firetruck',0,0,0,{ems:kind,ev});routeOn(v,r,sStop,90,kind==='amb'?13:11);EMS.list.push(v);return v;}
function emsLeave(v){if(!v||!v.script)return;const m=v.script;m.leave=true;m.arrived=false;m.cruise=12;m.stop=m.dir>0?m.r.len+50:-50;}
function emsUpdate(dt){const t=performance.now()/1000;let nd=1e9;
  for(const v of [...EMS.list]){moverStep(v,dt);syncV(v);const on=!v.script||!v.script.leave||camDist(v.x,v.z)<120;if(v.flash){const k=Math.floor(t*4)%2;v.flash[0].visible=k===0;v.flash[1].visible=k===1;}
    if(v.script&&v.script.sir!==false&&!(v.script.arrived&&v.script.quiet))nd=Math.min(nd,camDist(v.x,v.z));
    if(v.script&&v.script.leave&&(v.script.gone||camDist(v.x,v.z)>260))rmVeh(v);}
  emsSiren(nd,t);}
function emsSiren(d,t){if(!AU.ctx||AU.muted){return;}const vol=d<1e8?.03*clamp(1-d/240,0,1):0;
  if(vol<=0){if(EMS.sir){EMS.sir.g.gain.setTargetAtTime(0,AU.ctx.currentTime,.2);}return;}
  if(!EMS.sir){const c=AU.ctx;const o=c.createOscillator();o.type='triangle';const g=c.createGain();g.gain.value=0;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=2400;o.connect(f);f.connect(g);g.connect(AU.sfx);o.start();EMS.sir={o,g};}
  const c=AU.ctx;EMS.sir.o.frequency.setTargetAtTime(Math.floor(t*1.6)%2?960:700,c.currentTime,.02);EMS.sir.g.gain.setTargetAtTime(vol,c.currentTime,.15);}
{const _nc=nearCar;nearCar=function(){const v=_nc();if(v&&(v.ems||v.script||v.crashCar))return null;return v;};}

/* ======================================================================
   6. 城市隨機事件
   ====================================================================== */
const CR={ev:[],t:8,id:0,track:null,beam:null,P:{rob:.03,gang:.03,hit:.02,fire:.01},done:0};
const CR_INFO={rob:{n:'打劫',ic:'🔪',crime:true},gang:{n:'黑社會打人',ic:'👊',crime:true},hit:{n:'交通意外',ic:'🚑'},fire:{n:'大廈火警',ic:'🔥'}};
const LOOK_TRIAD=()=>({shirt:pick(['#111','#1d1d1d','#3a3a3a','#4a1010','#f4f4f0']),pants:pick(['#111','#222','#2b3550']),hair:pick(['#c8a032','#111','#6b3a1a'])});
const LOOK_CIV=()=>({shirt:pick(['#f4f4f0','#2b3a55','#c0392b','#e8d6b0','#3c6e47','#8e44ad','#f1c40f']),pants:pick(['#2b3550','#222','#5d4b3a','#3a4152']),long:rnd()<.4,bag:rnd()<.5?pick(['#c0392b','#1d4fa0','#333']):null});
function crimeAllowed(){return started&&!S.dead&&S.m!==0&&!FIGHT.length&&!(J&&J.on);}
function crSpot(minD,maxD){const P=PLAYER;for(let k=0;k<12;k++){const rs=pickRoadNear(P.x,P.z,minD,maxD);if(!rs)return null;const [r,s]=rs;const q=posOn(r,s);const side=rnd()<.5?1:-1;const off=r.w/2+1.8;const x=q.x-q.dz*off*side,z=q.z+q.dx*off*side;
    if(inCamp(x,z,6)||!inWB(x,z,30)||solidAt(x,1,z)||inWater(x,z))continue;return {r,s,q,x,z,side};}return null;}
function crNew(type){const sp=type==='fire'?null:crSpot(type==='hit'?70:90,380);if(type!=='fire'&&!sp)return null;
  const e={id:++CR.id,type,t:0,state:'start',ents:[],veh:[],fx:[],done:false,res:null,ok:null};if(sp){Object.assign(e,sp);e.road=ri_tagName(sp.r);}
  if(type==='rob')crRob(e);else if(type==='gang')crGang(e);else if(type==='hit')crHit(e);else if(!crFire(e))return null;
  CR.ev.push(e);if(phoneOpen())phoneShow('news');return e;}
function crMk(e,look,x,z,o){const p=mkPerson(look,x,z,o&&o.tag,o&&o.col);Object.assign(p,o||{});p.ev=e;e.ents.push(p);return p;}
/* --- 打劫 --- */
function crRob(e){const vx=e.x,vz=e.z;const a=R(0,TAU);e.victim=crMk(e,LOOK_CIV(),vx,vz,{name:'途人'});
  const k=rnd()<.65;e.robber=crMk(e,{shirt:'#1d1d1d',pants:'#111',hair:'#111'},vx+Math.sin(a)*1.3,vz+Math.cos(a)*1.3,{crim:true,hp:70,max:70,kind:k?'knife':'triad',name:'劫匪',tag:'劫匪'});if(k)knifeMesh(e.robber);
  e.state='rob';e.news=`${e.road}：有途人俾人${k?'揸刀':''}打劫！`;}
/* --- 黑社會打人 --- */
function crGang(e){e.victim=crMk(e,LOOK_CIV(),e.x,e.z,{name:'途人'});const n=3+Math.floor(rnd()*3);e.gang=[];
  for(let i=0;i<n;i++){const a=i/n*TAU+R(-.2,.2);const k=rnd()<.3;const g=crMk(e,LOOK_TRIAD(),e.x+Math.sin(a)*1.25,e.z+Math.cos(a)*1.25,{crim:true,hp:60,max:60,kind:k?'knife':'triad',name:'古惑仔',tag:i===0?'古惑仔':null,ang:a});if(k)knifeMesh(g);e.gang.push(g);}
  e.state='beat';e.news=`${e.road}：有人俾${n}個黑社會圍毆！`;}
/* --- 車撞人 --- */
function crHit(e){const r=e.r;const near=Math.hypot(e.q.x-PLAYER.x,e.q.z-PLAYER.z)<150;
  const col=pick(['#d9dcdf','#1d2a3a','#7a1f2b','#e7e3da','#3b3f46']);const car=addVeh(vehicleModel3('car',col),'car',0,0,0,{crashCar:true});e.veh.push(car);
  routeOn(car,r,e.s,near?42:1,near?15:1);car.script.quiet=true;car.script.sir=false;car.script.ram=true;const m0=car.script,lq=posOn(r,e.s);const lfx=lq.dx*m0.dir,lfz=lq.dz*m0.dir;
  e.victim=crMk(e,LOOK_CIV(),lq.x+lfz*m0.lane,lq.z-lfx*m0.lane,{name:'途人'});
  if(!near){car.script.s=car.script.stop;moverStep(car,0);e.state='after';crDown(e);e.t=0;}else{e.state='incoming';e.victim.g.rotation.y=Math.atan2(-e.q.dz,e.q.dx);}
  e.news=`${e.road}：發生交通意外，有途人俾車撞倒，救護車趕往現場。`;}
function crDown(e){const v=e.victim;v.g.rotation.x=-Math.PI/2;v.g.position.y=TH(v.g.position.x,v.g.position.z)+.15;blood(v.g.position.x,.3,v.g.position.z,8);
  for(let i=0;i<2+Math.floor(rnd()*2);i++){const a=R(0,TAU);const o=crMk(e,LOOK_CIV(),v.g.position.x+Math.sin(a)*2.6,v.g.position.z+Math.cos(a)*2.6,{name:'途人',look:true});o.g.rotation.y=a+Math.PI;}}
/* --- 火警 --- */
function crFire(e){const P=PLAYER;for(let k=0;k<20;k++){const rs=pickRoadNear(P.x,P.z,90,420);if(!rs)return false;const [r,s]=rs;const q=posOn(r,s);
    for(const b of queryB(q.x,q.z,26)){if(b.flag||b.nomap||b.soft||!b.pts||b.h<9||b.h>85||Math.abs(b.area)<60||inCamp((b.x0+b.x1)/2,(b.z0+b.z1)/2,10))continue;const f=edgeToward(b,q.x,q.z);if(!f||Math.hypot(f.x-q.x,f.z-q.z)>22)continue;
      e.b=b;e.r=r;e.s=s;e.q=q;e.x=f.x+f.nx*.4;e.z=f.z+f.nz*.4;e.road=ri_tagName(r);e.face=f;e.spots=[];const hs=[.4,.55,.7].map(u=>b.base+b.h*u);for(let i=0;i<3;i++){const along=R(-.3,.3)*Math.min(8,f.L);e.spots.push({x:f.x+f.ax*along+f.nx*.35,y:hs[i],z:f.z+f.az*along+f.nz*.35,k:1});}
      e.state='burn';e.news=`${e.road}：有大廈起火，消防車趕往現場。`;return true;}}return false;}
function crEnd(e,ok){if(e.done)return;e.done=true;e.ok=ok;e.endT=0;if(CR.track===e)crTrack(null);}
function crReward(e){const n=Math.round(R(500,1500)/10)*10;addMoney(n,true);gainXP(60,'打擊罪案');CR.done++;sfx('gold');toast(`🚔 打擊罪案成功！ +$${n}　+60 XP`);}
function crCleanup(e){for(const p of e.ents){BRAWL.delete(p);rmPerson(p);}for(const v of e.veh)rmVeh(v);if(e.light)scene.remove(e.light);if(e.amb)rmVeh(e.amb);if(e.truck)rmVeh(e.truck);for(const p of e.crew||[])rmPerson(p);CR.ev.splice(CR.ev.indexOf(e),1);}
function crUpdate(dt){CR.t-=dt;if(CR.t<=0){CR.t=15;if(crimeAllowed()&&CR.ev.filter(e=>!e.done).length<3){for(const k of ['rob','gang','hit','fire'])if(rnd()<CR.P[k]&&!CR.ev.some(e=>e.type===k&&!e.done)){crNew(k);break;}}}
  const P=PLAYER;for(const e of [...CR.ev]){e.t+=dt;const d=Math.hypot((e.x||0)-P.x,(e.z||0)-P.z);
    if(e.type==='rob')robUpdate(e,dt,d);else if(e.type==='gang')gangUpdate(e,dt,d);else if(e.type==='hit')hitUpdate(e,dt,d);else fireUpdate(e,dt,d);
    if(e.done){e.endT+=dt;const far=d>150&&camDist(e.x,e.z)>150;if((e.endT>40&&far)||e.endT>150||(e.type!=='fire'&&e.endT>25&&far&&!e.amb))crCleanup(e);}
    else if(e.t>300&&d>200)crCleanup(e);}
  if(CR.track)crTrackUpdate();}
function robUpdate(e,dt,d){const v=e.victim,rb=e.robber;if(e.done){if(!e.thanked&&v){v.g.rotation.y=Math.atan2(PLAYER.x-v.g.position.x,PLAYER.z-v.g.position.z);}return;}
  if(rb.hp<=0||rb.down>0){crEnd(e,true);crReward(e);e.thanked=true;subtitle('途人','多謝你呀！好人有好報！');v.arms[0].rotation.x=v.arms[1].rotation.x=0;return;}
  const t=performance.now()/1000;
  if(e.state==='rob'){v.arms[0].rotation.x=v.arms[1].rotation.x=-2.8+Math.sin(t*6)*.1;rb.g.rotation.y=Math.atan2(v.g.position.x-rb.g.position.x,v.g.position.z-rb.g.position.z);rb.arms[1].rotation.x=-1.4+Math.sin(t*3)*.15;
    if(d<38&&!e.yelled){e.yelled=true;subtitle('途人','救命呀！有人搶嘢呀！');}
    if(d<20&&!rb.br){e.state='flee';rb.arms[1].rotation.x=0;v.arms[0].rotation.x=0;v.arms[1].rotation.x=-2.6;subtitle('劫匪','有人嚟！走呀！');}}
  else if(e.state==='flee'&&!rb.br&&!(rb.webT>0)){const P=PLAYER;let dx=rb.g.position.x-P.x,dz=rb.g.position.z-P.z;const dd=Math.hypot(dx,dz)||1;dx/=dd;dz/=dd;const w=Math.sin(e.t*.7)*.5;const fx=dx*Math.cos(w)-dz*Math.sin(w),fz=dx*Math.sin(w)+dz*Math.cos(w);
    const o={x:rb.g.position.x+fx*6.3*dt,z:rb.g.position.z+fz*6.3*dt};const h=pushOut(o,.4,0,.45);if(h){o.x+=h.nz*6*dt;o.z-=h.nx*6*dt;}if(!inWB(o.x,o.z,10)){o.x=rb.g.position.x;o.z=rb.g.position.z;}
    rb.g.position.set(o.x,TH(o.x,o.z)+.02,o.z);rb.g.rotation.y=Math.atan2(fx,fz);animP(rb,6.3,dt);
    if(dd>95){e.lostT=(e.lostT||0)+dt;if(e.lostT>4){crEnd(e,false);toast('劫匪走甩咗……');}}else e.lostT=0;}
  if(rb.webT>0&&!rb.br){rb.webT-=dt;if(rb.webT<=0)cocoon(rb,false);}}
function gangUpdate(e,dt,d){const v=e.victim;const t=performance.now()/1000;
  if(e.done){return;}
  const alive=e.gang.filter(g=>g.hp>0&&!(g.down>0));
  if(!alive.length){crEnd(e,true);crReward(e);subtitle('途人','咳……多謝你……救命恩人……');e.amb=emsSpawn('amb',e,v.g.position.x,v.g.position.z);e.state='wait';return;}
  if(e.state==='beat'){v.b.rotation.x=.9;v.b.position.y=-.35;v.arms[0].rotation.x=v.arms[1].rotation.x=-2.2;
    for(const g of e.gang){if(g.br||g.webT>0)continue;g.g.rotation.y=Math.atan2(v.g.position.x-g.g.position.x,v.g.position.z-g.g.position.z);const k=Math.sin(t*7+g.ang*3);g.legs[0].rotation.x=k>.6?-1.1:0;g.arms[1].rotation.x=k<-.6?-1.5:0;}
    if(d<38&&!e.yelled){e.yelled=true;subtitle('途人','救命呀……唔好再打喇……');}
    if(d<16||e.gang.some(g=>g.hp<g.max)){e.state='fight';for(const g of e.gang){g.legs[0].rotation.x=0;brawlStart(g,g.kind);g.br.t=60;}}}
  else if(e.state==='fight'){for(const g of alive){if(g.br)g.br.t=Math.max(g.br.t,20);else if(!(g.webT>0))brawlStart(g,g.kind);}if(d>140){e.state='beat';for(const g of e.gang){BRAWL.delete(g);g.br=null;}}}}
function hitUpdate(e,dt,d){const car=e.veh[0],v=e.victim;
  if(e.state==='incoming'){moverStep(car,dt);const m=car.script;const vx=v.g.position.x,vz=v.g.position.z;const cd=Math.hypot(car.x-vx,car.z-vz);
    if(cd<2.4||m.arrived){sfx('crash',.8);e.state='fly';e.vy=6;e.vx=Math.sin(car.h)*9;e.vz=Math.cos(car.h)*9;m.ram=false;m.arrived=false;m.cruise=6;m.stop=clamp(m.s+m.dir*9,0,m.r.len);subtitle('途人','呀————！撞到人呀！');}
    else{animP(v,0,dt);}}
  else if(e.state==='fly'){moverStep(car,dt);const g=v.g.position;e.vy-=22*dt;g.x+=e.vx*dt;g.z+=e.vz*dt;g.y+=e.vy*dt;v.g.rotation.x-=dt*9;e.vx*=Math.exp(-1.5*dt);e.vz*=Math.exp(-1.5*dt);
    const gy=TH(g.x,g.z);if(g.y<=gy&&e.vy<0){e.state='after';e.t=0;crDown(e);}}
  else if(e.state==='after'){if(e.t>5&&!e.amb){e.amb=emsSpawn('amb',e,v.g.position.x,v.g.position.z);}}
  if(e.amb)ambLoad(e,dt);
  for(const p of e.ents)if(p.look){p.g.rotation.y=Math.atan2(v.g.position.x-p.g.position.x,v.g.position.z-p.g.position.z);}}
/* ambulance at the scene: paramedics come out, take the patient, drive off */
function ambLoad(e,dt){const a=e.amb,v=e.victim;if(!a||!a.script)return;
  if(a.script.arrived&&!e.loadT){e.loadT=.001;a.script.quiet=true;e.crew=[];for(const s of [-1,1]){const p=mkPerson({shirt:'#e8eef0',pants:'#1f4d3a',hair:'#111'},v.g.position.x+s*1.1,v.g.position.z+.8,'救護員','#7dffb0');e.crew.push(p);}}
  if(e.loadT){e.loadT+=dt;for(const p of e.crew||[]){p.g.rotation.y=Math.atan2(v.g.position.x-p.g.position.x,v.g.position.z-p.g.position.z);p.arms[0].rotation.x=p.arms[1].rotation.x=-1+Math.sin(e.loadT*4)*.2;}
    if(e.loadT>6&&v.g.visible){v.g.visible=false;for(const p of e.crew||[])rmPerson(p);e.crew=[];a.script.quiet=false;emsLeave(a);if(e.type==='hit'){crEnd(e,null);}for(const p of e.ents)if(p.look)p.look=false;}}}
function fireUpdate(e,dt,d){const t=performance.now()/1000;e.acc=(e.acc||0)+dt;const vis=camDist(e.x,e.z)<260;
  const k=e.state==='burn'?1:e.state==='spray'?Math.max(0,1-e.sprayT/16):0;
  if(vis&&e.acc>.05){e.acc=0;for(const s of e.spots){if(k>0){flame(s.x,s.y,s.z,1.1*k);if(rnd()<.5)flame(s.x,s.y+.8,s.z,.7*k);}if(rnd()<(k>0?.8:.3))smokePuff(s.x,s.y+1.2,s.z,k>0,1.3);}}
  if(e.state==='burn'){if(d<45&&!e.yelled){e.yelled=true;subtitle('途人','火燭呀！快啲走呀！');}if(e.t>16&&!e.truck){e.truck=emsSpawn('fire',e,e.q.x,e.q.z);if(!e.truck){e.state='out';e.outT=0;}}
    if(e.truck&&e.truck.script.arrived){e.state='spray';e.sprayT=0;e.truck.script.quiet=true;e.crew=[];const tr=e.truck;for(const s of [-1,1]){const p=mkPerson({shirt:'#2b2b2b',pants:'#2b2b2b',hair:'#111'},tr.x+Math.cos(tr.h)*s*2,tr.z-Math.sin(tr.h)*s*2,'消防員','#ffd23f');const hat=new THREE.Mesh(new THREE.SphereGeometry(.19,10,8,0,TAU,0,Math.PI/2),std('#f2c300',.4));hat.position.y=1.72;p.b.add(hat);e.crew.push(p);}}}
  else if(e.state==='spray'){e.sprayT+=dt;const tr=e.truck;const s=e.spots[Math.floor(t*1.3)%e.spots.length];
    for(const p of e.crew){p.g.rotation.y=Math.atan2(e.x-p.g.position.x,e.z-p.g.position.z);p.arms[0].rotation.x=p.arms[1].rotation.x=-1.4;}
    if(vis){const nz=new THREE.Vector3(0,3.3,-2).applyAxisAngle(new THREE.Vector3(0,1,0),tr.h).add(new THREE.Vector3(tr.x,tr.y,tr.z));for(let i=0;i<3;i++){const tt=R(.7,1.0);emit(PSN,{x:nz.x,y:nz.y,z:nz.z,vx:(s.x-nz.x)/tt+R(-.6,.6),vy:(s.y-nz.y)/tt+11*tt*.5,vz:(s.z-nz.z)/tt+R(-.6,.6),life:tt,s0:.18,s1:.5,r:.75,g:.85,b:1,a:.65,grav:11});}}
    if(e.sprayT>18){e.state='out';e.outT=0;}}
  else if(e.state==='out'){e.outT+=dt;if(e.outT>4&&e.crew){for(const p of e.crew)rmPerson(p);e.crew=null;if(e.truck)emsLeave(e.truck);crEnd(e,null);}if(!e.truck&&e.outT>40)crEnd(e,null);}
  if(e.state==='burn'&&!e.truck&&d>420&&e.t>120){e.state='out';e.outT=0;}}
function crimHit(t,dmg){if(t.hp<=0)return;t.hp-=dmg;blood(t.g.position.x,t.g.position.y+1.3,t.g.position.z,dmg>30?8:5);sfx('hit');const dx=t.g.position.x-PLAYER.x,dz=t.g.position.z-PLAYER.z,d=Math.hypot(dx,dz)||1;t.kx=dx/d*3;t.kz=dz/d*3;
  if(t.hp<=0){t.down=999;BRAWL.delete(t);t.br=null;t.g.rotation.x=-Math.PI/2;t.g.position.y=TH(t.g.position.x,t.g.position.z)+.2;cocoon(t,false);gainXP(12);if(rnd()<.6)dropCash(t.g.position.x,t.g.position.z,Math.round(R(10,60)));return;}
  if(!t.br&&!(t.webT>0))brawlStart(t,t.kind||'triad');else if(t.br)t.br.t=Math.max(t.br.t,20);}
/* track one crime with a red beam + distance chip */
function crTrack(e){CR.track=e;if(CR.beam){scene.remove(CR.beam);CR.beam=null;}const chip=$('#crimeChip');if(!e){chip.hidden=true;return;}
  const g=new THREE.Group();const c=new THREE.Mesh(new THREE.CylinderGeometry(1.2,1.2,60,16,1,true),new THREE.MeshBasicMaterial({color:0xff3b3b,transparent:true,opacity:.25,depthWrite:false,side:THREE.DoubleSide,toneMapped:false}));c.position.y=30;g.add(c);scene.add(g);CR.beam=g;chip.hidden=false;crTrackUpdate();}
function crTrackUpdate(){const e=CR.track;if(!e||e.done){crTrack(null);return;}const tgt=e.type==='rob'&&e.robber?e.robber.g.position:{x:e.x,z:e.z};CR.beam.position.set(tgt.x,TH(tgt.x,tgt.z),tgt.z);
  const d=Math.round(Math.hypot(tgt.x-PLAYER.x,tgt.z-PLAYER.z));const txt=`${CR_INFO[e.type].ic} ${CR_INFO[e.type].n}・${d} 米`;const el=$('#crimeChip');if(el.textContent!==txt)el.textContent=txt;}

/* ======================================================================
   7. 手提電話：老竇、新聞
   ====================================================================== */
const DAD={state:null,t:0,kind:null,veh:null,npc:null,walkT:0};
function phoneOpen(){return modal==='phone';}
function phoneBtnOK(){return started&&!S.dead&&!dlgQ&&!busy&&!mapOpen&&!PLAYER.dress&&!PLAYER.dance&&(!modal||modal==='phone');}
function togglePhone(){if(phoneOpen()){closeModal();return;}if(!phoneBtnOK()||modal)return;sfx('ding',.5);phoneShow('home');}
function phoneShell(inner,title){const hh=String(Math.floor(gameMin/60)%24).padStart(2,'0')+':'+String(Math.floor(gameMin%60)).padStart(2,'0');
  return `<div class="ph"><div class="phTop"><span>${hh}</span><span>元朗電訊 ▂▄▆█</span></div>${title?`<div class="phHd"><button class="phBack" data-go="home">‹</button><b>${title}</b><span></span></div>`:''}<div class="phScr">${inner}</div><button class="phHome" data-go="close" aria-label="收埋電話"></button></div>`;}
function phoneShow(scr){let html='';
  if(scr==='home'){const nCrime=CR.ev.filter(e=>!e.done).length;html=phoneShell(`<div class="phWall"><div class="phClock">${String(Math.floor(gameMin/60)%24).padStart(2,'0')}:${String(Math.floor(gameMin%60)).padStart(2,'0')}</div><div class="phDate">元朗・今日</div></div>
      <div class="phApps"><button class="phApp" data-go="dad"><i style="background:#2ecc71">📞</i><span>打俾老竇</span></button><button class="phApp" data-go="news"><i style="background:#e8432e">📰</i><span>即時新聞</span>${nCrime?`<em>${nCrime}</em>`:''}</button><button class="phApp" data-go="map"><i style="background:#2e86de">🗺</i><span>地圖</span></button><button class="phApp" data-go="close"><i style="background:#555">✕</i><span>收埋</span></button></div>
      <div class="phTip">打擊罪案已經 ${CR.done} 次</div>`);}
  else if(scr==='dad'){const busyDad=!!DAD.state;html=phoneShell(busyDad?`<div class="phCall"><div class="phAv">👨</div><b>老竇</b><p>${DAD.state==='coming'?'喺路上，仲有 '+Math.max(1,Math.ceil(DAD.t))+' 秒到':'已經送咗車俾你'}</p></div>`:
      `<div class="phCall"><div class="phAv">👨</div><b>老竇</b><p>要老竇送咩嚟？30 秒內到</p></div><div class="phOpts"><button class="phBtn" data-dad="ev">🚗 電動車<small>白色、靜、快</small></button><button class="phBtn" data-dad="bike">🚲 單車<small>可以跳、玩花式</small></button></div>`,'打俾老竇');}
  else if(scr==='news'){const L=CR.ev.slice().sort((a,b)=>a.done-b.done||b.id-a.id);const P=PLAYER;
    const items=L.map(e=>{const I=CR_INFO[e.type];const d=Math.round(Math.hypot((e.x||0)-P.x,(e.z||0)-P.z));const st=e.done?(e.ok===true?'✅ 已解決':e.ok===false?'❌ 疑犯逃去':'✔ 已處理'):'🔴 進行中';
      return `<div class="phNews${e.done?' old':''}"><div class="nh"><span>${I.ic} ${I.n}</span><span>${st}</span></div><p>${e.news}</p><div class="nf"><span>距離 ${d} 米</span>${!e.done&&I.crime?`<button class="phBtn sm" data-trk="${e.id}">${CR.track===e?'追蹤緊':'去幫手'}</button>`:''}</div></div>`;}).join('');
    html=phoneShell(items||`<div class="phEmpty">📭<p>暫時冇罪案報告</p><small>${pick(['元朗今日天氣晴朗，大馬路人流暢旺。','元朗公園百鳥塔重開，市民可以行樓梯上觀景台。','西鐵元朗站人流回升，形點商場週末有活動。','明渠水位正常，市民注意安全。'])}</small></div>`,'即時新聞');}
  else if(scr==='map'){closeModal();toggleMap();return;}
  else if(scr==='close'){closeModal();return;}
  openModal('phone',html);const m=$('#modal');m.classList.add('phoneM');
  m.onclick=ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.go){sfx('ding',.3);phoneShow(b.dataset.go);}else if(b.dataset.dad){callDad(b.dataset.dad);}else if(b.dataset.trk){const e=CR.ev.find(x=>x.id==+b.dataset.trk);if(e){crTrack(e);closeModal();toast('已經標記咗位置，紅色光柱就係現場');}}};}
{const _cm=closeModal;closeModal=function(){$('#modal').classList.remove('phoneM');return _cm();};}
function callDad(kind){if(DAD.state){toast('老竇已經喺路上');return;}if(!outdoorOK()||(PLAYER.y||0)>TH(PLAYER.x,PLAYER.z)+3){closeModal();say([['老竇','喂？你喺邊呀？出返去街先打俾我啦，我先揸得埋嚟。']]);return;}
  closeModal();DAD.state='coming';DAD.kind=kind;DAD.t=R(14,28);sfx('ok');say([['老竇',kind==='ev'?'喂，阿仔？要車呀？得！我而家揸架電動車過嚟，30 秒內到！':'單車？好呀，我踩過嚟俾你，30 秒內到，企喺度等我！']]);$('#dadChip').hidden=false;}
function dadSpawn(){const P=PLAYER;const kind=DAD.kind;if(DAD.veh&&DAD.veh!==P.car){rmVeh(DAD.veh);}DAD.veh=null;
  const nr=nearestRoad(P.x,P.z,70,r=>(kind==='bike'?r.cls<=7:r.cls<=5)&&r.len>20);
  const v=kind==='ev'?spawnVehicle('sports','#f2f3f5',P.x,P.z,0):spawnVehicle('bike','#e8432e',P.x,P.z,0);v.dad=true;if(kind==='ev'){v.name='老竇架電動車';}
  const npc=mkPerson({shirt:'#5d6f8a',pants:'#3a3a3a',hair:'#3a3a3a'},P.x,P.z,'老竇','#ffd23f');DAD.npc=npc;DAD.veh=v;
  if(nr){const r=nr.r;const s=r.cum[nr.seg-1]+nr.t*Math.hypot(r.pts[nr.seg][0]-r.pts[nr.seg-1][0],r.pts[nr.seg][1]-r.pts[nr.seg-1][1]);routeOn(v,r,s,kind==='ev'?70:38,kind==='ev'?13:7);v.script.quiet=true;v.script.sir=false;DAD.state='driving';npc.g.visible=kind==='bike';}
  else{const a=P.h+Math.PI;v.x=P.x+Math.sin(a)*4;v.z=P.z+Math.cos(a)*4;v.h=P.h;pushOut(v,1.2);syncV(v);dadArrive();}}
function dadArrive(){const v=DAD.veh,n=DAD.npc;v.script=null;v.speed=0;v.vx=v.vz=0;syncV(v);DAD.state='walk';DAD.walkT=0;DAD.turned=false;$('#dadChip').hidden=true;
  const s=Math.sin(v.h),c=Math.cos(v.h);n.g.visible=true;n.b.position.set(0,0,0);n.b.rotation.set(0,0,0);for(const q of [...n.legs,...n.arms])q.rotation.set(0,0,0);n.g.position.set(v.x-c*(v.W/2+.9),TH(v.x,v.z),v.z+s*(v.W/2+.9));
  subtitle('老竇',DAD.kind==='ev'?'阿仔！架車俾你，揸慢啲呀！記得早啲返屋企食飯！':'單車俾你，戴好頭盔……咦，冇頭盔，小心啲啦！');sfx('ok');}
function dadUpdate(dt){if(!DAD.state){return;}const el=$('#dadChip');
  if(DAD.state==='coming'){DAD.t-=dt;const txt='👨 老竇仲有 '+Math.max(1,Math.ceil(DAD.t))+' 秒到';if(el.textContent!==txt)el.textContent=txt;if(DAD.t<=(DAD.kind==='ev'?5.8:5.6))dadSpawn();return;}
  if(DAD.state==='driving'){const v=DAD.veh;moverStep(v,dt);syncV(v);DAD.t-=dt;if(el.textContent!=='👨 老竇就到！')el.textContent='👨 老竇就到！';
    if(DAD.kind==='bike'){const n=DAD.npc;n.g.position.set(v.x,v.y,v.z);n.g.rotation.set(0,v.h,0);n.b.position.set(0,.1,-.24);n.b.rotation.set(.3,0,0);const s=v.spin*.9;n.legs[0].rotation.x=-.75+Math.sin(s)*.38;n.legs[1].rotation.x=-.75-Math.sin(s)*.38;n.arms[0].rotation.x=n.arms[1].rotation.x=-1.05;}
    if(v.script.arrived)dadArrive();return;}
  if(DAD.state==='walk'){const n=DAD.npc;DAD.walkT+=dt;if(DAD.walkT<1.8){n.g.rotation.y=Math.atan2(PLAYER.x-n.g.position.x,PLAYER.z-n.g.position.z);if(DAD.walkT<.3)n.arms[1].rotation.x=-1.8;}else{const a=n.g.rotation.y;n.g.position.x+=Math.sin(a)*1.4*dt;n.g.position.z+=Math.cos(a)*1.4*dt;n.g.position.y=TH(n.g.position.x,n.g.position.z);animP(n,1.4,dt);if(!DAD.turned){DAD.turned=true;n.g.rotation.y+=Math.PI;}}
    if(DAD.walkT>12||(DAD.walkT>4&&camDist(n.g.position.x,n.g.position.z)>60)){rmPerson(n);DAD.npc=null;DAD.state=null;}}}

/* ======================================================================
   8. 單車：跳 + 花式
   ====================================================================== */
const BK={air:false,vy:0,y:0,trick:null,tt:0,k:0,dur:{'360':.42,flip:.48,superman:.45},nm:{'360':'360 轉身',flip:'後空翻',superman:'飛人'}};
function onBike(){const v=PLAYER.car;return v&&v.type==='bike'&&!v.wreck?v:null;}
function bikeJump(){const v=onBike();if(!v||dlgQ||modal||busy)return;if(!BK.air){BK.air=true;BK.vy=6.2+Math.min(17,Math.abs(v.speed))*.15;BK.y=v.y||0;BK.trick=null;sfx('swing',.6);}
  else if(!BK.trick){BK.trick=['360','flip','superman'][BK.k++%3];BK.tt=0;voice('shout',pick(['喲！','睇我！','嘿！']));}}
{const _ds=driveStep;driveStep=function(v,dt){_ds(v,dt);if(v.type==='bike'&&BK.air&&v===PLAYER.car){BK.vy-=22*dt;BK.y+=BK.vy*dt;const g=groundAt(v.x,v.z,Math.max(BK.y,v.y||0)+.2);if(BK.y<=g&&BK.vy<0){v.y=g;bikeLand();}else v.y=BK.y;}};}
{const _ri=readInput;readInput=function(){_ri();if(onBike())inp.hb=false;};}
function bikeLand(){BK.air=false;const tr=BK.trick;BK.trick=null;bikeTrickReset();if(!tr){sfx('hit',.25);return;}
  if(BK.tt<BK.dur[tr]*.82){sfx('crash',.6);toast('炒車！');const v=PLAYER.car;actCarForce();if(v){v.speed=0;v.vx=v.vz=0;}hurtPlayer(8);PLAYER.vy=3;PLAYER.grounded=false;return;}
  gainXP(10,'花式');toast('花式：'+BK.nm[tr]+'！ +10 XP');sfx('ok');}
function bikeTrickReset(){const v=PLAYER.car;if(v&&v.g){v.g.rotation.x=0;}const p=PLAYER.p;if(p){p.g.rotation.x=0;}}
function bikeTrickUpdate(dt){const v=onBike();if(!v){if(BK.air){BK.air=false;BK.trick=null;}return;}const p=PLAYER.p;v.g.rotation.order='YXZ';p.g.rotation.order='YXZ';
  if(!BK.trick){v.g.rotation.x=0;return;}BK.tt+=dt;const D=BK.dur[BK.trick];const u=Math.min(1,BK.tt/D);const ease=u<.5?2*u*u:1-Math.pow(-2*u+2,2)/2;
  if(BK.trick==='360'){const a=v.h+ease*TAU;v.g.rotation.y=a;p.g.rotation.y=a;}
  else if(BK.trick==='flip'){const th=-ease*TAU,h=.75;const oy=h-h*Math.cos(th),oz=-h*Math.sin(th);const ox=Math.sin(v.h)*oz,ozw=Math.cos(v.h)*oz;v.g.rotation.x=th;v.g.position.set(v.x+ox,v.y+oy,v.z+ozw);p.g.rotation.x=th;p.g.position.set(v.x+ox,v.y+oy,v.z+ozw);}
  else{const k=Math.sin(u*Math.PI);p.b.position.set(0,.1+k*.35,-.24-k*.35);p.b.rotation.x=.3+k*1.0;p.legs[0].rotation.x=p.legs[1].rotation.x=-.75+k*.9;p.arms[0].rotation.x=p.arms[1].rotation.x=-1.05-k*1.6;}}
function bikeKeys(e){if(e.code==='Space'&&!e.repeat&&onBike()&&started){bikeJump();}}

/* ======================================================================
   9. WASTED
   ====================================================================== */
const WST={on:false,t:0,cam:null};
{const _w=wasted;WST.orig=_w;wasted=function(){if(WST.on)return;if(S.dead)return;WST.on=true;WST.t=0;WST.fired=false;S.dead=true;S.hp=0;busy=true;clearPursuit();
  const P=PLAYER;if(P.car&&P.car.type==='bike')actCarForce();
  const el=$('#wasted');el.hidden=false;el.classList.remove('on');void el.offsetWidth;el.classList.add('on');renderer.domElement.style.filter='grayscale(1) contrast(1.15) brightness(.82)';
  WST.cam={pitch:cam.pitch,zoom:cam.zoom};sfx('crash',.4);wastedSfx();};}
function wastedEnd(){const el=$('#wasted');renderer.domElement.style.filter='';el.hidden=true;el.classList.remove('on');if(WST.cam){cam.zoom=WST.cam.zoom;cam.pitch=Math.min(WST.cam.pitch,.6);}WST.on=false;}
function wastedSfx(){if(!AU.ctx||AU.muted)return;const c=AU.ctx,t=c.currentTime;[220,165,110].forEach((f,i)=>tone(f,t+.3+i*.32,.9,'sawtooth',.05,AU.sfx));tone(55,t+.25,1.8,'sine',.25,AU.sfx);}
function wastedUpdate(dt){if(!WST.on)return;WST.t+=dt;if(!WST.fired&&WST.t>3.4){WST.fired=true;busy=false;S.dead=false;WST.orig();}if(WST.fired&&WST.t>4.2){wastedEnd();return;}cam.pitch=lerp(cam.pitch,.95,1-Math.exp(-.8*dt));cam.zoom=lerp(cam.zoom,1.5,1-Math.exp(-.6*dt));inp.x=inp.y=0;}

