/* ---------- 6. title music ---------- */
TRACKS.title={bpm:128,chords:[[53,57,60,65],[48,52,55,60],[50,53,57,62],[46,50,53,58]],
  mel:[72,_,77,_,76,_,77,_,79,_,77,_,72,_,_,_, 72,_,76,_,79,_,76,_,74,_,72,_,74,_,_,_, 74,_,77,_,81,_,79,_,77,_,76,_,74,_,72,_, 70,_,74,_,77,_,74,_,72,_,_,74,_,76,_,_,
       81,_,79,_,77,_,79,_,81,_,_,84,_,81,_,_, 79,_,76,_,72,_,76,_,79,_,_,_,77,_,76,_, 74,_,77,_,81,_,84,_,86,_,84,_,81,_,79,_, 77,_,_,_,79,_,76,_,77,_,_,_,_,_,_,_],
  play(s,t,sd){const bar=Math.floor(s/16)%4,st=s%16;const ch=this.chords[bar];
    if(st%4===0)mtone(mtof(ch[0]-12),t,sd*1.8,'triangle',.13);if(st%4===2)mtone(mtof(ch[0]),t,sd*1.4,'triangle',.07);
    if(st%4===2||st===15)ch.slice(1).forEach(n=>mtone(mtof(n+12),t,sd*.9,'square',.012));
    if(st===0||st===8||st===10)mkick(t,.38);if(st===4||st===12){mnoise(t,.12,.14,1900,'bandpass');mnoise(t,.05,.05,6000);}if(st%2===1)mnoise(t,.025,.035,9000);
    const m=this.mel[s%128];if(m){mtone(mtof(m),t,sd*1.7,'square',.032);mtone(mtof(m+12),t+sd*.5,sd*1.2,'sine',.014);}}};
const TMUS={started:false};
function titleMusicStart(){if(TMUS.started&&AU.ctx&&AU.ctx.state==='running')return;try{audioInit();if(AU.ctx&&AU.ctx.state!=='running')AU.ctx.resume();musicInit();}catch(e){}TMUS.started=true;if(!started)MUS.want=AU.muted?null:'title';sndBtn();}
{const _mu=musicUpdate;musicUpdate=function(){if(!started){if(AU.ctx){musicInit();MUS.want=AU.muted?null:'title';}return;}return _mu();};}
function sndBtn(){const b=$('#iSnd');if(!b)return;if(AU.ctx&&!AU.ctx._snd){AU.ctx._snd=1;AU.ctx.addEventListener('statechange',sndBtn);}const on=TMUS.started&&!AU.muted&&AU.ctx&&AU.ctx.state==='running';b.textContent=on?'🔊 音樂：開':'🔈 撳一下開音樂';b.classList.toggle('on',on);}
function titleMusicTick(){if(started)return;musicUpdate();}

