  if(P.grounded!==false){for(const t of allTargets()){const q=t.g.position;const dx=q.x-P.x,dz=q.z-P.z,d=Math.hypot(dx,dz);if(d>td||d<.5)continue;if((dx*fx+dz*fz)/d<.72)continue;if(Math.abs(q.y-(P.y||0))>6)continue;td=d;tgt=t;}}
