/* poses */
function hipRot0(b,ax,ang,h=1){b.rotation.set(0,0,0);if(ax==='x'){b.rotation.x=ang;b.position.set(0,h-h*Math.cos(ang),-h*Math.sin(ang));}else if(ax==='z'){b.rotation.z=ang;b.position.set(h*Math.sin(ang),h-h*Math.cos(ang),0);}else{b.rotation.y=ang;b.position.set(0,0,0);}}
