/* ================= v3m: West Rail (屯馬綫) in service
   - both real tracks on the viaduct (westbound = MTR.path, eastbound built from the other track)
   - 4 five-car trains looping the whole line, stopping at 元朗 and 朗屏 with sliding doors
   - the viaduct deck is solid: you can stand / land on it (watch out for trains)
   - riding is first person: walk inside the carriages; at the next station you walk out onto the platform
   - eastbound platforms at both stations (朗屏 1 號月台 往元朗)
================= */
const WR={PA:null,PB:null,stB:{},trains:[],ride:null,NC:5,CL:20.4,DECK:12.2,ext:160};
function pathFrom(ways){const P=chainPath(ways);return P;}
function posX(P,s){if(s<0){const q=posOn(P,0);return {x:q.x+q.dx*s,z:q.z+q.dz*s,dx:q.dx,dz:q.dz};}if(s>P.len){const q=posOn(P,P.len);return {x:q.x+q.dx*(s-P.len),z:q.z+q.dz*(s-P.len),dx:q.dx,dz:q.dz};}return posOn(P,s);}
