  let w=null,bd=30;for(const p of peds){if(p===victim||!p.g.visible||p.down>0||p.crawl)continue;const d=Math.hypot(p.g.position.x-o.x,p.g.position.z-o.z);if(d<bd){bd=d;w=p;}}
