  {const ch=$('#rptChip');if(ch){const r=WANT.reports[0];ch.hidden=!r||S.dead;if(r){const k=Math.min(1,r.t0/(r.t0+r.t));ch.querySelector('i').style.width=Math.round(k*100)+'%';}}}
