  PIN.t-=dt;PIN.prog=Math.max(0,PIN.prog-.3*dt);const bar=PIN.ui.querySelector('i');bar.style.width=Math.round(PIN.prog*100)+'%';PIN.ui.querySelector('em').textContent=Math.max(0,PIN.t).toFixed(1)+'s';
