  bustT=0;clearPursuit();const el=$('#wasted');const w=el.querySelector('.w');w.textContent=kind==='mom'?'捉返屋企':'捉返學校';el.classList.add('busted');el.hidden=false;el.classList.remove('on');void el.offsetWidth;el.classList.add('on');busy=true;voice('busted');
