const ROCK=[];
function fireRocket(){const P=PLAYER;let D;if(AIM.on)D=camera.getWorldDirection(new V3());else{const t=autoAim(90);if(t){const tp=t.g.position;D=new V3(tp.x-P.x,(tp.y||0)+1-((P.y||0)+1.4),tp.z-P.z).normalize();P.h=Math.atan2(D.x,D.z);}else D=new V3(Math.sin(P.h),0,Math.cos(P.h));}
  const o=AIM.on?camera.position.clone().addScaledVector(D,1.6):muzzlePos();const m=new THREE.Group();const b=new THREE.Mesh(new THREE.CylinderGeometry(.06,.06,.5,8),std('#6b6b5a',.5,.3));b.rotation.x=Math.PI/2;m.add(b);const f=new THREE.Mesh(new THREE.SphereGeometry(.1,8,6),new THREE.MeshBasicMaterial({color:0xffb040,toneMapped:false}));f.position.z=-.3;m.add(f);
  m.position.copy(o);m.lookAt(o.clone().add(D));scene.add(m);ROCK.push({m,d:D,t:3.2});FIRE.pose=.6;shake=Math.max(shake,.25);
  if(AU.ctx&&!AU.muted){const c=AU.ctx,t=c.currentTime;noiseHit(t,.6,.5,700,'lowpass',AU.sfx);tone(90,t,.4,'sawtooth',.12,AU.sfx);}for(let i=0;i<10;i++)smokePuff(o.x,o.y,o.z,false,.7);crime('gunfire',null);}
function rocketUpdate(dt){for(let i=ROCK.length-1;i>=0;i--){const r=ROCK[i];r.t-=dt;const step=48*dt;const n=Math.max(1,Math.ceil(step/.8));let boom=null;
    for(let k=0;k<n&&!boom;k++){r.m.position.addScaledVector(r.d,step/n);const p=r.m.position;if(p.y<TH(p.x,p.z)+.1||solidAt(p.x,p.y,p.z))boom=p.clone();
      else{for(const v of vehicles){if(v===PLAYER.car)continue;if(Math.hypot(v.x-p.x,v.z-p.z)<Math.max(1.4,(v.L||4)/2)&&p.y<(v.y||0)+2.2){boom=p.clone();break;}}if(!boom)for(const t of shootTargets()){const q=t.g.position;if(Math.hypot(q.x-p.x,q.z-p.z)<.8&&p.y>(q.y||0)&&p.y<(q.y||0)+2.1){boom=p.clone();break;}}}}
    if(rnd()<.9)smokePuff(r.m.position.x,r.m.position.y,r.m.position.z,false,.45);emit(PSA,{x:r.m.position.x,y:r.m.position.y,z:r.m.position.z,life:.15,s0:.5,s1:.1,r:1,g:.7,b:.3});
    if(boom||r.t<=0){scene.remove(r.m);ROCK.splice(i,1);rocketBoom(r.m.position.x,r.m.position.y,r.m.position.z);}}}
function rocketBoom(x,y,z){boomSfx();shake=Math.max(shake,.9);flash(x,y+1,z,9,1.1);
  for(let i=0;i<46;i++){const a=R(0,TAU),u=R(-.2,1),s=R(3,11);emit(PSA,{x,y:y+R(0,1),z,vx:Math.cos(a)*s*Math.sqrt(1-u*u),vy:Math.abs(u)*s+2,vz:Math.sin(a)*s*Math.sqrt(1-u*u),life:R(.5,1.1),s0:R(1.2,2.4),s1:R(.4,1),r:1,g:R(.45,.75),b:R(.1,.25),a:1,drag:2.2});}
  for(let i=0;i<22;i++)smokePuff(x+R(-1.5,1.5),y+R(0,2),z+R(-1.5,1.5),true,1.6);sparks(x,y,z,36,10);debris(x,y,z,22);
  let killed=0;for(const p of carTargetsList()){if(FLY.some(f=>f.p===p))continue;const dx=p.g.position.x-x,dz=p.g.position.z-z,d=Math.hypot(dx,dz);if(d>7.5)continue;const k=1-d/7.5;
    if(peds.includes(p)||COPS.includes(p)||FIGHT.includes(p)){hitPerson(p,dx/(d||1)*16*k,4+9*k,dz/(d||1)*16*k,k>.3);if(k>.3)killed++;}else if(p.crim||p.debtor){HIT.part='torso';HIT.explo=true;hitTarget(p,Math.round(180*k));launch(p,dx/(d||1)*12*k,3+7*k,dz/(d||1)*12*k);}else{const dy0=p.g.position.y-TH(p.g.position.x,p.g.position.z);launch(p,dx/(d||1)*10*k,3+6*k,dz/(d||1)*10*k);KNOCK.push({p,t:6,dy:dy0});}}
  for(const o of vehicles){if(o.wreck)continue;const d=Math.hypot(o.x-x,o.z-z);if(d>8)continue;if(o===PLAYER.car){carDamage(o,90*(1-d/8),x,z);continue;}if(d<3.5&&typeof explode==='function'){explode(o);continue;}carDamage(o,110*(1-d/8),o.x,o.z);if(o.ai){o.ai=false;}o.vx=(o.vx||0)+(o.x-x)/(d||1)*7;o.vz=(o.vz||0)+(o.z-z)/(d||1)*7;}
  const P=PLAYER;if(!P.car){const d=Math.hypot(P.x-x,P.z-z);if(d<6){hurtPlayer(Math.round(85*(1-d/6)));P.vy=Math.max(P.vy||0,6*(1-d/6));}}
  if(killed)crime('kill',null);else crime('assault',null);}
