  const clear=(p,q)=>{const L=Math.hypot(q.x-p.x,q.z-p.z),n=Math.ceil(L/1.2);const ux=(q.x-p.x)/L,uz=(q.z-p.z)/L;for(let k=1;k<n;k++){const x=p.x+ux*L*k/n,z=p.z+uz*L*k/n;if(blockedAt(x,z)||blockedAt(x-uz*1.7,z+ux*1.7)||blockedAt(x+uz*1.7,z-ux*1.7))return false;}return true;};
  const out=[path[0]];let i=0;while(i<path.length-1){let j=path.length-1;while(j>i+1&&!clear(path[i],path[j]))j--;out.push(path[j]);i=j;}
