/* ---------- 元朗廣場 ---------- */
const YLP={b:null,F:[0,5,10,15],x0:0,z0:0,shoppers:[],doors:[]};
function ylpBuilding(){const L=D.lab.find(l=>l[0]==='元朗廣場');if(!L)return null;let best=null;for(const b of BL){if(!b.pts||b.nomap)continue;if(inPoly(L[1],L[2],b.pts)&&(!best||Math.abs(b.area)>Math.abs(best.area)))best=b;}return best;}
