function ringPos(p){const R0=p.ring;const n=R0.length;let t=((p.t%n)+n)%n;const i=Math.floor(t),k=t-i;const a=R0[i],b=R0[(i+1)%n];return [a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k,Math.atan2(b[0]-a[0],b[1]-a[1])*(p.spd>0?1:-1)+(p.spd>0?0:Math.PI)];}
function ylpUpdate(dt){if(curRoom!==YLP.room)return;for(const p of YLP.shoppers){const R0=p.ring;const i=Math.floor(((p.t%4)+4)%4),a=R0[i],b=R0[(i+1)%4];const L=Math.hypot(b[0]-a[0],b[1]-a[1])||1;p.t+=p.spd*dt/L;const [x,z,h]=ringPos(p);p.g.position.set(YLP.x0+x,YLP.F[p.f],YLP.z0+z);p.g.rotation.y=Math.atan2(b[0]-a[0],b[1]-a[1])+(p.spd>0?0:Math.PI);animP(p,Math.abs(p.spd),dt);}
  const P=PLAYER;const f=YLP.F.reduce((best,y,i)=>Math.abs((P.y||0)-y)<Math.abs((P.y||0)-YLP.F[best])?i:best,0);lampLights.forEach((L,i)=>{const q=YLP.room.lights[i];if(!q){L.intensity=0;return;}L.position.set(q[0],YLP.F[f]+4.2,q[1]);L.intensity=.5;});}
/* entrances: G/F street door, 2/F bridge doors */
