function rideCamSync(){const P=PLAYER;let r=null;
  if(P.riding==='wr'&&typeof WR!=='undefined'&&WR.ride)r=WR.ride;else if(P.riding==='lrt2'&&typeof LR2!=='undefined'&&LR2.ride)r=LR2.ride;if(!r)return;
  const eye=1.58+Math.sin(r.bob||0)*.025;const cp=Math.cos(cam.pitch);
  camera.position.set(P.x,P.y+eye,P.z);camera.lookAt(P.x-Math.sin(cam.yaw)*cp,P.y+eye-Math.sin(cam.pitch),P.z-Math.cos(cam.yaw)*cp);camera.updateMatrixWorld();
  cam.tx=P.x;cam.tz=P.z;cam.ty=P.y+1.5;}
{const _gu=gameUpdate;gameUpdate=function(dt){_gu(dt);rideCamSync();};}

