function grBreakNear(x,z,r){for(let i=Math.floor((x-r)/10);i<=Math.floor((x+r)/10);i++)for(let j=Math.floor((z-r)/10);j<=Math.floor((z+r)/10);j++){const L=GR.grid.get(i+','+j);if(!L)continue;for(const s of L)if(!s.broken&&Math.hypot(s.x-x,s.z-z)<r)grBreak(s,s.x-x,s.z-z);}}
function grUpdate(dt){for(const v of vehicles){if(v.ai&&!(v.speed>13))continue;const sp=v.ai?v.speed:Math.hypot(v.vx||0,v.vz||0);const ps=v._grSp||0;v._grSp=sp;const s0=Math.max(sp,ps);if(s0<6.5)continue;
    const r=(v.W||2)/2+.55,fx=Math.sin(v.h),fz=Math.cos(v.h),HLc=(v.L||4.4)/2;
    for(let i=Math.floor((v.x-6)/10);i<=Math.floor((v.x+6)/10);i++)for(let j=Math.floor((v.z-6)/10);j<=Math.floor((v.z+6)/10);j++){const L=GR.grid.get(i+','+j);if(!L)continue;
      for(const s of L){if(s.broken)continue;const dx=s.x-v.x,dz=s.z-v.z;const a=dx*fx+dz*fz,l=dx*fz-dz*fx;if(Math.abs(a)<HLc+.6&&Math.abs(l)<r+(s.k==='m'?.4:.1)){grBreak(s,v.vx||fx*sp,v.vz||fz*sp);sfx('crash',.35);
        if(v===PLAYER.car){carDamage(v,s.k==='m'?2:4,s.x,s.z);shake=Math.max(shake,.15);}if(!v.ai){v.vx*=.9;v.vz*=.9;}}}}}}

