  const combos=[['through'],['left'],['right'],['left','through'],['through','right'],['left','right'],['left','through','right']];combos.forEach((k,i)=>arrow(i,k));
  // text cells (row 1): 望右 LOOK RIGHT / 望左 LOOK LEFT, 2 cells wide each
  g.font=`900 64px ${FS}`;g.textAlign='center';g.textBaseline='middle';g.fillText('望右',128,300);g.font='800 40px "Barlow Condensed",sans-serif';g.fillText('LOOK RIGHT',128,372);
  g.font=`900 64px ${FS}`;g.fillText('望左',384,300);g.font='800 40px "Barlow Condensed",sans-serif';g.fillText('LOOK LEFT',384,372);
