  // meshes
  const gt=(()=>{const [c,g]=cvs(256,256);g.fillStyle='#b4b9ae';g.fillRect(0,0,256,256);noiseFill(g,256,256,'#b4b9ae',3000,.04,.12,2);for(let y=0;y<256;y+=64){g.fillStyle='rgba(0,0,0,.06)';g.fillRect(0,y,256,2);g.fillRect(y,0,2,256);}return ctex(c,true);})();
