function wlBoard(text,w,h,o={}){const cw=512,ch=Math.round(cw*h/w);const [c,g]=cvs(cw,ch);g.fillStyle=o.bg||'#f4f0de';g.fillRect(0,0,cw,ch);const ch2=[...text];let fs=64,lines;
  for(;fs>12;fs-=2){g.font=`700 ${fs}px ${FS}`;lines=[];let cur='';for(const k of ch2){if(g.measureText(cur+k).width>cw-28){lines.push(cur);cur=k;}else cur+=k;}if(cur)lines.push(cur);if(lines.length*fs*1.25<=ch-16)break;}
  g.fillStyle=o.fg||'#222';g.textBaseline='middle';const y0=ch/2-(lines.length-1)*fs*1.25/2;lines.forEach((l,i)=>g.fillText(l,14,y0+i*fs*1.25));
  return new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshStandardMaterial({map:ctex(c),roughness:.7}));}
function wlChunks(geo,mat,L,fn,shadow=true){const T=new Map();for(const p of L){const k=Math.floor(p[0]/120)+','+Math.floor(p[1]/120);let q=T.get(k);if(!q){q=[];T.set(k,q);}q.push(p);}
  for(const q of T.values()){const im=new THREE.InstancedMesh(geo,mat,q.length);q.forEach((p,i)=>fn(im,i,p));im.castShadow=shadow;scene.add(im);lcCull(im,q);}}
function wlOnPath(x,z,m=2){for(const L of WLX.paths)for(let i=1;i<L.length;i++){const a=L[i-1],b=L[i];const dx=b[0]-a[0],dz=b[1]-a[1],l2=dx*dx+dz*dz;const t=clamp(((x-a[0])*dx+(z-a[1])*dz)/l2,0,1);if(Math.hypot(a[0]+dx*t-x,a[1]+dz*t-z)<m)return true;}return false;}
