  const fg=new THREE.CircleGeometry(.5,10);fg.rotateX(-Math.PI/2);fg.scale(.32,1,1);WLP.fishIM=wlInst(fg,new THREE.MeshBasicMaterial({color:0x1d2a22,transparent:true,opacity:.42,depthWrite:false}),90);
