  if(k==='m')m=new THREE.MeshStandardMaterial({...o,roughness:.4,metalness:.5});else if(k==='p')m=new THREE.MeshStandardMaterial({...o,roughness:.72,metalness:.08});
  else if(k==='w')m=new THREE.MeshStandardMaterial({...o,roughness:.6,metalness:0});else if(k==='b')m=new THREE.MeshStandardMaterial({...o,roughness:.28,metalness:.45,emissive:new THREE.Color(0x2a2e34)});
