// ---------- attach to the player's hand every frame (the body is rebuilt when the outfit changes) ----------
function wxBuild(){for(const id in WX_MODELS){let inner;try{inner=WX_MODELS[id]();}catch(e){console.error('wx model',id,e);continue;}WX.inner[id]=inner;
    const hold=new THREE.Group();hold.rotation.x=Math.PI/2;hold.position.y=-.6;inner.scale.setScalar(1.35);hold.add(inner);hold.visible=false;hold.userData.inner=inner;WX.holder[id]=hold;
    const old=wpnMeshes[id];if(old&&old.parent)old.parent.remove(old);wpnMeshes[id]=hold;}
  wxIcons();}
function wxAttach(){const P=PLAYER;if(!P.p)return;const arm=P.p.arms[1];for(const id in wpnMeshes){const g=wpnMeshes[id];if(g&&g.parent!==arm)arm.add(g);}}
{const _so=setupWeapons;setupWeapons=function(){_so();for(const id in WX.holder)wpnMeshes[id]=WX.holder[id];};}
// muzzle position from the model itself
{const _mp=muzzlePos;muzzlePos=function(){const w=WEAPONS[S.wpn];const h=w&&WX.holder[w.id];if(h&&h.visible&&h.parent){h.parent.updateWorldMatrix(true,true);return h.userData.inner.userData.muz.getWorldPosition(new V3());}return _mp();};}
// ---------- effects ----------
let WXF=null;
const WX_MELEE={knife:1.05,katana:1.15,pipe:.9,brush:.9,duster:.9};
function wxFxInit(){const [c,g]=cvs(128,128);const gr=g.createRadialGradient(64,64,2,64,64,62);gr.addColorStop(0,'rgba(255,255,230,1)');gr.addColorStop(.25,'rgba(255,210,110,.95)');gr.addColorStop(.6,'rgba(255,140,40,.35)');gr.addColorStop(1,'rgba(255,90,0,0)');g.fillStyle=gr;g.fillRect(0,0,128,128);
  g.globalCompositeOperation='lighter';g.fillStyle='rgba(255,220,140,.9)';for(let i=0;i<5;i++){g.save();g.translate(64,64);g.rotate(i/5*TAU);g.beginPath();g.moveTo(-5,0);g.lineTo(0,-62);g.lineTo(5,0);g.fill();g.restore();}
  const tex=ctex(c);const mat=new THREE.MeshBasicMaterial({map:tex,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false,side:THREE.DoubleSide});
  const fl=new THREE.Group();for(let i=0;i<3;i++){const p=new THREE.Mesh(new THREE.PlaneGeometry(.34,.34),mat);if(i===1)p.rotation.y=Math.PI/2;if(i===2)p.rotation.x=Math.PI/2;fl.add(p);}fl.visible=false;scene.add(fl);
  const light=new THREE.PointLight(0xffb060,0,9,2);scene.add(light);
  const sh=new THREE.BoxGeometry(.012,.012,.03),shm=std('#d8a640',.3,.9);for(let i=0;i<28;i++){const m=new THREE.Mesh(sh,shm);m.visible=false;scene.add(m);WX.shells.push({m,t:0,vx:0,vy:0,vz:0,rest:false});}
  const [hc,hg]=cvs(64,64);const hgr=hg.createRadialGradient(32,32,2,32,32,30);hgr.addColorStop(0,'rgba(10,10,10,.95)');hgr.addColorStop(.35,'rgba(25,22,20,.8)');hgr.addColorStop(.7,'rgba(60,55,50,.25)');hgr.addColorStop(1,'rgba(0,0,0,0)');hg.fillStyle=hgr;hg.fillRect(0,0,64,64);
  const hmat=new THREE.MeshBasicMaterial({map:ctex(hc),transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-4});
  const tmat=new THREE.MeshBasicMaterial({color:0xffe6a0,transparent:true,opacity:.9,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false});
  const smat=new THREE.MeshBasicMaterial({color:0xcfe8ff,transparent:true,opacity:.8,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false,side:THREE.DoubleSide});
  WXF={fl,light,hmat,hgeo:new THREE.PlaneGeometry(.11,.11),tmat,tgeo:new THREE.CylinderGeometry(.014,.014,1,5,1,true),smat,tr:[]};
  // sniper scope overlay
  const sc=document.createElement('div');sc.id='wxScope';sc.hidden=true;sc.innerHTML='<i></i><b></b>';document.body.appendChild(sc);
  const st=document.createElement('style');st.textContent=`#wxScope{position:fixed;inset:0;z-index:5;pointer-events:none;background:radial-gradient(circle at 50% 50%,transparent 0,transparent min(34vh,34vw),rgba(0,0,0,.97) calc(min(34vh,34vw) + 2px))}
#wxScope i{position:absolute;left:50%;top:0;bottom:0;width:2px;background:linear-gradient(transparent 16%,rgba(0,0,0,.85) 16%,rgba(0,0,0,.85) 47%,transparent 47%,transparent 53%,rgba(0,0,0,.85) 53%,rgba(0,0,0,.85) 84%,transparent 84%);transform:translateX(-1px)}
#wxScope b{position:absolute;top:50%;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent 16%,rgba(0,0,0,.85) 16%,rgba(0,0,0,.85) 47%,transparent 47%,transparent 53%,rgba(0,0,0,.85) 53%,rgba(0,0,0,.85) 84%,transparent 84%);transform:translateY(-1px)}
#wwheel image{pointer-events:none}#wwheel .rar{font-size:11px}#wwheel .bar{fill:rgba(255,255,255,.14)}#wwheel .barf{fill:#ffd23f}#wwheel .bl{font-size:10px;fill:#c9c3b6;text-anchor:start}`;document.head.appendChild(st);}
function wxFlash(p,w,big){if(!WXF)return;const f=WXF.fl;f.position.copy(p);f.lookAt(camera.position);f.rotation.z=R(0,TAU);const s=(big||1)*R(.8,1.25)*(w&&w.id==='shotgun'?1.5:w&&(w.id==='sniper'||w.id==='lmg')?1.3:1);f.scale.setScalar(s);f.visible=true;WX.flashT=.045;
  WXF.light.position.copy(p);WXF.light.intensity=2.4*s;}
function wxShell(w){if(!WXF||!w||!(w.g2||w.id==='bb')||w.rocket||w.grenade)return;const h=WX.holder[w.id];if(!h||!h.parent)return;const e=h.userData.inner.userData.ej.getWorldPosition(new V3());
  const s=WX.shells.find(q=>!q.m.visible)||WX.shells[WX.t++%WX.shells.length];const H=PLAYER.h;const rx=Math.cos(H),rz=-Math.sin(H);s.m.position.copy(e);s.m.visible=true;s.t=3.5;s.rest=false;s.bounce=0;
  s.vx=rx*R(1.6,2.6)+R(-.3,.3);s.vz=rz*R(1.6,2.6)+R(-.3,.3);s.vy=R(2,3.2);s.m.rotation.set(R(0,6),R(0,6),R(0,6));if(w.id==='shotgun'){s.m.scale.set(1.6,1.6,1.9);s.m.material.color.set('#b8302a');}else{s.m.scale.set(1,1,1);}}
function wxTracer(x0,y0,z0,x1,y1,z1,col){if(!WXF)return;const a=new V3(x0,y0,z0),b=new V3(x1,y1,z1),d=b.clone().sub(a),L=d.length();if(L<.3)return;const m=new THREE.Mesh(WXF.tgeo,WXF.tmat.clone());if(col)m.material.color.set(col);
  m.scale.set(1,L,1);m.position.copy(a).addScaledVector(d,.5);m.quaternion.setFromUnitVectors(new V3(0,1,0),d.normalize());scene.add(m);WXF.tr.push({m,t:.09});}
function wxHole(p,from){if(!WXF)return;const m=new THREE.Mesh(WXF.hgeo,WXF.hmat);const back=from.clone().sub(p).normalize();m.position.copy(p).addScaledVector(back,.06);m.lookAt(from);m.rotation.z=R(0,TAU);scene.add(m);WX.holes.push({m,t:25});
  if(WX.holes.length>40){const o=WX.holes.shift();scene.remove(o.m);}}
function wxSlash(){if(!WXF)return;const P=PLAYER;const g=new THREE.Mesh(new THREE.RingGeometry(.7,1.25,24,1,-1.25,2.5),WXF.smat.clone());g.position.set(P.x,(P.y||0)+1.2,P.z);g.rotateY(P.h-Math.PI/2);g.rotateX(-Math.PI/2+R(-.45,.45));scene.add(g);WX.slash.push({m:g,t:.18});}
function wxKick(w){const k={pistol:.035,smg:.018,shotgun:.08,sniper:.11,lmg:.022,gl:.06,rpg:.09,bb:.02}[w&&w.id]||.03;WX.kick=Math.min(.14,WX.kick+k);
  if(AIM.on){AIM.pitch=clamp(AIM.pitch-k*.6,-.6,.8);}shake=Math.max(shake,k*(w&&w.id==='sniper'?2.2:1.3));}
// ---------- hooks into firing ----------
{const _tr=tracer;tracer=function(x0,y0,z0,x1,y1,z1){_tr(x0,y0,z0,x1,y1,z1);const w=WEAPONS[S.wpn];wxTracer(x0,y0,z0,x1,y1,z1,w&&w.rar==='legend'?'#ffe08a':w&&w.rar==='rare'?'#e0b8ff':null);
  if(WX.firing){if(!WX.flashed){WX.flashed=true;wxFlash(new V3(x0,y0,z0),w);}}else if(MP&&MP.replay){wxFlash(new V3(x0,y0,z0),null,.8);}};}
{const _cs=castShot;castShot=function(o,d,range,list){const r=_cs(o,d,range,list);if(WX.firing&&r&&r.wall&&r.p)wxHole(r.p,o);return r;};}
{const _fw=fireWeapon;fireWeapon=function(){const w=WEAPONS[S.wpn];if(w&&w.grenade){wxGrenadeFire(w);return;}if(w&&(w.gun||w.g2)&&PLAYER.p&&!PLAYER.car){const A=PLAYER.p.arms;A[1].rotation.x=-1.5;if(['smg','shotgun','rifle','heavy'].includes(wCat(w))&&w.id!=='bb'){A[0].rotation.x=-1.35;A[0].rotation.z=.42;}PLAYER.p.g.position.set(PLAYER.x,PLAYER.y||0,PLAYER.z);PLAYER.p.g.rotation.y=PLAYER.h;PLAYER.p.g.updateWorldMatrix(true,true);}
  WX.firing=true;WX.flashed=false;let fired=false;
  try{_fw();fired=!!w&&Math.abs(FIRE.cd-w.cd)<1e-6;}finally{WX.firing=false;}
  if(fired&&w&&(w.gun||w.g2)){wxKick(w);wxShell(w);if(!WX.flashed&&w.rocket){const p=muzzlePos();wxFlash(p,w,1.6);}}};}
{const _gs=gunSfx;gunSfx=function(w){if(!AU.ctx||AU.muted||!w)return _gs(w);const c=AU.ctx,t=c.currentTime;
  if(w.id==='sniper'){noiseHit(t,.35,.7,700,'lowpass',AU.sfx);tone(55,t,.4,'sine',.45,AU.sfx);noiseHit(t+.28,.5,.18,500,'lowpass',AU.sfx);noiseHit(t+.6,.5,.08,400,'lowpass',AU.sfx);return;}
  if(w.id==='lmg'){noiseHit(t,.09,.34,1200,'bandpass',AU.sfx);tone(90,t,.06,'square',.08,AU.sfx);return;}
  if(w.id==='gl'){tone(80,t,.18,'sine',.5,AU.sfx);noiseHit(t,.12,.25,500,'lowpass',AU.sfx);return;}
  if(w.id==='pistol'){noiseHit(t,.12,.42,1700,'lowpass',AU.sfx);tone(130,t,.08,'triangle',.22,AU.sfx);noiseHit(t+.18,.25,.05,900,'lowpass',AU.sfx);return;}
  if(w.id==='shotgun'){noiseHit(t,.38,.6,850,'lowpass',AU.sfx);tone(62,t,.28,'sine',.4,AU.sfx);noiseHit(t+.45,.07,.12,2400,'bandpass',AU.sfx);tone(300,t+.48,.04,'square',.05,AU.sfx);return;}
  return _gs(w);};}
