  if(s==='chalk'){e.atkT=.4;sfx('swing',.5);const o=[e.x+Math.sin(e.h)*1.2,e.y+2.4,e.z+Math.cos(e.h)*1.2];for(let k=-2;k<=2;k++){const h=e.h+k*.13;const dy=a.dy||0;const l=Math.hypot(1,dy);bossShot('chalk',o,[Math.sin(h)/l,dy/l,Math.cos(h)/l],30,1.6,7,src,host);}return;}
