// ---------- per frame ----------
function bossUpdate(dt){for(const k in BOSS.cool)if(BOSS.cool[k]>0)BOSS.cool[k]=Math.max(0,BOSS.cool[k]-dt);
  pfxTick(dt);teleTick(dt);vfxTick(dt);
  if(!started||curRoom&&!BOSS.act){bossHud();return;}
  BOSS.pjHost=bossHost();if(bossHost())bossHostUpdate(dt);else bossPjTick(dt);
  const F=BOSS.act;if(!F){bossHud();return;}const host=bossHost();if(F.endT!=null){F.endT-=dt;if(F.endT<=0){bossClear();return;}}
  for(const e of F.ents){if(!host&&e.st!=='dead'){const k=1-Math.exp(-10*dt);e.x+=(e.tx-e.x)*k;e.z+=(e.tz-e.z)*k;e.h=mpAng(e.h,e.th,k);e.y=e.ty!=null?e.y+(e.ty-e.y)*k:TH(e.x,e.z);}
    e.g.visible=!(e.st==='dead'&&(e.deadT||0)>8);
    if(e.st==='dead'){e.deadT=(e.deadT||0)+dt;if(e.b){e.b.rotation.x=Math.max(-1.5,e.b.rotation.x-dt*4);e.b.position.y=.22;}else e.g.position.y=Math.max(TH(e.x,e.z)+.05,e.g.position.y-dt*6);e.g.position.x=e.x;e.g.position.z=e.z;if(e.tag)e.tag.sp.visible=false;continue;}
    let y=e.y;if(e.boss&&e.st==='jump'){const u=Math.min(1,(e.jumpT||0)/.75);y+=Math.sin(u*Math.PI)*3.2;e.jumpT=(e.jumpT||0)+(host?0:dt);}
    e.g.position.set(e.x,y,e.z);e.g.rotation.set(0,e.h,0);
    if(e.kind==='paper'){e.g.rotation.z=Math.sin(BOSS.clock*3+e.i)*.4;e.g.rotation.x=e.st==='dive'?.5:0;continue;}
    const sleeping=e.boss&&F.sleep;
    if(sleeping){e.b.rotation.x=-1.45;e.b.position.y=.2;if(Math.random()<dt*1.5){const q=e.g.position;emit(PSA,{x:q.x+R(-.3,.3),y:q.y+1.2,z:q.z,vx:R(-.2,.2),vy:1,vz:R(-.2,.2),life:1.6,s0:.5,s1:.8,r:.8,g:.9,b:1,a:.8,drag:.3});}}
    else{animP(e,e.st==='idle'?0:e.sp,dt);e.b.rotation.x=e.st==='dash'||e.st==='windup'?.45:e.st==='dazed'?-.25:0;e.b.position.y=e.b.position.y||0;}
    if(e.atkT>0||(e.kind==='mcop'&&e.gun)){e.arms[1].rotation.x=-1.5;}
    if(e.boss&&e.def.id==='teacher'&&e.p.book){e.p.book.rotation.z=e.anim==='book'&&(e.animT=(e.animT||0)+dt)<1?Math.sin(e.animT*10)*.6:0;}
    if(e.boss&&e.st==='spin'){e.g.rotation.y=BOSS.clock*14;}
    if(e.boss&&F.rage){if(Math.random()<dt*20){const q=e.g.position;emit(PSA,{x:q.x+R(-.8,.8),y:q.y+R(.5,3.5),z:q.z+R(-.8,.8),vx:R(-.5,.5),vy:R(1,3),vz:R(-.5,.5),life:.5,s0:.6,s1:.1,r:1,g:.15,b:.1,a:.8,drag:1});}
      if(e.def.id==='bull'&&e.p.bullHead&&Math.random()<dt*6){const hp=e.p.bullHead.getWorldPosition(new V3());for(const s of [-1,1])emit(PSN,{x:hp.x+Math.sin(e.h)*.6+Math.cos(e.h)*s*.1,y:hp.y-.15,z:hp.z+Math.cos(e.h)*.6-Math.sin(e.h)*s*.1,vx:Math.sin(e.h)*2,vy:-.3,vz:Math.cos(e.h)*2,life:.6,s0:.3,s1:1.2,r:.95,g:.95,b:.95,a:.6,drag:1});}}
    if(e.boss&&e.def.id==='bull'&&e.p.bullHead){const red=F.rage?1:0;for(const s of [-1,1]){const ey=e.p.bullHead.userData['eye'+s];if(ey)ey.material.color.setHex(red?0xff2a1a:0x111111);}}
    if(e.tag){e.tag.sp.position.set(e.x,y+e.sc*2.3+.9,e.z);e.tag.sp.visible=true;bossTagDraw(e);}}
  // the cop's shield bubble
  if(F.def.id==='cop'){const B=F.ents[0];if(F.shield&&B.st!=='dead'){if(!F.bubble){F.bubble=new THREE.Mesh(new THREE.IcosahedronGeometry(2.6,1),new THREE.MeshBasicMaterial({color:0x6cc8ff,transparent:true,opacity:.22,wireframe:true,toneMapped:false}));scene.add(F.bubble);}F.bubble.visible=true;F.bubble.position.set(B.x,B.y+2,B.z);F.bubble.rotation.y+=dt*.6;}else if(F.bubble)F.bubble.visible=false;}
  // clients still move the dash locally so it looks smooth
  bossHud();}
