function bossBanner(t,s,win){const el=$('#bossBan');if(!el)return;el.innerHTML=`<b>${escapeHtml(t)}</b><i>${escapeHtml(s||'')}</i>`;el.className=win?'win':'';el.hidden=false;clearTimeout(el._t);el._t=setTimeout(()=>el.hidden=true,win?7000:5200);}
function bossHud(){const el=$('#bossBar');if(!el)return;const F=BOSS.act;const B=F&&F.ents[0];const o=PLAYER.car||PLAYER;const show=!!(B&&B.st!=='dead'&&F.st!=='idle'&&Math.hypot(B.x-o.x,B.z-o.z)<160);if(el.hidden===show)el.hidden=!show;if(!show)return;
  const left=F.ents.filter(e=>!e.boss&&e.st!=='dead').length;const bi=bossBarInfo(F);const k=Math.round(bi.f*1000)+'|'+bi.n+'|'+left+'|'+(F.shield?1:0)+(F.sleep?1:0)+(F.rage?1:0);if(el._k===k)return;el._k=k;
  const cur=F.shield?'#6cc8ff':BAR_COLS[(bi.n-1)%BAR_COLS.length],nxt=bi.n>1?BAR_COLS[(bi.n-2)%BAR_COLS.length]:'rgba(20,8,8,.8)';
  const tags=[F.shield?'<em class="sh">護盾（先打小警察）</em>':'',F.sleep?'<em class="zz">瞓緊覺 💤 傷害 ×1.6</em>':'',F.rage?'<em class="rg">暴怒</em>':'',left?'手下 ×'+left:''].filter(Boolean).join(' ');
  el.innerHTML=`<div class="bn">☠ ${F.def.name}<span>${tags}</span></div><div class="bb" style="background:${nxt}"><i style="width:${Math.max(0,bi.f*100)}%;background:${cur}"></i><b>×${bi.n}</b></div>`;}
function bossMapPos(){const F=BOSS.act;if(!F)return null;const B=F.ents[0];return {x:B.x,z:B.z,def:F.def,F};}
