function skR(id){return SKT.ranks[id]|0;}
function skLv(){try{return rpg().lv;}catch(e){return 1;}}
function skPts(){let spent=0;for(const k in SKT.ranks){const a=SK_ACTIVE.find(x=>x.id===k);if(a&&a.boss)spent+=Math.max(0,(SKT.ranks[k]|0)-1);else spent+=SKT.ranks[k]|0;}return Math.max(0,skLv()-1-spent);}
