// ---------- passives ----------
{const _ht=hitTarget;hitTarget=function(t,dmg){if(t&&!t.mpPid){const gun=HIT.gun;let m=1+(gun?skR('gun')*.08:skR('melee')*.12);const c=skR('crit')*.06;if(c&&rnd()<c){m*=2;skCritFx(t);}dmg*=m;}return _ht(t,dmg);};}
