    scene.add(g);SKT.fx.push({m:g,t:0,life:.6,upd:(f)=>{mat.opacity=1-f.t/f.life;g.children.forEach(l=>{const p=l.geometry.attributes.position;for(let i=0;i<p.count;i++)p.setY(i,y+1.2+R(-.4,.4));p.needsUpdate=true;});}});
    for(let i=0;i<40;i++){const s=R(1,11),an=h+R(-.45,.45);emit(PSA,{x:x+Math.sin(an)*s,y:y+R(.5,2),z:z+Math.cos(an)*s,vx:R(-2,2),vy:R(-1,2),vz:R(-2,2),life:R(.2,.5),s0:.3,s1:.04,r:.6,g:.9,b:1,drag:3});}
