// ---------- per frame ----------
function skTick(dt){const now=performance.now();
  for(let i=SKT.fx.length-1;i>=0;i--){const f=SKT.fx[i];f.t+=dt;if(f.upd&&f.t>=0)try{f.upd(f,dt);}catch(e){}if(f.t>=f.life){if(f.m)scene.remove(f.m);SKT.fx.splice(i,1);if(f.end)try{f.end();}catch(e){}}}
  if(SKT.shield>0)SKT.shield-=dt;
  const P=PLAYER;if(SKT.move){const m=SKT.move;m.t+=dt;const u=Math.min(1,m.t/m.dur);P.x=m.x0+(m.x1-m.x0)*u;P.z=m.z0+(m.z1-m.z0)*u;if(u>=1){SKT.move=null;pushOut(P,.4,P.y);}}
  if(SKT.chan){SKT.chan.t-=dt;if(SKT.chan.t<=0||S.dead)SKT.chan=null;}
  if(!started||S.dead)return;
  const quiet=now-SKT.lastHurt>4000;
  if(quiet&&skR('regen')&&S.hp<100){S.hp=Math.min(100,S.hp+skR('regen')*1.5*dt);}
  const cap=skR('plate')*15;if(quiet&&cap&&(S.armor||0)<cap){S.armor=Math.min(cap,(S.armor||0)+3*dt);}
  if((SKT.hudT=(SKT.hudT||0)-dt)<=0){SKT.hudT=.2;skHud();skBadge();}}
