{const _ws=walkStep;walkStep=function(dt){if(SKT.move)return;if(SKT.chan&&SKT.chan.k==='laser'){const ix=inp.x,iy=inp.y;inp.x=inp.y=0;try{return _ws(dt);}finally{inp.x=ix;inp.y=iy;}}return _ws(dt);};}
