function skHud(force){let el=$('#skHud');if(!el)return;const show=started&&!PLAYER.car&&!PLAYER.riding&&!curRoom&&!modal&&!mapOpen&&!S.dead;if(el.hidden===show)el.hidden=!show;if(!show)return;const now=performance.now()/1000;
  let h='';for(let s=0;s<2;s++){const id=SKT.eq[s];const a=id&&SK_ACTIVE.find(x=>x.id===id);const left=a?Math.max(0,(SKT.cd[id]||0)-now):0;const tot=a?a.cd*(1-.1*(skRank(a)-1)):1;
    h+=`<button class="skb${a?'':' empty'}" data-s="${s}" style="--c:${a?a.col:'#555'};--p:${a?Math.round(left/tot*100):0}%"><b>${a?a.n:'空'}</b><i>${left>0?Math.ceil(left):(isMobile?'':s?'X':'Z')}</i></button>`;}
  if(force||el._h!==h){el._h=h;el.innerHTML=h;}}
