// ---------- lobby (held by the host) ----------
function arcReq(k,o){o=Object.assign({t:'areq',k,pid:arcMe(),name:MP.on?MP.name:'你'},o||{});if(arcHost())arcHandleReq(o);else mpSend(o);}
function arcHandleReq(o){let L=ARC.lobby;
  if(o.k==='open'){if(ARC.M){arcTell(o.pid,'而家有一局玩緊，等佢完先');return;}if(!L||L.g!==o.g){L=ARC.lobby={g:o.g,owner:o.pid,mem:[]};}}
  if(!L)return;const me=L.mem.find(m=>m.pid===o.pid);
  if(o.k==='open'||o.k==='join'){if(!me){const t0=L.mem.filter(m=>m.team===0).length,t1=L.mem.length-t0;L.mem.push({pid:o.pid,name:String(o.name||'').slice(0,12),team:L.g==='cs'?(t0<=t1?0:1):0});}}
  else if(o.k==='leave'){L.mem=L.mem.filter(m=>m.pid!==o.pid);if(!L.mem.length)ARC.lobby=null;else if(L.owner===o.pid)L.owner=L.mem[0].pid;}
  else if(o.k==='team'&&me){me.team=me.team?0:1;}
  else if(o.k==='start'&&me&&L.owner===o.pid){arcStart(L);return;}
  arcLobbySend();}
function arcTell(pid,m){if(pid===arcMe())toast(m);else{const L=MP.links.get(pid);if(L)L.send({t:'asys',to:pid,m});}}
function arcLobbySend(){if(MP.on)mpSend({t:'alob',L:ARC.lobby});arcLobbyUi();}
function arcInLobby(){return !!(ARC.lobby&&ARC.lobby.mem.some(m=>m.pid===arcMe()));}
function arcPanel(){if(ARC.on){toast('打緊機，完咗先');return;}const L=ARC.lobby;
  const card=(g,t,d,col)=>{const mine=L&&L.g===g;const inL=mine&&arcInLobby();const other=L&&L.g!==g;
    let body=`<b style="color:${col}">${t}</b><small>${d}</small>`;
    if(mine){body+=`<div class="aml">${L.mem.map(m=>`<span style="border-color:${g==='cs'?TEAM_C[m.team]:'#7fdc6a'}">${escapeHtml(m.name)}${g==='cs'?'・'+TEAM_N[m.team]:''}${m.pid===L.owner?' 👑':''}</span>`).join('')}</div>`;}
    body+='<div class="amb">';if(ARC.M)body+='<button disabled>玩緊一局</button>';
    else if(!MP.on)body+=`<button data-a="solo" data-g="${g}">開始（同電腦玩）</button>`;
    else if(other)body+='<button disabled>另一部機開緊房</button>';
    else if(!mine)body+=`<button data-a="open" data-g="${g}">開房</button>`;
    else if(!inL)body+=`<button data-a="join" data-g="${g}">加入</button>`;
    else{if(g==='cs')body+='<button data-a="team">換隊</button>';if(L.owner===arcMe())body+='<button data-a="start" class="go">開始！</button>';else body+='<button disabled>等房主開始</button>';body+='<button data-a="leave">退出</button>';}
    return `<div class="amc" style="--c:${col}">${body}</div></div>`;};
  openModal('arcade',`<div class="amw"><h2>🕹 元朗電玩對戰館</h2><p class="amp">${MP.on?'喺房入面開一局，隊友會收到邀請（撳 J 加入）。':'單人模式會同電腦對戰。'}贏咗有錢同經驗，存返自己部機。</p>
    ${card('cs','💣 反恐對戰','廢棄停車場・攻方埋炸彈、守方拆彈或者全殲對手。先贏 3 局。每局開頭有買嘢時間（B），人唔夠由電腦補位。','#ff8a3a')}
    ${card('zb','🧟 喪屍生存','工業邨圍場・一波一波喪屍，每 5 波有喪屍大佬。死咗等下一波復活，全隊陣亡就完。','#7fdc6a')}
    <button id="amClose">關閉</button></div>`);
  const m=$('#modal');m.classList.add('amm');m.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='amClose'){m.classList.remove('amm');closeModal();return;}
    const a=b.dataset.a;if(a==='solo'){m.classList.remove('amm');closeModal();ARC.lobby={g:b.dataset.g,owner:1,mem:[{pid:1,name:'你',team:0}]};arcStart(ARC.lobby);return;}
    if(a)arcReq(a,{g:b.dataset.g});setTimeout(()=>{if(modal==='arcade')arcPanel();},120);};}
function arcLobbyUi(){if(modal==='arcade')arcPanel();const el=$('#arcInv');if(!el)return;const L=ARC.lobby;const show=!!(MP.on&&L&&!ARC.M&&!arcInLobby());el.hidden=!show;if(show)el.innerHTML=`${escapeHtml(arcName(L.owner))} 開咗${L.g==='cs'?'反恐對戰':'喪屍生存'}（${L.mem.length} 人）<button id="arcJoin">加入 (J)</button>`;}
// ---------- inventory swap while playing ----------
function arcSaveInv(){ARC.saved={weapons:Object.assign({},S.weapons),ammo:Object.assign({},S.ammo||{}),wpn:S.wpn,armor:S.armor||0,x:PLAYER.x,z:PLAYER.z,y:PLAYER.y||0,h:PLAYER.h};}
function arcRestoreInv(){const s=ARC.saved;if(!s)return;S.weapons=s.weapons;S.ammo=s.ammo;S.wpn=s.wpn;S.armor=s.armor;ARC.saved=null;try{updateWeapon();}catch(e){}}
{const _sv=save;save=function(){if(ARC.on&&ARC.saved&&ARC.M&&ARC.M.g==='cs'){const w=S.weapons,a=S.ammo,i=S.wpn,ar=S.armor;S.weapons=ARC.saved.weapons;S.ammo=ARC.saved.ammo;S.wpn=ARC.saved.wpn;try{return _sv();}finally{S.weapons=w;S.ammo=a;S.wpn=i;S.armor=ar;}}return _sv();};}
function arcLoadout(list){S.weapons={knife:true};S.ammo={};for(const [id,n] of list){S.weapons[id]=true;if(n)S.ammo[id]=n;}const w=list.length?list[list.length-1][0]:'knife';S.wpn=Math.max(0,WEAPONS.findIndex(x=>x.id===w));try{updateWeapon();}catch(e){}}
// ---------- arenas ----------
