{const _pp=playerPose;playerPose=function(dt){_pp(dt);const P=PLAYER;if(!ARC.dead||!P.p)return;ARC.downT=(ARC.downT||0)+dt;const u=Math.min(1,ARC.downT/.6);P.p.b.rotation.x=-1.5*u;P.p.b.position.y=.22*u;};}
