qAutoStart=function(){return (isMobile||(LITE.on&&LITE.lvl>0))?0:2;};
{const _aq=applyQuality;applyQuality=function(lv,force){const r=_aq(lv,force);try{if(LITE.on&&LITE.lvl>=2&&renderer.getPixelRatio()>.6){renderer.setPixelRatio(.6);renderer.setSize(innerWidth,innerHeight);if(composer){composer.setPixelRatio(.6);composer.setSize(innerWidth,innerHeight);}}}catch(e){}return r;};}

// ===== v18.7 multiplayer over the claude.ai "room" capability (claude.ai pages block WebRTC); PeerJS stays for copies opened elsewhere =====
const RM={api:null,p:null,denied:false,sent:0,winT:0,rate:0};
function rmApi(){if(RM.p)return RM.p;RM.p=(async()=>{try{if(window.claude&&typeof window.claude.use==='function'){RM.api=await window.claude.use('room');}}catch(e){RM.api=null;}return RM.api;})();return RM.p;}
const rmBytes=s=>{try{return new TextEncoder().encode(s).length;}catch(e){return s.length*3;}};
const RM_LIMIT=3600;
function rmErr(e){const c=e&&e.code;if(c==='not_permitted'){RM.denied=true;return new Error('你冇權限喺呢個房傳訊息：叫開遊戲 link 嗰位用 Contributor（或者 Editor）權限邀請你個 Claude 帳號，再重新開過');}
  if(c==='not_granted'||c==='revoked')return new Error('連唔到多人伺服器：要登入 Claude，而且要係被邀請嘅帳號先用到');if(c==='limit_reached')return new Error('房間太多人／太多房，遲啲再試');return new Error((e&&e.message)||'連線失敗');}
// one batched emit about every 66 ms per page; the same message to several players goes once
function rmBatcher(room,me,onFail){const q=new Map();let t=null;
  const flush=()=>{t=null;if(!q.size)return;let pack=[],size=20;const out=[];
    for(const [d,tos] of q){let to=[...tos];to=to.length===1?to[0]:to;const it={t:to,d};const s=JSON.stringify(it);const b=rmBytes(s);if(b>RM_LIMIT){console.warn('room msg too big',b,d&&d.t);continue;}
      if(size+b>RM_LIMIT&&pack.length){out.push(pack);pack=[];size=20;}pack.push(it);size+=b+1;}
    if(pack.length)out.push(pack);q.clear();
    for(const p of out){RM.sent++;room.emit('mp',{f:me,m:p}).catch(e=>{if(e&&e.code==='not_permitted'){RM.denied=true;if(onFail)onFail(rmErr(e));}});}};
  return {send(to,d){if(d==null)return;let s=q.get(d);if(!s){s=new Set();q.set(d,s);}s.add(to);if(!t)t=setTimeout(flush,66);},flush};}
const rmWait=ms=>new Promise(r=>setTimeout(r,ms));
const rmName=code=>'ylr-'+String(code).toLowerCase().replace(/[^a-z0-9]/g,'');
const NET_ROOM={
  async host(code,onConn,onLost){const api=RM.api;let room;try{room=await api.join(rmName(code));}catch(e){throw rmErr(e);}
    await rmWait(1500);if(room.peers().some(p=>!p.isMe&&p.presence&&p.presence.host)){try{await room.leave();}catch(e){}const er=new Error('busy');er.type='unavailable-id';throw er;}
    try{await room.presence({host:1});}catch(e){}
    const B=rmBatcher(room,'H',e=>{toast(e.message);});const links=new Map();
    const off=room.on('mp',msg=>{if(msg.isMe&&msg.sameTab)return;const v=msg.data;if(!v||typeof v.f!=='string'||!Array.isArray(v.m))return;const from=v.f;if(from==='H')return;
      for(const it of v.m){if(!it||it.t!=='H')continue;const d=it.d;
        if(d&&d.k==='rjoin'){if(!links.has(from)){const L=mpMkLink(x=>B.send(from,x),()=>{B.send(from,{k:'rbye'});links.delete(from);});L.peer=msg.peer;links.set(from,L);onConn(L);}B.send(from,{k:'racc'});continue;}
        if(d&&d.k==='rbye'){const L=links.get(from);if(L){links.delete(from);L._close();}continue;}
        const L=links.get(from);if(L)L._msg(d);}},e=>{if(onLost)onLost('room');});
    const offP=room.onPeers(ch=>{for(const p of ch.left)for(const [id,L] of links)if(L.peer===p.peer){links.delete(id);L._close();}});
    return {room,destroy(){for(const L of [...links.values()])L.close();B.flush();setTimeout(()=>{try{off();offP();}catch(e){}room.leave().catch(()=>{});},200);}};},
  async join(code,ms){const api=RM.api;let room;try{room=await api.join(rmName(code));}catch(e){throw rmErr(e);}const id='c'+Math.random().toString(36).slice(2,9);let L=null,done=false,fail=null;
    const B=rmBatcher(room,id,e=>{fail=e;});
    return await new Promise((res,rej)=>{let off=null,offP=null;const end=e=>{if(done)return;done=true;clearTimeout(t);try{off&&off();offP&&offP();}catch(_){}room.leave().catch(()=>{});rej(e);};
      const t=setTimeout(()=>end(fail||new Error(room.peers().some(p=>p.presence&&p.presence.host)?'房主冇回應':'搵唔到房間 '+code)),ms||9000);
      off=room.on('mp',msg=>{if(msg.isMe&&msg.sameTab)return;const v=msg.data;if(!v||v.f!=='H'||!Array.isArray(v.m))return;
        for(const it of v.m){if(!it)continue;const to=it.t;if(!(to===id||(Array.isArray(to)&&to.includes(id))))continue;const d=it.d;
          if(d&&d.k==='racc'){if(!L&&!done){done=true;clearTimeout(t);L=mpMkLink(x=>B.send('H',x),()=>{B.send('H',{k:'rbye'});B.flush();setTimeout(()=>{try{off();offP();}catch(e){}room.leave().catch(()=>{});},250);});res({link:L,destroy(){L.close();}});}continue;}
          if(d&&d.k==='rbye'){if(L)L._close();continue;}if(L)L._msg(d);}});
      offP=room.onPeers(ch=>{for(const p of ch.left)if(p.presence&&p.presence.host&&L)L._close();});
      const ping=()=>{if(L||done)return;if(fail){end(fail);return;}B.send('H',{k:'rjoin'});setTimeout(ping,1000);};ping();});}};
// pick a transport: claude.ai room when this page is on claude.ai, else PeerJS (WebRTC), else explain
const NET_AUTO={async host(code,onConn,onLost){const api=await rmApi();if(api){MP.kind='room';return NET_ROOM.host(code,onConn,onLost);}if(window.RTCPeerConnection){MP.kind='peer';return NET_PEER.host(code,onConn,onLost);}throw new Error(MP_NOTE);},
  async join(code,ms){const api=await rmApi();if(api){MP.kind='room';return NET_ROOM.join(code,ms);}if(window.RTCPeerConnection){MP.kind='peer';return NET_PEER.join(code,ms);}throw new Error(MP_NOTE);}};
const MP_NOTE='呢度開唔到多人模式：請喺 Claude app（或者已經登入 claude.ai 嘅瀏覽器）開遊戲 link；朋友要用 Contributor 權限邀請佢個 Claude 帳號';
mpNet=function(){return (window.__MP_BC||MP.kind==='bc')?NET_BC:NET_AUTO;};
{const _mm=mpMenu;mpMenu=function(){_mm();try{const p=document.querySelector('#iPanel .mpf + p')||[...document.querySelectorAll('#iPanel p')].pop();if(p&&!p.querySelector('.rmn')){const s=document.createElement('span');s.className='rmn';s.innerHTML='<br><b>點樣同朋友玩：</b>大家都要喺 Claude app（或者已登入 claude.ai）開呢個遊戲。開 artifact 嘅人喺 Share 用朋友個 Claude 帳號 email 邀請，權限揀 <b>Contributor</b>。';p.appendChild(s);}}catch(e){}};}
