    if(y<-.1){const t=rgS(-.1,-1,y);x*=1-F.jaw*t;if(z<0)z*=1-.35*t;}if(y<-.72)y=-.72+(y+.72)*.55;if(y>.6)x*=1-.15*(y-.6);
