function v10cBoot(){const st=document.createElement('style');st.textContent=`.abuy kbd{font:800 11px var(--f-num);background:rgba(0,0,0,.25);border-radius:4px;padding:0 4px;margin-right:2px}`;document.head.appendChild(st);}



/* ---------- loop ---------- */
let headSpot=null,last=performance.now(),acc=0,roadT=0;
function update(dt){readInput();if(gameBlocked()){inp.x=inp.y=0;inp.run=inp.hb=false;}
  if(todT<1){todT=Math.min(1,todT+dt/1.6);applyTod(todT);if(todT>=1)envDirty=true;}
  if(envDirty){envDirty=false;rebuildEnv();}
  acc+=dt;const STEP=(typeof PERF!=='undefined'&&PERF.step&&!PLAYER.car)?PERF.step:1/120;let n=0;while(acc>=STEP&&n<12){if(PLAYER.car)driveStep(PLAYER.car,STEP);else if(!PLAYER.riding)walkStep(STEP);acc-=STEP;n++;}if(n>=12)acc=0;
  for(const v of vehicles){if(v.ai)trafficUpdate(v,dt);else{if(v!==PLAYER.car){v.vx*=Math.exp(-2*dt);v.vz*=Math.exp(-2*dt);v.x+=v.vx*dt;v.z+=v.vz*dt;v.speed=v.vx*Math.sin(v.h)+v.vz*Math.cos(v.h);v.spin+=v.speed/v.wr*dt;}syncV(v);}
    const br=v.brakeOn;v.body.children.forEach(m=>{if(m.material===tailM||m.material===brakeM)m.material=br?brakeM:tailM;});}
  for(const t of lrts)lrtUpdate(t,dt);
  for(const p of peds)pedUpdate(p,dt);
  const P=PLAYER;if(!P.car){P.p.g.position.set(P.x,P.y,P.z);P.p.g.rotation.y=P.h;animP(P.p,P.spd,dt);}else{P.x=P.car.x;P.z=P.car.z;}
  camUpdate(dt);
  sunFollow();
  if(headSpot&&P.car){headSpot.position.set(P.car.x+Math.sin(P.car.h)*2,.8,P.car.z+Math.cos(P.car.h)*2);headSpot.target.position.set(P.car.x+Math.sin(P.car.h)*20,0,P.car.z+Math.cos(P.car.h)*20);headSpot.visible=cur.head>.1;}else if(headSpot)headSpot.visible=false;
  if(lampLights.length&&LAMPS.length){const cx=cam.tx,cz=cam.tz;let near=[];for(const l of LAMPS){const d=(l[0]-cx)**2+(l[2]-cz)**2;if(d<120*120)near.push([l,d]);}near.sort((a,b)=>a[1]-b[1]);
    lampLights.forEach((L,i)=>{const n=near[i];if(!n){L.intensity=0;return;}L.position.set(n[0][0],n[0][1],n[0][2]);L.intensity=cur.lamp*.22;});}
  if(fillLight){fillLight.position.set(cam.tx,cam.ty+1.6,cam.tz);fillLight.intensity=P.car?0:Math.max(0,cur.lamp-1)*.07;}
  if(P.car)$('#speedo .n').textContent=Math.round(Math.abs(P.car.speed)*3.6);
  if(toastT>0){toastT-=dt;if(toastT<=0)$('#toast').classList.remove('show');}
  roadT-=dt;if(roadT<=0){roadT=.5;const nr=nearestRoad(P.x,P.z,30,r=>!!r.name&&r.cls<=6);const nm=curRoom?curRoom.name:placeName()||(PLAYER.riding==='mtr'?'屯馬綫列車':P.plat?'港鐵'+P.plat.zh+'站 月台':nr?nr.r.name:'元朗');const el=$('#road');if(el.textContent!==nm)el.textContent=nm;}
  gameUpdate(dt);labelsUpdate();minimapDraw();}
function render(){if(composer)composer.render();else renderer.render(scene,camera);}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;update(dt);render();}

/* ---------- boot ---------- */
let BOOT_LY=0,AS1=0,AS2=0;
function bootProg(p,msg,force){const b=document.querySelector('#bootL .bar i');if(b){b.style.animation='barStripe .6s linear infinite';b.style.transition='width .3s';b.style.width=Math.max(6,Math.round(p*100))+'%';}
  if(msg){const t=document.querySelector('#bootL .bs');if(t)t.textContent=msg;}
  if(!force&&performance.now()-BOOT_LY<110)return Promise.resolve();
  return new Promise(r=>{let d=0;const f=()=>{if(!d){d=1;BOOT_LY=performance.now();r();}};requestAnimationFrame(()=>setTimeout(f,0));setTimeout(f,60);});}
const bootWait=ms=>new Promise(r=>setTimeout(r,ms));
function fontsRefresh(){let n=0;const keep=[];for(const e of TPL){let ok=false;try{ok=document.fonts.check(e.spec,e.text);}catch(_){ok=true;}if(!ok){keep.push(e);continue;}const t=e.m.map;t.image=tpDraw(e.text,e.w,e.h,e.o);t.needsUpdate=true;n++;}TPL.length=0;TPL.push(...keep);
  if(AS1&&!FONT_ATLAS_OK){FONT_ATLAS_OK=true;const cur=seed,sv=SIGNS.v.slice(),sh=SIGNS.h.slice(),m1=TX.signMat,m2=TX.shopMat;
    try{seed=AS1;makeSignAtlas();m1.map.image=TX.signMat.map.image;m1.emissiveMap.image=TX.signMat.emissiveMap.image;m1.map.needsUpdate=m1.emissiveMap.needsUpdate=true;
      seed=AS2;makeShopAtlas();m2.map.image=TX.shopMat.map.image;m2.emissiveMap.image=TX.shopMat.emissiveMap.image;m2.map.needsUpdate=m2.emissiveMap.needsUpdate=true;}catch(e){}
    TX.signMat=m1;TX.shopMat=m2;SIGNS.v.length=0;SIGNS.v.push(...sv);SIGNS.h.length=0;SIGNS.h.push(...sh);seed=cur;n+=2;}
  return n;}
let FONT_ATLAS_OK=true;
async function boot(){
  await bootProg(.03,'載入緊字體……',true);
  const FL=['900 40px "Noto Sans HK"','900 40px "Noto Serif HK"','800 20px "Barlow Condensed"'];
  try{await Promise.race([Promise.all(FL.map(f=>document.fonts.load(f,'元朗狂飆西鐵站'))),bootWait(800)]);}catch(e){}
  await bootProg(.08,'畫緊招牌……',true);
  makeTextures();makeFacades();makeExtraFacades();
  try{const sample=(SHOPS.join('')+VWORDS.join('')).slice(0,400);FONT_ATLAS_OK=document.fonts.check('900 40px '+FS,sample)&&document.fonts.check('900 40px '+FSERIF,sample);}catch(e){}
  AS1=seed;makeSignAtlas();AS2=seed;makeShopAtlas();
  await bootProg(.14,'起緊路同樓……');
  roofB=new Batch();detailB=new Batch();markW=new Batch();markY=new Batch();
  v3Pre();decodeRoads();buildFurnitureInst();await bootProg(.2);buildGround();buildHills();buildRoads();buildRail();await bootProg(.28);buildBuildings();await bootProg(.38,'起緊學校同車站……');v3Build();await bootProg(.46);buildFurniture();await bootProg(.5);
  roofB.mesh(new THREE.MeshStandardMaterial({map:TX.roof,roughness:.95}));detailB.mesh(std('#a9a69d',.85));markW.mesh(std('#e9e7e0',.6,0,{polygonOffset:true,polygonOffsetFactor:-8,polygonOffsetUnits:-8}),false);markY.mesh(std('#e8b923',.6,0,{polygonOffset:true,polygonOffsetFactor:-8,polygonOffsetUnits:-8}),false);
  flushInst();buildLabels();buildMinimap();buildLrtPath();spawnLrts();
  // spawn on Tai Yuk Road outside the school
  const sch=D.lab.find(l=>l[0]==='趙聿修紀念中學')||[0,D.spawn[0],D.spawn[1]];const nr=nearestRoad(sch[1],sch[2],120,r=>r.name==='元朗體育路'&&r.cls<=4)||nearestRoad(sch[1],sch[2],200,r=>r.cls<=4);
  let sx=D.spawn[0],sz=D.spawn[1],rd=[0,1];if(nr){rd=nr.dir;const nx=-rd[1],nz=rd[0];const side=((sch[1]-nr.x)*nx+(sch[2]-nr.z)*nz)>0?1:-1;sx=nr.x+nx*side*(nr.r.w/2+2.2);sz=nr.z+nz*side*(nr.r.w/2+2.2);
    const tx=nr.x+nx*side*(nr.r.w/2+.7)+rd[0]*7,tz=nr.z+nz*side*(nr.r.w/2+.7)+rd[1]*7;myTaxi=spawnVehicle('taxi','#c8102e',tx,tz,Math.atan2(rd[0],rd[1]));}
  PLAYER.x=sx;PLAYER.z=sz;pushOut(PLAYER,.35);PLAYER.h=Math.atan2(rd[0],rd[1]);cam.tx=PLAYER.x;cam.tz=PLAYER.z;cam.yaw=PLAYER.h+Math.PI*.8;
  spawnTraffic(PLAYER.x,PLAYER.z);spawnPeds(isMobile?30:50,PLAYER.x,PLAYER.z);
  PLAYER.p=uniformPerson(false,{hair:'#121212',bag:'#1d4fa0'});
  headSpot=new THREE.SpotLight(0xfff1d6,0,60,.45,.6,1.2);scene.add(headSpot,headSpot.target);
  for(let i=0;i<5;i++){const l=new THREE.PointLight(0xffc88a,0,26,1.6);scene.add(l);lampLights.push(l);}fillLight=new THREE.PointLight(0xffe6c8,0,9,1.5);scene.add(fillLight);
  await bootProg(.55,'叫緊街坊出嚟……');
  setupPost();setTod('dusk',true);rebuildEnv();setHud();gameBoot();
  for(let i=0;i<BOOTQ.length;i++){await bootProg(.6+.25*i/BOOTQ.length,i===10?'起緊西鐵站同天橋……':null);BOOTQ[i]();}
  gameBootTail();
  if(isMobile){$('#touch').hidden=false;$('#tQual').textContent='畫質：慳電';}
  window.__pv={renderOnce:()=>{update(1/60);render();return canvas.toDataURL('image/jpeg',.85);},setTod:(n)=>{setTod(n,true);applyTod(1);rebuildEnv();},tp:(x,z,yaw,pitch,zoom,y)=>{PLAYER.x=x;PLAYER.z=z;PLAYER.y=y!=null?y:TH(x,z);PLAYER.vy=0;PLAYER.grounded=true;PLAYER.ind=null;cam.ty=PLAYER.y+1.55;cam.tx=x;cam.tz=z;cam.yaw=yaw;cam.pitch=pitch;cam.zoom=zoom||1;cam.cd=6.2*(zoom||1);cam.noCol=(zoom||1)>3;},
    enterTaxi:()=>{PLAYER.x=myTaxi.x+1;PLAYER.z=myTaxi.z+1;act();return !!PLAYER.car;},step:(n,iy,ix)=>{for(let i=0;i<n;i++){keys.KeyW=iy>0;keys.KeyS=iy<0;keys.KeyD=ix>0;keys.KeyA=ix<0;update(1/60);}keys.KeyW=keys.KeyS=keys.KeyA=keys.KeyD=false;const o=PLAYER.car||PLAYER;return [o.x,o.z,PLAYER.car?PLAYER.car.speed:0];},
    info:()=>({calls:renderer.info.render.calls,tris:renderer.info.render.triangles,bld:BL.length,roads:ROADS.length,veh:vehicles.length,lamps:LAMPS.length,lrt:lrtPath?Math.round(lrtPath.len):0,stops:lrtPath?lrtPath.stops.length:0,post:!!composer,player:[PLAYER.x,PLAYER.z],mini:$('#mini').toDataURL().length})};
  window.__vl=vehicles;window.__mtr=()=>({s:MTR.train&&MTR.train.s,at:MTR.train&&MTR.train.at,wait:MTR.train&&MTR.train.wait,to:MTR.train&&MTR.train.to,yl:MTR.st.yl&&MTR.st.yl.s,lp:MTR.st.lp&&MTR.st.lp.s,len:MTR.path&&MTR.path.len});window.__g={SCH,HOME,CAKES,TAXI,KF,BM,jump:()=>{jumpReq=true;},openDress,closeDress,applyOutfit,toggleTaxi,openFishing,get fish(){return fishG;},CX,CZ,L2W,HX,HZ,WB,schoolPeriod,stairMenu,S,LOC,startGame,get dlg(){return dlgQ;},nextLine,act,attack,setStep,get gameMin(){return gameMin;},set gameMin(v){gameMin=v;},FIGHT,COPS,PCARS,addHeat,van:()=>van,PLAYER,toggleMap,get modal(){return modal;},closeModal,skew:()=>skewG,peds,INTER,bestInter};
  await bootFinish();
  if(window.__PV_TEST){for(let i=0;i<30;i++)update(1/60);return;}

  requestAnimationFrame(t=>{last=t;frame(t);});
}
async function bootFinish(){
  // fonts that were still downloading: fetch the glyphs the signs need, then repaint them before upload
  try{if(TPL.length||!FONT_ATLAS_OK){await bootProg(.86,'執緊招牌字體……',true);const txt=[...new Set(TPL.map(e=>e.text).join('')+SHOPS.join('')+VWORDS.join(''))].join('');
    const late=Promise.all(['900 40px "Noto Sans HK"','900 40px "Noto Serif HK"'].map(f=>document.fonts.load(f,txt))).catch(()=>{});
    await Promise.race([late,bootWait(1200)]);fontsRefresh();if(TPL.length||!FONT_ATLAS_OK)late.then(()=>{fontsRefresh();setTimeout(fontsRefresh,1500);});}}catch(e){}
  if(window.__PV_NOWARM)return;
  // pre-compile every shader and draw the first frame while the loading bar is still up
  await bootProg(.9,'準備緊畫面……',true);
  await bootProg(.95,'準備緊畫面……',true);
  await bootProg(.98,'差唔多……',true);
  try{update(1/60);render();}catch(e){}
  BOOT_STATS={tex:renderer.info.memory.textures,prog:renderer.info.programs?renderer.info.programs.length:0};}
let BOOT_STATS=null;
setTimeout(()=>{boot().catch(e=>console.error(e)).finally(()=>{introBoot();const b=document.getElementById('bootL');if(b){bootProg(1,'搞掂！',true);b.classList.add('done');setTimeout(()=>b.remove(),700);}hideRun();});},60);

